/** Exact-ID usage facts; these never choose a physical bank destination. */
final class ItemUsageTags
{
	private static final RequiredResource<Map<Integer, Set<String>>> DATA = new RequiredResource<>("item usage tags",
		() -> load(ItemUsageTags.class.getResourceAsStream("item-usage-tags.tsv")));

	static Set<String> forItem(int itemId)
	{
		return DATA.get().getOrDefault(itemId, Collections.emptySet());
	}

	static Map<Integer, Set<String>> load(InputStream stream)
	{
		if (stream == null) throw new IllegalStateException("Missing item usage tags");
		Map<Integer, Set<String>> result = new LinkedHashMap<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			if (!"# schema=1".equals(reader.readLine())) throw new IllegalStateException("Invalid usage tag schema");
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#")) continue;
				String[] fields = line.split("\t", -1);
				if (fields.length != 2) throw new IllegalStateException("Invalid usage tag row: " + line);
				int id = Integer.parseInt(fields[0]);
				String[] values = fields[1].split(",", -1);
				Set<String> tags = new LinkedHashSet<>(Arrays.asList(values));
				if (id <= 0 || tags.size() != values.length
					|| tags.stream().anyMatch(tag -> !tag.matches("[a-z][a-z0-9-]*"))
					|| result.putIfAbsent(id, Collections.unmodifiableSet(tags)) != null)
					throw new IllegalStateException("Invalid or duplicate usage tags: " + line);
			}
		}
		catch (IOException | IllegalArgumentException ex)
		{
			throw new IllegalStateException("Cannot read item usage tags", ex);
		}
		if (result.isEmpty()) throw new IllegalStateException("Empty item usage tags");
		return Collections.unmodifiableMap(result);
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.List;



/** Ordered item families with configurable overlap between rows. Loading failure is retained until analysis asks for the data. */
public final class OrderedItemFamilies
{
	private Map<String, List<Integer>> families = Collections.emptyMap();
	private CatalogUnavailableException failure;

	public OrderedItemFamilies(InputStream stream, int requiredWidth)
	{
		this(stream, requiredWidth, true);
	}

	/** Some layout tables deliberately reference the same item in different rows. */
	public OrderedItemFamilies(InputStream stream, int requiredWidth, boolean disjoint)
	{
		try
		{
			if (stream == null) throw new IOException("Missing item-family resource");
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
			{
				if (!"# schema=1".equals(reader.readLine())) throw new IOException("Invalid item-family schema");
				Map<String, List<Integer>> parsed = new LinkedHashMap<>();
				Set<Integer> seen = new HashSet<>();
				String line;
				while ((line = reader.readLine()) != null)
				{
					if (line.isEmpty() || line.startsWith("#")) continue;
					String[] fields = line.split("\t", -1);
					if (fields.length != 2 || fields[0].trim().isEmpty()) throw new IOException("Invalid family row: " + line);
					List<Integer> ids = new ArrayList<>();
					if (!disjoint) seen.clear();
					for (String value : fields[1].split(",", -1))
					{
						int id = Integer.parseInt(value);
						if (id <= 0 || !seen.add(id)) throw new IOException("Invalid or repeated family item: " + id);
						ids.add(id);
					}
					if (requiredWidth > 0 && ids.size() != requiredWidth) throw new IOException("Invalid family width: " + fields[0]);
					if (parsed.put(fields[0], Collections.unmodifiableList(ids)) != null) throw new IOException("Duplicate family: " + fields[0]);
				}
				if (parsed.isEmpty()) throw new IOException("Empty item-family table");
				families = Collections.unmodifiableMap(parsed);
			}
		}
		catch (IOException | IllegalArgumentException ex)
		{
			failure = new CatalogUnavailableException(
				"Bank analysis is unavailable because a required item layout table is missing or invalid.", ex);
		}
	}

	public Map<String, List<Integer>> entries()
	{
		if (failure != null) throw failure;
		return families;
	}

	public List<Integer> ids(String key)
	{
		List<Integer> ids = entries().get(key);
		if (ids == null) throw new CatalogUnavailableException(
			"Bank analysis is unavailable because a required item layout row is missing.",
			new IllegalStateException("Missing layout row: " + key));
		return ids;
	}

	/** Named groups retain declaration order and expose the original family keys. */
	public Map<String, List<Integer>> group(String prefix)
	{
		Map<String, List<Integer>> group = new LinkedHashMap<>();
		entries().forEach((key, ids) ->
		{
			if (key.startsWith(prefix + "/")) group.put(key.substring(prefix.length() + 1), ids);
		});
		if (group.isEmpty()) throw new CatalogUnavailableException(
			"Bank analysis is unavailable because a required item layout group is missing.",
			new IllegalStateException("Missing layout group: " + prefix));
		return Collections.unmodifiableMap(group);
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import java.util.Objects;
import java.util.function.Supplier;

/** Defers required data until use; a broken resource never poisons class initialization. */
public final class RequiredResource<T>
{
	private final String name;
	private Supplier<T> loader;
	private T value;
	private CatalogUnavailableException failure;

	public RequiredResource(String name, Supplier<T> loader)
	{
		this.name = name;
		this.loader = Objects.requireNonNull(loader);
	}

	public synchronized T get()
	{
		if (loader != null)
		{
			try
			{
				value = Objects.requireNonNull(loader.get());
			}
			catch (CatalogUnavailableException ex)
			{
				failure = ex;
			}
			catch (RuntimeException ex)
			{
				failure = new CatalogUnavailableException(
					"Bank analysis is unavailable because its " + name + " data is missing or invalid.", ex);
			}
			finally
			{
				loader = null;
			}
		}
		if (failure != null) throw failure;
		return value;
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsAny;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsWord;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;




public final class ResourceItemRegistry implements ItemCatalog
{
	static final String RESOURCE_PATH = "/com/pkoka5/ironmanbankarchitect/catalog/item-registry.tsv";

	private static final String[] TELEPORT_NEEDLES = {
		"ring of dueling", "games necklace", "amulet of glory", "skills necklace",
		"combat bracelet", "burning amulet", "necklace of passage", "digsite pendant", "ring of wealth",
		"bracelet of ethereum", "teleport", "tablet", "teletab", "jewellery", "ectophial",
		"xeric's talisman", "xeric talisman", "drakan's medallion", "drakans medallion",
		"book of the dead", "magic whistle"
	};

	private static final RequiredResource<java.util.List<String[]>> NAME_RULES =
		new RequiredResource<>("registry name rules", () -> loadNameRules(ResourceItemRegistry.class.getResourceAsStream(
			"/com/pkoka5/ironmanbankarchitect/catalog/registry-name-rules.tsv")));

	public static final ResourceItemRegistry INSTANCE = new ResourceItemRegistry();

	private final RequiredResource<Map<Integer, CatalogItem>> itemsById;
	private final CanonicalItemClassificationOverrides overrides;

	private ResourceItemRegistry()
	{
		this(CanonicalItemClassificationOverrides.INSTANCE);
	}

	ResourceItemRegistry(CanonicalItemClassificationOverrides overrides)
	{
		this.overrides = overrides;
		this.itemsById = new RequiredResource<>("item registry",
			() -> Collections.unmodifiableMap(loadItems(ResourceItemRegistry.class.getResourceAsStream(RESOURCE_PATH), overrides)));
	}

	@Override
	public void requireAvailable()
	{
		overrides.requireAvailable();
		NAME_RULES.get();
		itemsById.get();
		GearTierCatalog.INSTANCE.size();
		WikiItemLists.INSTANCE.requireAvailable();
		com.pkoka5.ironmanbankarchitect.organize.layout.ItemSetCatalog.requireAvailable();
	}

	@Override
	public Optional<CatalogItem> findById(int itemId)
	{
		requireAvailable();
		return Optional.ofNullable(itemsById.get().get(itemId));
	}

	public boolean containsId(int itemId)
	{
		requireAvailable();
		return itemsById.get().containsKey(itemId);
	}

	public int size()
	{
		requireAvailable();
		return itemsById.get().size();
	}

	static Map<Integer, CatalogItem> loadItems(InputStream stream, CanonicalItemClassificationOverrides overrides)
	{
		if (stream == null)
		{
			throw new IllegalStateException("Missing item registry resource: " + RESOURCE_PATH);
		}

		Map<Integer, CatalogItem> items = new LinkedHashMap<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.trim().isEmpty())
				{
					continue;
				}

				String[] fields = line.split("\t", -1);
				if (fields.length != 4)
				{
					throw new IllegalStateException("Invalid item registry line: " + line);
				}

				String itemIdText = fields[0];
				if (!itemIdText.isEmpty() && itemIdText.charAt(0) == '\uFEFF')
				{
					itemIdText = itemIdText.substring(1);
				}

				int itemId = Integer.parseInt(itemIdText);
				String displayName = fields[1];
				if (itemId <= 0 || displayName.trim().isEmpty() || items.containsKey(itemId))
				{
					throw new IllegalStateException("Invalid or duplicate item registry row: " + line);
				}
				ItemCategory explicitCategory = parseRegistryCategory(fields.length >= 3 ? fields[2] : "");
				String constantName = fields.length >= 4 ? fields[3] : "";
				ItemCategory legacyCategory = resolveCategory(displayName, constantName, explicitCategory);
				ItemClassificationRefiner.Classification classification =
					ItemClassificationRefiner.refine(displayName, constantName, legacyCategory);
				Optional<ItemSortMetadata> sortMetadata =
					ResourceItemSortMetadataCatalog.INSTANCE.findById(itemId);
				if (sortMetadata.isPresent() && sortMetadata.get().isFood())
				{
					// ID facts catch potatoes and hunter meats without broad display-name
					// rules that could also capture raw or non-edible items.
					classification = new ItemClassificationRefiner.Classification(ItemCategory.POTION, "food");
				}
				else if (sortMetadata.isPresent()
					&& sortMetadata.get().getVariantKind() == ItemSortMetadata.VariantKind.DOSE
					&& classification.getCategory() == ItemCategory.POTION)
				{
					// A curated canonical ID disambiguates true potion doses from jewellery,
					// waterskins and other unrelated items with numeric name suffixes.
					classification = new ItemClassificationRefiner.Classification(ItemCategory.POTION,
						"potion-dose-" + sortMetadata.get().getVariantValue());
				}
				String subcategory = classification.getSubcategory();
				if (classification.getCategory() == ItemCategory.CLEANUP
					&& "cleanup".equals(subcategory)
					&& WikiItemLists.INSTANCE.isQuestItem(displayName))
				{
					// Wiki-confirmed quest items get an honest review label
					// instead of the generic cleanup bucket.
					subcategory = "quest-item";
				}
				ItemCategory category = classification.getCategory();
				Optional<ItemClassificationRefiner.Classification> wikiClassification =
					WikiItemCategories.INSTANCE.overrideFor(itemId, category);
				if (wikiClassification.isPresent())
				{
					// Wiki category membership is a recorded fact about the item, so it
					// settles the tab where the name-shaped rules above only guessed.
					// Where both already agree, the refiner keeps its finer subcategory:
					// it is what separates herb seeds from the rest of the seeds and
					// partial potion doses from whole potions.
					category = wikiClassification.get().getCategory();
					subcategory = wikiClassification.get().getSubcategory();
				}
				Optional<ItemClassificationRefiner.Classification> canonicalOverride =
					overrides.lookup(itemId);
				if (canonicalOverride.isPresent())
				{
					// Exact item-ID overrides for canonical equipment run last, so cert,
					// placeholder, and Battle Royale records sharing a display name or
					// constant family never inherit them.
					category = canonicalOverride.get().getCategory();
					subcategory = canonicalOverride.get().getSubcategory();
				}
				if ("cosmetics".equals(com.pkoka5.ironmanbankarchitect.organize.layout.ItemSetCatalog.domainOf(itemId).orElse(""))
					|| com.pkoka5.ironmanbankarchitect.organize.layout.ItemSetCatalog.cosmeticFamilyOf(itemId).isPresent())
				{
					category = ItemCategory.CLUE;
					subcategory = "cosmetic";
				}
				items.putIfAbsent(itemId, new CatalogItem(itemId, displayName, category,
					subcategory, ItemUsageTags.forItem(itemId), null));
			}
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Failed to load item registry resource", ex);
		}

		if (items.isEmpty()) throw new IllegalStateException("Empty item registry");
		return items;
	}

	private static ItemCategory parseRegistryCategory(String value)
	{
		if (value == null || value.trim().isEmpty() || "UNKNOWN".equals(value))
		{
			return null;
		}

		try
		{
			return ItemCategory.valueOf(value);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	/**
	 * Explicit registry categories win over the name-based refinement, with two exceptions
	 * where the generated column is known to be unreliable:
	 * teleport jewellery is labelled GEAR or POTION (charge suffixes like "(4)" were read as
	 * potion doses), and every item containing the word "rune" was labelled RUNE (Rune
	 * scimitar, Rune dart, ...). Items without an explicit category are refined by name and
	 * default to CLEANUP for manual review.
	 */
	private static ItemCategory resolveCategory(String displayName, String constantName, ItemCategory explicitCategory)
	{
		String name = (displayName + " " + constantName.replace('_', ' ')).toLowerCase(java.util.Locale.ROOT);
		if (containsAny(name, TELEPORT_NEEDLES))
		{
			return ItemCategory.TELEPORT;
		}
		if (isGearOverride(displayName))
		{
			return ItemCategory.GEAR;
		}
		if (isToolOverride(displayName))
		{
			return ItemCategory.TOOL;
		}
		if (explicitCategory == ItemCategory.RUNE && !isActualRune(displayName))
		{
			return refineCategory(displayName, constantName, ItemCategory.CLEANUP);
		}
		if (explicitCategory == ItemCategory.SKILLING
			&& refineCategory(displayName, constantName, ItemCategory.SKILLING) == ItemCategory.TOOL)
		{
			// Plain tools (hammer, saw, chisel) carry an explicit SKILLING label
			// in the generated registry but belong in the tools tab.
			return ItemCategory.TOOL;
		}
		if (explicitCategory != null)
		{
			return explicitCategory;
		}

		return refineCategory(displayName, constantName, ItemCategory.CLEANUP);
	}

	private static boolean isGearOverride(String displayName)
	{
		String name = displayName.toLowerCase(java.util.Locale.ROOT);
		if (name.startsWith("torag's hammers")) return true;
		if (name.contains("thrownaxe") && !containsAny(name, "head", "crate", "ornament kit")) return true;
		return containsWord(name, "warhammer") && !containsAny(name, "crate", "ornament kit");
	}

	private static boolean isToolOverride(String displayName)
	{
		String name = displayName.toLowerCase(java.util.Locale.ROOT);
		String base = name.replaceFirst("\\s*\\([^)]*\\)$", "").trim();
		if (containsWord(name, "pickaxe") && !containsAny(name, "head", "handle", "kit", "crate")) return true;
		if ((base.equals("harpoon") || base.endsWith(" harpoon")) && !name.contains("crate")) return true;
		if ((base.equals("machete") || base.endsWith(" machete")) && !name.contains("crate")) return true;
		if (base.endsWith("butterfly net") || base.endsWith("fishing rod")
			|| base.equals("barbarian rod") || base.equals("lobster pot") || base.endsWith("fishing net"))
		{
			return true;
		}

		String[] axeMaterials = {"bronze", "iron", "steel", "black", "mithril", "adamant",
			"rune", "dragon", "crystal", "infernal", "3rd age", "gilded", "blessed", "imcando"};
		for (String material : axeMaterials)
		{
			if (base.equals(material + " axe") || base.equals(material + " felling axe")) return true;
		}
		return false;
	}

	private static boolean isActualRune(String displayName)
	{
		String name = displayName.toLowerCase(java.util.Locale.ROOT);
		return name.endsWith(" rune") || name.contains("essence");
	}

	private static ItemCategory refineCategory(String displayName, String constantName, ItemCategory category)
	{
		String name = (displayName + " " + constantName.replace('_', ' ')).toLowerCase(java.util.Locale.ROOT);
		for (String[] rule : NAME_RULES.get())
			for (int i = 2; i < rule.length; i++)
				if ("word".equals(rule[1]) ? containsWord(name, rule[i]) : name.contains(rule[i]))
					return ItemCategory.valueOf(rule[0]);
		return category;
	}

	static java.util.List<String[]> loadNameRules(InputStream stream)
	{
		if (stream == null) throw new IllegalStateException("Missing registry name rules");
		java.util.List<String[]> rules = new java.util.ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			if (!"# schema=1".equals(reader.readLine())) throw new IllegalStateException("Invalid name-rule schema");
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.startsWith("#") || line.trim().isEmpty()) continue;
				String[] rule = line.split("\\t", -1);
				if (rule.length < 3 || !("contains".equals(rule[1]) || "word".equals(rule[1])))
					throw new IllegalStateException("Invalid registry name rule");
				ItemCategory.valueOf(rule[0]);
				for (String field : rule) if (field.isEmpty()) throw new IllegalStateException("Empty name-rule field");
				rules.add(rule);
			}
		}
		catch (IOException ex) { throw new IllegalStateException("Cannot read registry name rules", ex); }
		if (rules.isEmpty()) throw new IllegalStateException("Empty registry name rules");
		return Collections.unmodifiableList(rules);
	}

}

package com.pkoka5.ironmanbankarchitect.catalog;

import static com.pkoka5.ironmanbankarchitect.util.TextValidation.requireText;

import java.io.*;
// Used only to validate the shape of source-attribution strings in a bundled
// manifest. This class opens no connection; the plugin makes no network calls.
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.function.Consumer;







public final class ResourceItemSortMetadataCatalog implements ItemSortMetadataCatalog
{
	private static final String SCHEMA_HEADER = "# schema=1";

	static final String METADATA_RESOURCE_PATH =
		"/com/pkoka5/ironmanbankarchitect/catalog/item-sort-metadata.tsv";
	static final String SOURCES_RESOURCE_PATH =
		"/com/pkoka5/ironmanbankarchitect/catalog/item-sort-metadata-sources.tsv";

	public static final ResourceItemSortMetadataCatalog INSTANCE =
		new ResourceItemSortMetadataCatalog();

	private final RequiredResource<Map<Integer, ItemSortMetadata>> metadataById;
	private final RequiredResource<Set<String>> sourceKeys;

	private ResourceItemSortMetadataCatalog()
	{
		this.sourceKeys = new RequiredResource<>("item metadata sources",
			() -> Collections.unmodifiableSet(loadSourceKeys(openRequired(SOURCES_RESOURCE_PATH))));
		this.metadataById = new RequiredResource<>("item sort metadata",
			() -> Collections.unmodifiableMap(loadMetadata(openRequired(METADATA_RESOURCE_PATH), sourceKeys.get())));
	}

	@Override
	public Optional<ItemSortMetadata> findById(int itemId)
	{
		return Optional.ofNullable(metadataById.get().get(itemId));
	}

	public int size()
	{
		return metadataById.get().size();
	}

	Collection<ItemSortMetadata> entries()
	{
		return metadataById.get().values();
	}

	Set<String> sourceKeys()
	{
		return sourceKeys.get();
	}

	static Map<Integer, ItemSortMetadata> loadMetadata(InputStream stream, Set<String> knownSourceKeys)
	{
		if (stream == null)
		{
			throw new IllegalArgumentException("metadata stream must not be null");
		}
		if (knownSourceKeys == null)
		{
			throw new IllegalArgumentException("knownSourceKeys must not be null");
		}

		Map<Integer, ItemSortMetadata> result = new LinkedHashMap<>();
		readTable(stream, 11, false, fields ->
		{
			int itemId = parseInt(fields[0], "item_id");
			String sourceKey = fields[10];
			if (!knownSourceKeys.contains(sourceKey))
			{
				throw new IllegalArgumentException("unknown sourceKey: " + sourceKey);
			}
			ItemSortMetadata metadata = new ItemSortMetadata(itemId, fields[1],
				parseEnum(ItemSortMetadata.VariantKind.class, fields[2], "variant_kind"),
				parseInt(fields[3], "variant_value"),
				parseEnum(ItemSortMetadata.FoodRole.class, fields[4], "food_role"),
				parseEnum(ItemSortMetadata.HealModel.class, fields[5], "heal_model"),
				parseInt(fields[6], "immediate_heal_min"), parseInt(fields[7], "immediate_heal_max"),
				parseInt(fields[8], "secondary_heal"),
				parseEnum(ItemSortMetadata.AreaRestriction.class, fields[9], "area_restriction"), sourceKey);
			if (result.putIfAbsent(itemId, metadata) != null)
			{
				throw new IllegalArgumentException("duplicate item_id: " + itemId);
			}
		});
		if (result.isEmpty()) throw new IllegalStateException("Empty required metadata table");
		return result;
	}

	static Set<String> loadSourceKeys(InputStream stream)
	{
		if (stream == null)
		{
			throw new IllegalArgumentException("source stream must not be null");
		}

		Set<String> result = new LinkedHashSet<>();
		readTable(stream, 5, true, fields ->
		{
			String sourceKey = ItemSortMetadata.requireKey(fields[0], "source_key");
			URI uri = URI.create(requireText(fields[1], "source_url"));
			if (!"https".equalsIgnoreCase(uri.getScheme()) || uri.getHost() == null)
				throw new IllegalArgumentException("source_url must be an absolute HTTPS URL");
			LocalDate.parse(requireText(fields[2], "retrieved_on"));
			String revision = requireText(fields[3], "revision");
			boolean wiki = "oldschool.runescape.wiki".equalsIgnoreCase(uri.getHost());
			if (wiki && !hasQueryParameter(uri, "oldid", revision))
				throw new IllegalArgumentException("Wiki source_url oldid must match revision");
			String license = requireText(fields[4], "license");
			if (wiki)
			{
				if (!revision.matches("\\d+")) throw new IllegalArgumentException("Wiki revision must be numeric");
				if (!"CC BY-NC-SA 3.0".equals(license))
					throw new IllegalArgumentException("Wiki license must be CC BY-NC-SA 3.0");
			}
			if (!result.add(sourceKey)) throw new IllegalArgumentException("duplicate source_key: " + sourceKey);
		});
		if (result.isEmpty()) throw new IllegalStateException("Empty required metadata table");
		return result;
	}

	/** Common framing keeps attribution and item tables equally strict. */
	private static void readTable(InputStream stream, int fieldCount, boolean source, Consumer<String[]> row)
	{
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			int lineNumber = 0;
			boolean schemaSeen = false;
			while ((line = reader.readLine()) != null)
			{
				lineNumber++;
				line = stripBom(line);
				if (!schemaSeen)
				{
					if (line.trim().isEmpty())
					{
						continue;
					}
					if (!SCHEMA_HEADER.equals(line.trim()))
					{
						throw invalid(source, "first non-empty line must be " + SCHEMA_HEADER,
							lineNumber, null);
					}
					schemaSeen = true;
					continue;
				}
				if (isIgnored(line))
				{
					continue;
				}

				String[] fields = line.split("\t", -1);
				if (fields.length != fieldCount)
				{
					throw invalid(source, "expected exactly " + fieldCount + " tab-separated fields", lineNumber, null);
				}

				try
				{
					row.accept(fields);
				}
				catch (IllegalArgumentException | DateTimeParseException ex)
				{
					throw invalid(source, ex.getMessage(), lineNumber, ex);
				}
			}
			if (!schemaSeen)
			{
				throw invalid(source, "missing " + SCHEMA_HEADER, lineNumber, null);
			}
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Failed to read item sort metadata" + (source ? " sources" : ""), ex);
		}
	}

	private static InputStream openRequired(String resourcePath)
	{
		InputStream stream = ResourceItemSortMetadataCatalog.class.getResourceAsStream(resourcePath);
		if (stream == null)
		{
			throw new IllegalStateException("Missing item sort resource: " + resourcePath);
		}
		return stream;
	}

	private static boolean isIgnored(String line)
	{
		String trimmed = line.trim();
		return trimmed.isEmpty() || trimmed.startsWith("#");
	}

	private static String stripBom(String value)
	{
		return !value.isEmpty() && value.charAt(0) == '\uFEFF' ? value.substring(1) : value;
	}

	private static boolean hasQueryParameter(URI uri, String key, String expectedValue)
	{
		String query = uri.getRawQuery();
		if (query == null)
		{
			return false;
		}
		for (String parameter : query.split("&"))
		{
			String[] parts = parameter.split("=", 2);
			if (parts.length == 2 && key.equals(parts[0]) && expectedValue.equals(parts[1]))
			{
				return true;
			}
		}
		return false;
	}

	private static int parseInt(String value, String field)
	{
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException ex)
		{
			throw new IllegalArgumentException(field + " must be an integer", ex);
		}
	}

	private static <E extends Enum<E>> E parseEnum(Class<E> enumType, String value, String field)
	{
		try
		{
			return Enum.valueOf(enumType, value);
		}
		catch (IllegalArgumentException ex)
		{
			throw new IllegalArgumentException("invalid " + field + ": " + value, ex);
		}
	}


	private static IllegalStateException invalid(boolean source, String message, int lineNumber, Throwable cause)
	{
		return new IllegalStateException("Invalid item sort metadata" + (source ? " source" : "")
			+ " at line " + lineNumber + ": " + message, cause);
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import java.util.*;







/**
 * Verified seed workflow items and supplemental items missing from the bundled registry.
 * Unknown IDs are never treated as an error.
 */
public final class StaticItemCatalog implements ItemCatalog
{
	public static final StaticItemCatalog INSTANCE = new StaticItemCatalog();

