	private static Set<String> tags(String... values)
	{
		return new LinkedHashSet<>(Arrays.asList(values));
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.List;




/**
 * Build-time OSRS Wiki categories (oldschool.runescape.wiki, CC BY-NC-SA 3.0); refresh with
 * tools/fetch-wiki-item-categories.ps1. No runtime network calls. First matching mapping wins.
 * Functional categories may override name rules; topical categories only resolve unclassified
 * items. Food, Fish, Arrows and Bolts are excluded because their categories mix materials and
 * finished items; curated metadata distinguishes them.
 */
final class WikiItemCategories
{
	static final String RESOURCE_PATH =
		"/com/pkoka5/ironmanbankarchitect/catalog/wiki-item-categories.tsv";

	private static final List<Mapping> MAPPINGS = Collections.unmodifiableList(Arrays.asList(
		Mapping.functional("Runes", ItemCategory.RUNE, "rune"),
		// Skilling outfits belong beside the tools they are worn with rather
		// than in the resources tab with the raw materials, and they rank above
		// teleports because a skillcape is filed under both: it is worn for the
		// skill and teleports as a side effect.
		Mapping.functional("Skilling equipment", ItemCategory.TOOL, "skilling-equipment"),
		Mapping.topical("Teleportation items", ItemCategory.TELEPORT, "teleport"),
		Mapping.functional("Clue scrolls", ItemCategory.CLUE, "treasure-trail"),
		// Tools outrank the workflow categories below so the implement stays
		// with the other tools: a seed dibber is not a seed, and a pestle and
		// mortar is not a Herblore ingredient.
		Mapping.topical("Tools", ItemCategory.TOOL, "tool"),
		Mapping.topical("Potions", ItemCategory.POTION, "potion"),
		Mapping.functional("Herbs", ItemCategory.HERBLORE, "herb"),
		Mapping.functional("Seeds", ItemCategory.FARMING, "seed"),
		Mapping.functional("Saplings", ItemCategory.FARMING, "sapling"),
		// Everything left in the broad Herblore category once potions, herbs
		// and seeds have been claimed: vials, secondaries, pastes and mixtures.
		Mapping.functional("Herblore", ItemCategory.HERBLORE, "herblore-supply"),
		Mapping.functional("Currency", ItemCategory.CURRENCY, "currency"),
		Mapping.functional("Ores", ItemCategory.SKILLING, "ore"),
		Mapping.functional("Metal bars", ItemCategory.SKILLING, "bar"),
		Mapping.functional("Logs", ItemCategory.SKILLING, "log"),
		// Gems carries the slayer master's enchanted gem alongside the real ones.
		Mapping.topical("Gems", ItemCategory.SKILLING, "gem"),
		Mapping.functional("Bones", ItemCategory.SKILLING, "bones"),
		Mapping.functional("Leather", ItemCategory.SKILLING, "leather")
	));

	static final WikiItemCategories INSTANCE = new WikiItemCategories();

	private final RequiredResource<Map<Integer, Mapping>> mappingsById;

	private WikiItemCategories()
	{
		this.mappingsById = new RequiredResource<>("wiki category",
			() -> Collections.unmodifiableMap(load(WikiItemCategories.class.getResourceAsStream(RESOURCE_PATH))));
	}

	/**
	 * The classification this snapshot has for the item, or empty when it has
	 * none or when it is not allowed to replace {@code current}.
	 */
	Optional<ItemClassificationRefiner.Classification> overrideFor(int itemId, ItemCategory current)
	{
		Mapping mapping = mappingsById.get().get(itemId);
		if (mapping == null || !overrules(current, mapping.category, mapping.functional))
		{
			return Optional.empty();
		}

		return Optional.of(new ItemClassificationRefiner.Classification(
			mapping.category, mapping.subcategory));
	}

	int size()
	{
		return mappingsById.get().size();
	}

	/**
	 * The first mapping whose wiki category the item belongs to, or empty when
	 * the item carries none of the categories this snapshot tracks.
	 */
	static Optional<Mapping> classify(List<String> wikiCategories)
	{
		for (Mapping mapping : MAPPINGS)
		{
			if (wikiCategories.contains(mapping.wikiCategory))
			{
				return Optional.of(mapping);
			}
		}

		return Optional.empty();
	}

	/**
	 * Whether a wiki category may replace the classification the name rules
	 * arrived at.
	 *
	 * A topical category only ever promotes an item the name rules left for
	 * review. Beyond that, two moves are refused outright. Gear never leaves the
	 * combat tab for carrying a teleport, because a great many teleports are
	 * worn. And nothing crosses between the Herblore and potion tabs, which
	 * split by workflow stage rather than by what an item is: one holds what a
	 * potion is made from and made into, the other holds what gets drunk. The
	 * wiki records no such stage and files every unfinished potion under both.
	 */
	static boolean overrules(ItemCategory current, ItemCategory wikiCategory, boolean functional)
	{
		if (current == wikiCategory)
		{
			return false;
		}
		if (!functional)
		{
			return isUnplaced(current);
		}
		if (current == ItemCategory.GEAR && wikiCategory == ItemCategory.TELEPORT)
		{
			return false;
		}

		return !(current == ItemCategory.HERBLORE && wikiCategory == ItemCategory.POTION
			|| current == ItemCategory.POTION && wikiCategory == ItemCategory.HERBLORE);
	}

	private static boolean isUnplaced(ItemCategory category)
	{
		return category == ItemCategory.CLEANUP
			|| category == ItemCategory.UNCATEGORIZED
			|| category == ItemCategory.UNKNOWN;
	}

	static Map<Integer, Mapping> load(InputStream stream)
	{
		if (stream == null)
		{
			throw new IllegalStateException("Missing wiki category resource: " + RESOURCE_PATH);
		}

		Map<Integer, Mapping> mappings = new LinkedHashMap<>();
		Set<Integer> seen = new HashSet<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (!line.isEmpty() && line.charAt(0) == '\uFEFF')
				{
					line = line.substring(1);
				}
				if (line.trim().isEmpty() || line.charAt(0) == '#')
				{
					continue;
				}

				String[] fields = line.split("\t", -1);
				if (fields.length != 3)
				{
					throw new IllegalStateException("Invalid wiki category line: " + line);
				}

				int itemId;
				try
				{
					itemId = Integer.parseInt(fields[0].trim());
				}
				catch (NumberFormatException ex)
				{
					throw new IllegalStateException("Invalid wiki category item id: " + line, ex);
				}

				if (itemId <= 0 || !seen.add(itemId) || fields[1].trim().isEmpty() || fields[2].trim().isEmpty())
				{
					throw new IllegalStateException("Invalid or duplicate wiki category row: " + line);
				}
				List<String> wikiCategories = Arrays.asList(fields[2].trim().split(","));
				int id = itemId;
				classify(wikiCategories).ifPresent(mapping -> mappings.put(id, mapping));
			}
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Failed to load wiki category resource", ex);
		}

		if (seen.isEmpty()) throw new IllegalStateException("Empty wiki category resource");
		return mappings;
	}

	static final class Mapping
	{
		private final String wikiCategory;
		private final ItemCategory category;
		private final String subcategory;
		private final boolean functional;

		private Mapping(String wikiCategory, ItemCategory category, String subcategory, boolean functional)
		{
			this.wikiCategory = wikiCategory;
			this.category = category;
			this.subcategory = subcategory;
			this.functional = functional;
		}

		static Mapping functional(String wikiCategory, ItemCategory category, String subcategory)
		{
			return new Mapping(wikiCategory, category, subcategory, true);
		}

		static Mapping topical(String wikiCategory, ItemCategory category, String subcategory)
		{
			return new Mapping(wikiCategory, category, subcategory, false);
		}

		ItemCategory getCategory()
		{
			return category;
		}

		boolean isFunctional()
		{
			return functional;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;




/**
 * Static item name lists sourced from the Old School RuneScape Wiki
 * (oldschool.runescape.wiki, CC BY-NC-SA 3.0), baked in at build time so the
 * plugin never makes network calls at runtime.
 */
public final class WikiItemLists
{
	static final String SPECIAL_ATTACK_WEAPONS_PATH =
		"/com/pkoka5/ironmanbankarchitect/catalog/special-attack-weapons.txt";
	static final String QUEST_ITEMS_PATH =
		"/com/pkoka5/ironmanbankarchitect/catalog/quest-items.txt";

	public static final WikiItemLists INSTANCE = new WikiItemLists();

	private final RequiredResource<Set<String>> specialAttackWeapons =
		new RequiredResource<>("special attack weapon", WikiItemLists::loadWeapons);
	private final RequiredResource<Set<String>> questItems =
		new RequiredResource<>("quest item", () -> loadNames(QUEST_ITEMS_PATH));

	private WikiItemLists()
	{
	}

	public void requireAvailable()
	{
		specialAttackWeapons.get();
		questItems.get();
	}

	private static Set<String> loadWeapons()
	{
		Set<String> weapons = new LinkedHashSet<>();
		for (String name : loadNames(SPECIAL_ATTACK_WEAPONS_PATH))
		{
			weapons.add(name);
			weapons.add(baseName(name));
		}
		return Collections.unmodifiableSet(weapons);
	}

	/**
	 * Matches on the base name, so charged and poisoned variants such as
	 * "Dragon dagger(p++)" count as their special attack weapon.
	 */
	public boolean isSpecialAttackWeapon(String displayName)
	{
		return displayName != null && specialAttackWeapons.get().contains(baseName(displayName.toLowerCase(Locale.ROOT)));
	}

	/**
	 * Exact name matches only: the wiki category also lists quest-specific
	 * variants of regular items ("Abyssal whip (My Arm's Big Adventure)"),
	 * which are filtered out of the resource to avoid false positives.
	 */
	public boolean isQuestItem(String displayName)
	{
		return displayName != null && questItems.get().contains(displayName.toLowerCase(Locale.ROOT).trim());
	}

	static String baseName(String name)
	{
		String trimmed = name.trim();
		int parenthesis = trimmed.indexOf('(');
		if (parenthesis > 0)
		{
			trimmed = trimmed.substring(0, parenthesis);
		}

		return trimmed.trim();
	}

	private static Set<String> loadNames(String resourcePath)
	{
		return loadNames(WikiItemLists.class.getResourceAsStream(resourcePath));
	}

	static Set<String> loadNames(InputStream stream)
	{
		if (stream == null)
		{
			throw new IllegalStateException("Missing wiki item list resource");
		}

		Set<String> names = new LinkedHashSet<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				String trimmed = (!line.isEmpty() && line.charAt(0) == '\uFEFF' ? line.substring(1) : line).trim();
				if (trimmed.isEmpty() || trimmed.startsWith("#"))
				{
					continue;
				}
				if (trimmed.indexOf('\t') >= 0) throw new IllegalStateException("Invalid wiki item name: " + line);
				names.add(trimmed.toLowerCase(Locale.ROOT));
			}
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Failed to load wiki item list", ex);
		}

		if (names.isEmpty()) throw new IllegalStateException("Empty wiki item list");
		return Collections.unmodifiableSet(names);
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

import com.pkoka5.ironmanbankarchitect.analysis.BankAnalysisStatus;
import com.pkoka5.ironmanbankarchitect.blueprint.*;
import com.pkoka5.ironmanbankarchitect.match.BlockMatchResult;
import com.pkoka5.ironmanbankarchitect.organize.BankOrganizationPreview;
import java.util.*;
import java.util.List;
import java.util.concurrent.atomic.*;



public final class BankGuideController
{
	public static final String BANK_CLOSED_STATUS = "Open your bank to preview the guide.";
	public static final String GUIDE_ACTIVE_STATUS = "Guide preview active.";
	public static final String GUIDE_DISABLED_STATUS = "Guide preview off.";
	public static final String NO_ANALYSIS_STATUS = "No bank analysis yet.";
	public static final String ANALYSIS_BANK_CLOSED_STATUS = "Open your bank before analyzing.";
	public static final String ANALYSIS_RUNNING_STATUS = BankAnalysisStatus.RUNNING_TEXT;
	public static final String ANALYSIS_FAILED_STATUS = BankAnalysisStatus.FAILED_TEXT;
	public static final String NO_CATALOG_SUMMARY_STATUS = BankAnalysisStatus.NO_CATALOG_SUMMARY_TEXT;
	public static final String NO_ORGANIZATION_PREVIEW_STATUS = BankAnalysisStatus.NO_ORGANIZATION_PREVIEW_TEXT;
	public static final String NO_GUIDANCE_PROGRESS_STATUS = "Analyze your bank to start item-order guidance.";
	public static final String GUIDANCE_BANK_CLOSED_STATUS = "Open your bank for item-order guidance.";
	public static final String GUIDANCE_DISABLED_STATUS = "Enable Bank Guide to show the next manual move.";
	public static final String GUIDANCE_READY_STATUS = "Open the vanilla All items view to begin item-order guidance.";
	public static final String NO_OVERRIDES_STATUS = "No category corrections yet.";
	public static final String ASSIGN_MODE_HINT =
		"Right-click a bank item and pick a tag to correct where it lands.";

	private final List<VisualBlock> availableBlocks;
	private final AtomicReference<BankGuideState> state;
	private final AtomicReference<BlockMatchResult> latestMatchResult = new AtomicReference<>();
	private final AtomicReference<String> analysisText = new AtomicReference<>(NO_ANALYSIS_STATUS);
	private final AtomicReference<String> analysisDetailText = new AtomicReference<>("");
	private final AtomicReference<BankAnalysisStatus> bankAnalysisStatus =
		new AtomicReference<>(BankAnalysisStatus.notStarted());
	private final AtomicReference<String> guideProgressText = new AtomicReference<>(NO_GUIDANCE_PROGRESS_STATUS);
	private final AtomicInteger guideProgressPercent = new AtomicInteger(-1);
	private final AtomicBoolean bankOpen = new AtomicBoolean(false);
	private final AtomicBoolean guideArmedAutomatically = new AtomicBoolean(false);
	private final AtomicReference<Runnable> bankOpenedListener = new AtomicReference<>();
	private final AtomicBoolean categoryAssignMode = new AtomicBoolean(false);
	private final AtomicInteger categoryOverrideCount = new AtomicInteger(0);

	public BankGuideController(BankProfile profile)
	{
		Objects.requireNonNull(profile, "profile");
		this.availableBlocks = collectBlocks(profile);
		if (availableBlocks.isEmpty())
		{
			throw new IllegalArgumentException("profile must contain at least one block");
		}

		this.state = new AtomicReference<>(new BankGuideState(availableBlocks.get(0).getKey(), false));
	}

	public List<VisualBlock> getAvailableBlocks()
	{
		return availableBlocks;
	}

	public VisualBlock getSelectedBlock()
	{
		return findBlock(state.get().getSelectedBlockKey());
	}

	public void selectBlock(String blockKey)
	{
		findBlock(blockKey);
		state.updateAndGet(current -> current.withSelectedBlockKey(blockKey));
	}

	public boolean isGuideEnabled()
	{
		return state.get().isGuideEnabled();
	}

	public void setGuideEnabled(boolean enabled)
	{
		guideArmedAutomatically.set(false);
		state.updateAndGet(current -> current.withGuideEnabled(enabled));
		if (enabled)
		{
			categoryAssignMode.set(false);
		}
	}

	public void toggleGuide()
	{
		guideArmedAutomatically.set(false);
		boolean enabled = state
			.updateAndGet(current -> current.withGuideEnabled(!current.isGuideEnabled()))
			.isGuideEnabled();
		if (enabled)
		{
			categoryAssignMode.set(false);
		}
	}

	/**
	 * While assign mode is on, the bank right-click menu offers the blueprint
	 * destinations so the player can correct a classification.
	 *
	 * <p>Assign mode and the guide are mutually exclusive. Each one paints the
	 * bank in a different colour language: assign mode tints an item with the
	 * colour of the tab it is headed for, the guide tints a slot by whether it
	 * is already correct. Both at once would leave the player unable to tell
	 * which question a colour is answering, so switching one on switches the
	 * other off.</p>
	 */
	public boolean isCategoryAssignMode()
	{
		return categoryAssignMode.get();
	}

	public void toggleCategoryAssignMode()
	{
		setCategoryAssignMode(!categoryAssignMode.get());
	}

	public void setCategoryAssignMode(boolean enabled)
	{
		categoryAssignMode.set(enabled);
		if (enabled)
		{
			state.updateAndGet(current -> current.withGuideEnabled(false));
		}
	}

	public void publishCategoryOverrideCount(int count)
	{
		categoryOverrideCount.set(Math.max(0, count));
	}

	public int getCategoryOverrideCount()
	{
		return categoryOverrideCount.get();
	}

	public String getCategoryOverrideText()
	{
		int count = categoryOverrideCount.get();
		String summary = count == 0 ? NO_OVERRIDES_STATUS
			: count + (count == 1 ? " item is" : " items are") + " corrected by hand.";
		return categoryAssignMode.get() ? summary + " " + ASSIGN_MODE_HINT : summary;
	}

	public boolean isBankOpen()
	{
		return bankOpen.get();
	}

	public void setBankOpen(boolean open)
	{
		boolean was = bankOpen.getAndSet(open);
		if (open && !was)
		{
			Runnable listener = bankOpenedListener.get();
			if (listener != null)
			{
				listener.run();
			}
		}
	}

	/**
	 * Runs once each time the bank goes from closed to open. The overlay reports
	 * the bank state every frame, so the transition is detected here rather than
	 * by the caller.
	 */
	public void setBankOpenedListener(Runnable listener)
	{
		bankOpenedListener.set(listener);
	}

	/**
	 * Arms the guide the way opening the bank does under the auto-guide setting.
	 * Guidance armed this way renders quietly: no banners on unsortable views
	 * and no confirmation on sorted slots. Any manual guide action reverts the
	 * guide to its usual, fully spoken form.
	 */
	public void enableGuideAutomatically()
	{
		setGuideEnabled(true);
		guideArmedAutomatically.set(true);
	}

	public boolean isGuideArmedAutomatically()
	{
		return guideArmedAutomatically.get() && isGuideEnabled();
	}

	public String getStatusText()
	{
		if (!bankOpen.get())
		{
			return BANK_CLOSED_STATUS;
		}

		return isGuideEnabled() ? GUIDE_ACTIVE_STATUS : GUIDE_DISABLED_STATUS;
	}

	public BankGuideState getState()
	{
		return state.get();
	}

	public synchronized void publishBankAnalysis(BankAnalysisStatus status)
	{
		Objects.requireNonNull(status, "status");
		if (status.kind() == BankAnalysisStatus.Kind.BANK_CLOSED)
		{
			latestMatchResult.set(null);
			analysisText.set(ANALYSIS_BANK_CLOSED_STATUS);
			analysisDetailText.set("");
		}

		if (status.kind() == BankAnalysisStatus.Kind.SUCCESS)
		{
			guideProgressText.set(GUIDANCE_READY_STATUS);
			guideProgressPercent.set(-1);
			bankAnalysisStatus.set(status);
			return;
		}

		bankAnalysisStatus.set(status);
		guideProgressText.set(NO_GUIDANCE_PROGRESS_STATUS);
		guideProgressPercent.set(-1);
	}

	public void publishMatchResult(BlockMatchResult result)
	{
		Objects.requireNonNull(result, "result");
		latestMatchResult.set(result);
		analysisText.set(result.toCompactSummary());
		analysisDetailText.set(result.toSlotDetailText());
	}

	public BlockMatchResult getLatestMatchResult()
	{
		return latestMatchResult.get();
	}

	public String getAnalysisText()
	{
		return analysisText.get();
	}

	public String getAnalysisDetailText()
	{
		return analysisDetailText.get();
	}

	public BankAnalysisStatus bankAnalysisStatus()
	{
		return bankAnalysisStatus.get();
	}

	public BankOrganizationPreview organizationPreview()
	{
		return bankAnalysisStatus.get().organizationPreview().orElse(null);
	}

	public void publishGuideProgressText(String text)
	{
		guideProgressText.set(Objects.requireNonNull(text, "text"));
	}

	/**
	 * Publishes the guidance status line together with an overall progress
	 * percentage; pass -1 when no meaningful percentage is available.
	 */
	public void publishGuideProgress(String text, int percent)
	{
		publishGuideProgressText(text);
		guideProgressPercent.set(Math.max(-1, Math.min(100, percent)));
	}

	public int getGuideProgressPercent()
	{
		BankAnalysisStatus analysis = bankAnalysisStatus.get();
		if (analysis.kind() != BankAnalysisStatus.Kind.SUCCESS
			|| !bankOpen.get() || !isGuideEnabled())
		{
			return -1;
		}
		return guideProgressPercent.get();
	}

	public String getGuideProgressText()
	{
		BankAnalysisStatus analysis = bankAnalysisStatus.get();
		if (analysis.kind() == BankAnalysisStatus.Kind.RUNNING)
		{
			return ANALYSIS_RUNNING_STATUS;
		}
		if (analysis.kind() == BankAnalysisStatus.Kind.FAILED)
		{
			return analysis.organizationPreviewText();
		}
		if (analysis.kind() != BankAnalysisStatus.Kind.SUCCESS)
		{
			return NO_GUIDANCE_PROGRESS_STATUS;
		}
		if (!bankOpen.get())
		{
			return GUIDANCE_BANK_CLOSED_STATUS;
		}
		if (!isGuideEnabled())
		{
			return GUIDANCE_DISABLED_STATUS;
		}
		return guideProgressText.get();
	}

	private VisualBlock findBlock(String key)
	{
		for (VisualBlock block : availableBlocks)
		{
			if (block.getKey().equals(key))
			{
				return block;
			}
		}

		throw new IllegalArgumentException("Unknown block key: " + key);
	}

	private static List<VisualBlock> collectBlocks(BankProfile profile)
	{
		List<VisualBlock> blocks = new ArrayList<>();
		for (BlueprintTab tab : profile.getTabs())
		{
			for (BlueprintSection section : tab.getSections())
			{
				blocks.addAll(section.getBlocks());
			}
		}

		return Collections.unmodifiableList(blocks);
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

import static com.pkoka5.ironmanbankarchitect.util.TextValidation.requireText;

import java.util.Objects;

public final class BankGuideState
{
	private final String selectedBlockKey;
	private final boolean guideEnabled;

	public BankGuideState(String selectedBlockKey, boolean guideEnabled)
	{
		this.selectedBlockKey = requireText(selectedBlockKey, "selectedBlockKey");
		this.guideEnabled = guideEnabled;
	}

	public String getSelectedBlockKey()
	{
		return selectedBlockKey;
	}

	public boolean isGuideEnabled()
	{
		return guideEnabled;
	}

	public BankGuideState withSelectedBlockKey(String blockKey)
	{
		return new BankGuideState(blockKey, guideEnabled);
	}

	public BankGuideState withGuideEnabled(boolean enabled)
	{
		return new BankGuideState(selectedBlockKey, enabled);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}

		if (!(other instanceof BankGuideState))
		{
			return false;
		}

		BankGuideState that = (BankGuideState) other;
		return guideEnabled == that.guideEnabled && selectedBlockKey.equals(that.selectedBlockKey);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(selectedBlockKey, guideEnabled);
	}

}

package com.pkoka5.ironmanbankarchitect.guide;

import com.pkoka5.ironmanbankarchitect.organize.*;
import java.util.*;
import java.util.List;



/**
 * Dense physical-bank-tab plan derived from the ten blueprint categories.
 * Blueprint category 1 is the existing untabbed/main range. Non-empty
 * categories 2..10 are mapped densely to the nine physical bank tabs because
 * OSRS cannot retain an empty numbered tab.
 */
public final class BankTabPlan
{
	private static final int MAIN_CATEGORY_INDEX = 0;
	private static final int FIRST_NUMBERED_CATEGORY_INDEX = 1;
	private static final int TOTAL_CATEGORY_COUNT = 10;

	private final List<TargetTab> numberedTabs;
	private final String mainCategoryKey;
	private final String mainCategoryName;
	private final List<BankPreviewItem> mainItems;
	private final List<BankPreviewItem> flattenedItems;
	private final BankLayoutPlan layout;
	private int[] lastActual;
	private int[] lastCounts;
	private List<BankPreviewItem> lastEffective;

	private BankTabPlan(List<TargetTab> numberedTabs, String mainCategoryKey,
		String mainCategoryName, List<BankPreviewItem> mainItems, BankLayoutPlan layout)
	{
		this.layout = Objects.requireNonNull(layout, "layout");
		this.numberedTabs = Collections.unmodifiableList(new ArrayList<>(numberedTabs));
		this.mainCategoryKey = Objects.requireNonNull(mainCategoryKey, "mainCategoryKey");
		this.mainCategoryName = Objects.requireNonNull(mainCategoryName, "mainCategoryName");
		this.mainItems = immutableCopy(mainItems);

		List<BankPreviewItem> flattened = new ArrayList<>();
		for (TargetTab tab : numberedTabs)
		{
			flattened.addAll(tab.getItems());
		}
		flattened.addAll(mainItems);
		this.flattenedItems = Collections.unmodifiableList(flattened);
	}

	public static BankTabPlan fromPreview(BankOrganizationPreview preview)
	{
		return fromPreview(preview, BankLayoutPlan.defaultFor(preview.getPreset()));
	}

	public static BankTabPlan fromPreview(BankOrganizationPreview preview, BankLayoutPlan layout)
	{
		Objects.requireNonNull(preview, "preview");
		List<BankCategoryPreview> categories = preview.getCategories();
		if (categories.size() != TOTAL_CATEGORY_COUNT)
		{
			throw new IllegalArgumentException("tab guidance requires exactly 10 blueprint categories");
		}

		BankCategoryPreview main = categories.get(MAIN_CATEGORY_INDEX);
		List<TargetTab> numbered = new ArrayList<>();
		for (int categoryIndex = FIRST_NUMBERED_CATEGORY_INDEX;
			categoryIndex < TOTAL_CATEGORY_COUNT; categoryIndex++)
		{
			BankCategoryPreview category = categories.get(categoryIndex);
			if (category.getItemCount() == 0)
			{
				continue;
			}
			numbered.add(new TargetTab(numbered.size() + 1, categoryIndex + 1,
				category.getCategory().getKey(), category.getCategory().getName(), category.getItems()));
		}

		return new BankTabPlan(numbered, main.getCategory().getKey(),
			main.getCategory().getName(), main.getItems(), layout);
	}

	/** Project live order without changing the plan identity or its item destinations. */
	public synchronized List<BankPreviewItem> effectiveItems(int[] actualItemIds, int[] tabCounts)
	{
		if (!layout.hasCurrentOrder()) return flattenedItems;
		if (Arrays.equals(lastActual, actualItemIds) && Arrays.equals(lastCounts, tabCounts)) return lastEffective;
		if (tabCounts.length != TabRouteAdvisor.MAX_TABS) throw new IllegalArgumentException("Invalid tab counts");
		long total = 0;
		for (int count : tabCounts)
		{
			if (count < 0) throw new IllegalArgumentException("Negative tab count");
			total += count;
		}
		if (total > actualItemIds.length) throw new IllegalArgumentException("Tab counts exceed bank size");
		List<BankPreviewItem> result = new ArrayList<>();
		int start = 0;
		for (TargetTab tab : numberedTabs)
		{
			int end = start + tabCounts[tab.getBankTabNumber() - 1];
			result.addAll(currentOrder(tab.getItems(), actualItemIds, start, end,
				layout.keepsCurrentOrder(tab.getBlueprintCategoryNumber() - 1)));
			start = end;
		}
		result.addAll(currentOrder(mainItems, actualItemIds, start, actualItemIds.length,
			layout.keepsCurrentOrder(0)));
		lastActual = actualItemIds.clone();
		lastCounts = tabCounts.clone();
		lastEffective = Collections.unmodifiableList(result);
		return lastEffective;
	}

	private static List<BankPreviewItem> currentOrder(List<BankPreviewItem> target, int[] actual,
		int start, int end, boolean keep)
	{
		if (!keep) return target;
		Map<Integer, Deque<BankPreviewItem>> remaining = new HashMap<>();
		for (BankPreviewItem item : target)
			remaining.computeIfAbsent(item.getItemId(), key -> new ArrayDeque<>()).addLast(item);
		List<BankPreviewItem> result = new ArrayList<>();
		for (int slot = start; slot < end; slot++)
		{
			Deque<BankPreviewItem> copies = remaining.get(actual[slot]);
			if (copies != null && !copies.isEmpty()) result.add(copies.removeFirst());
		}
		for (BankPreviewItem item : target)
		{
			Deque<BankPreviewItem> copies = remaining.get(item.getItemId());
			if (!copies.isEmpty() && copies.peekFirst() == item) result.add(copies.removeFirst());
		}
		return result;
	}

	public List<TargetTab> getNumberedTabs()
	{
		return numberedTabs;
	}

	public List<BankPreviewItem> getMainItems()
	{
		return mainItems;
	}

	public String getMainCategoryKey()
	{
		return mainCategoryKey;
	}

	public String getMainCategoryName()
	{
		return mainCategoryName;
	}

	public List<BankPreviewItem> getFlattenedItems()
	{
		return flattenedItems;
	}

	public boolean keepsCurrentOrder(int destinationIndex) { return layout.keepsCurrentOrder(destinationIndex); }

	private static List<BankPreviewItem> immutableCopy(List<BankPreviewItem> items)
	{
		return Collections.unmodifiableList(new ArrayList<>(Objects.requireNonNull(items, "items")));
	}

	public static final class TargetTab
	{
		private final int bankTabNumber;
		private final int blueprintCategoryNumber;
		private final String categoryKey;
		private final String categoryName;
		private final List<BankPreviewItem> items;

		private TargetTab(int bankTabNumber, int blueprintCategoryNumber, String categoryKey,
			String categoryName, List<BankPreviewItem> items)
		{
			this.bankTabNumber = bankTabNumber;
			this.blueprintCategoryNumber = blueprintCategoryNumber;
			this.categoryKey = Objects.requireNonNull(categoryKey, "categoryKey");
			this.categoryName = Objects.requireNonNull(categoryName, "categoryName");
			this.items = immutableCopy(items);
		}

		public int getBankTabNumber()
		{
			return bankTabNumber;
		}

		public int getBlueprintCategoryNumber()
		{
			return blueprintCategoryNumber;
		}

		public String getCategoryKey()
		{
			return categoryKey;
		}

		public String getCategoryName()
		{
			return categoryName;
		}

		public List<BankPreviewItem> getItems()
		{
			return items;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.*;
import java.util.List;



/** Matches interchangeable occurrences of one item ID to physical target slots. */
final class ItemOccurrenceMatcher
{
	private ItemOccurrenceMatcher()
	{
	}

	/**
	 * Returns the target offset assigned to every current offset. Occurrences
	 * already in a matching slot stay fixed, then the remaining equal-ID copies
	 * are paired in target order. Returns {@code null} when the section bounds or
	 * item multiplicities do not match the target.
	 */
	static int[] targetOffsets(int[] actualItemIds, int sectionStart,
		List<BankPreviewItem> targetItems)
	{
		int size = targetItems.size();
		if (sectionStart < 0 || size == 0 || sectionStart + size > actualItemIds.length)
		{
			return null;
		}

		int[] targetOffsets = new int[size];
		boolean[] assignedCurrent = new boolean[size];
		boolean[] assignedTarget = new boolean[size];
		for (int offset = 0; offset < size; offset++)
		{
			if (actualItemIds[sectionStart + offset] == targetItems.get(offset).getItemId())
			{
				targetOffsets[offset] = offset;
				assignedCurrent[offset] = true;
				assignedTarget[offset] = true;
			}
		}

		return fillRemainingOffsets(actualItemIds, sectionStart, targetItems,
			targetOffsets, assignedCurrent, assignedTarget);
	}

	/**
	 * Assigns equal-ID copies so that insert mode can keep a longest common
	 * subsequence in place. Remaining copies are paired in order after those
	 * optimal matches have been reserved.
	 */
	static int[] orderedTargetOffsets(int[] actualItemIds, int sectionStart,
		List<BankPreviewItem> targetItems)
	{
		int size = targetItems.size();
		if (sectionStart < 0 || size == 0 || sectionStart + size > actualItemIds.length)
		{
			return null;
		}

		if (targetItems.stream().map(BankPreviewItem::getItemId).distinct().count() == size)
			return targetOffsets(actualItemIds, sectionStart, targetItems);
		int[][] commonSuffixLengths = new int[size + 1][size + 1];
		for (int current = size - 1; current >= 0; current--)
		{
			for (int target = size - 1; target >= 0; target--)
			{
				if (actualItemIds[sectionStart + current] == targetItems.get(target).getItemId())
				{
					commonSuffixLengths[current][target] =
						commonSuffixLengths[current + 1][target + 1] + 1;
				}
				else
				{
					commonSuffixLengths[current][target] = Math.max(
						commonSuffixLengths[current + 1][target],
						commonSuffixLengths[current][target + 1]);
				}
			}
		}

		int[] targetOffsets = new int[size];
		boolean[] assignedCurrent = new boolean[size];
		boolean[] assignedTarget = new boolean[size];
		int current = 0;
		int target = 0;
		while (current < size && target < size)
		{
			if (actualItemIds[sectionStart + current] == targetItems.get(target).getItemId()
				&& commonSuffixLengths[current][target]
					== commonSuffixLengths[current + 1][target + 1] + 1)
			{
				targetOffsets[current] = target;
				assignedCurrent[current] = true;
				assignedTarget[target] = true;
				current++;
				target++;
			}
			else if (commonSuffixLengths[current + 1][target]
				>= commonSuffixLengths[current][target + 1])
			{
				current++;
			}
			else
			{
				target++;
			}
		}

		return fillRemainingOffsets(actualItemIds, sectionStart, targetItems,
			targetOffsets, assignedCurrent, assignedTarget);
	}

	private static int[] fillRemainingOffsets(int[] actualItemIds, int sectionStart,
		List<BankPreviewItem> targetItems, int[] targetOffsets,
		boolean[] assignedCurrent, boolean[] assignedTarget)
	{
		int size = targetItems.size();
		Map<Integer, ArrayDeque<Integer>> targetsByItemId = new HashMap<>();
		for (int offset = 0; offset < size; offset++)
		{
			if (!assignedTarget[offset])
			{
				targetsByItemId.computeIfAbsent(targetItems.get(offset).getItemId(),
					ignored -> new ArrayDeque<>()).addLast(offset);
			}
		}

		for (int offset = 0; offset < size; offset++)
		{
			if (assignedCurrent[offset])
			{
				continue;
			}
			ArrayDeque<Integer> targets = targetsByItemId.get(actualItemIds[sectionStart + offset]);
			if (targets == null || targets.isEmpty())
			{
				return null;
			}
			targetOffsets[offset] = targets.removeFirst();
		}
		for (ArrayDeque<Integer> targets : targetsByItemId.values())
		{
			if (!targets.isEmpty())
			{
				return null;
			}
		}
		return targetOffsets;
	}

	/** Sorted item IDs whose live occurrence count exceeds the planned count. */
	static List<Integer> excessRepeatedItemIds(Map<Integer, Integer> actualCounts,
		Map<Integer, Integer> plannedCounts)
	{
		TreeSet<Integer> result = new TreeSet<>();
		for (Map.Entry<Integer, Integer> entry : actualCounts.entrySet())
		{
			int planned = plannedCounts.getOrDefault(entry.getKey(), 0);
			if (entry.getValue() > 1 && entry.getValue() > planned)
			{
				result.add(entry.getKey());
			}
		}
		return List.copyOf(result);
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

/**
 * Player-selected rearrange mode: SWAP exchanges two slots; INSERT shifts intervening slots.
 * Fixed-pairing swap distance is n minus permutation cycles, an estimate with duplicate IDs. Insert
 * lower bound is n minus LIS for stable occurrence order.
 */
public enum RearrangeMode
{
	SWAP,
	INSERT
}

package com.pkoka5.ironmanbankarchitect.guide;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.List;
import java.util.Objects;

/**
 * Pure dense-section insert planner. Each manual insert shifts intervening slots, so guidance
 * targets the current drop-slot occupant. Keeps a longest increasing subsequence and serves other
 * items in target order, achieving exactly n - LIS moves.
 */
public final class SectionInsertPlanner
{
	private SectionInsertPlanner()
	{
	}

	/**
	 * Exact same-section insert lower bound: every item outside a longest
	 * increasing subsequence of the target permutation must be dragged once.
	 * Returns 0 when the section cannot be interpreted against the plan.
	 */
	static int minimumRemainingInserts(int[] actualItemIds, int sectionStart,
		List<BankPreviewItem> targetItems)
	{
		int[] permutation = permutation(actualItemIds, sectionStart, targetItems);
		return permutation == null
			? 0 : permutation.length - longestIncreasingSubsequence(permutation).length;
	}

	/**
	 * Next drag for this section, or {@code null} when it is already in target
	 * order or cannot be interpreted against the plan.
	 */
	static Step nextStep(int[] actualItemIds, int sectionStart, List<BankPreviewItem> targetItems)
	{
		Objects.requireNonNull(actualItemIds, "actualItemIds");
		Objects.requireNonNull(targetItems, "targetItems");

		int[] permutation = permutation(actualItemIds, sectionStart, targetItems);
		if (permutation == null)
		{
			return null;
		}

		int size = permutation.length;
		boolean[] settled = new boolean[size];
		for (int index : longestIncreasingSubsequence(permutation))
		{
			settled[index] = true;
		}

		int movePosition = -1;
		for (int position = 0; position < size; position++)
		{
			if (!settled[position]
				&& (movePosition < 0 || permutation[position] < permutation[movePosition]))
			{
				movePosition = position;
			}
		}
		if (movePosition < 0)
		{
			return null;
		}

		// Settled items already sit in target order, so the first settled
		// position holding a later target offset is the item this drag must
		// land in front of.
		int anchorPosition = -1;
		for (int position = 0; position < size; position++)
		{
			if (settled[position] && permutation[position] > permutation[movePosition])
			{
				anchorPosition = position;
				break;
			}
		}

		// Dropping on a slot to the right of the source lands the item behind
		// that slot's occupant, because removing the source shifts the section
		// left first. Aim one slot earlier so the item lands in front instead.
		int dropPosition;
		if (anchorPosition < 0)
		{
			dropPosition = size - 1;
		}
		else
		{
			dropPosition = movePosition < anchorPosition ? anchorPosition - 1 : anchorPosition;
		}
		if (dropPosition == movePosition || dropPosition < 0 || dropPosition >= size)
		{
			// A no-op drop would mean the item could have joined the longest
			// increasing subsequence. Fail closed rather than advise nothing.
			return null;
		}

		return new Step(targetItems.get(permutation[movePosition]),
			sectionStart + movePosition, sectionStart + dropPosition,
			actualItemIds[sectionStart + dropPosition]);
	}

	/**
	 * Applies one insert drag: removes {@code fromSlot} and reinserts that item
	 * at {@code dropSlot}. Mirrors how the game rearranges the item container.
	 */
	static int[] applyInsert(int[] itemIds, int fromSlot, int dropSlot)
	{
		Objects.requireNonNull(itemIds, "itemIds");
		if (fromSlot < 0 || fromSlot >= itemIds.length
			|| dropSlot < 0 || dropSlot >= itemIds.length)
		{
			throw new IllegalArgumentException("insert slots must be inside the bank");
		}

		int[] result = new int[itemIds.length];
		int moved = itemIds[fromSlot];
		int source = 0;
		for (int slot = 0; slot < itemIds.length; slot++)
		{
			if (slot == dropSlot)
			{
				result[slot] = moved;
				continue;
			}
			if (source == fromSlot)
			{
				source++;
			}
			result[slot] = itemIds[source++];
		}
		return result;
	}

	private static int[] permutation(int[] actualItemIds, int sectionStart,
		List<BankPreviewItem> targetItems)
	{
		return ItemOccurrenceMatcher.orderedTargetOffsets(actualItemIds, sectionStart, targetItems);
	}

	/**
	 * Indices of one longest strictly increasing subsequence, ascending. The
	 * patience construction is deterministic, which keeps a pinned guidance
	 * step stable while only the bank viewport changes.
	 */
	static int[] longestIncreasingSubsequence(int[] values)
	{
		int size = values.length;
		int[] tailIndexByLength = new int[size + 1];
		int[] predecessor = new int[size];
		int length = 0;
		for (int index = 0; index < size; index++)
		{
			int low = 1;
			int high = length;
			while (low <= high)
			{
				int middle = (low + high) >>> 1;
				if (values[tailIndexByLength[middle]] < values[index])
				{
					low = middle + 1;
				}
				else
				{
					high = middle - 1;
				}
			}
			predecessor[index] = low > 1 ? tailIndexByLength[low - 1] : -1;
			tailIndexByLength[low] = index;
			if (low > length)
			{
				length = low;
			}
		}

		int[] indices = new int[length];
		int index = length > 0 ? tailIndexByLength[length] : -1;
		for (int position = length - 1; position >= 0; position--)
		{
			indices[position] = index;
			index = predecessor[index];
		}
		return indices;
	}

	/** One advised insert drag inside a single section. */
	static final class Step
	{
		private final BankPreviewItem item;
		private final int fromSlot;
		private final int dropSlot;
		private final int anchorItemId;

		private Step(BankPreviewItem item, int fromSlot, int dropSlot, int anchorItemId)
		{
			this.item = Objects.requireNonNull(item, "item");
			this.fromSlot = fromSlot;
			this.dropSlot = dropSlot;
			this.anchorItemId = anchorItemId;
		}

		BankPreviewItem getItem()
		{
			return item;
		}

		int getFromSlot()
		{
			return fromSlot;
		}

		/** Slot the player drops on; its current occupant is the anchor. */
		int getDropSlot()
		{
			return dropSlot;
		}

		int getAnchorItemId()
		{
			return anchorItemId;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

import com.pkoka5.ironmanbankarchitect.guide.BankTabPlan.TargetTab;
import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.*;
import java.util.List;





/**
 * Pure tab-aware route planner. It first builds clean category buckets from
 * main in top-to-bottom order, then sorts main and every numbered range using
 * same-section swaps only.
 */
public final class TabRouteAdvisor
{
	public static final int MAX_TABS = 9;

	private TabRouteAdvisor()
	{
	}

	public static Assessment assess(int[] actualItemIds, BankTabPlan plan, int[] tabCounts)
	{
		return assess(actualItemIds, plan, tabCounts, 0);
	}

	/**
	 * @param focusTabNumber 1-based bank tab whose interior sorting should be
	 * served first (the tab the player is currently viewing); 0 for the
	 * default order. Earlier phases (recovery, collapse, create, distribute)
	 * are unaffected because those require the All items view anyway.
	 */
	public static Assessment assess(int[] actualItemIds, BankTabPlan plan, int[] tabCounts,
		int focusTabNumber)
	{
		return assess(actualItemIds, plan, tabCounts, focusTabNumber, RearrangeMode.SWAP);
	}

	/**
	 * @param mode bank rearrange mode the player has selected. Only the sorting
	 * phase differs: swap mode advises same-section exchanges, insert mode
	 * advises same-section drops. Collapse, create, distribute, transfer, and
	 * return-to-main drags behave identically in both modes.
	 */
	public static Assessment assess(int[] actualItemIds, BankTabPlan plan, int[] tabCounts,
		int focusTabNumber, RearrangeMode mode)
	{
		Objects.requireNonNull(actualItemIds, "actualItemIds");
		Objects.requireNonNull(plan, "plan");
		Objects.requireNonNull(tabCounts, "tabCounts");
		Objects.requireNonNull(mode, "mode");

		if (tabCounts.length != MAX_TABS || plan.getNumberedTabs().size() > MAX_TABS)
		{
			return Assessment.blocked(Status.UNSTABLE_BANK, Progress.none(), List.of());
		}

		Validation validation = validateItems(actualItemIds, plan.getFlattenedItems());
		if (validation.status != null)
		{
			return Assessment.blocked(validation.status, Progress.none(),
				validation.duplicateItemIds);
		}

		int currentTabs = leadingTabCount(tabCounts);
		if (currentTabs < 0)
		{
			return Assessment.blocked(Status.UNSTABLE_BANK, Progress.none(), List.of());
		}
		int mainStart = sumLeadingCounts(tabCounts, currentTabs);
		if (mainStart > actualItemIds.length)
		{
			return Assessment.blocked(Status.UNSTABLE_BANK, Progress.none(), List.of());
		}

		List<TargetTab> targets = plan.getNumberedTabs();
		boolean cleanBuckets = isCleanBucketSkeleton(actualItemIds, plan, tabCounts, currentTabs);
		Move tabReorder = cleanBuckets ? null : firstTabReorder(actualItemIds, targets, tabCounts, currentTabs);
		if (tabReorder != null)
			return Assessment.ready(tabReorder, Progress.outsideSorting(Phase.REORDERING, 0, 1));
		Map<Integer, BankPreviewItem> itemById = itemsById(plan.getFlattenedItems());
		Map<Integer, Integer> targetTabByItemId = targetTabsByItemId(targets);
		Move recovery = firstRecoveryMove(actualItemIds, plan, tabCounts, currentTabs,
			itemById, targetTabByItemId);
		if (recovery != null)
		{
			return Assessment.ready(recovery,
				Progress.recovering(foreignItemCount(actualItemIds, targets,
					tabCounts, currentTabs)));
		}
		if (!cleanBuckets)
		{
			if (currentTabs == 0)
			{
				return Assessment.blocked(Status.UNSTABLE_BANK, Progress.none(), List.of());
			}
			TargetTab target = currentTabs <= targets.size() ? targets.get(currentTabs - 1) : null;
			return Assessment.ready(Move.collapseTab(currentTabs, target),
				Progress.repairing(currentTabs));
		}

		if (currentTabs < targets.size())
		{
			TargetTab target = targets.get(currentTabs);
			int sourceSlot = firstMainSourceForItem(actualItemIds, mainStart,
				target.getItems().get(0).getItemId());
			if (sourceSlot < 0)
			{
				sourceSlot = firstMainSourceForTab(actualItemIds, mainStart,
					targetTabByItemId, target.getBankTabNumber());
			}
			if (sourceSlot < 0)
			{
				return Assessment.blocked(Status.UNSTABLE_BANK,
					Progress.creating(currentTabs, targets.size()), List.of());
			}
			return Assessment.ready(Move.dragToNewTab(itemById.get(actualItemIds[sourceSlot]),
				sourceSlot, target), Progress.creating(currentTabs, targets.size()));
		}

		int numberedItemTotal = numberedItemCount(targets);
		Move appendFriendly = nextAppendFriendlyDistribution(actualItemIds, mainStart,
			targets, tabCounts, itemById, mode);
		if (appendFriendly != null)
		{
			return Assessment.ready(appendFriendly,
				Progress.distributing(mainStart, numberedItemTotal));
		}
		for (int slot = mainStart; slot < actualItemIds.length; slot++)
		{
			Integer targetTab = targetTabByItemId.get(actualItemIds[slot]);
			if (targetTab != null)
			{
				TargetTab target = targets.get(targetTab - 1);
				return Assessment.ready(Move.distributeToTab(itemById.get(actualItemIds[slot]),
					slot, target), Progress.distributing(mainStart, numberedItemTotal));
			}
		}

		if (!hasExactSectionMembership(actualItemIds, plan, tabCounts, mainStart))
		{
			return Assessment.blocked(Status.UNSTABLE_BANK,
				Progress.distributing(mainStart, numberedItemTotal), List.of());
		}

		List<BankPreviewItem> effective = plan.effectiveItems(actualItemIds, tabCounts);
		int correctPositions = correctPositionCount(actualItemIds, effective);
		Progress sorting = Progress.sorting(correctPositions, actualItemIds.length, mode,
			estimatedRemainingSwaps(actualItemIds, effective),
			minimumRemainingInserts(actualItemIds, plan, mainStart, effective));
		if (focusTabNumber >= 1 && focusTabNumber <= targets.size())
		{
			int focusStart = 0;
			for (int tabIndex = 0; tabIndex < focusTabNumber - 1; tabIndex++)
			{
				focusStart += targets.get(tabIndex).getItems().size();
			}
			TargetTab focus = targets.get(focusTabNumber - 1);
			Move focusMove = nextSectionMove(mode, actualItemIds, focusStart,
				effective.subList(focusStart, focusStart + focus.getItems().size()),
				focus.getBankTabNumber(), focus.getBlueprintCategoryNumber(),
				focus.getCategoryName());
			if (focusMove != null)
			{
				return Assessment.ready(focusMove, sorting);
			}
		}
		Move mainMove = nextSectionMove(mode, actualItemIds, mainStart,
			effective.subList(mainStart, effective.size()),
			0, 1, plan.getMainCategoryName());
		if (mainMove != null)
		{
			return Assessment.ready(mainMove, sorting);
		}

		int sectionStart = 0;
		for (TargetTab target : targets)
		{
			Move tabMove = nextSectionMove(mode, actualItemIds, sectionStart,
				effective.subList(sectionStart, sectionStart + target.getItems().size()),
				target.getBankTabNumber(), target.getBlueprintCategoryNumber(),
				target.getCategoryName());
			if (tabMove != null)
			{
				return Assessment.ready(tabMove, sorting);
			}
			sectionStart += target.getItems().size();
		}

		return Assessment.blocked(Status.COMPLETE,
			Progress.complete(actualItemIds.length), List.of());
	}

	/** Adjacent header drags have identical results whether the game swaps or inserts tabs. */
	private static Move firstTabReorder(int[] ids, List<TargetTab> targets, int[] counts, int tabs)
	{
		if (tabs < 2) return null;
		List<Map<Integer, Integer>> observed = new ArrayList<>();
		List<Map<Integer, Integer>> planned = new ArrayList<>();
		for (TargetTab target : targets) planned.add(itemCounts(target.getItems()));
		int[] destinations = new int[tabs];
		Set<Integer> matched = new HashSet<>();
		boolean permutation = tabs <= targets.size();
		int start = 0;
		for (int tab = 0; tab < tabs; tab++)
		{
			Map<Integer, Integer> members = sectionCounts(ids, start, start + counts[tab]);
			observed.add(members);
			start += counts[tab];
			int destination = -1;
			for (int target = 0; target < planned.size(); target++)
				if (foreignMembers(members, planned.get(target)) == 0)
				{
					if (destination >= 0) { destination = -1; break; }
					destination = target;
				}
			destinations[tab] = destination;
			permutation &= destination >= 0 && destination < tabs && matched.add(destination);
		}
		while (planned.size() < tabs) planned.add(Collections.emptyMap());
		for (int tab = 0; tab + 1 < tabs; tab++)
		{
			boolean improves = permutation ? destinations[tab] > destinations[tab + 1]
				: (destinations[tab] == tab + 1 || destinations[tab + 1] == tab)
					&& foreignMembers(observed.get(tab), planned.get(tab + 1))
					+ foreignMembers(observed.get(tab + 1), planned.get(tab))
					<= foreignMembers(observed.get(tab), planned.get(tab))
						+ foreignMembers(observed.get(tab + 1), planned.get(tab + 1)) - 2;
			if (improves) return Move.reorderTabs(tab + 1, tab + 2);
		}
		return null;
	}

	private static int foreignMembers(Map<Integer, Integer> observed, Map<Integer, Integer> planned)
	{
		int foreign = 0;
		for (Map.Entry<Integer, Integer> entry : observed.entrySet())
			foreign += Math.max(0, entry.getValue() - planned.getOrDefault(entry.getKey(), 0));
		return foreign;
	}

	static boolean isCleanBucketSkeleton(int[] actualItemIds, BankTabPlan plan,
		int[] tabCounts, int currentTabs)
	{
		List<TargetTab> targets = plan.getNumberedTabs();
		if (currentTabs > targets.size())
		{
			return false;
		}

		int sectionStart = 0;
		for (int tabIndex = 0; tabIndex < currentTabs; tabIndex++)
		{
			int count = tabCounts[tabIndex];
			TargetTab target = targets.get(tabIndex);
			if (count <= 0 || count > target.getItems().size()
				|| sectionStart + count > actualItemIds.length)
			{
				return false;
			}
			Map<Integer, Integer> targetCounts = itemCounts(target.getItems());
			for (int slot = sectionStart; slot < sectionStart + count; slot++)
			{
				if (!decrementItemCount(targetCounts, actualItemIds[slot]))
				{
					return false;
				}
			}
			sectionStart += count;
		}
		return true;
	}

	private static Move firstRecoveryMove(int[] actualItemIds, BankTabPlan plan,
		int[] tabCounts, int currentTabs, Map<Integer, BankPreviewItem> itemById,
		Map<Integer, Integer> targetTabByItemId)
	{
		List<TargetTab> targets = plan.getNumberedTabs();
		int sectionStart = 0;
		for (int sourceIndex = 0; sourceIndex < currentTabs; sourceIndex++)
		{
			int sourceCount = tabCounts[sourceIndex];
			Map<Integer, Integer> sourceTargetCounts = sourceIndex < targets.size()
				? itemCounts(targets.get(sourceIndex).getItems())
				: java.util.Collections.emptyMap();
			for (int slot = sectionStart; slot < sectionStart + sourceCount; slot++)
			{
				int itemId = actualItemIds[slot];
				if (decrementItemCount(sourceTargetCounts, itemId) || sourceCount <= 1)
				{
					continue;
				}
				Integer targetTab = targetTabByItemId.get(itemId);
				BankPreviewItem item = itemById.get(itemId);
				if (targetTab == null)
				{
					return Move.returnToMain(item, slot, sourceIndex + 1,
						plan.getMainCategoryName());
				}
				if (targetTab <= currentTabs)
				{
					return Move.transferToTab(item, slot, sourceIndex + 1,
						targets.get(targetTab - 1));
				}
			}
			sectionStart += sourceCount;
		}
		return null;
	}

	private static int foreignItemCount(int[] actualItemIds, List<TargetTab> targets,
		int[] tabCounts, int currentTabs)
	{
		int foreign = 0;
		int sectionStart = 0;
		for (int tabIndex = 0; tabIndex < currentTabs; tabIndex++)
		{
			Map<Integer, Integer> targetCounts = tabIndex < targets.size()
				? itemCounts(targets.get(tabIndex).getItems())
				: java.util.Collections.emptyMap();
			for (int slot = sectionStart; slot < sectionStart + tabCounts[tabIndex]; slot++)
			{
				if (!decrementItemCount(targetCounts, actualItemIds[slot]))
				{
					foreign++;
				}
			}
			sectionStart += tabCounts[tabIndex];
		}
		return foreign;
	}

	private static boolean hasExactSectionMembership(int[] actualItemIds, BankTabPlan plan,
		int[] tabCounts, int mainStart)
	{
		List<TargetTab> targets = plan.getNumberedTabs();
		int sectionStart = 0;
		for (int tabIndex = 0; tabIndex < targets.size(); tabIndex++)
		{
			TargetTab target = targets.get(tabIndex);
			if (tabCounts[tabIndex] != target.getItems().size()
				|| !sectionCounts(actualItemIds, sectionStart,
					sectionStart + tabCounts[tabIndex]).equals(itemCounts(target.getItems())))
			{
				return false;
			}
			sectionStart += tabCounts[tabIndex];
		}
		return actualItemIds.length - mainStart == plan.getMainItems().size()
			&& sectionCounts(actualItemIds, mainStart, actualItemIds.length)
				.equals(itemCounts(plan.getMainItems()));
	}

	/**
	 * Anchored cycle walk: the first mismatched slot is the fixed pickup anchor.
	 * Each advised swap drags the anchor's occupant to that item's final slot, so
	 * the displaced item lands back on the anchor and the player keeps grabbing
	 * from one unchanged slot until the cycle closes and the anchor becomes
	 * correct. Every swap still fixes at least one slot, so the total stays at
	 * the exact lower bound {@code n - permutation cycles}, but consecutive
	 * pickups no longer jump between interleaved cycles.
	 */
	private static Move nextSectionSwap(int[] actualItemIds, int sectionStart,
		List<BankPreviewItem> targetItems, int targetTab, int blueprintTabNumber,
		String categoryName)
	{
		int[] targetOffsets = ItemOccurrenceMatcher.targetOffsets(actualItemIds,
			sectionStart, targetItems);
		if (targetOffsets == null)
		{
			return null;
		}

		for (int offset = 0; offset < targetItems.size(); offset++)
		{
			int anchorSlot = sectionStart + offset;
			int homeOffset = targetOffsets[offset];
			if (homeOffset == offset)
			{
				continue;
			}
			BankPreviewItem occupant = targetItems.get(homeOffset);
			return Move.swapSection(occupant, anchorSlot, sectionStart + homeOffset,
				targetTab, blueprintTabNumber, categoryName);
		}
		return null;
	}

	private static Move nextSectionMove(RearrangeMode mode, int[] actualItemIds, int sectionStart,
		List<BankPreviewItem> targetItems, int targetTab, int blueprintTabNumber,
		String categoryName)
	{
		if (mode == RearrangeMode.SWAP)
		{
			return nextSectionSwap(actualItemIds, sectionStart, targetItems, targetTab,
				blueprintTabNumber, categoryName);
		}

		SectionInsertPlanner.Step step = SectionInsertPlanner.nextStep(actualItemIds,
			sectionStart, targetItems);
		return step == null ? null
			: Move.insertSection(step.getItem(), step.getFromSlot(), step.getDropSlot(),
				step.getAnchorItemId(), targetTab, blueprintTabNumber, categoryName);
	}

	/**
	 * Exact remaining-insert lower bound for the sorting phase. Counted per
	 * section because an insert may not cross a section boundary, unlike the
	 * swap bound where a permutation cycle never leaves its own section once
	 * membership is exact.
	 */
	private static int minimumRemainingInserts(int[] actualItemIds, BankTabPlan plan,
		int mainStart, List<BankPreviewItem> effective)
	{
		int total = SectionInsertPlanner.minimumRemainingInserts(actualItemIds, mainStart,
			effective.subList(mainStart, effective.size()));
		int sectionStart = 0;
		for (TargetTab target : plan.getNumberedTabs())
		{
			total += SectionInsertPlanner.minimumRemainingInserts(actualItemIds, sectionStart,
				effective.subList(sectionStart, sectionStart + target.getItems().size()));
			sectionStart += target.getItems().size();
		}
		return total;
	}

	private static Move nextAppendFriendlyDistribution(int[] actualItemIds, int mainStart,
		List<TargetTab> targets, int[] tabCounts, Map<Integer, BankPreviewItem> itemById,
		RearrangeMode mode)
	{
		int sectionStart = 0;
		for (TargetTab target : targets)
		{
			int count = tabCounts[target.getBankTabNumber() - 1];
			if (count >= target.getItems().size())
			{
				sectionStart += count;
				continue;
			}
			int appendItemId = mode == RearrangeMode.INSERT || hasRepeatedItemIds(target.getItems())
				? firstMissingTargetItemId(actualItemIds, sectionStart, count, target.getItems())
				: cycleClosingAppendItemId(actualItemIds, sectionStart, count, target.getItems());
			int sourceSlot = firstMainSourceForItem(actualItemIds, mainStart,
				appendItemId);
			if (sourceSlot >= 0)
			{
				return Move.distributeToTab(itemById.get(actualItemIds[sourceSlot]),
					sourceSlot, target);
			}
			sectionStart += count;
		}
		return null;
	}

	private static boolean hasRepeatedItemIds(List<BankPreviewItem> items)
	{
		return itemCounts(items).size() < items.size();
	}

	private static int firstMissingTargetItemId(int[] actualItemIds, int sectionStart,
		int currentCount, List<BankPreviewItem> targetItems)
	{
		Map<Integer, Integer> remainingCounts = itemCounts(targetItems);
		for (int slot = sectionStart; slot < sectionStart + currentCount; slot++)
		{
			remainingCounts.computeIfPresent(actualItemIds[slot],
				(ignored, count) -> count > 1 ? count - 1 : null);
		}
		for (BankPreviewItem targetItem : targetItems)
		{
			if (remainingCounts.getOrDefault(targetItem.getItemId(), 0) > 0)
			{
				return targetItem.getItemId();
			}
		}
		throw new IllegalArgumentException("partial section contains too many planned items");
	}

	/**
	 * Selects the remaining item that maximizes the permutation-cycle count after append.
	 *
	 * <p>If the item expected at the append slot is still in Main, appending it creates a fixed
	 * point. If it is already misplaced in the fixed tab prefix, that prefix contains one open
	 * path ending at the append slot. Following predecessor items back to the path start identifies
	 * the still-unplaced item that closes the whole path into one cycle. Closing every path
	 * independently maximizes cycles and therefore minimizes the later swap count {@code n-cycles}.
	 * No search tree is required.</p>
	 */
	static int cycleClosingAppendItemId(int[] actualItemIds, int sectionStart, int currentCount,
		List<BankPreviewItem> targetItems)
	{
		if (sectionStart < 0 || currentCount < 0
			|| sectionStart + currentCount > actualItemIds.length
			|| currentCount >= targetItems.size())
		{
			throw new IllegalArgumentException("invalid partial section bounds");
		}

		Map<Integer, Integer> prefixPositionByItemId = new HashMap<>();
		for (int position = 0; position < currentCount; position++)
		{
			prefixPositionByItemId.put(actualItemIds[sectionStart + position], position);
		}

		int pathStart = currentCount;
		boolean[] visitedPrefixPositions = new boolean[currentCount];
		while (true)
		{
			int itemId = targetItems.get(pathStart).getItemId();
			Integer predecessor = prefixPositionByItemId.get(itemId);
			if (predecessor == null)
			{
				return itemId;
			}
			if (visitedPrefixPositions[predecessor])
			{
				throw new IllegalArgumentException("partial section does not form an open append path");
			}
			visitedPrefixPositions[predecessor] = true;
			pathStart = predecessor;
		}
	}

	private static Validation validateItems(int[] actualItemIds, List<BankPreviewItem> plannedItems)
	{
		Map<Integer, Integer> plannedCounts = new HashMap<>();
		for (BankPreviewItem item : plannedItems)
		{
			if (item == null || item.isBlank() || item.getItemId() <= 0)
			{
				return Validation.blocked(Status.UNSUPPORTED_PLAN, List.of());
			}
			plannedCounts.merge(item.getItemId(), 1, Integer::sum);
		}

		Map<Integer, Integer> actualCounts = new HashMap<>();
		for (int itemId : actualItemIds)
		{
			if (itemId <= 0)
			{
				return Validation.blocked(Status.UNSTABLE_BANK, List.of());
			}
			actualCounts.merge(itemId, 1, Integer::sum);
		}
		if (actualItemIds.length == plannedItems.size() && actualCounts.equals(plannedCounts))
		{
			return Validation.valid();
		}
		List<Integer> duplicates = ItemOccurrenceMatcher.excessRepeatedItemIds(
			actualCounts, plannedCounts);
		return duplicates.isEmpty()
			? Validation.blocked(Status.RESCAN_REQUIRED, List.of())
			: Validation.blocked(Status.DUPLICATE_ITEMS, duplicates);
	}

	private static Map<Integer, BankPreviewItem> itemsById(List<BankPreviewItem> items)
	{
		Map<Integer, BankPreviewItem> result = new HashMap<>();
		for (BankPreviewItem item : items)
		{
			result.put(item.getItemId(), item);
		}
		return result;
	}

	private static Map<Integer, Integer> targetTabsByItemId(List<TargetTab> targets)
	{
		Map<Integer, Integer> result = new HashMap<>();
		for (TargetTab target : targets)
		{
			for (BankPreviewItem item : target.getItems())
			{
				result.put(item.getItemId(), target.getBankTabNumber());
			}
		}
		return result;
	}

	private static int firstMainSourceForTab(int[] actualItemIds, int mainStart,
		Map<Integer, Integer> targetTabByItemId, int targetTab)
	{
		for (int slot = mainStart; slot < actualItemIds.length; slot++)
		{
			if (Integer.valueOf(targetTab).equals(targetTabByItemId.get(actualItemIds[slot])))
			{
				return slot;
			}
		}
		return -1;
	}

	private static int firstMainSourceForItem(int[] actualItemIds, int mainStart, int itemId)
	{
		for (int slot = mainStart; slot < actualItemIds.length; slot++)
		{
			if (actualItemIds[slot] == itemId)
			{
				return slot;
			}
		}
		return -1;
	}

	/**
	 * Deterministic unrestricted swap estimate. It is exact when item IDs are
	 * unique. With duplicate IDs, another occurrence pairing can require fewer
	 * swaps than this stable pairing.
	 */
	static int estimatedRemainingSwaps(int[] actualItemIds, List<BankPreviewItem> targetItems)
	{
		int[] targetOffsets = ItemOccurrenceMatcher.targetOffsets(actualItemIds, 0, targetItems);
		if (targetOffsets == null)
		{
			throw new IllegalArgumentException("actual and target item occurrences must match");
		}
		boolean[] visited = new boolean[actualItemIds.length];
		int cycles = 0;
		for (int start = 0; start < actualItemIds.length; start++)
		{
			if (visited[start])
			{
				continue;
			}
			cycles++;
			int slot = start;
			while (!visited[slot])
			{
				visited[slot] = true;
				slot = targetOffsets[slot];
			}
		}
		return actualItemIds.length - cycles;
	}

	private static int numberedItemCount(List<TargetTab> targets)
	{
		int count = 0;
		for (TargetTab target : targets)
		{
			count += target.getItems().size();
		}
		return count;
	}

	private static int correctPositionCount(int[] actualItemIds, List<BankPreviewItem> targetItems)
	{
		int correct = 0;
		for (int slot = 0; slot < actualItemIds.length; slot++)
		{
			if (actualItemIds[slot] == targetItems.get(slot).getItemId())
			{
				correct++;
			}
		}
		return correct;
	}

	private static Map<Integer, Integer> itemCounts(List<BankPreviewItem> items)
	{
		Map<Integer, Integer> result = new HashMap<>();
		for (BankPreviewItem item : items)
		{
			result.merge(item.getItemId(), 1, Integer::sum);
		}
		return result;
	}

	private static Map<Integer, Integer> sectionCounts(int[] itemIds, int start, int end)
	{
		Map<Integer, Integer> result = new HashMap<>();
		for (int slot = start; slot < end; slot++)
		{
			result.merge(itemIds[slot], 1, Integer::sum);
		}
		return result;
	}

	private static int leadingTabCount(int[] tabCounts)
	{
		int tabs = 0;
		boolean ended = false;
		for (int count : tabCounts)
		{
			if (count < 0)
			{
				return -1;
			}
			if (count == 0)
			{
				ended = true;
			}
			else if (ended)
			{
				return -1;
			}
			else
			{
				tabs++;
			}
		}
		return tabs;
	}

	private static int sumLeadingCounts(int[] tabCounts, int currentTabs)
	{
		int sum = 0;
		for (int tabIndex = 0; tabIndex < currentTabs; tabIndex++)
		{
			sum += tabCounts[tabIndex];
		}
		return sum;
	}

	/**
	 * Pins one recommendation while only widgets/scrolling change and verifies
	 * the bank transition before advancing.
	 */
	public static final class Session
	{
		private BankTabPlan pinnedPlan;
		private int[] pinnedActualItemIds;
		private int[] pinnedTabCounts;
		private int pinnedFocusTab;
		private Assessment pinnedAssessment;
		private int[] pendingActualItemIds;
		private int[] pendingTabCounts;
		private int pendingSinceTick;
		private int syntheticTick;
		private int focusTabNumber;
		private RearrangeMode mode = RearrangeMode.SWAP;

		public Assessment assess(int[] actualItemIds, BankTabPlan plan, int[] tabCounts)
		{
			return assess(actualItemIds, plan, tabCounts, ++syntheticTick);
		}

		public Assessment assess(int[] actualItemIds, BankTabPlan plan, int[] tabCounts,
			int tickCount)
		{
			return assess(actualItemIds, plan, tabCounts, tickCount, 0);
		}

		public Assessment assess(int[] actualItemIds, BankTabPlan plan, int[] tabCounts,
			int tickCount, int focusTabNumber)
		{
			return assess(actualItemIds, plan, tabCounts, tickCount, focusTabNumber,
				RearrangeMode.SWAP);
		}

		public Assessment assess(int[] actualItemIds, BankTabPlan plan, int[] tabCounts,
			int tickCount, int focusTabNumber, RearrangeMode mode)
		{
			Objects.requireNonNull(actualItemIds, "actualItemIds");
			Objects.requireNonNull(plan, "plan");
			Objects.requireNonNull(tabCounts, "tabCounts");
			Objects.requireNonNull(mode, "mode");

			this.focusTabNumber = focusTabNumber;
			if (pinnedPlan != plan || this.mode != mode)
			{
				// Switching rearrange mode invalidates the pinned advice: the
				// pending drag would be verified against the wrong transform.
				reset();
				pinnedPlan = plan;
				this.mode = mode;
			}
			if (pinnedAssessment != null
				&& Arrays.equals(pinnedActualItemIds, actualItemIds)
				&& Arrays.equals(pinnedTabCounts, tabCounts))
			{
				if (pinnedFocusTab != focusTabNumber)
				{
					// Only the viewed tab changed; the bank itself did not, so
					// recompute directly without transition verification.
					pin(actualItemIds, tabCounts, TabRouteAdvisor.assess(actualItemIds, plan,
						tabCounts, focusTabNumber, mode));
				}
				clearPending();
				return pinnedAssessment;
			}

			if (pinnedAssessment != null)
			{
				if (pinnedAssessment.getStatus() != Status.READY
					|| !transitionMatches(pinnedActualItemIds, pinnedTabCounts,
						actualItemIds, tabCounts, pinnedAssessment.getMove().get()))
				{
					return recoverAlternative(actualItemIds, plan, tabCounts, tickCount);
				}
			}

			pin(actualItemIds, tabCounts, TabRouteAdvisor.assess(actualItemIds, plan, tabCounts,
				focusTabNumber, mode));
			return pinnedAssessment;
		}

		private Assessment recoverAlternative(int[] actualItemIds, BankTabPlan plan,
			int[] tabCounts, int tickCount)
		{
			if (!Arrays.equals(pendingActualItemIds, actualItemIds)
				|| !Arrays.equals(pendingTabCounts, tabCounts))
			{
				pendingActualItemIds = Arrays.copyOf(actualItemIds, actualItemIds.length);
				pendingTabCounts = Arrays.copyOf(tabCounts, tabCounts.length);
				pendingSinceTick = tickCount;
				return Assessment.blocked(Status.WAITING_FOR_BANK,
					pinnedAssessment.getProgress(), List.of());
			}
			if (tickCount <= pendingSinceTick)
			{
				return Assessment.blocked(Status.WAITING_FOR_BANK,
					pinnedAssessment.getProgress(), List.of());
			}
			Assessment alternative = TabRouteAdvisor.assess(actualItemIds, plan, tabCounts,
				focusTabNumber, mode);
			if (isContentsMismatch(alternative))
			{
				// The bank gained or lost an item: a deposit, a withdrawal or a
				// released placeholder. No drag happened that the player could
				// undo, so say the plan is stale. The pinned move stays, so
				// putting the item back resumes it.
				return alternative;
			}
			if (isSafeAlternative(alternative)
				&& (matchesSafeManualTransition(pinnedActualItemIds, pinnedTabCounts,
					actualItemIds, tabCounts, mode)
					|| Arrays.equals(pinnedTabCounts, tabCounts)
						&& changesOnlyKeptOrder(pinnedActualItemIds, actualItemIds, plan, tabCounts)))
			{
				pin(actualItemIds, tabCounts, alternative);
				return alternative;
			}
			return Assessment.blocked(Status.MANUAL_RECOVERY_REQUIRED,
				pinnedAssessment.getProgress(), List.of());
		}

		private static boolean isContentsMismatch(Assessment assessment)
		{
			return assessment.getStatus() == Status.RESCAN_REQUIRED
				|| assessment.getStatus() == Status.DUPLICATE_ITEMS;
		}

		private static boolean isSafeAlternative(Assessment assessment)
		{
			return assessment.getStatus() == Status.COMPLETE
				|| assessment.getStatus() == Status.READY
					&& assessment.getProgress().getPhase() != Phase.REPAIRING;
		}

		private void pin(int[] actualItemIds, int[] tabCounts, Assessment assessment)
		{
			pinnedActualItemIds = Arrays.copyOf(actualItemIds, actualItemIds.length);
			pinnedTabCounts = Arrays.copyOf(tabCounts, tabCounts.length);
			pinnedFocusTab = focusTabNumber;
			pinnedAssessment = assessment;
			clearPending();
		}

		private void clearPending()
		{
			pendingActualItemIds = null;
			pendingTabCounts = null;
			pendingSinceTick = 0;
		}

		public void reset()
		{
			pinnedPlan = null;
			pinnedActualItemIds = null;
			pinnedTabCounts = null;
			pinnedAssessment = null;
			clearPending();
		}
	}

	private static boolean changesOnlyKeptOrder(int[] before, int[] after, BankTabPlan plan, int[] counts)
	{
		if (before.length != after.length) return false;
		List<TargetTab> tabs = plan.getNumberedTabs();
		if (leadingTabCount(counts) != tabs.size()) return false;
		int start = 0;
		for (int index = 0; index <= tabs.size(); index++)
		{
			int end = index < tabs.size() ? start + counts[index] : before.length;
			int destination = index < tabs.size() ? tabs.get(index).getBlueprintCategoryNumber() - 1 : 0;
			if (plan.keepsCurrentOrder(destination))
			{
				if (!sectionCounts(before, start, end).equals(sectionCounts(after, start, end))) return false;
			}
			else for (int slot = start; slot < end; slot++) if (before[slot] != after[slot]) return false;
			start = end;
		}
		return true;
	}

	private static boolean matchesSafeManualTransition(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, RearrangeMode mode)
	{
		if (!sameItemCounts(beforeItems, afterItems)
			|| beforeCounts.length != afterCounts.length
			|| !hasValidSectionBounds(beforeItems, beforeCounts)
			|| !hasValidSectionBounds(afterItems, afterCounts))
		{
			return false;
		}
		int beforeTabs = leadingTabCount(beforeCounts);
		int afterTabs = leadingTabCount(afterCounts);
		if (beforeTabs < 0 || afterTabs < beforeTabs || afterTabs > beforeTabs + 1)
		{
			return false;
		}
		if (afterTabs == beforeTabs + 1)
		{
			return beforeTabs < afterCounts.length && afterCounts[beforeTabs] == 1
				&& matchesCreate(beforeItems, beforeCounts, afterItems, afterCounts,
					afterItems[sumLeadingCounts(afterCounts, beforeTabs)], beforeTabs + 1);
		}
		for (int tab = 1; tab < beforeTabs; tab++)
			if (matchesTabReorder(beforeItems, beforeCounts, afterItems, afterCounts, tab, tab + 1)) return true;

		int increased = -1;
		int decreased = -1;
		for (int index = 0; index < beforeCounts.length; index++)
		{
			int delta = afterCounts[index] - beforeCounts[index];
			if (delta == 1 && increased < 0)
			{
				increased = index;
			}
			else if (delta == -1 && decreased < 0)
			{
				decreased = index;
			}
			else if (delta != 0)
			{
				return false;
			}
		}

		if (increased >= 0 || decreased >= 0)
		{
			int changed = increased >= 0 ? increased : decreased;
			Map<Integer, Integer> before = tabSectionCounts(beforeItems, beforeCounts, changed);
			Map<Integer, Integer> after = tabSectionCounts(afterItems, afterCounts, changed);
			Integer itemId = increased >= 0 ? singleCountDifference(before, after) : singleCountDifference(after, before);
			return itemId != null && matchesTabMove(beforeItems, beforeCounts, afterItems, afterCounts,
				itemId, decreased, increased);
		}
		return mode == RearrangeMode.INSERT
			? matchesAnyInsert(beforeItems, beforeCounts, afterItems)
			: matchesAnySwap(beforeItems, afterItems);
	}

	private static boolean hasValidSectionBounds(int[] items, int[] counts)
	{
		int tabs = leadingTabCount(counts);
		return tabs >= 0 && sumLeadingCounts(counts, tabs) <= items.length;
	}

	private static boolean matchesAnySwap(int[] beforeItems, int[] afterItems)
	{
		int first = -1;
		int second = -1;
		for (int slot = 0; slot < beforeItems.length; slot++)
		{
			if (beforeItems[slot] == afterItems[slot])
			{
				continue;
			}
			if (first < 0)
			{
				first = slot;
			}
			else if (second < 0)
			{
				second = slot;
			}
			else
			{
				return false;
			}
		}
		return first >= 0 && second >= 0
			&& beforeItems[first] == afterItems[second]
			&& beforeItems[second] == afterItems[first];
	}

	/**
	 * Recognises one insert drag: a single item lifted out and dropped back
	 * elsewhere, which rotates every slot in between by one. The rotated window
	 * must stay inside one section, otherwise the drag moved an item between
	 * tabs and the tab counts would have changed.
	 */
	private static boolean matchesAnyInsert(int[] beforeItems, int[] beforeCounts,
		int[] afterItems)
	{
		if (beforeItems.length != afterItems.length)
		{
			return false;
		}
		int first = -1;
		int last = -1;
		for (int slot = 0; slot < beforeItems.length; slot++)
		{
			if (beforeItems[slot] == afterItems[slot])
			{
				continue;
			}
			if (first < 0)
			{
				first = slot;
			}
			last = slot;
		}
		if (first < 0 || !sameSection(beforeCounts, beforeItems.length, first, last))
		{
			return false;
		}
		return Arrays.equals(afterItems, SectionInsertPlanner.applyInsert(beforeItems, first, last))
			|| Arrays.equals(afterItems, SectionInsertPlanner.applyInsert(beforeItems, last, first));
	}

	/** True when both slots fall inside the same tab section or both inside main. */
	private static boolean sameSection(int[] counts, int itemCount, int firstSlot, int lastSlot)
	{
		int tabs = leadingTabCount(counts);
		if (tabs < 0 || firstSlot < 0 || lastSlot >= itemCount)
		{
			return false;
		}
		int sectionStart = 0;
		for (int tabIndex = 0; tabIndex < tabs; tabIndex++)
		{
			int sectionEnd = sectionStart + counts[tabIndex];
			if (firstSlot < sectionEnd)
			{
				return lastSlot < sectionEnd;
			}
			sectionStart = sectionEnd;
		}
		return firstSlot >= sectionStart;
	}

	private static Integer singleCountDifference(Map<Integer, Integer> smaller,
		Map<Integer, Integer> larger)
	{
		Integer changedItemId = null;
		Set<Integer> itemIds = new HashSet<>(smaller.keySet());
		itemIds.addAll(larger.keySet());
		for (int itemId : itemIds)
		{
			int difference = larger.getOrDefault(itemId, 0) - smaller.getOrDefault(itemId, 0);
			if (difference == 1 && changedItemId == null)
			{
				changedItemId = itemId;
			}
			else if (difference != 0)
			{
				return null;
			}
		}
		return changedItemId;
	}

	private static boolean transitionMatches(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, Move move)
	{
		switch (move.getType())
		{
			case REORDER_TAB:
				return matchesTabReorder(beforeItems, beforeCounts, afterItems, afterCounts,
					move.getSourceTab(), move.getTargetTab());
			case COLLAPSE_TAB:
				return matchesCollapse(beforeItems, beforeCounts,
					afterItems, afterCounts, move.getTargetTab());
			case DRAG_TO_NEW_TAB:
				return matchesCreate(beforeItems, beforeCounts,
					afterItems, afterCounts, move.getItemId(), move.getTargetTab());
			case DISTRIBUTE_TO_TAB:
				return matchesTabMove(beforeItems, beforeCounts, afterItems, afterCounts,
					move.getItemId(), -1, move.getTargetTab() - 1);
			case TRANSFER_TO_TAB:
				return move.getSourceTab() > 0 && move.getTargetTab() > 0
					&& matchesTabMove(beforeItems, beforeCounts, afterItems, afterCounts,
						move.getItemId(), move.getSourceTab() - 1, move.getTargetTab() - 1);
			case RETURN_TO_MAIN:
				return move.getSourceTab() > 0 && matchesTabMove(beforeItems, beforeCounts,
					afterItems, afterCounts, move.getItemId(), move.getSourceTab() - 1, -1);
			case SWAP_SECTION:
				return matchesSwap(beforeItems, beforeCounts,
					afterItems, afterCounts, move);
			case INSERT_SECTION:
				return matchesInsert(beforeItems, beforeCounts,
					afterItems, afterCounts, move);
			default:
				return false;
		}
	}

	private static boolean matchesTabReorder(int[] before, int[] counts, int[] after, int[] afterCounts,
		int source, int target)
	{
		int left = Math.min(source, target) - 1;
		if (Math.abs(source - target) != 1 || left < 0 || left + 1 >= counts.length
			|| counts.length != afterCounts.length || before.length != after.length
			|| !hasValidSectionBounds(before, counts) || !hasValidSectionBounds(after, afterCounts)
			|| counts[left] <= 0 || counts[left + 1] <= 0) return false;
		for (int tab = 0; tab < counts.length; tab++)
			if (afterCounts[tab] != counts[tab == left ? left + 1 : tab == left + 1 ? left : tab]) return false;
		int start = sumLeadingCounts(counts, left);
		int middle = start + counts[left];
		int end = middle + counts[left + 1];
		for (int slot = 0; slot < before.length; slot++)
		{
			int oldSlot = slot < start || slot >= end ? slot
				: slot < start + counts[left + 1] ? middle + slot - start : slot - counts[left + 1];
			if (after[slot] != before[oldSlot]) return false;
		}
		return true;
	}

	private static boolean matchesInsert(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, Move move)
	{
		if (!Arrays.equals(beforeCounts, afterCounts)
			|| beforeItems.length != afterItems.length
			|| move.getFromSlot() < 0 || move.getFromSlot() >= beforeItems.length
			|| move.getToSlot() < 0 || move.getToSlot() >= beforeItems.length)
		{
			return false;
		}
		return Arrays.equals(afterItems, SectionInsertPlanner.applyInsert(beforeItems,
			move.getFromSlot(), move.getToSlot()));
	}

	private static boolean matchesCollapse(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, int targetTab)
	{
		int targetIndex = targetTab - 1;
		if (!sameItemCounts(beforeItems, afterItems)
			|| targetIndex < 0 || targetIndex >= beforeCounts.length
			|| beforeCounts.length != afterCounts.length
			|| beforeCounts[targetIndex] <= 0)
		{
			return false;
		}
		int preservedPrefixSize = 0;
		for (int index = 0; index < targetIndex; index++)
		{
			if (afterCounts[index] != beforeCounts[index])
			{
				return false;
			}
			preservedPrefixSize += beforeCounts[index];
		}
		for (int index = targetIndex; index < afterCounts.length; index++)
		{
			if (afterCounts[index] != 0)
			{
				return false;
			}
		}
		for (int slot = 0; slot < preservedPrefixSize; slot++)
		{
			if (beforeItems[slot] != afterItems[slot])
			{
				return false;
			}
		}
		return true;
	}

	private static boolean matchesCreate(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, int itemId, int targetTab)
	{
		int targetIndex = targetTab - 1;
		if (!sameItemCounts(beforeItems, afterItems)
			|| beforeCounts.length != afterCounts.length
			|| targetIndex < 0 || targetIndex >= beforeCounts.length)
		{
			return false;
		}
		for (int index = 0; index < beforeCounts.length; index++)
		{
			int expected = index < targetIndex ? beforeCounts[index]
				: index == targetIndex ? 1 : 0;
			if (afterCounts[index] != expected || index >= targetIndex && beforeCounts[index] != 0)
			{
				return false;
			}
		}
		int afterStart = sumLeadingCounts(afterCounts, targetIndex);
		if (afterItems[afterStart] != itemId)
		{
			return false;
		}
		return lowerSectionsUnchanged(beforeItems, beforeCounts, afterItems, afterCounts,
			targetIndex) && mainLostOnly(beforeItems, beforeCounts, afterItems, afterCounts,
			itemId);
	}

	private static boolean matchesSwap(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, Move move)
	{
		if (!Arrays.equals(beforeCounts, afterCounts)
			|| beforeItems.length != afterItems.length
			|| move.getFromSlot() < 0 || move.getFromSlot() >= beforeItems.length
			|| move.getToSlot() < 0 || move.getToSlot() >= beforeItems.length)
		{
			return false;
		}
		int[] expected = Arrays.copyOf(beforeItems, beforeItems.length);
		int temporary = expected[move.getFromSlot()];
		expected[move.getFromSlot()] = expected[move.getToSlot()];
		expected[move.getToSlot()] = temporary;
		return Arrays.equals(expected, afterItems);
	}

	private static boolean matchesTabMove(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, int itemId, int source, int target)
	{
		int tabs = leadingTabCount(beforeCounts);
		if (!sameItemCounts(beforeItems, afterItems) || beforeCounts.length != afterCounts.length
			|| tabs < 0 || leadingTabCount(afterCounts) != tabs || source < -1 || source >= tabs
			|| target < -1 || target >= tabs || source == target || source >= 0 && beforeCounts[source] <= 1) return false;
		for (int index = 0; index < beforeCounts.length; index++)
			if (afterCounts[index] != beforeCounts[index] + (index == target ? 1 : 0) - (index == source ? 1 : 0)) return false;
		for (int index = 0; index <= tabs; index++)
		{
			Map<Integer, Integer> expected = index == tabs ? mainSectionCounts(beforeItems, beforeCounts)
				: tabSectionCounts(beforeItems, beforeCounts, index);
			if ((index == tabs ? source == -1 : source == index) && !decrementItemCount(expected, itemId)) return false;
			if (index == tabs ? target == -1 : target == index) expected.merge(itemId, 1, Integer::sum);
			Map<Integer, Integer> actual = index == tabs ? mainSectionCounts(afterItems, afterCounts)
				: tabSectionCounts(afterItems, afterCounts, index);
			if (!expected.equals(actual)) return false;
		}
		return true;
	}

	private static boolean lowerSectionsUnchanged(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, int sectionLimit)
	{
		for (int index = 0; index < sectionLimit; index++)
		{
			if (!tabSectionCounts(beforeItems, beforeCounts, index)
				.equals(tabSectionCounts(afterItems, afterCounts, index)))
			{
				return false;
			}
		}
		return true;
	}

	private static boolean mainLostOnly(int[] beforeItems, int[] beforeCounts,
		int[] afterItems, int[] afterCounts, int itemId)
	{
		Map<Integer, Integer> expectedMain = mainSectionCounts(beforeItems, beforeCounts);
		if (!decrementItemCount(expectedMain, itemId))
		{
			return false;
		}
		return expectedMain.equals(mainSectionCounts(afterItems, afterCounts));
	}

	private static Map<Integer, Integer> tabSectionCounts(int[] items, int[] counts, int tabIndex)
	{
		int start = sumLeadingCounts(counts, tabIndex);
		return sectionCounts(items, start, start + counts[tabIndex]);
	}

	private static Map<Integer, Integer> mainSectionCounts(int[] items, int[] counts)
	{
		int tabs = leadingTabCount(counts);
		int start = tabs < 0 ? items.length : sumLeadingCounts(counts, tabs);
		return sectionCounts(items, start, items.length);
	}

	private static boolean decrementItemCount(Map<Integer, Integer> counts, int itemId)
	{
		Integer count = counts.get(itemId);
		if (count == null)
		{
			return false;
		}
		if (count == 1)
		{
			counts.remove(itemId);
		}
		else
		{
			counts.put(itemId, count - 1);
		}
		return true;
	}

	private static boolean sameItemCounts(int[] first, int[] second)
	{
		if (first.length != second.length)
		{
			return false;
		}
		return sectionCounts(first, 0, first.length)
			.equals(sectionCounts(second, 0, second.length));
	}

	public enum Status
	{
		READY,
		COMPLETE,
		RESCAN_REQUIRED,
		DUPLICATE_ITEMS,
		UNSTABLE_BANK,
		UNSUPPORTED_PLAN,
		WAITING_FOR_BANK,
		MANUAL_RECOVERY_REQUIRED,
		MECHANICS_MISMATCH
	}

	public enum Phase
	{
		REORDERING,
		RECOVERING,
		REPAIRING,
		CREATING,
		DISTRIBUTING,
		SORTING,
		COMPLETE
	}

	public enum MoveType
	{
		REORDER_TAB,
		COLLAPSE_TAB,
		DRAG_TO_NEW_TAB,
		DISTRIBUTE_TO_TAB,
		TRANSFER_TO_TAB,
		RETURN_TO_MAIN,
		SWAP_SECTION,
		INSERT_SECTION
	}

	public static final class Move
	{
		private final MoveType type;
		private final int itemId;
		private final String displayName;
		private final int fromSlot;
		private final int toSlot;
		private final int sourceTab;
		private final int targetTab;
		private final int blueprintTabNumber;
		private final String categoryName;
		private final int anchorItemId;

		private Move(MoveType type, int itemId, String displayName, int fromSlot,
			int toSlot, int sourceTab, int targetTab, int blueprintTabNumber,
			String categoryName)
		{
			this(type, itemId, displayName, fromSlot, toSlot, sourceTab, targetTab,
				blueprintTabNumber, categoryName, -1);
		}

		private Move(MoveType type, int itemId, String displayName, int fromSlot,
			int toSlot, int sourceTab, int targetTab, int blueprintTabNumber,
			String categoryName, int anchorItemId)
		{
			this.type = Objects.requireNonNull(type, "type");
			this.itemId = itemId;
			this.displayName = Objects.requireNonNull(displayName, "displayName");
			this.fromSlot = fromSlot;
			this.toSlot = toSlot;
			this.sourceTab = sourceTab;
			this.targetTab = targetTab;
			this.blueprintTabNumber = blueprintTabNumber;
			this.categoryName = Objects.requireNonNull(categoryName, "categoryName");
			this.anchorItemId = anchorItemId;
		}

		private static Move reorderTabs(int source, int target)
		{
			return new Move(MoveType.REORDER_TAB, -1, "Tab " + (source + 1),
				-1, -1, source, target, -1, "");
		}

		private static Move collapseTab(int tabNumber, TargetTab target)
		{
			int blueprintNumber = target == null ? tabNumber + 1
				: target.getBlueprintCategoryNumber();
			String categoryName = target == null ? "" : target.getCategoryName();
