public final class BankBlueprintTextExporter
{
	private static final int BANK_COLUMNS = 8;

	private BankBlueprintTextExporter()
	{
	}

	public static String export(BankOrganizationPreview preview)
	{
		StringBuilder builder = new StringBuilder();
		builder.append("Bank Architect blueprint export\n")
			.append("Preset: ").append(preview.getPreset().getName()).append('\n')
			.append("Columns: ").append(BANK_COLUMNS).append('\n');

		int tabNumber = 1;
		for (BankCategoryPreview category : preview.getCategories())
		{
			builder.append('\n')
				.append("TAB ").append(tabNumber)
				.append(" | placement=").append(tabNumber == 1 ? "MAIN" : "NUMBERED_CANDIDATE")
				.append(" | key=").append(category.getCategory().getKey())
				.append(" | name=").append(category.getCategory().getName())
				.append(" | items=").append(category.getItemCount())
				.append('\n');

			for (int slot = 0; slot < category.getItems().size(); slot++)
			{
				BankPreviewItem item = category.getItems().get(slot);
				int row = slot / BANK_COLUMNS + 1;
				int column = slot % BANK_COLUMNS + 1;
				builder.append("row=").append(row)
					.append(" col=").append(column)
					.append(" slot=").append(slot + 1);

				if (item.isBlank())
				{
					builder.append(" | EMPTY\n");
					continue;
				}

				builder.append(" | id=").append(item.getItemId())
					.append(" | name=").append(item.getDisplayName())
					.append(" | quantity=").append(item.getQuantity())
					.append(" | placeholder=").append(item.isPlaceholder())
					.append(" | catalogCategory=").append(item.getItemCategory())
					.append(" | subcategory=").append(item.getSubcategory());
				if (item.getLayoutTagKey() != null)
				{
					builder.append(" | layoutTag=").append(item.getLayoutTagKey());
				}
				builder.append('\n');
			}

			tabNumber++;
		}

		return builder.toString();
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static com.pkoka5.ironmanbankarchitect.util.TextValidation.requireText;

import java.util.Objects;

public final class BankCategory
{
	private final String key;
	private final String name;
	private final BankCategorySortMode sortMode;

	public BankCategory(String key, String name)
	{
		this(key, name, legacySortMode(key));
	}

	public BankCategory(String key, String name, BankCategorySortMode sortMode)
	{
		this.key = requireText(key, "key");
		this.name = requireText(name, "name");
		this.sortMode = Objects.requireNonNull(sortMode, "sortMode");
	}

	public String getKey()
	{
		return key;
	}

	public String getName()
	{
		return name;
	}

	public BankCategorySortMode getSortMode()
	{
		return sortMode;
	}

	private static BankCategorySortMode legacySortMode(String key)
	{
		if ("currency-utilities".equals(key)) return BankCategorySortMode.CURRENCY;
		if ("teleports-runes".equals(key)) return BankCategorySortMode.TELEPORTS;
		if ("combat-gear".equals(key)) return BankCategorySortMode.GEAR;
		if ("potions-food".equals(key)) return BankCategorySortMode.SUPPLIES;
		if ("farming-herblore".equals(key)) return BankCategorySortMode.HERBLORE;
		if ("herblore".equals(key)) return BankCategorySortMode.HERBLORE;
		if ("seeds-farming".equals(key)) return BankCategorySortMode.FARMING;
		if ("skilling-tools".equals(key)) return BankCategorySortMode.TOOLS;
		if ("resources".equals(key)) return BankCategorySortMode.RESOURCES;
		if ("slayer-boss-loot".equals(key)) return BankCategorySortMode.BOSS_LOOT;
		if ("clues-cosmetics".equals(key)) return BankCategorySortMode.CLUES;
		if ("storage-cleanup".equals(key)) return BankCategorySortMode.REVIEW;
		return BankCategorySortMode.GENERIC;
	}


	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof BankCategory))
		{
			return false;
		}

		BankCategory that = (BankCategory) other;
		return key.equals(that.key) && name.equals(that.name) && sortMode == that.sortMode;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(key, name, sortMode);
	}
}

