package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.catalog.*;
import com.pkoka5.ironmanbankarchitect.organize.layout.ItemSetCatalog;
import java.util.*;
import net.runelite.api.gameval.ItemID;

public final class PresetCategoryMapper
{
	private static final Set<Integer> IRONMAN_RESOURCE_IDS = ids(7936, 24704, 32083, 32085);
	private static final Set<Integer> IRONMAN_RUNECRAFTING_TOOL_IDS = ids(
		5509, 5510, 5511, 5512, 5513, 5514, 5515, 26784, 26786, 5521);
	private static final Set<Integer> IRONMAN_UTILITY_CONTAINER_IDS = ids(19634);
	private static final Set<Integer> IRONMAN_REVIEWED_TOOL_IDS = ids(13392, 25781);
	private static final Set<Integer> IRONMAN_REVIEWED_LOOT_IDS = ids(
		ItemID.TOME_OF_FIRE_UNCHARGED,
		ItemID.TOME_OF_WATER_UNCHARGED,
		ItemID.TOME_OF_EARTH_UNCHARGED);
	private static final Set<Integer> IRONMAN_REVIEWED_CLEANUP_IDS = ids(762, 1588);

	private PresetCategoryMapper()
	{
	}

	public static BankCategory map(BankPreset preset, CatalogItem item)
	{
		return map(preset, item, true);
	}

	/**
	 * Maps with the player's choice about the Frequently Used gathering: when
	 * off, nothing is hoisted to the quick-access main tab and every item
	 * files with its own category.
	 */
	public static BankCategory map(BankPreset preset, CatalogItem item, boolean gatherFrequentlyUsed)
	{
		return preset.getCategory(categoryKey(preset.getType(), item, gatherFrequentlyUsed));
	}

	private static String categoryKey(BankPresetType type, CatalogItem item, boolean gather)
	{
		switch (type)
		{
			case IRONMAN: return mapIronman(item, gather);
			case MAIN: return mapMain(item);
			case PVM:
			case PVP: return mapCombat(item.getCategory(), type == BankPresetType.PVP);
			case SKILLER: return mapSkiller(item);
			default: throw new IllegalArgumentException("Unsupported preset type: " + type);
		}
	}

	private static String mapIronman(CatalogItem item,
		boolean gatherFrequentlyUsed)
	{
		ItemCategory category = item.getCategory();
		if (IRONMAN_RESOURCE_IDS.contains(item.getItemId()))
		{
			return "resources";
		}
		if (IRONMAN_RUNECRAFTING_TOOL_IDS.contains(item.getItemId())
			|| IRONMAN_UTILITY_CONTAINER_IDS.contains(item.getItemId())
			|| IRONMAN_REVIEWED_TOOL_IDS.contains(item.getItemId()))
		{
			return "skilling-tools";
		}
		if (IRONMAN_REVIEWED_LOOT_IDS.contains(item.getItemId()))
		{
			return "slayer-boss-loot";
		}
		if (IRONMAN_REVIEWED_CLEANUP_IDS.contains(item.getItemId()))
		{
			return "storage-cleanup";
		}
		// Frog token redeems cosmetic clothing; spendable activity currencies use Currency.
		if (item.getItemId() == 6183)
		{
			return "clues-cosmetics";
		}
		if (gatherFrequentlyUsed && IronmanMainTabPolicy.belongsOnMain(item))
		{
			return "currency-utilities";
		}
		String setDomain = ItemSetCatalog.domainOf(item.getItemId()).orElse("");
		if ("gear".equals(setDomain))
		{
			return "combat-gear";
		}
		if ("tools".equals(setDomain))
		{
			return "skilling-tools";
		}
		if ("cosmetics".equals(setDomain))
		{
			return "clues-cosmetics";
		}
		if (isRunecraftingFocus(item))
		{
			return "skilling-tools";
		}
		if (isPartialPotionDose(item))
		{
			return "herblore";
		}
		switch (category)
		{
			case CURRENCY:
			case RUNE:
			case TELEPORT: return "currency-utilities";
			case GEAR: return "combat-gear";
			case POTION: return "potions-food";
			case HERBLORE: return "herblore";
			case FARMING:
				return "herb-seed".equals(item.getSubcategory()) ? "herblore" : "seeds-farming";
			case TOOL: return "skilling-tools";
			case SKILLING: return "resources";
			case UNIQUE: return "slayer-boss-loot";
			case CLUE: return "clues-cosmetics";
			default: return "storage-cleanup";
		}
	}

	private static boolean isRunecraftingFocus(CatalogItem item)
	{
		return "runecrafting-focus".equals(item.getSubcategory());
	}

	private static Set<Integer> ids(Integer... itemIds)
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(itemIds)));
	}

	private static boolean isPartialPotionDose(CatalogItem item)
	{
		return ResourceItemSortMetadataCatalog.INSTANCE.findById(item.getItemId())
			.filter(metadata -> metadata.getVariantKind()
				== com.pkoka5.ironmanbankarchitect.catalog.ItemSortMetadata.VariantKind.DOSE)
			.map(metadata -> metadata.getVariantValue() >= 1 && metadata.getVariantValue() <= 3)
			.orElseGet(() -> item.getCategory() == ItemCategory.POTION
				&& (item.getSubcategory().matches("(?:potion-)?dose-[123]")));
	}

	private static boolean isKnownFood(CatalogItem item)
	{
		if ("food".equals(item.getSubcategory()))
		{
			return true;
		}
		return ResourceItemSortMetadataCatalog.INSTANCE.findById(item.getItemId())
			.map(metadata -> metadata.isFood())
			.orElse(false);
	}

	private static String mapMain(CatalogItem item)
	{
		if (item.getItemId() == 27641 || item.getItemId() == 22324 || item.getItemId() == 25734
			|| IRONMAN_REVIEWED_LOOT_IDS.contains(item.getItemId())) return "combat-gear";
		if (item.getItemId() == 9084) return "currency-utilities";
		if (isPartialPotionDose(item)) return "potions-food";
		return mapIronman(item, false);
	}

	private static String mapCombat(ItemCategory category, boolean pvp)
	{
		switch (category)
		{
			case CURRENCY: return pvp ? "coins-risk" : "currency-utilities";
			case TELEPORT: return "teleports-escapes";
			case RUNE: return pvp ? "magic-pk-gear" : "magic-gear";
			case POTION: return pvp ? "food-potions" : "potions-food";
			case GEAR: return pvp ? "melee-pk-gear" : "melee-gear";
			case UNIQUE:
			case CLUE: return pvp ? "loot-keys-review" : "loot-drops";
			case CLEANUP:
			case UNKNOWN:
			case UNCATEGORIZED: return pvp ? "loot-keys-review" : "low-use-review";
			default: return pvp ? "wildy-tools" : "slayer-boss-tools";
		}
	}

	private static String mapSkiller(CatalogItem item)
	{
		switch (item.getCategory())
		{
			case CURRENCY: return "currency-utilities";
			case RUNE:
			case TELEPORT: return "teleports-runes";
			case FARMING: return "farming";
			case POTION: return isKnownFood(item) ? "fishing-cooking" : "herblore-materials";
			case HERBLORE: return "herblore-materials";
			case SKILLING:
			case TOOL: return "tools-outfits-pets";
			default: return "loot-clues-storage";
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsAny;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.normalized;
import com.pkoka5.ironmanbankarchitect.catalog.ItemCategory;
import com.pkoka5.ironmanbankarchitect.organize.layout.ItemSetCatalog;
import java.util.*;
import java.util.List;

public final class PresetItemSorter
{
	private static final int[] IRONMAN_ACTIVITY_REWARD_IDS = {
		6183, 6529, 6306, 12012, 25527, 21555
	};
	private PresetItemSorter()
	{
	}

	public static List<BankPreviewItem> sort(BankCategory category, List<BankPreviewItem> items)
	{
		return sort(category, items, GearStatsSource.NONE);
	}

	public static List<BankPreviewItem> sort(BankCategory category, List<BankPreviewItem> items,
		GearStatsSource gearStats)
	{
		switch (category.getSortMode())
		{
			case MAIN:
				return IronmanMainItemSorter.sort(items);
			case GEAR:
				return GearItemSorter.layout(items, gearStats);
			case CURRENCY:
				return CurrencyItemSorter.sort(items);
			case SUPPLIES:
				return SupplyItemSorter.sort(items);
			case HERBLORE:
				return HerbloreItemSorter.layout(items);
			case FARMING:
				return FarmingItemSorter.layout(items, 0);
			case TELEPORTS:
				return TeleportItemSorter.sort(items);
			case CLUES:
				return sortClues(items);
			case TOOLS:
				return ToolItemSorter.sort(items);
			case RESOURCES:
				return ResourceItemSorter.sort(items);
			case BOSS_LOOT:
				return sortBossLoot(items);
			case REVIEW:
				return sortReview(items);
			case GENERIC:
			default:
				return sortGeneric(category, items);
		}
	}

	private static List<BankPreviewItem> sortGeneric(BankCategory category, List<BankPreviewItem> items)
	{
		List<BankPreviewItem> sorted = new ArrayList<>(items);
		sorted.sort(Comparator
			.comparingInt((BankPreviewItem item) -> subgroupRank(category.getKey(), item))
			.thenComparing(item -> normalized(item.getDisplayName()))
			.thenComparingInt(BankPreviewItem::getItemId));
		return sorted;
	}

	private static List<BankPreviewItem> sortClues(List<BankPreviewItem> items)
	{
		List<BankPreviewItem> sorted = new ArrayList<>(items);
		sorted.sort(Comparator
			.comparingInt(PresetItemSorter::clueRank)
			.thenComparingInt(item -> ItemSetCatalog.cosmeticFamilyRankOf(item.getItemId()))
			.thenComparing(PresetItemSorter::clueFamily)
			.thenComparing(item -> normalized(item.getDisplayName()))
			.thenComparingInt(BankPreviewItem::getItemId));
		return sorted;
	}

	/**
	 * Keeps a cosmetic family adjacent where plain alphabetical order would
	 * scatter it. Recoloured cosmetics lead with their colour word, so sorting
	 * them by name alone files each partyhat or dye next to whatever else
	 * shares its colour instead of next to the rest of its family. Families
	 * come from the set catalogue by exact ID, so a lookalike name such as the
	 * plain wig disguise never rides along with the real partyhats.
	 */
	private static String clueFamily(BankPreviewItem item)
	{
		return ItemSetCatalog.cosmeticFamilyOf(item.getItemId())
			.map(value -> normalized(value))
			.orElseGet(() -> normalized(item.getDisplayName()));
	}

	private static List<BankPreviewItem> sortBossLoot(List<BankPreviewItem> items)
	{
		List<BankPreviewItem> sorted = new ArrayList<>(items);
		sorted.sort(Comparator
			.comparingInt(PresetItemSorter::bossLootRank)
			.thenComparing(PresetItemSorter::bossLootFamily)
			.thenComparing(item -> normalized(item.getDisplayName()))
			.thenComparingInt(BankPreviewItem::getItemId));
		return sorted;
	}

	private static List<BankPreviewItem> sortReview(List<BankPreviewItem> items)
	{
		List<BankPreviewItem> sorted = new ArrayList<>(items);
		sorted.sort(Comparator
			.comparingInt(ReviewItemSorter::rank)
			.thenComparing(item -> normalized(item.getDisplayName()))
			.thenComparingInt(BankPreviewItem::getItemId));
		return sorted;
	}

	static int subgroupRank(String categoryKey, BankPreviewItem item)
	{
		String name = normalized(item.getDisplayName());
		String subcategory = normalized(item.getSubcategory());

		if ("currency-utilities".equals(categoryKey))
		{
			return rank(name, subcategory,
				group(0, "coins", "tokkul", "numulite", "trading sticks", "stardust", "nugget", "pearl"),
				group(10, "mark of grace", "castle wars ticket", "pieces of eight"),
				group(20, "blessing", "banner", "hilt"),
				group(30, "key", "token"));
		}

		if ("teleports-runes".equals(categoryKey))
		{
			if (item.getItemCategory() == ItemCategory.RUNE || containsAny(name, " rune", "rune ", "essence"))
			{
				return 0;
			}
			return rank(name, subcategory,
				group(10, "tablet", "teletab", "teleport"),
				group(20, "ring of", "games necklace", "amulet of", "skills necklace", "combat bracelet",
					"necklace of passage", "burning amulet"),
				group(30, "talisman", "ectophial", "medallion", "book of the dead", "whistle"));
		}

		if ("combat-gear".equals(categoryKey))
		{
			return GearItemSorter.rank(item);
		}

		if ("potions-food".equals(categoryKey))
		{
			return rank(name, subcategory,
				group(0, "brew", "restore", "prayer potion", "stamina", "super combat",
					"ranging potion", "magic potion", "attack", "strength", "defence", "holy wrench"),
				group(30, "shark", "monkfish", "karambwan", "manta", "anglerfish", "lobster",
					"swordfish", "tuna", "salmon", "trout", "pizza", "pie", "potato", "cake"),
				group(60, "wine", "stew", "curry", "kebab", "fruit", "stout", "mind bomb",
					"lizardkicker"));
		}

		if ("farming-herblore".equals(categoryKey))
		{
			return herbloreSpilloverRank(item);
		}

		if ("resources".equals(categoryKey))
		{
			return rank(name, subcategory,
				group(0, "ore", "coal"),
				group(10, "bar"),
				group(20, "log", "plank"),
				group(30, "hide", "leather", "dragonhide"),
				group(40, "gem", "uncut"),
				group(50, "bone", "bones", "ash"),
				group(60, "vial", "orb", "glass", "sand", "clay"),
				group(70, "feather", "nail", "flax", "bow string"));
		}

		if ("storage-cleanup".equals(categoryKey))
		{
			return ReviewItemSorter.rank(item);
		}

		return 50;
	}

	static int herbloreSpilloverRank(BankPreviewItem item)
	{
		String name = normalized(item.getDisplayName());
		String subcategory = normalized(item.getSubcategory());
		return rank(name, subcategory,
			group(0, "seed", "sapling"),
			group(10, "grimy", "clean", "herb", "leaf"),
			group(20, "secondary", "eye of newt", "snape grass", "limpwurt", "white berries",
				"mort myre", "unicorn horn"),
			group(30, "unf", "unfinished"),
			group(40, "potion"));
	}

	public static String subgroupLabel(BankCategory category, BankPreviewItem item)
	{
		if (category.getSortMode() != BankCategorySortMode.REVIEW)
		{
			return "";
		}

		return ReviewItemSorter.label(item);
	}

	private static int rank(String name, String subcategory, Group... groups)
	{
		for (Group group : groups)
		{
			for (String needle : group.needles)
			{
				if (name.contains(needle))
				{
					return group.rank;
				}
			}
		}

		return 50;
	}

	private static Group group(int rank, String... needles)
	{
		return new Group(rank, needles);
	}

	private static int clueRank(BankPreviewItem item)
	{
		String name = normalized(item.getDisplayName());
		String[] order = {"beginner", "easy", "medium", "hard", "elite", "master"};
		for (int i = 0; i < order.length; i++)
		{
			if (name.contains("(" + order[i] + ")"))
			{
				return i;
			}
		}
		if (isIronmanActivityReward(item.getItemId())) return 10;
		return 20;
	}

	private static boolean isIronmanActivityReward(int itemId)
	{
		for (int candidate : IRONMAN_ACTIVITY_REWARD_IDS)
		{
			if (candidate == itemId) return true;
		}
		return false;
	}

	private static int bossLootRank(BankPreviewItem item)
	{
		if (item.getItemCategory() == ItemCategory.UNIQUE)
		{
			String subcategory = normalized(item.getSubcategory());
			if (subcategory.contains("weapon-upgrade")) return 0;
			if (subcategory.contains("equipment-upgrade")) return 10;
			if (subcategory.contains("charge")) return 20;
			return 30;
		}
		if (item.getItemCategory() == ItemCategory.GEAR)
		{
			return 100;
		}
		return 50;
	}

	private static String bossLootFamily(BankPreviewItem item)
	{
		String name = normalized(item.getDisplayName());
		if (name.contains("crystal weapon seed")) return "crystal-weapon-seed";
		if (name.endsWith(" page")) return "charge-page";
		return name;
	}

	private static final class Group
	{
		private final int rank;
		private final String[] needles;

		private Group(int rank, String[] needles)
		{
			this.rank = rank;
			this.needles = needles;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsAny;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsWord;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.normalized;
import com.pkoka5.ironmanbankarchitect.catalog.*;
import java.util.*;
import java.util.List;



/**
 * Keeps resource workflows dense and deterministic. The primary
 * {@link ResourceSkillZone} is the first sort key; the existing
 * workflow/family/stage ordering is preserved inside each zone. Name checks
 * deliberately use complete suffixes/tokens so items such as bark, barb-tailed
 * kebbit and smashed mirrors cannot leak into bar or ash blocks.
 */
final class ResourceItemSorter
{
	private static final int METAL = 0;
	private static final int WOOD = 10;
	private static final int HIDE = 20;
	private static final int GEM = 30;
	private static final int PRAYER = 40;
	private static final int GLASS = 50;
	private static final int ASH = 60;
	private static final int AMMO_COMPONENT = 70;
	private static final int RAW_FOOD = 80;
	private static final int COOKING = 90;
	private static final int TEXTILE = 100;
	private static final int CONSTRUCTION = 110;
	private static final int TROLL_SALT = 120;
	private static final int FOSSIL = 121;
	private static final int VALUABLE_RESOURCE = 122;
	private static final int OTHER = 130;
	private static final Map<String, Integer> WORKFLOW_FAMILY_RANKS = workflowFamilyRanks();

	private ResourceItemSorter()
	{
	}

	static List<BankPreviewItem> sort(List<BankPreviewItem> items)
	{
		List<BankPreviewItem> sorted = new ArrayList<>(items);
		sorted.sort(Comparator
			.comparingInt((BankPreviewItem item) -> ResourceSkillZoneClassifier.classify(item).ordinal())
			.thenComparingInt(ResourceItemSorter::roleRank)
			.thenComparingInt(ResourceItemSorter::processRank)
			.thenComparingInt(ResourceItemSorter::familyRank)
			.thenComparingInt(ResourceItemSorter::stageRank)
			.thenComparing(item -> normalized(item.getDisplayName()))
			.thenComparingInt(BankPreviewItem::getItemId));
		return sorted;
	}

	private static int processRank(BankPreviewItem item)
	{
		if (isSawmillCoupon(item)) return 2;
		String name = normalized(item.getDisplayName());
		String subcategory = normalized(item.getSubcategory());
		if (isSailingMetal(name)) return 2;
		if (isMiningResource(name)) return 3;

		Optional<ItemSortMetadata> metadata = ResourceItemSortMetadataCatalog.INSTANCE.findById(item.getItemId())
			.filter(value -> value.getVariantKind() == ItemSortMetadata.VariantKind.WORKFLOW_STAGE);
		if (metadata.isPresent())
		{
			String family = metadata.get().getFamilyKey();
			if (family.startsWith("metal.")) return family.equals("metal.bars") ? 1 : 0;
			if (family.startsWith("wood."))
			{
				if (family.equals("wood.planks")) return 1;
				return isStandardLog(name) || family.equals("wood.logs.normal") ? 0 : 2;
			}
			if (family.startsWith("gem.")) return metadata.get().getVariantValue();
		}

		if (isMetal(name)) return name.endsWith(" bar") ? 1 : 0;
		if (isWood(name))
		{
			if (name.equals("plank") || name.endsWith(" plank")) return 1;
			return isStandardLog(name) ? 0 : 2;
		}
		if (subcategory.contains("jewellery")) return 2;
		if (isGem(name)) return name.startsWith("uncut ") ? 0 : 1;
		return 0;
	}

	private static int roleRank(BankPreviewItem item)
	{
		if (isSawmillCoupon(item)) return WOOD;
		Optional<ItemSortMetadata> metadata = resourceWorkflowMetadata(item);
		if (metadata.isPresent())
		{
			String family = metadata.get().getFamilyKey();
			if (family.startsWith("metal.")) return METAL;
			if (family.equals("fletching.ballista-assembly")) return AMMO_COMPONENT;
			return GEM;
		}

		String name = normalized(item.getDisplayName());
		String subcategory = normalized(item.getSubcategory());
		if (isMetal(name)) return METAL;
		if (isMiningResource(name)) return METAL;
		if (isWood(name)) return WOOD;
		if (containsAny(name, "hide", "leather") || name.endsWith(" fur")) return HIDE;
		if (subcategory.contains("ammo-component")) return AMMO_COMPONENT;
		if (subcategory.contains("gem") || subcategory.contains("jewellery") || isGem(name)) return GEM;
		if (subcategory.contains("prayer") || containsWord(name, "bone")
			|| containsWord(name, "bones") || containsWord(name, "remains")) return PRAYER;
		if (isGlassMaterial(name, subcategory)) return GLASS;
		if (name.endsWith(" ash") || name.endsWith(" ashes")) return ASH;
		if (subcategory.contains("raw-food") || name.startsWith("raw ")
			|| name.startsWith("leaping ")) return RAW_FOOD;
		if (isFishingResource(name)) return RAW_FOOD;
		if (subcategory.contains("cooking")) return COOKING;
		if (isTextile(name, subcategory)) return TEXTILE;
		if (subcategory.contains("construction") || isConstructionMaterial(name)) return CONSTRUCTION;
		if (isTrollSalt(name)) return TROLL_SALT;
		if (isFossil(name)) return FOSSIL;
		if (subcategory.contains("resource")) return VALUABLE_RESOURCE;
		return OTHER;
	}

	private static int familyRank(BankPreviewItem item)
	{
		if (isSawmillCoupon(item)) return 2000;
		Optional<ItemSortMetadata> metadata = resourceWorkflowMetadata(item);
		if (metadata.isPresent())
		{
			return WORKFLOW_FAMILY_RANKS.get(metadata.get().getFamilyKey());
		}

		String name = normalized(item.getDisplayName());
		switch (roleRank(item))
		{
			case METAL:
				return metalRank(name);
			case WOOD:
				return woodRank(name);
			case HIDE:
				return hideRank(name);
			case GEM:
				return gemRank(name);
			case PRAYER:
				return prayerRank(name);
			case RAW_FOOD:
				return foodRank(name);
			case TEXTILE:
				return textileRank(name);
			case CONSTRUCTION:
				return constructionRank(name);
			default:
				return 100;
		}
	}

	private static int stageRank(BankPreviewItem item)
	{
		Optional<ItemSortMetadata> metadata = resourceWorkflowMetadata(item);
		if (metadata.isPresent())
		{
			return metadata.get().getVariantValue();
		}

		String name = normalized(item.getDisplayName());
		switch (roleRank(item))
		{
			case METAL:
				if (name.endsWith(" ore")) return name.startsWith("tin ") ? 1 : 0;
				if (name.equals("coal")) return 1;
				if (name.startsWith("steel ")) return 3;
				return 2;
			case WOOD:
				return name.equals("plank") || name.endsWith(" plank") ? 1 : 0;
			case HIDE:
				return name.contains("leather") ? 1 : 0;
			case GEM:
				return name.startsWith("uncut ") ? 0 : 1;
			case GLASS:
				if (containsAny(name, "seaweed")) return 0;
				if (name.equals("soda ash")) return 1;
				if (name.contains("sand")) return 2;
				if (name.contains("molten glass")) return 3;
				return 4;
			case AMMO_COMPONENT:
				if (name.contains("shaft")) return 0;
				if (name.equals("feather")) return 1;
				if (name.contains("headless")) return 2;
				if (containsAny(name, ClassificationNames.group(63))) return 3;
				return 4;
			case TEXTILE:
				if (name.equals("flax")) return 0;
				if (name.contains("string")) return 1;
				if (name.equals("thread")) return 2;
				return 3;
			default:
				return 0;
		}
	}

	private static Optional<ItemSortMetadata> resourceWorkflowMetadata(BankPreviewItem item)
	{
		return ResourceItemSortMetadataCatalog.INSTANCE.findById(item.getItemId())
			.filter(metadata -> metadata.getVariantKind() == ItemSortMetadata.VariantKind.WORKFLOW_STAGE)
			.filter(metadata -> WORKFLOW_FAMILY_RANKS.containsKey(metadata.getFamilyKey()));
	}

	private static boolean isSawmillCoupon(BankPreviewItem item)
	{
		return item.getItemId() == 32083 || item.getItemId() == 32085;
	}

	private static Map<String, Integer> workflowFamilyRanks()
	{
		Map<String, Integer> ranks = new LinkedHashMap<>();
		ranks.put("metal.ores-base", 0);
		ranks.put("metal.ores-tier", 10);
		ranks.put("metal.bars", 20);
		ranks.put("gem.sapphire", 40);
		ranks.put("gem.emerald", 50);
		ranks.put("gem.ruby", 60);
		ranks.put("gem.diamond", 70);
		ranks.put("gem.dragonstone", 80);
		ranks.put("fletching.ballista-assembly", 10);
		return Collections.unmodifiableMap(ranks);
	}

	static boolean isMetal(String name)
	{
		return name.equals("coal") || name.endsWith(" ore")
			|| (name.endsWith(" bar") && !name.equals("chocolate bar"));
	}

	static boolean isWood(String name)
	{
		return name.equals("logs") || name.endsWith(" logs") || name.equals("plank")
			|| name.endsWith(" plank") || name.endsWith(" bark");
	}

	private static boolean isStandardLog(String name)
	{
		return name.equals("logs") || name.equals("oak logs") || name.equals("teak logs")
			|| name.equals("maple logs") || name.equals("mahogany logs")
			|| name.equals("yew logs") || name.equals("magic logs")
			|| name.equals("redwood logs");
	}

	private static boolean isSailingMetal(String name)
	{
		return name.contains("nickel ore") || name.contains("cupronickel bar");
	}

	static boolean isGlassMaterial(String name, String subcategory)
	{
		return subcategory.contains("glass") || name.equals("seaweed") || name.equals("giant seaweed")
			|| name.equals("soda ash") || name.contains("molten glass") || name.contains("bucket of sand")
			|| name.contains("lantern lens") || name.equals("vial") || name.equals("vial of water")
			|| name.contains("unpowered orb");
	}

	static boolean isTextile(String name, String subcategory)
	{
		return subcategory.contains("textile") || name.equals("flax") || name.equals("thread")
			|| name.equals("ball of wool") || name.contains("bolt of cloth")
			|| name.contains("bolt of canvas") || name.contains("bolt of linen");
	}

	static boolean isConstructionMaterial(String name)
	{
		return name.endsWith(" nails") || name.equals("clay") || name.equals("soft clay")
			|| name.contains("limestone") || name.equals("curved bone") || name.equals("long bone");
	}

	static boolean isMiningResource(String name)
	{
		return name.equals("volcanic ash") || name.equals("basalt") || name.equals("calcite")
			|| name.equals("pyrophosphite") || name.equals("dynamite")
			|| name.equals("saltpetre");
	}

	static boolean isFishingResource(String name)
	{
		return name.equals("spirit flakes") || name.equals("fish offcuts")
			|| name.equals("fishing bait");
	}

	static boolean isHunterResource(String name, String subcategory)
	{
		return subcategory.contains("hunter-resource") || name.equals("sunlight antelope antler")
			|| name.equals("pheasant tail feathers");
	}

	static boolean isSailingResource(String name)
	{
		return name.equals("large mahogany hull parts") || name.equals("repair kit")
			|| name.equals("teak repair kit");
	}

	private static boolean isTrollSalt(String name)
	{
		return name.equals("efh salt") || name.equals("te salt") || name.equals("urt salt");
	}

	private static boolean isFossil(String name)
	{
		return name.equals("unidentified small fossil")
			|| name.equals("unidentified medium fossil");
	}

	private static int prayerRank(String name)
	{
		if (name.contains("bone shard")) return 0;
		if (containsWord(name, "bone") || containsWord(name, "bones")) return 10;
		if (name.startsWith("ensouled ")) return 20;
		if (containsWord(name, "remains")) return 30;
		if (name.endsWith(" ash") || name.endsWith(" ashes")) return 40;
		if (name.contains("bird's egg")) return 50;
		return 45;
	}

	private static int metalRank(String name)
	{
		if (containsAny(name, ClassificationNames.group(64))) return 0;
		if (containsAny(name, "blurite")) return 5;
		if (containsAny(name, ClassificationNames.group(65))) return 10;
		if (name.contains("silver")) return 20;
		if (name.contains("gold")) return 30;
		if (name.contains("mithril")) return 40;
		if (name.contains("adamant")) return 50;
		if (containsAny(name, "runite", "rune ")) return 60;
		if (containsAny(name, "cupronickel", "nickel")) return 70;
		return 100;
	}

	private static int woodRank(String name)
	{
		if (name.equals("logs") || name.equals("plank")) return 0;
		String[] species = ClassificationNames.group(72);
		return orderedMatch(name, species);
	}

	private static int hideRank(String name)
	{
		String[] types = ClassificationNames.group(73);
		return orderedMatch(name, types);
	}

	private static int gemRank(String name)
	{
		String[] gems = ClassificationNames.group(74);
		return orderedMatch(name, gems);
	}

	private static int foodRank(String name)
	{
		if (name.contains("leaping trout")) return 200;
		if (name.contains("leaping salmon")) return 210;
		if (name.contains("leaping sturgeon")) return 220;
		String[] food = ClassificationNames.group(75);
		return orderedMatch(name, food);
	}

	private static int textileRank(String name)
	{
		if (containsAny(name, "flax", "bow string")) return 0;
		if (name.contains("wool")) return 10;
		if (name.equals("thread")) return 20;
		if (name.contains("canvas")) return 30;
		if (name.contains("cloth")) return 40;
		if (name.contains("linen")) return 50;
		return 100;
	}

	private static int constructionRank(String name)
	{
		if (name.endsWith(" nails")) return metalRank(name);
		if (name.contains("clay")) return 80;
		if (name.contains("limestone")) return 90;
		return 100;
	}

	private static int orderedMatch(String name, String[] values)
	{
		for (int i = 0; i < values.length; i++)
		{
			if (name.contains(values[i])) return (i + 1) * 10;
		}
		return 1000;
	}

	static boolean isGem(String name)
	{
		return containsAny(name, ClassificationNames.group(66));
	}

}

package com.pkoka5.ironmanbankarchitect.organize;

import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsAny;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsWord;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.normalized;
import com.pkoka5.ironmanbankarchitect.catalog.*;
import java.util.Optional;

/**
 * Assigns every bank item exactly one primary {@link ResourceSkillZone}.
 *
	 * <p>Curated metadata families decide first ({@code metal.*}, {@code wood.*}, {@code gem.*},
	 * {@code fletching.*});
 * narrow subcategory facts and the existing complete-suffix/token name rules follow. Secondary
 * skill use never moves an item: logs and planks stay Woodcutting, bars stay Mining/Smithing,
 * gems and glass stay Crafting, arrow and bow components stay Fletching, and nails stay
 * Construction. Bow and crossbow strings are exact Fletching components and are claimed before
 * the generic textile rule.</p>
 */
final class ResourceSkillZoneClassifier
{
	private ResourceSkillZoneClassifier()
	{
	}

	static ResourceSkillZone classify(BankPreviewItem item)
	{
		if (item.getItemId() == 32083 || item.getItemId() == 32085)
		{
			return ResourceSkillZone.WOODCUTTING;
		}
		if (item.getItemId() == 7936 || item.getItemId() == 24704)
		{
			return ResourceSkillZone.OTHER_RESOURCE;
		}
		Optional<ItemSortMetadata> metadata =
			ResourceItemSortMetadataCatalog.INSTANCE.findById(item.getItemId());
		if (metadata.isPresent())
		{
			String familyKey = metadata.get().getFamilyKey();
			if (familyKey.startsWith("metal."))
			{
				return ResourceSkillZone.MINING_SMITHING;
			}
			if (familyKey.startsWith("wood."))
			{
				return ResourceSkillZone.WOODCUTTING;
			}
			if (familyKey.startsWith("gem."))
			{
				return ResourceSkillZone.CRAFTING;
			}
			if (familyKey.startsWith("fletching."))
			{
				return ResourceSkillZone.FLETCHING;
			}
		}

		String name = normalized(item.getDisplayName());
		String subcategory = normalized(item.getSubcategory());

		if (ResourceItemSorter.isMiningResource(name))
		{
			return ResourceSkillZone.MINING_SMITHING;
		}
		if (ResourceItemSorter.isFishingResource(name))
		{
			return ResourceSkillZone.FISHING_COOKING;
		}
		if (ResourceItemSorter.isHunterResource(name, subcategory))
		{
			return ResourceSkillZone.HUNTER;
		}
		if (ResourceItemSorter.isSailingResource(name))
		{
			return ResourceSkillZone.SAILING;
		}
		if (subcategory.contains("ammo-component") || isExactFletchingString(name))
		{
			return ResourceSkillZone.FLETCHING;
		}
		if (subcategory.contains("construction") || ResourceItemSorter.isConstructionMaterial(name))
		{
			return ResourceSkillZone.CONSTRUCTION;
		}
		if (subcategory.contains("gem") || subcategory.contains("jewellery")
			|| subcategory.contains("glass-material") || subcategory.contains("crafting-material")
			|| subcategory.contains("textile"))
		{
			return ResourceSkillZone.CRAFTING;
		}
		if (ResourceItemSorter.isMetal(name))
		{
			return ResourceSkillZone.MINING_SMITHING;
		}
		if (ResourceItemSorter.isWood(name))
		{
			return ResourceSkillZone.WOODCUTTING;
		}
		if (containsAny(name, "hide", "leather") || name.endsWith(" fur")
			|| ResourceItemSorter.isGem(name)
			|| ResourceItemSorter.isGlassMaterial(name, subcategory)
			|| ResourceItemSorter.isTextile(name, subcategory))
		{
			return ResourceSkillZone.CRAFTING;
		}
		if (subcategory.contains("prayer") || containsWord(name, "bone")
			|| containsWord(name, "bones")
			|| containsWord(name, "remains")
			|| name.equals("ashes")
			|| (!name.equals("volcanic ash") && (name.endsWith(" ash") || name.endsWith(" ashes"))))
		{
			return ResourceSkillZone.PRAYER;
		}
		if (subcategory.contains("raw-food") || subcategory.contains("cooking")
			|| name.startsWith("raw ") || name.startsWith("leaping "))
		{
			return ResourceSkillZone.FISHING_COOKING;
		}
		return ResourceSkillZone.OTHER_RESOURCE;
	}

	private static boolean isExactFletchingString(String name)
	{
		return name.equals("bow string") || name.equals("crossbow string");
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static com.pkoka5.ironmanbankarchitect.util.NameMatching.normalized;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsWord;
import com.pkoka5.ironmanbankarchitect.catalog.ItemCategory;

final class ReviewItemSorter
{
	private ReviewItemSorter()
	{
	}

	static int rank(BankPreviewItem item)
	{
		if (item.getItemCategory() == ItemCategory.UNKNOWN)
		{
			return 90;
		}
		if ("quest-item".equals(item.getSubcategory()))
		{
			// Wiki-confirmed quest items go straight to the quest lane, no
			// name guessing needed.
			return 30;
		}

		String name = normalized(item.getDisplayName());
		return rankByName(name,
			group(0, "seed vault", "costume room", "poh", "stash", "armour case", "magic wardrobe",
				"treasure chest", "toy box", "cape rack"),
			group(10, "clue", "casket"),
			group(20, "graceful", "pyromancer", "prospector", "angler", "rogue", "lumberjack",
				"farmer's", "carpenter", "costume", "cosmetic", "mask", "gown", "robe top",
				"robe bottom"),
			group(30, "quest", "key", "greegree", "notes", "letter", "book", "scroll", "manual",
				"certificate", "sample", "specimen", "plaque", "report", "tome", "binding book"),
			group(40, "christmas", "easter", "halloween", "holiday", "santa", "partyhat", "pumpkin",
				"snow", "event"),
			group(50, "burnt", "beer glass", "junk", "old boot", "buttons", "broken", "empty"),
			group(60, "bronze", "iron", "steel", "black", "mithril", "adamant", "rune"));
	}

	static String label(BankPreviewItem item)
	{
		int rank = rank(item);
		if (rank == 0)
		{
			return "External Storage";
		}
		if (rank == 10)
		{
			return "Clue & STASH";
		}
		if (rank == 20)
		{
			return "Cosmetics & Collection";
		}
		if (rank == 30)
		{
			return "Quest Leftovers";
		}
		if (rank == 40)
		{
			return "Holiday & Event";
		}
		if (rank == 50)
		{
			return "Burnt & Junk";
		}
		if (rank == 60)
		{
			return "Redundant Gear Review";
		}
		if (rank == 90)
		{
			return "Unknown Safe Review";
		}

		return "General Review";
	}

	private static int rankByName(String name, Group... groups)
	{
		for (Group group : groups)
		{
			for (String needle : group.needles)
			{
				if (matches(name, needle))
				{
					return group.rank;
				}
			}
		}

		return 70;
	}

	private static boolean matches(String name, String needle)
	{
		return "key".equals(needle) ? containsWord(name, needle) : name.contains(needle);
	}

	private static Group group(int rank, String... needles)
	{
		return new Group(rank, needles);
	}

	private static final class Group
	{
		private final int rank;
		private final String[] needles;

		private Group(int rank, String[] needles)
		{
			this.rank = rank;
			this.needles = needles;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

/**
 * How runes order among themselves.
 *
 * <p>{@link #ALPHABETICAL} is the shipped behaviour. {@link #ELEMENTAL} is
 * the canonical sequence players know from spellbooks and shops: air, water,
 * earth, fire, then mind, body, cosmic, chaos, nature, law, death, blood,
 * soul, astral, wrath, with anything unrecognized following alphabetically.</p>
 */
public enum RuneOrder
{
	ALPHABETICAL("Alphabetical"),
	ELEMENTAL("Elemental");

	private final String label;

	RuneOrder(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsAny;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.normalized;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.numericSuffix;
import com.pkoka5.ironmanbankarchitect.catalog.*;
import java.util.*;
import java.util.List;


final class SupplyItemSorter
{
	private SupplyItemSorter()
	{
	}

	static List<BankPreviewItem> sort(List<BankPreviewItem> items)
	{
		return sort(items, ResourceItemSortMetadataCatalog.INSTANCE);
	}

	static List<BankPreviewItem> sort(List<BankPreviewItem> items, ItemSortMetadataCatalog metadataCatalog)
	{
		return sort(items, metadataCatalog, PotionDoseOrder.GRAB_AREA);
	}

	static List<BankPreviewItem> sort(List<BankPreviewItem> items,
		ItemSortMetadataCatalog metadataCatalog, PotionDoseOrder doseOrder)
	{
		List<BankPreviewItem> sorted = new ArrayList<>(items);
		sorted.sort(Comparator
			.comparingInt((BankPreviewItem item) -> doseOrder == PotionDoseOrder.BY_FAMILY
				? byFamilyRoleRank(item, metadataCatalog) : roleRank(item, metadataCatalog))
			.thenComparingInt(item -> doseMetadataRank(item, metadataCatalog))
			.thenComparingInt(item -> foodMetadataRank(item, metadataCatalog))
			.thenComparingInt(item -> -immediateHealMax(item, metadataCatalog))
			.thenComparingInt(item -> -immediateHealMin(item, metadataCatalog))
			.thenComparingInt(item -> foodRoleRank(item, metadataCatalog))
			.thenComparing(item -> familyName(item, metadataCatalog))
			.thenComparingInt(item -> areaRestrictionRank(item, metadataCatalog))
			.thenComparingInt(item -> variantRank(item, metadataCatalog))
			.thenComparing(item -> normalized(item.getDisplayName()))
			.thenComparingInt(BankPreviewItem::getItemId));
		return sorted;
	}

	/**
	 * Under the by-family order every dose counts as its potion, so the
	 * family keys further down the comparator run each potion 4 to 1 in one
	 * place instead of trailing the partials as a to-decant pile.
	 */
	private static int byFamilyRoleRank(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		String subcategory = normalized(item.getSubcategory());
		if (subcategory.startsWith("potion-dose-") || subcategory.startsWith("dose-"))
		{
			return 0;
		}
		return roleRank(item, metadataCatalog);
	}

	private static int roleRank(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		String name = normalized(item.getDisplayName());
		String subcategory = normalized(item.getSubcategory());
		if (doseMetadata(item, metadataCatalog).isPresent()) return 0;
		if (subcategory.equals("potion-dose-4") || subcategory.equals("dose-4")) return 0;
		if (subcategory.contains("pvm-utility")) return 10;
		if (foodMetadata(item, metadataCatalog).isPresent()) return 30;
		if (subcategory.contains("food") || isFoodName(name)) return 30;
		if (subcategory.contains("drink")) return 40;
		if (subcategory.contains("potion") || name.contains(" mix")) return 20;
		return 50;
	}

	private static int doseMetadataRank(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		if (roleRank(item, metadataCatalog) != 0)
		{
			return 0;
		}
		return doseMetadata(item, metadataCatalog).isPresent() ? 0 : 1;
	}

	private static int foodMetadataRank(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		if (roleRank(item, metadataCatalog) != 30)
		{
			return 0;
		}
		return foodMetadata(item, metadataCatalog).isPresent() ? 0 : 1;
	}

	private static int foodRoleRank(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		Optional<ItemSortMetadata> metadata = foodMetadata(item, metadataCatalog);
		if (!metadata.isPresent()) return 100;
		switch (metadata.get().getFoodRole())
		{
			case STANDARD:
				return 0;
			case COMBO:
				return 10;
			case DELAYED:
				return 20;
			case MULTI_BITE:
				return 30;
			case NONE:
			default:
				return 100;
		}
	}

	private static int immediateHealMax(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		return foodMetadata(item, metadataCatalog)
			.map(ItemSortMetadata::getImmediateHealMax)
			.orElse(0);
	}

	private static int immediateHealMin(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		return foodMetadata(item, metadataCatalog)
			.map(ItemSortMetadata::getImmediateHealMin)
			.orElse(0);
	}

	private static String familyName(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		Optional<ItemSortMetadata> metadata = sortMetadata(item, metadataCatalog);
		if (metadata.isPresent()) return metadata.get().getFamilyKey();

		String name = normalized(item.getDisplayName());
		if (name.startsWith("half a ")) name = name.substring("half a ".length());
		if (name.startsWith("1/2 ")) name = name.substring("1/2 ".length());
		return name.replaceFirst("\\s*\\([1-4]\\)$", "");
	}

	private static int areaRestrictionRank(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		return sortMetadata(item, metadataCatalog)
			.map(metadata -> metadata.getAreaRestriction() == ItemSortMetadata.AreaRestriction.NONE ? 0 : 1)
			.orElse(0);
	}

	private static int variantRank(BankPreviewItem item, ItemSortMetadataCatalog metadataCatalog)
	{
		Optional<ItemSortMetadata> metadata = sortMetadata(item, metadataCatalog);
		if (metadata.isPresent() && metadata.get().getVariantKind() != ItemSortMetadata.VariantKind.NONE)
		{
			return -metadata.get().getVariantValue();
		}

		String name = normalized(item.getDisplayName());
		if (name.startsWith("half a ") || name.startsWith("1/2 ")) return 1;
		return 10 - numericSuffix(name, 10);
	}

	private static Optional<ItemSortMetadata> foodMetadata(BankPreviewItem item,
		ItemSortMetadataCatalog metadataCatalog)
	{
		return sortMetadata(item, metadataCatalog).filter(ItemSortMetadata::isFood);
	}

	private static Optional<ItemSortMetadata> doseMetadata(BankPreviewItem item,
		ItemSortMetadataCatalog metadataCatalog)
	{
		return sortMetadata(item, metadataCatalog)
			.filter(metadata -> metadata.getVariantKind() == ItemSortMetadata.VariantKind.DOSE)
			.filter(metadata -> !metadata.isFood());
	}

	private static Optional<ItemSortMetadata> sortMetadata(BankPreviewItem item,
		ItemSortMetadataCatalog metadataCatalog)
	{
		return metadataCatalog.findById(item.getItemId());
	}

	private static boolean isFoodName(String name)
	{
		return containsAny(name, ClassificationNames.group(67));
	}

}

package com.pkoka5.ironmanbankarchitect.organize;

/**
 * How a category lays its items onto the tab.
 *
 * <p>{@link #PACKED} is the shipped behaviour: families stay whole as
 * rectangles and rows are completed, at the price of a run of singles
 * sometimes being interrupted. {@link #SEQUENTIAL} keeps the sorter's order
 * and simply wraps row by row: adjacent kinds stay adjacent, and a charge set
 * may break across a row boundary instead.</p>
 */
public enum TabOrder
{
	PACKED("Grid"),
	SEQUENTIAL("List");

	private final String label;

	TabOrder(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static com.pkoka5.ironmanbankarchitect.util.NameMatching.containsAny;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.normalized;
import static com.pkoka5.ironmanbankarchitect.util.NameMatching.numericSuffix;
import com.pkoka5.ironmanbankarchitect.catalog.*;
import java.util.*;
import java.util.List;


final class TeleportItemSorter
{
	private static final Comparator<BankPreviewItem> TELEPORT_ORDER = Comparator
		.comparingInt(TeleportItemSorter::roleRank)
		.thenComparingInt(TeleportItemSorter::runeRank)
		.thenComparingInt(TeleportItemSorter::pouchRank)
		.thenComparing(TeleportItemSorter::familyName)
		.thenComparingInt(item -> -charge(item))
		.thenComparing(item -> normalized(item.getDisplayName()))
		.thenComparingInt(BankPreviewItem::getItemId);

	private TeleportItemSorter()
	{
	}

	static List<BankPreviewItem> sort(List<BankPreviewItem> items)
	{
		List<BankPreviewItem> sorted = new ArrayList<>(items);
		sorted.sort(TELEPORT_ORDER);
		return sorted;
	}

	static int compareTeleportItems(BankPreviewItem left, BankPreviewItem right)
	{
		return TELEPORT_ORDER.compare(left, right);
	}

	private static int roleRank(BankPreviewItem item)
	{
		String name = normalized(item.getDisplayName());
		String subcategory = normalized(item.getSubcategory());
		if (item.getItemCategory() == ItemCategory.RUNE)
		{
			if (name.contains("essence"))
			{
				return 10;
			}
			if (subcategory.contains("focus")) return 20;
			if (isEssencePouch(name)) return 21;
			if (name.equals("rune pouch")) return 22;
			if (subcategory.contains("container")) return 22;
			if (subcategory.contains("utility")) return 23;
			return 0;
		}
		if (subcategory.contains("transport-access"))
		{
			return 90;
		}
		if (subcategory.contains("teleport-charge") || name.contains("crystal teleport seed"))
		{
			return 80;
		}
		if (isReusableDevice(name))
		{
			return 30;
		}
		if (isJewellery(item)) return 40;
		if (subcategory.contains("teleport-container")) return 50;
		if (isTablet(item)) return 60;
		if (isScroll(item)) return 70;
		return 85;
	}

	private static int runeRank(BankPreviewItem item)
	{
		int role = roleRank(item);
		if (role != 0 && role != 20)
		{
			return 100;
		}
		String name = normalized(item.getDisplayName());
		String[] order = {"air", "water", "earth", "fire", "mind", "body", "cosmic", "chaos",
			"nature", "law", "death", "blood", "soul", "astral", "wrath"};
		for (int i = 0; i < order.length; i++)
		{
			if ((role == 0 && name.equals(order[i] + " rune"))
				|| (role == 20 && name.startsWith(order[i] + " ")))
			{
				return i;
			}
		}
		return 90;
	}

	private static int pouchRank(BankPreviewItem item)
	{
		if (roleRank(item) != 21) return 100;
		String name = normalized(item.getDisplayName());
		String[] order = {"small", "medium", "large", "giant", "colossal"};
		for (int i = 0; i < order.length; i++)
		{
			if (name.startsWith(order[i] + " pouch")) return i;
		}
		return 90;
	}

	private static boolean isEssencePouch(String name)
	{
		return containsAny(name, "small pouch", "medium pouch", "large pouch", "giant pouch",
			"colossal pouch");
	}

	private static boolean isJewellery(BankPreviewItem item)
	{
		Optional<ItemSortMetadata> metadata = teleportJewelleryMetadata(item);
		if (metadata.isPresent()) return true;
		String name = normalized(item.getDisplayName());
		return containsAny(name, "ring of dueling", "games necklace", "amulet of glory",
			"skills necklace", "combat bracelet", "burning amulet", "necklace of passage",
			"digsite pendant", "ring of wealth", "slayer ring", "ring of returning",
			"ring of the elements", "ring of shadows", "camulet", "desert amulet",
			"giantsoul amulet", "sailors' amulet");
	}

	private static String familyName(BankPreviewItem item)
	{
		Optional<ItemSortMetadata> metadata = teleportJewelleryMetadata(item);
		if (metadata.isPresent()) return metadata.get().getFamilyKey();
		String name = normalized(item.getDisplayName());
		return name.replaceFirst("\\s*\\([0-9]+\\)$", "");
	}

	private static int charge(BankPreviewItem item)
	{
		Optional<ItemSortMetadata> metadata = teleportJewelleryMetadata(item);
		if (metadata.isPresent()) return metadata.get().getVariantValue();
		String name = normalized(item.getDisplayName());
		return numericSuffix(name, -1);
	}

	private static Optional<ItemSortMetadata> teleportJewelleryMetadata(BankPreviewItem item)
	{
		return ResourceItemSortMetadataCatalog.INSTANCE.findById(item.getItemId())
			.filter(metadata -> metadata.getVariantKind() == ItemSortMetadata.VariantKind.CHARGE)
			.filter(metadata -> metadata.getFamilyKey().startsWith("jewellery."));
	}

	private static boolean isReusableDevice(String name)
	{
		return containsAny(name, "ectophial", "xeric's talisman", "drakan's medallion",
			"royal seed pod", "enchanted lyre", "pharaoh's sceptre", "chronicle",
			"kharedst's memoirs", "book of the dead", "teleport crystal",
			"quetzal whistle", "pendant of ates", "skull sceptre");
	}

	private static boolean isTablet(BankPreviewItem item)
	{
		String subcategory = normalized(item.getSubcategory());
		String name = normalized(item.getDisplayName());
		return subcategory.contains("teleport-tablet") || name.contains("tablet")
			|| name.contains("teletab");
	}

	private static boolean isScroll(BankPreviewItem item)
	{
		String subcategory = normalized(item.getSubcategory());
		String name = normalized(item.getDisplayName());
		return subcategory.contains("teleport-scroll") || name.contains("teleport scroll");
	}

}

