package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * Breaks equal LayoutScores using canonical block vectors, component by component: all identities,
 * then width ranks, widths, primitives, origins and row geometry, then the final item-ID vector.
 * Never compares entire blocks sequentially or collapses geometry to scalars. Fallback uses no
 * blocks. Independent of map/insertion order.
 */
public final class DeterministicTieKey implements Comparable<DeterministicTieKey>
{
	private final List<PlacedBlock> blocks;
	private final List<Integer> finalTargetOrderItemIds;

	public DeterministicTieKey(List<PlacedBlock> blocks, List<Integer> finalTargetOrderItemIds)
	{
		this.blocks = requireBlocks(blocks);
		this.finalTargetOrderItemIds = requireItemIds(finalTargetOrderItemIds);
		validateBlockItems(this.blocks, this.finalTargetOrderItemIds);
	}

	public List<PlacedBlock> getBlocks()
	{
		return blocks;
	}

	public List<Integer> getFinalTargetOrderItemIds()
	{
		return finalTargetOrderItemIds;
	}

	@Override
	public int compareTo(DeterministicTieKey other)
	{
		Objects.requireNonNull(other, "other");

		int result = LayoutOrdering.compareBlockVectors(blocks, other.blocks);
		return result != 0 ? result
			: LayoutOrdering.compareValues(finalTargetOrderItemIds, other.finalTargetOrderItemIds);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof DeterministicTieKey))
		{
			return false;
		}

		DeterministicTieKey key = (DeterministicTieKey) other;
		return blocks.equals(key.blocks) && finalTargetOrderItemIds.equals(key.finalTargetOrderItemIds);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(blocks, finalTargetOrderItemIds);
	}

	@Override
	public String toString()
	{
		return "DeterministicTieKey{blocks=" + blocks + ", finalOrder=" + finalTargetOrderItemIds + "}";
	}

	private static List<PlacedBlock> requireBlocks(List<PlacedBlock> blocks)
	{
		Objects.requireNonNull(blocks, "blocks");
		List<PlacedBlock> canonical = new ArrayList<>(blocks.size());
		for (PlacedBlock block : blocks)
		{
			canonical.add(Objects.requireNonNull(block, "blocks must not contain null"));
		}
		canonical.sort(LayoutOrdering.IDENTITY);
		for (int index = 1; index < canonical.size(); index++)
		{
			if (LayoutOrdering.IDENTITY.compare(canonical.get(index - 1), canonical.get(index)) == 0)
			{
				throw new IllegalArgumentException("blocks must not contain duplicate stable block identity "
					+ canonical.get(index).getRuleKey() + "/" + canonical.get(index).getAtomKeys());
			}
		}

		return Collections.unmodifiableList(canonical);
	}

	private static List<Integer> requireItemIds(List<Integer> itemIds)
	{
		Objects.requireNonNull(itemIds, "finalTargetOrderItemIds");

		Set<Integer> seen = new HashSet<>();
		List<Integer> validated = new ArrayList<>(itemIds.size());
		for (Integer itemId : itemIds)
		{
			if (itemId == null || itemId <= 0)
			{
				throw new IllegalArgumentException("finalTargetOrderItemIds must contain positive item IDs");
			}
			if (itemId == ItemID.BANK_FILLER)
			{
				throw new IllegalArgumentException("finalTargetOrderItemIds must not contain Bank Filler");
			}
			if (!seen.add(itemId))
			{
				throw new IllegalArgumentException("finalTargetOrderItemIds must not contain duplicate item ID "
					+ itemId);
			}
			validated.add(itemId);
		}

		return Collections.unmodifiableList(validated);
	}

	private static void validateBlockItems(List<PlacedBlock> blocks, List<Integer> finalItemIds)
	{
		Set<Integer> finalItems = new HashSet<>(finalItemIds);
		Set<Integer> seenBlockItems = new HashSet<>();
		for (PlacedBlock block : blocks)
		{
			for (LayoutCandidate.Row row : block.getRows())
			{
				for (Integer itemId : row.getItemIds())
				{
					if (!finalItems.contains(itemId))
					{
						throw new IllegalArgumentException("block item " + itemId
							+ " is absent from finalTargetOrderItemIds");
					}
					if (!seenBlockItems.add(itemId))
					{
						throw new IllegalArgumentException("item " + itemId + " appears in more than one block");
					}
				}
			}
		}
	}

}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.catalog.*;
import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.*;
import java.util.List;




/** Exact combat families whose reviewed equipment order is vertical outside the primary setups. */
public final class GearSetSemanticRuleSet
{

	/**
	 * Every curated gear set's item IDs in slot order, for layouts that read a
	 * set as one run. Sets keep the catalog's order.
	 */
	public static java.util.List<java.util.List<Integer>> gearSetsInSlotOrder()
	{
		java.util.List<java.util.List<Integer>> sets = new java.util.ArrayList<>();
		for (ItemSetCatalog.SetDefinition set : ItemSetCatalog.sets("gear"))
		{
			sets.add(set.getItemIds());
		}
		return sets;
	}

	public static boolean isCannonPart(int itemId)
	{
		return ItemSetCatalog.setKeyOf(itemId).orElse("").startsWith("gear.dwarf-cannon");
	}

	private static final OrderedItemFamilies TABLE = new OrderedItemFamilies(
		GearSetSemanticRuleSet.class.getResourceAsStream(
			"/com/pkoka5/ironmanbankarchitect/catalog/gear-layout-families.tsv"), 0);
	private static final RequiredResource<List<ItemSetCatalog.SetDefinition>> SETS =
		new RequiredResource<>("gear layout", GearSetSemanticRuleSet::buildSets);

	private GearSetSemanticRuleSet()
	{
	}

	public static LayoutRequest forEntries(List<LayoutEntry> entries)
	{
		return forEntries(entries, Integer.MAX_VALUE);
	}

	/**
	 * Builds the vertical-set request for the physically available gear-tail height. A set that
	 * lost a primary BIS member may otherwise be one item taller than the dense tail. When its
	 * owned remainder forms an exact rectangle, keep the equipment order in adjacent vertical
	 * columns instead of abandoning the family to dense fallback.
	 */
	public static LayoutRequest forEntries(List<LayoutEntry> entries, int maxVerticalHeight)
	{
		Objects.requireNonNull(entries, "entries");
		if (maxVerticalHeight < 1)
		{
			throw new IllegalArgumentException("maxVerticalHeight must be positive");
		}

		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			present.add(entry.getItem().getItemId());
		}

		List<ItemSetCatalog.SetDefinition> verticalDefinitions = new ArrayList<>();
		List<SemanticRule> rules = new ArrayList<>();
		Map<Integer, Integer> cannonTargets = new LinkedHashMap<>();
		for (ItemSetCatalog.SetDefinition definition : SETS.get())
		{
			List<Integer> owned = new ArrayList<>();
			for (Integer itemId : definition.getItemIds())
			{
				if (present.contains(itemId))
				{
					owned.add(itemId);
				}
			}
			if (definition.getKey().startsWith("gear.dwarf-cannon"))
			{
				for (int itemId : owned) cannonTargets.put(itemId, cannonTargets.size());
				continue;
			}

			SemanticRule compact = owned.size() > maxVerticalHeight
				? compactRectangleRule(definition.getKey(), owned, maxVerticalHeight) : null;
			if (compact == null)
			{
				verticalDefinitions.add(definition);
			}
			else
			{
				rules.add(compact);
			}
		}

		SemanticRule rule = VerticalItemSetRuleFactory.build(
			"gear.vertical-sets", entries, verticalDefinitions);
		if (rule != null)
		{
			rules.add(rule);
		}
		List<LayoutEntry> anchored = new ArrayList<>(entries.size());
		for (LayoutEntry entry : entries)
		{
			Integer target = cannonTargets.get(entry.getItem().getItemId());
			anchored.add(target == null ? entry : entry.withLockedTarget(target));
		}
		return new LayoutRequest(anchored, rules);
	}

	private static SemanticRule compactRectangleRule(String setKey, List<Integer> owned,
		int maxVerticalHeight)
	{
		int columns = 2;
		while (columns <= SemanticRule.MAX_WIDTH
			&& (owned.size() % columns != 0 || owned.size() / columns > maxVerticalHeight))
		{
			columns++;
		}
		if (columns > SemanticRule.MAX_WIDTH)
		{
			return null;
		}

		int rows = owned.size() / columns;
		List<SemanticAtom> atoms = new ArrayList<>(rows);
		for (int row = 0; row < rows; row++)
		{
			List<SemanticAtom.Member> members = new ArrayList<>(columns);
			for (int column = 0; column < columns; column++)
			{
				members.add(new SemanticAtom.Member("column-" + column,
					owned.get(column * rows + row)));
			}
			atoms.add(new SemanticAtom("row-" + row, members));
		}
		return SemanticRule.builder()
			.ruleKey("gear.compact." + setKey)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.ROW_GROUP_MATRIX)
			.allowedWidths(Collections.singleton(columns))
			.build();
	}

	/**
	 * Returns real owned members of eligible vertical families. The gear setup planner uses this
	 * exact-ID set to keep non-primary family members out of arbitrary row-filler cells.
	 */
	public static Set<Integer> presentFamilyItemIds(List<BankPreviewItem> items)
	{
		return ownedFamilySizeByItemId(items).keySet();
	}

	/**
	 * How many members of its own family the player owns, per owned family member. An item in no
	 * eligible family is absent. The gear setup planner uses this to break a tie between equally
	 * tiered candidates for a primary cell: a piece of a family the player actually holds wins
	 * over a loose item of the same tier, so owning a set cannot cost you its body row.
	 */
	public static Map<Integer, Integer> ownedFamilySizeByItemId(List<BankPreviewItem> items)
	{
		Objects.requireNonNull(items, "items");
		Set<Integer> present = new LinkedHashSet<>();
		for (BankPreviewItem item : items)
		{
			present.add(item.getItemId());
		}

		Map<Integer, Integer> sizeByItemId = new LinkedHashMap<>();
		for (ItemSetCatalog.SetDefinition set : SETS.get())
		{
			List<Integer> owned = new ArrayList<>();
			for (int itemId : set.getItemIds())
			{
				if (present.contains(itemId))
				{
					owned.add(itemId);
				}
			}
			if (owned.size() < 2)
			{
				continue;
			}
			// An item can sit in more than one family; the largest one it is
			// actually part of is the one worth keeping whole.
			for (int itemId : owned)
			{
				sizeByItemId.merge(itemId, owned.size(), Math::max);
			}
		}
		return Collections.unmodifiableMap(sizeByItemId);
	}

	private static List<ItemSetCatalog.SetDefinition> buildSets()
	{
		List<ItemSetCatalog.SetDefinition> sets = new ArrayList<>();
		TABLE.entries().forEach((key, ids) -> sets.add(ItemSetCatalog.definition("gear", key, key, ids)));

		Set<Integer> reserved = new LinkedHashSet<>();
		for (ItemSetCatalog.SetDefinition set : sets) reserved.addAll(set.getItemIds());
		for (ItemSetCatalog.SetDefinition definition : ItemSetCatalog.sets("gear"))
		{
			if (Collections.disjoint(reserved, definition.getItemIds()))
			{
				reserved.addAll(definition.getItemIds());
				sets.add(ItemSetCatalog.definition("gear", definition.getKey(), definition.getKey(), definition.getItemIds()));
			}
		}
		return Collections.unmodifiableList(sets);
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.catalog.RequiredResource;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.List;




/** Exact-ID set dictionary compiled from the reviewed user-supplied master workbook. */
public final class ItemSetCatalog
{
	private static final String RESOURCE_PATH =
		"/com/pkoka5/ironmanbankarchitect/organize/item-set-catalog.tsv";
	private static final String SCHEMA_HEADER = "# schema=1";
	private static final String COSMETIC_FAMILY_DOMAIN = "cosmetic-family";
	private static final RequiredResource<Map<String, List<SetDefinition>>> SETS_BY_DOMAIN =
		new RequiredResource<>("item set", () -> load(ItemSetCatalog.class.getResourceAsStream(RESOURCE_PATH)));
	private static final RequiredResource<Map<Integer, String>> DOMAIN_BY_ITEM_ID =
		new RequiredResource<>("item set", ItemSetCatalog::indexDomains);
	private static final RequiredResource<Map<Integer, String>> COSMETIC_FAMILY_BY_ITEM_ID =
		new RequiredResource<>("item set", ItemSetCatalog::indexCosmeticFamilies);
	private static final RequiredResource<Map<Integer, Integer>> COSMETIC_FAMILY_RANK_BY_ITEM_ID =
		new RequiredResource<>("item set", ItemSetCatalog::indexCosmeticFamilyRanks);
	private static final RequiredResource<Map<Integer, SetDefinition>> SET_BY_ITEM_ID =
		new RequiredResource<>("item set", ItemSetCatalog::indexSets);

	public static void requireAvailable()
	{
		DOMAIN_BY_ITEM_ID.get();
	}

	private ItemSetCatalog()
	{
	}

	/**
	 * The name of the colour family the item belongs to, if any. Recoloured
	 * cosmetics lead with a colour word, so a sorter that files them by name
	 * scatters each family; this lookup lets it file them by what they are.
	 */
	public static Optional<String> cosmeticFamilyOf(int itemId)
	{
		return Optional.ofNullable(COSMETIC_FAMILY_BY_ITEM_ID.get().get(itemId));
	}

	/**
	 * Where the item's colour family stands in the catalogue's declaration
	 * order, which is the curated display order: showpieces first, materials
	 * last. Items outside every family rank after all of them.
	 */
	public static int cosmeticFamilyRankOf(int itemId)
	{
		Integer rank = COSMETIC_FAMILY_RANK_BY_ITEM_ID.get().get(itemId);
		return rank == null ? Integer.MAX_VALUE : rank;
	}

	/** The catalogued set key the item belongs to, across every domain. */
	public static Optional<String> setKeyOf(int itemId)
	{
		SetDefinition definition = SET_BY_ITEM_ID.get().get(itemId);
		return definition == null ? Optional.empty() : Optional.of(definition.key);
	}

	/** The catalogued set's display name for the item, across every domain. */
	public static Optional<String> setNameOf(int itemId)
	{
		SetDefinition definition = SET_BY_ITEM_ID.get().get(itemId);
		return definition == null ? Optional.empty() : Optional.of(definition.name);
	}

	private static Map<Integer, SetDefinition> indexSets()
	{
		Map<Integer, SetDefinition> byId = new LinkedHashMap<>();
		for (List<SetDefinition> domain : SETS_BY_DOMAIN.get().values())
		{
			for (SetDefinition definition : domain)
			{
				for (Integer itemId : definition.itemIds)
				{
					byId.put(itemId, definition);
				}
			}
		}
		return Collections.unmodifiableMap(byId);
	}

	private static Map<Integer, String> indexCosmeticFamilies()
	{
		Map<Integer, String> families = new LinkedHashMap<>();
		for (SetDefinition definition : sets(COSMETIC_FAMILY_DOMAIN))
		{
			for (Integer itemId : definition.itemIds)
			{
				families.put(itemId, definition.name);
			}
		}
		return Collections.unmodifiableMap(families);
	}

	private static Map<Integer, Integer> indexCosmeticFamilyRanks()
	{
		Map<Integer, Integer> ranks = new LinkedHashMap<>();
		List<SetDefinition> definitions = sets(COSMETIC_FAMILY_DOMAIN);
		for (int rank = 0; rank < definitions.size(); rank++)
		{
			for (Integer itemId : definitions.get(rank).itemIds)
			{
				ranks.put(itemId, rank);
			}
		}
		return Collections.unmodifiableMap(ranks);
	}

	static List<SetDefinition> sets(String domain)
	{
		List<SetDefinition> sets = SETS_BY_DOMAIN.get().get(domain);
		return sets == null ? Collections.emptyList() : sets;
	}

	public static Optional<String> domainOf(int itemId)
	{
		return Optional.ofNullable(DOMAIN_BY_ITEM_ID.get().get(itemId));
	}

	private static Map<Integer, String> indexDomains()
	{
		Map<Integer, String> domains = new LinkedHashMap<>();
		for (Map.Entry<String, List<SetDefinition>> domain : SETS_BY_DOMAIN.get().entrySet())
		{
			for (SetDefinition definition : domain.getValue())
			{
				for (Integer itemId : definition.itemIds)
				{
					String earlier = domains.put(itemId, domain.getKey());
					if (earlier != null && !earlier.equals(domain.getKey()))
					{
						throw new IllegalStateException(
							"Item ID " + itemId + " appears in multiple set domains");
					}
				}
			}
		}
		return Collections.unmodifiableMap(domains);
	}

	static SetDefinition definition(String domain, String key, String name, List<Integer> itemIds)
	{
		return new SetDefinition(domain, key, name, new ArrayList<>(itemIds));
	}

	static Map<String, List<SetDefinition>> load(InputStream stream)
	{
		if (stream == null)
		{
			throw new IllegalStateException("Missing item set catalog resource: " + RESOURCE_PATH);
		}

		Map<String, MutableSet> byKey = new LinkedHashMap<>();
		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String header = reader.readLine();
			if (!SCHEMA_HEADER.equals(header))
			{
				throw new IllegalStateException("Unexpected item set catalog schema: " + header);
			}
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] columns = line.split("\t", -1);
				if (columns.length != 5)
				{
					throw new IllegalStateException("Malformed item set catalog row: " + line);
				}
				String domain = columns[0];
				String key = columns[1];
				String name = columns[2];
				int slotRank = Integer.parseInt(columns[3]);
				int itemId = Integer.parseInt(columns[4]);
				if (domain.isEmpty() || key.isEmpty() || name.isEmpty() || slotRank < 0 || itemId <= 0)
				{
					throw new IllegalStateException("Invalid item set catalog row: " + line);
				}
				String compoundKey = domain + "\u0000" + key;
				MutableSet set = byKey.computeIfAbsent(compoundKey,
					ignored -> new MutableSet(domain, key, name));
				if (!set.name.equals(name))
				{
					throw new IllegalStateException("Conflicting set name for " + key);
				}
				set.add(slotRank, itemId);
			}
		}
		catch (IOException | NumberFormatException e)
		{
			throw new IllegalStateException("Failed to read item set catalog", e);
		}

		if (byKey.isEmpty()) throw new IllegalStateException("Empty item set catalog");
		Map<String, List<SetDefinition>> domains = new LinkedHashMap<>();
		Map<String, Set<Integer>> idsByDomain = new LinkedHashMap<>();
		for (MutableSet mutable : byKey.values())
		{
			SetDefinition definition = mutable.freeze();
			Set<Integer> domainIds = idsByDomain.computeIfAbsent(
				definition.domain, ignored -> new LinkedHashSet<>());
			for (int itemId : definition.itemIds)
			{
				if (!domainIds.add(itemId))
				{
					throw new IllegalStateException(
						"Item ID " + itemId + " appears in multiple " + definition.domain + " sets");
				}
			}
			domains.computeIfAbsent(definition.domain, ignored -> new ArrayList<>()).add(definition);
		}
		for (Map.Entry<String, List<SetDefinition>> entry : domains.entrySet())
		{
			entry.setValue(Collections.unmodifiableList(entry.getValue()));
		}
		return Collections.unmodifiableMap(domains);
	}

	static final class SetDefinition
	{
		private final String domain;
		private final String key;
		private final String name;
		private final List<Integer> itemIds;

		private SetDefinition(String domain, String key, String name, List<Integer> itemIds)
		{
			this.domain = domain;
			this.key = key;
			this.name = name;
			this.itemIds = Collections.unmodifiableList(itemIds);
		}

		String getKey()
		{
			return key;
		}

		String getName()
		{
			return name;
		}

		List<Integer> getItemIds()
		{
			return itemIds;
		}
	}

	private static final class MutableSet
	{
		private final String domain;
		private final String key;
		private final String name;
		private final List<Member> members = new ArrayList<>();
		private final Set<Integer> itemIds = new LinkedHashSet<>();

		private MutableSet(String domain, String key, String name)
		{
			this.domain = domain;
			this.key = key;
			this.name = name;
		}

		private void add(int slotRank, int itemId)
		{
			if (!itemIds.add(itemId))
			{
				throw new IllegalStateException("Duplicate item ID " + itemId + " in " + key);
			}
			members.add(new Member(slotRank, itemId, members.size()));
		}

		private SetDefinition freeze()
		{
			members.sort((left, right) ->
			{
				int bySlot = Integer.compare(left.slotRank, right.slotRank);
				return bySlot != 0 ? bySlot : Integer.compare(left.sourceOrder, right.sourceOrder);
			});
			List<Integer> ordered = new ArrayList<>(members.size());
			for (Member member : members)
			{
				ordered.add(member.itemId);
			}
			return new SetDefinition(domain, key, name, ordered);
		}
	}

	private static final class Member
	{
		private final int slotRank;
		private final int itemId;
		private final int sourceOrder;

		private Member(int slotRank, int itemId, int sourceOrder)
		{
			this.slotRank = slotRank;
			this.itemId = itemId;
			this.sourceOrder = sourceOrder;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * Immutable local rule shape with ordered atoms and explicit rows. Each row has a start offset and
 * nonempty contiguous IDs within width. IDs are positive, unique and real: no blanks, fillers or
 * phantom cells. Row boundaries and offsets participate in identity.
 */
public final class LayoutCandidate
{
	private final String ruleKey;
	private final ShapePrimitive shapePrimitive;
	private final int width;
	private final List<String> atomKeys;
	private final List<Row> rows;

	public LayoutCandidate(String ruleKey, ShapePrimitive shapePrimitive, int width, List<String> atomKeys,
		List<Row> rows)
	{
		this.ruleKey = SemanticRule.requireRuleKey(ruleKey, "ruleKey");
		this.shapePrimitive = Objects.requireNonNull(shapePrimitive, "shapePrimitive");
		if (width < SemanticRule.MIN_WIDTH || width > SemanticRule.MAX_WIDTH)
		{
			throw new IllegalArgumentException("width must be within "
				+ SemanticRule.MIN_WIDTH + ".." + SemanticRule.MAX_WIDTH);
		}
		this.width = width;
		this.atomKeys = requireAtomKeys(atomKeys);
		this.rows = requireRows(rows, width);
	}

	public String getRuleKey()
	{
		return ruleKey;
	}

	public ShapePrimitive getShapePrimitive()
	{
		return shapePrimitive;
	}

	public int getWidth()
	{
		return width;
	}

	public List<String> getAtomKeys()
	{
		return atomKeys;
	}

	public List<Row> getRows()
	{
		return rows;
	}

	/**
	 * Derived flat view over all rows in row-major order.
	 */
	public List<Integer> getRowMajorItemIds()
	{
		List<Integer> itemIds = new ArrayList<>();
		for (Row row : rows)
		{
			itemIds.addAll(row.getItemIds());
		}
		return Collections.unmodifiableList(itemIds);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof LayoutCandidate))
		{
			return false;
		}

		LayoutCandidate candidate = (LayoutCandidate) other;
		return width == candidate.width
			&& ruleKey.equals(candidate.ruleKey)
			&& shapePrimitive == candidate.shapePrimitive
			&& atomKeys.equals(candidate.atomKeys)
			&& rows.equals(candidate.rows);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(ruleKey, shapePrimitive, width, atomKeys, rows);
	}

	@Override
	public String toString()
	{
		return "LayoutCandidate{" + ruleKey + ", " + shapePrimitive + ", width=" + width
			+ ", atoms=" + atomKeys + ", rows=" + rows + "}";
	}

	static List<String> requireAtomKeys(List<String> atomKeys)
	{
		if (atomKeys == null || atomKeys.isEmpty())
		{
			throw new IllegalArgumentException("atomKeys must not be empty");
		}

		Set<String> seen = new HashSet<>();
		List<String> validated = new ArrayList<>(atomKeys.size());
		for (String atomKey : atomKeys)
		{
			String valid = SemanticRule.requireRuleKey(atomKey, "atomKeys");
			if (!seen.add(valid))
			{
				throw new IllegalArgumentException("duplicate atom key " + valid);
			}
			validated.add(valid);
		}

		return Collections.unmodifiableList(validated);
	}

	static List<Row> requireRows(List<Row> rows, int width)
	{
		if (rows == null || rows.isEmpty())
		{
			throw new IllegalArgumentException("rows must not be empty");
		}

		Set<Integer> seenItemIds = new HashSet<>();
		for (Row row : rows)
		{
			if (row == null)
			{
				throw new IllegalArgumentException("rows must not contain null");
			}
			if (row.getStartOffset() > width - row.length())
			{
				throw new IllegalArgumentException("row with start offset " + row.getStartOffset()
					+ " and length " + row.length() + " does not fit width " + width);
			}
			for (Integer itemId : row.getItemIds())
			{
				if (!seenItemIds.add(itemId))
				{
					throw new IllegalArgumentException("duplicate item ID " + itemId + " across rows");
				}
			}
		}

		return Collections.unmodifiableList(new ArrayList<>(rows));
	}

	/**
	 * One explicit candidate row: a local start offset inside the block plus one non-empty
	 * contiguous item-ID vector. Uniqueness of IDs is enforced candidate-wide, not per row.
	 */
	public static final class Row
	{
		private final int startOffset;
		private final List<Integer> itemIds;

		public Row(int startOffset, List<Integer> itemIds)
		{
			if (startOffset < 0)
			{
				throw new IllegalArgumentException("startOffset must not be negative");
			}
			this.startOffset = startOffset;
			this.itemIds = requireItemIds(itemIds);
		}

		public int getStartOffset()
		{
			return startOffset;
		}

		public List<Integer> getItemIds()
		{
			return itemIds;
		}

		public int length()
		{
			return itemIds.size();
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof Row))
			{
				return false;
			}

			Row row = (Row) other;
			return startOffset == row.startOffset && itemIds.equals(row.itemIds);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(startOffset, itemIds);
		}

		@Override
		public String toString()
		{
			return "Row{offset=" + startOffset + ", items=" + itemIds + "}";
		}

		private static List<Integer> requireItemIds(List<Integer> itemIds)
		{
			if (itemIds == null || itemIds.isEmpty())
			{
				throw new IllegalArgumentException("row itemIds must not be empty");
			}

			for (Integer itemId : itemIds)
			{
				if (itemId == null || itemId <= 0)
				{
					throw new IllegalArgumentException("row itemIds must contain positive item IDs");
				}
				if (itemId == ItemID.BANK_FILLER)
				{
					throw new IllegalArgumentException("row itemIds must not contain Bank Filler");
				}
			}

			return Collections.unmodifiableList(new ArrayList<>(itemIds));
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;




/**
 * Pure deterministic generation of eligible semantic block groups and their canonical local
 * shapes. Geometry depends only on a valid request's owned item IDs and reviewed rule topology;
 * entry order, quantities, locks, dense ranks, and width preferences never filter alternatives.
 */
final class LayoutCandidateGenerator
{
	private LayoutCandidateGenerator()
	{
	}

	/**
	 * Flat run-only view retained for the focused 3A2 geometry contract. Packing code must consume
	 * {@link #generate(LayoutRequest)} so eligible groups with no feasible candidate are not lost.
	 */
	static List<LayoutCandidate> generateRunCandidates(LayoutRequest request)
	{
		List<LayoutCandidate> candidates = new ArrayList<>();
		for (LayoutCandidateGroup group : generate(request))
		{
			if (group.getShapePrimitive() == ShapePrimitive.HORIZONTAL_RUN
				|| group.getShapePrimitive() == ShapePrimitive.VERTICAL_RUN)
			{
				candidates.addAll(group.getCandidates());
			}
		}
		return Collections.unmodifiableList(candidates);
	}

	static List<LayoutCandidateGroup> generate(LayoutRequest request)
	{
		Objects.requireNonNull(request, "request");
		List<LayoutConflict> conflicts = LayoutRequestValidator.validate(request);
		if (!conflicts.isEmpty())
		{
			throw new IllegalArgumentException(
				"request must be valid before candidate generation: " + conflicts);
		}

		Set<Integer> ownedItemIds = new HashSet<>();
		for (LayoutEntry entry : request.getEntries())
		{
			ownedItemIds.add(entry.getItem().getItemId());
		}

		List<SemanticRule> rules = new ArrayList<>(request.getRules());
		rules.sort(Comparator.comparing(SemanticRule::getRuleKey));

		List<LayoutCandidateGroup> groups = new ArrayList<>();
		for (SemanticRule rule : rules)
		{
			switch (rule.getShapePrimitive())
			{
				case HORIZONTAL_RUN:
				case VERTICAL_RUN:
					groups.addAll(generateRunGroups(rule, ownedItemIds));
					break;
				case STAGE_MATRIX:
					groups.addAll(generateStageMatrixGroups(rule, ownedItemIds));
					break;
				case ROW_GROUP_MATRIX:
					LayoutCandidateGroup rowGroup = generateRowGroupMatrix(rule, ownedItemIds);
					if (rowGroup != null)
					{
						groups.add(rowGroup);
					}
					break;
				default:
					throw new IllegalStateException("Unhandled shape primitive: " + rule.getShapePrimitive());
			}
		}

		return Collections.unmodifiableList(groups);
	}

	private static List<LayoutCandidateGroup> generateRunGroups(SemanticRule rule,
		Set<Integer> ownedItemIds)
	{
		List<LayoutCandidateGroup> groups = new ArrayList<>();
		for (SemanticAtom atom : rule.getAtoms())
		{
			LayoutCandidateGroup.AtomProjection projection = project(atom, ownedItemIds);
			if (projection == null)
			{
				continue;
			}

			List<LayoutCandidateGroup.AtomProjection> projections = Collections.singletonList(projection);
			List<LayoutCandidate> candidates = new ArrayList<>();
			for (int width = SemanticRule.MIN_WIDTH; width <= SemanticRule.MAX_WIDTH; width++)
			{
				if (!rule.getAllowedWidths().contains(width))
				{
					continue;
				}

				List<LayoutCandidate.Row> rows = LayoutCandidateGeometry.rowsFor(
					rule.getShapePrimitive(), projections, width);
				if (rows != null)
				{
					candidates.add(candidate(rule, width, projections, rows));
				}
			}
			groups.add(new LayoutCandidateGroup(rule, projections, candidates));
		}
		return groups;
	}

	private static List<LayoutCandidateGroup> generateStageMatrixGroups(SemanticRule rule,
		Set<Integer> ownedItemIds)
	{
		Map<List<String>, List<LayoutCandidateGroup.AtomProjection>> projectionsBySignature =
			new LinkedHashMap<>();
		for (SemanticAtom atom : rule.getAtoms())
		{
			LayoutCandidateGroup.AtomProjection projection = project(atom, ownedItemIds);
			if (projection != null)
			{
				projectionsBySignature.computeIfAbsent(projection.getMemberKeys(), key -> new ArrayList<>())
					.add(projection);
			}
		}

		List<LayoutCandidateGroup> groups = new ArrayList<>();
		for (List<LayoutCandidateGroup.AtomProjection> projections : projectionsBySignature.values())
		{
			List<LayoutCandidate> candidates = new ArrayList<>();
			for (int width = SemanticRule.MIN_WIDTH; width <= SemanticRule.MAX_WIDTH; width++)
			{
				if (rule.getAllowedWidths().contains(width))
				{
					candidates.add(candidate(rule, width, projections,
						LayoutCandidateGeometry.rowsFor(rule.getShapePrimitive(), projections, width)));
				}
			}
			groups.add(new LayoutCandidateGroup(rule, projections, candidates));
		}
		return groups;
	}

	private static LayoutCandidateGroup generateRowGroupMatrix(SemanticRule rule,
		Set<Integer> ownedItemIds)
	{
		List<LayoutCandidateGroup.AtomProjection> projections = new ArrayList<>();
		for (SemanticAtom atom : rule.getAtoms())
		{
			LayoutCandidateGroup.AtomProjection projection = project(atom, ownedItemIds);
			if (projection != null)
			{
				projections.add(projection);
			}
		}
		if (projections.isEmpty())
		{
			return null;
		}

		List<LayoutCandidate> candidates = new ArrayList<>();
		for (int width = SemanticRule.MIN_WIDTH; width <= SemanticRule.MAX_WIDTH; width++)
		{
			if (rule.getAllowedWidths().contains(width))
			{
				List<LayoutCandidate.Row> rows = LayoutCandidateGeometry.rowsFor(
					rule.getShapePrimitive(), projections, width);
				if (rows != null)
				{
					candidates.add(candidate(rule, width, projections, rows));
				}
			}
		}
		return new LayoutCandidateGroup(rule, projections, candidates);
	}

	private static LayoutCandidateGroup.AtomProjection project(SemanticAtom atom,
		Set<Integer> ownedItemIds)
	{
		List<String> memberKeys = new ArrayList<>();
		List<Integer> itemIds = new ArrayList<>();
		for (SemanticAtom.Member member : atom.getMembers())
		{
			if (ownedItemIds.contains(member.getItemId()))
			{
				memberKeys.add(member.getMemberKey());
				itemIds.add(member.getItemId());
			}
		}
		return itemIds.size() < 2 ? null : new LayoutCandidateGroup.AtomProjection(
			atom.getAtomKey(), atom.getMembers().size(), memberKeys, itemIds);
	}

	private static LayoutCandidate candidate(SemanticRule rule, int width,
		List<LayoutCandidateGroup.AtomProjection> projections, List<LayoutCandidate.Row> rows)
	{
		List<String> atomKeys = new ArrayList<>(projections.size());
		for (LayoutCandidateGroup.AtomProjection projection : projections)
		{
			atomKeys.add(projection.getAtomKey());
		}
		return new LayoutCandidate(rule.getRuleKey(), rule.getShapePrimitive(), width, atomKeys, rows);
	}

}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;


/**
 * Single canonical row-derivation path shared by generation and group validation. A {@code null}
 * result means the requested nominal width is structurally infeasible for the primitive.
 */
final class LayoutCandidateGeometry
{
	private LayoutCandidateGeometry()
	{
	}

	static List<LayoutCandidate.Row> rowsFor(ShapePrimitive primitive,
		List<LayoutCandidateGroup.AtomProjection> projections, int width)
	{
		Objects.requireNonNull(primitive, "primitive");
		if (projections == null || projections.isEmpty())
		{
			throw new IllegalArgumentException("projections must not be empty");
		}
		if (width < SemanticRule.MIN_WIDTH || width > SemanticRule.MAX_WIDTH)
		{
			throw new IllegalArgumentException("width must be within 1..8");
		}

		switch (primitive)
		{
			case HORIZONTAL_RUN:
				return horizontalRows(projections, width);
			case VERTICAL_RUN:
				return verticalRows(projections, width);
			case STAGE_MATRIX:
				return stageMatrixRows(projections, width);
			case ROW_GROUP_MATRIX:
				return rowGroupRows(projections, width);
			default:
				throw new IllegalStateException("Unhandled shape primitive: " + primitive);
		}
	}

	private static List<LayoutCandidate.Row> horizontalRows(
		List<LayoutCandidateGroup.AtomProjection> projections, int width)
	{
		requireSingleProjection(projections);
		List<Integer> itemIds = projections.get(0).getItemIds();
		return itemIds.size() <= width
			? Collections.singletonList(new LayoutCandidate.Row(0, itemIds))
			: null;
	}

	private static List<LayoutCandidate.Row> verticalRows(
		List<LayoutCandidateGroup.AtomProjection> projections, int width)
	{
		requireSingleProjection(projections);
		if (width != 1)
		{
			return null;
		}

		List<LayoutCandidate.Row> rows = new ArrayList<>();
		for (Integer itemId : projections.get(0).getItemIds())
		{
			rows.add(new LayoutCandidate.Row(0, Collections.singletonList(itemId)));
		}
		return rows;
	}

	private static List<LayoutCandidate.Row> stageMatrixRows(
		List<LayoutCandidateGroup.AtomProjection> projections, int width)
	{
		List<LayoutCandidate.Row> rows = new ArrayList<>();
		int stageCount = projections.get(0).size();
		for (int chunkStart = 0; chunkStart < projections.size(); chunkStart += width)
		{
			int chunkEnd = Math.min(chunkStart + width, projections.size());
			for (int stageIndex = 0; stageIndex < stageCount; stageIndex++)
			{
				List<Integer> stageItemIds = new ArrayList<>(chunkEnd - chunkStart);
				for (int atomIndex = chunkStart; atomIndex < chunkEnd; atomIndex++)
				{
					stageItemIds.add(projections.get(atomIndex).getItemIds().get(stageIndex));
				}
				rows.add(new LayoutCandidate.Row(0, stageItemIds));
			}
		}
		return rows;
	}

	private static List<LayoutCandidate.Row> rowGroupRows(
		List<LayoutCandidateGroup.AtomProjection> projections, int width)
	{
		List<LayoutCandidate.Row> rows = new ArrayList<>(projections.size());
		for (LayoutCandidateGroup.AtomProjection projection : projections)
		{
			if (projection.size() > width)
			{
				return null;
			}
			rows.add(new LayoutCandidate.Row(0, projection.getItemIds()));
		}
		return rows;
	}

	private static void requireSingleProjection(List<LayoutCandidateGroup.AtomProjection> projections)
	{
		if (projections.size() != 1)
		{
			throw new IllegalArgumentException("run geometry requires exactly one projection");
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * One immutable eligible semantic block group plus all of its feasible canonical local shapes.
 * A group may intentionally have no candidates: the later packer must still retain its fallback
 * transition and charge the group's missed semantic relations and completeness.
 */
final class LayoutCandidateGroup
{
	private final SemanticRule rule;
	private final List<AtomProjection> atomProjections;
	private final List<String> atomKeys;
	private final List<Integer> projectedItemIds;
	private final List<LayoutCandidate> candidates;
	private final int missedRelations;
	private final int missedCompleteness;

	LayoutCandidateGroup(SemanticRule rule, List<AtomProjection> atomProjections,
		List<LayoutCandidate> candidates)
	{
		this.rule = Objects.requireNonNull(rule, "rule");
		this.atomProjections = requireProjections(rule, atomProjections);
		this.atomKeys = atomKeys(this.atomProjections);
		this.projectedItemIds = projectedItemIds(this.atomProjections);
		this.candidates = requireCandidates(rule, this.atomProjections, this.atomKeys, candidates);
		this.missedRelations = sumRelations(this.atomProjections);
		this.missedCompleteness = sumCompleteness(this.atomProjections);
	}

	SemanticRule getRule()
	{
		return rule;
	}

	String getRuleKey()
	{
		return rule.getRuleKey();
	}

	ShapePrimitive getShapePrimitive()
	{
		return rule.getShapePrimitive();
	}

	ConfidenceTier getConfidenceTier()
	{
		return rule.getConfidenceTier();
	}

	List<AtomProjection> getAtomProjections()
	{
		return atomProjections;
	}

	List<String> getAtomKeys()
	{
		return atomKeys;
	}

	List<Integer> getProjectedItemIds()
	{
		return projectedItemIds;
	}

	List<LayoutCandidate> getCandidates()
	{
		return candidates;
	}

	int getMissedRelations()
	{
		return missedRelations;
	}

	int getMissedCompleteness()
	{
		return missedCompleteness;
	}

	void requireCandidate(LayoutCandidate candidate)
	{
		if (candidate == null || !candidates.contains(candidate))
		{
			throw new IllegalArgumentException("candidate does not belong to group "
				+ getRuleKey() + "/" + atomKeys);
		}
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof LayoutCandidateGroup))
		{
			return false;
		}

		LayoutCandidateGroup group = (LayoutCandidateGroup) other;
		return sameRuleFacts(rule, group.rule)
			&& atomProjections.equals(group.atomProjections)
			&& candidates.equals(group.candidates);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(rule.getRuleKey(), rule.getConfidenceTier(), rule.getShapePrimitive(),
			rule.getAllowedWidths(), widthEvidenceOrNull(rule), rule.getSpilloverCompatibleRuleKeys(),
			atomProjections, candidates);
	}

	@Override
	public String toString()
	{
		return "LayoutCandidateGroup{" + getRuleKey() + ", " + getShapePrimitive() + ", atoms="
			+ atomKeys + ", projected=" + projectedItemIds + ", candidates=" + candidates + "}";
	}

	private static List<AtomProjection> requireProjections(SemanticRule rule,
		List<AtomProjection> projections)
	{
		if (projections == null || projections.isEmpty())
		{
			throw new IllegalArgumentException("atomProjections must not be empty");
		}

		List<AtomProjection> validated = new ArrayList<>(projections.size());
		Set<String> seenAtomKeys = new HashSet<>();
		Set<Integer> seenItemIds = new HashSet<>();
		int previousAtomIndex = -1;
		for (AtomProjection projection : projections)
		{
			if (projection == null)
			{
				throw new IllegalArgumentException("atomProjections must not contain null");
			}
			if (!seenAtomKeys.add(projection.getAtomKey()))
			{
				throw new IllegalArgumentException("duplicate projected atom " + projection.getAtomKey());
			}

			int atomIndex = validateProjectionAgainstRule(rule, projection);
			if (atomIndex <= previousAtomIndex)
			{
				throw new IllegalArgumentException("atomProjections must retain reviewed atom order");
			}
			previousAtomIndex = atomIndex;

			for (Integer itemId : projection.getItemIds())
			{
				if (!seenItemIds.add(itemId))
				{
					throw new IllegalArgumentException("duplicate projected item ID " + itemId);
				}
			}
			validated.add(projection);
		}

		ShapePrimitive primitive = rule.getShapePrimitive();
		if ((primitive == ShapePrimitive.HORIZONTAL_RUN || primitive == ShapePrimitive.VERTICAL_RUN)
			&& validated.size() != 1)
		{
			throw new IllegalArgumentException("run groups must contain exactly one atom projection");
		}
		if (primitive == ShapePrimitive.STAGE_MATRIX)
		{
			List<String> signature = validated.get(0).getMemberKeys();
			for (AtomProjection projection : validated)
			{
				if (!signature.equals(projection.getMemberKeys()))
				{
					throw new IllegalArgumentException(
						"stage-matrix projections must have the same ordered member signature");
				}
			}
		}

		return Collections.unmodifiableList(validated);
	}

	private static int validateProjectionAgainstRule(SemanticRule rule, AtomProjection projection)
	{
		for (int atomIndex = 0; atomIndex < rule.getAtoms().size(); atomIndex++)
		{
			SemanticAtom atom = rule.getAtoms().get(atomIndex);
			if (!atom.getAtomKey().equals(projection.getAtomKey()))
			{
				continue;
			}
			if (atom.getMembers().size() != projection.getReviewedMemberCount())
			{
				throw new IllegalArgumentException("projection reviewed-member count does not match atom "
					+ projection.getAtomKey());
			}

			int projectedIndex = 0;
			for (SemanticAtom.Member member : atom.getMembers())
			{
				if (projectedIndex < projection.size()
					&& member.getMemberKey().equals(projection.getMemberKeys().get(projectedIndex))
					&& member.getItemId() == projection.getItemIds().get(projectedIndex))
				{
					projectedIndex++;
				}
			}
			if (projectedIndex != projection.size())
			{
				throw new IllegalArgumentException("projection is not an ordered member subset of atom "
					+ projection.getAtomKey());
			}
			return atomIndex;
		}

		throw new IllegalArgumentException("projection atom is absent from rule: " + projection.getAtomKey());
	}

	private static List<LayoutCandidate> requireCandidates(SemanticRule rule,
		List<AtomProjection> projections, List<String> atomKeys, List<LayoutCandidate> candidates)
	{
		Objects.requireNonNull(candidates, "candidates");
		List<LayoutCandidate> canonical = new ArrayList<>(candidates.size());
		for (LayoutCandidate candidate : candidates)
		{
			if (candidate == null)
			{
				throw new IllegalArgumentException("candidates must not contain null");
			}
			if (!rule.getRuleKey().equals(candidate.getRuleKey())
				|| rule.getShapePrimitive() != candidate.getShapePrimitive()
				|| !atomKeys.equals(candidate.getAtomKeys()))
			{
				throw new IllegalArgumentException("candidate identity does not match its group");
			}
			if (!rule.getAllowedWidths().contains(candidate.getWidth()))
			{
				throw new IllegalArgumentException("candidate width is not allowed by its rule");
			}
			canonical.add(candidate);
		}

		canonical.sort(Comparator.comparingInt(LayoutCandidate::getWidth));

		List<LayoutCandidate> expected = new ArrayList<>();
		for (int width = SemanticRule.MIN_WIDTH; width <= SemanticRule.MAX_WIDTH; width++)
		{
			if (!rule.getAllowedWidths().contains(width))
			{
				continue;
			}
			List<LayoutCandidate.Row> rows = LayoutCandidateGeometry.rowsFor(
				rule.getShapePrimitive(), projections, width);
			if (rows != null)
			{
				expected.add(new LayoutCandidate(rule.getRuleKey(), rule.getShapePrimitive(), width,
					atomKeys, rows));
			}
		}
		if (!expected.equals(canonical))
		{
			throw new IllegalArgumentException(
				"candidates must exactly match every feasible canonical width for their group");
		}
		return Collections.unmodifiableList(canonical);
	}

	private static List<String> atomKeys(List<AtomProjection> projections)
	{
		List<String> keys = new ArrayList<>(projections.size());
		for (AtomProjection projection : projections)
		{
			keys.add(projection.getAtomKey());
		}
		return Collections.unmodifiableList(keys);
	}

	private static List<Integer> projectedItemIds(List<AtomProjection> projections)
	{
		List<Integer> itemIds = new ArrayList<>();
		for (AtomProjection projection : projections)
		{
			itemIds.addAll(projection.getItemIds());
		}
		return Collections.unmodifiableList(itemIds);
	}

	private static int sumRelations(List<AtomProjection> projections)
	{
		int result = 0;
		for (AtomProjection projection : projections)
		{
			result = Math.addExact(result, projection.getMissedRelations());
		}
		return result;
	}

	private static int sumCompleteness(List<AtomProjection> projections)
	{
		int result = 0;
		for (AtomProjection projection : projections)
		{
			result = Math.addExact(result, projection.getMissedCompleteness());
		}
		return result;
	}

	private static boolean sameRuleFacts(SemanticRule left, SemanticRule right)
	{
		return left.getRuleKey().equals(right.getRuleKey())
			&& left.getConfidenceTier() == right.getConfidenceTier()
			&& left.getShapePrimitive() == right.getShapePrimitive()
			&& left.getAllowedWidths().equals(right.getAllowedWidths())
			&& Objects.equals(widthEvidenceOrNull(left), widthEvidenceOrNull(right))
			&& left.getSpilloverCompatibleRuleKeys().equals(right.getSpilloverCompatibleRuleKeys());
	}

	private static WidthEvidence widthEvidenceOrNull(SemanticRule rule)
	{
		return rule.hasWidthEvidence() ? rule.getWidthEvidence() : null;
	}

	/**
	 * One eligible atom projected onto its present members, retaining reviewed member-key order and
	 * the reviewed family size needed for exact completeness scoring.
	 */
	static final class AtomProjection
	{
		private final String atomKey;
		private final int reviewedMemberCount;
		private final List<String> memberKeys;
		private final List<Integer> itemIds;

		AtomProjection(String atomKey, int reviewedMemberCount, List<String> memberKeys,
			List<Integer> itemIds)
		{
			this.atomKey = SemanticRule.requireRuleKey(atomKey, "atomKey");
			if (reviewedMemberCount < 2)
			{
				throw new IllegalArgumentException("reviewedMemberCount must be at least two");
			}
			if (memberKeys == null || itemIds == null || memberKeys.size() != itemIds.size()
				|| memberKeys.size() < 2 || memberKeys.size() > reviewedMemberCount)
			{
				throw new IllegalArgumentException(
					"projected member keys and item IDs must have the same eligible size");
			}

			Set<String> seenKeys = new HashSet<>();
			Set<Integer> seenItemIds = new HashSet<>();
			List<String> validatedKeys = new ArrayList<>(memberKeys.size());
			List<Integer> validatedItemIds = new ArrayList<>(itemIds.size());
			for (int index = 0; index < memberKeys.size(); index++)
			{
				String memberKey = SemanticRule.requireRuleKey(memberKeys.get(index), "memberKey");
				Integer itemId = itemIds.get(index);
				if (!seenKeys.add(memberKey))
				{
					throw new IllegalArgumentException("duplicate projected member key " + memberKey);
				}
				if (itemId == null || itemId <= 0 || itemId == ItemID.BANK_FILLER
					|| !seenItemIds.add(itemId))
				{
					throw new IllegalArgumentException("projected item IDs must be positive, unique, and real");
				}
				validatedKeys.add(memberKey);
				validatedItemIds.add(itemId);
			}

			this.reviewedMemberCount = reviewedMemberCount;
			this.memberKeys = Collections.unmodifiableList(validatedKeys);
			this.itemIds = Collections.unmodifiableList(validatedItemIds);
		}

		String getAtomKey()
		{
			return atomKey;
		}

		int getReviewedMemberCount()
		{
			return reviewedMemberCount;
		}

		List<String> getMemberKeys()
		{
			return memberKeys;
		}

		List<Integer> getItemIds()
		{
			return itemIds;
		}

		int size()
		{
			return itemIds.size();
		}

		int getMissedRelations()
		{
			return size() - 1;
		}

		int getMissedCompleteness()
		{
			return (int) ((1000L * size()) / reviewedMemberCount);
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof AtomProjection))
			{
				return false;
			}

			AtomProjection projection = (AtomProjection) other;
			return reviewedMemberCount == projection.reviewedMemberCount
				&& atomKey.equals(projection.atomKey)
				&& memberKeys.equals(projection.memberKeys)
				&& itemIds.equals(projection.itemIds);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(atomKey, reviewedMemberCount, memberKeys, itemIds);
		}

		@Override
		public String toString()
		{
			return atomKey + "{" + memberKeys + "=" + itemIds + ", reviewed="
				+ reviewedMemberCount + "}";
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.Objects;

/**
 * Candidate-local 3A3 scoring. Only width evidence and canonical stage-matrix fragmentation are
 * known before placement; every packing, spillover, footprint, span, and movement component stays
 * zero until the bounded packer has a concrete state.
 */
final class LayoutCandidateScorer
{
	private LayoutCandidateScorer()
	{
	}

	static LayoutScore score(LayoutCandidateGroup group, LayoutCandidate candidate)
	{
		Objects.requireNonNull(group, "group");
		group.requireCandidate(candidate);

		return LayoutScore.builder()
			.widthEvidenceRegret(widthRegret(group.getRule(), candidate.getWidth()))
			.semanticFragmentation(fragmentation(group, candidate))
			.build();
	}

	static int widthPreferenceRank(LayoutCandidateGroup group, LayoutCandidate candidate)
	{
		Objects.requireNonNull(group, "group");
		group.requireCandidate(candidate);
		SemanticRule rule = group.getRule();
		return rule.hasWidthEvidence()
			? rule.getWidthEvidence().preferenceRankForWidth(candidate.getWidth())
			: 0;
	}

	static LayoutScore scoreFallback(LayoutCandidateGroup group)
	{
		Objects.requireNonNull(group, "group");
		LayoutScore.Builder score = LayoutScore.builder();
		switch (group.getConfidenceTier())
		{
			case HIGH:
				return score.highMissedRelations(group.getMissedRelations())
					.highMissedCompleteness(group.getMissedCompleteness())
					.build();
			case MEDIUM:
				return score.mediumMissedRelations(group.getMissedRelations())
					.mediumMissedCompleteness(group.getMissedCompleteness())
					.build();
			case LOW:
				return score.lowMissedRelations(group.getMissedRelations())
					.lowMissedCompleteness(group.getMissedCompleteness())
					.build();
			default:
				throw new IllegalStateException("Unhandled confidence tier: " + group.getConfidenceTier());
		}
	}

	private static int widthRegret(SemanticRule rule, int width)
	{
		return rule.hasWidthEvidence() ? rule.getWidthEvidence().regretForWidth(width) : 0;
	}

	private static int fragmentation(LayoutCandidateGroup group, LayoutCandidate candidate)
	{
		if (group.getShapePrimitive() != ShapePrimitive.STAGE_MATRIX)
		{
			return 0;
		}

		return (group.getAtomKeys().size() - 1) / candidate.getWidth();
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import static com.pkoka5.ironmanbankarchitect.util.TextValidation.requireText;

import java.util.*;


/**
 * One typed validation conflict. A conflict never produces a partial plan: any conflict makes the
 * whole request or plan invalid via {@link LayoutResult}.
 */
public final class LayoutConflict
{
	/**
	 * Canonical stable conflict order used by the validators: type, then item ID, then detail.
	 */
	static final Comparator<LayoutConflict> CANONICAL_ORDER =
		Comparator.comparingInt((LayoutConflict conflict) -> conflict.getType().ordinal())
			.thenComparingInt(LayoutConflict::getItemId)
			.thenComparing(LayoutConflict::getDetail);

	/**
	 * Item ID value for conflicts that are not about one specific item.
	 */
	public static final int NO_ITEM = -1;

	public enum Type
	{
		NULL_ENTRY,
		NON_POSITIVE_ITEM_ID,
		BANK_FILLER_ITEM,
		BLANK_ITEM,
		INVALID_PLACEHOLDER_STATE,
		DUPLICATE_ITEM_ID,
		DUPLICATE_RULE_KEY,
		RULE_ITEM_OVERLAP,
		LOCK_TARGET_OUT_OF_RANGE,
		DUPLICATE_LOCK_TARGET,
		DENSE_ORDER_NOT_PERMUTATION,
		DENSE_ORDER_RANK_MISMATCH,
		DENSE_RANK_WITHOUT_ORDER,
		DENSE_RANK_OUT_OF_RANGE,
		DENSE_RANK_DUPLICATE,
		FALLBACK_ORDER_NOT_PERMUTATION,
		PLAN_SIZE_MISMATCH,
		PLAN_DUPLICATE_ITEM,
		PLAN_PHANTOM_ITEM,
		PLAN_MISSING_ITEM,
		PLAN_TARGET_OUT_OF_RANGE,
		PLAN_DUPLICATE_TARGET,
		PLAN_QUANTITY_MISMATCH,
		PLAN_PLACEHOLDER_MISMATCH,
		PLAN_LOCK_VIOLATION,
		PLAN_SEMANTIC_GEOMETRY_MISMATCH
	}

	private final Type type;
	private final int itemId;
	private final String detail;

	public LayoutConflict(Type type, int itemId, String detail)
	{
		this.type = Objects.requireNonNull(type, "type");
		this.itemId = itemId;
		this.detail = requireText(detail, "detail");
	}

	public Type getType()
	{
		return type;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getDetail()
	{
		return detail;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof LayoutConflict))
		{
			return false;
		}

		LayoutConflict conflict = (LayoutConflict) other;
		return type == conflict.type && itemId == conflict.itemId && detail.equals(conflict.detail);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(type, itemId, detail);
	}

	@Override
	public String toString()
	{
		return type + "(itemId=" + itemId + "): " + detail;
	}

}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.Objects;

/**
 * Bank item plus placement context. Flat source slots do not imply a dense category rank; ranks
 * require explicit proof. Locks specify final category-local indices, not immobility during manual
 * moves. LayoutRequestValidator reports invalid item content as typed conflicts.
 */
public final class LayoutEntry
{
	private final BankPreviewItem item;
	private final int sourceFlatBankSlot;
	private final boolean hasDenseCategoryRank;
	private final int denseCategoryRank;
	private final boolean hasLockedTarget;
	private final int lockedTarget;

	private LayoutEntry(BankPreviewItem item, int sourceFlatBankSlot, boolean hasDenseCategoryRank,
		int denseCategoryRank, boolean hasLockedTarget, int lockedTarget)
	{
		this.item = Objects.requireNonNull(item, "item");
		this.sourceFlatBankSlot = sourceFlatBankSlot;
		this.hasDenseCategoryRank = hasDenseCategoryRank;
		this.denseCategoryRank = denseCategoryRank;
		this.hasLockedTarget = hasLockedTarget;
		this.lockedTarget = lockedTarget;
	}

	public static LayoutEntry of(BankPreviewItem item, int sourceFlatBankSlot)
	{
		if (sourceFlatBankSlot < 0)
		{
			throw new IllegalArgumentException("sourceFlatBankSlot must not be negative");
		}

		return new LayoutEntry(item, sourceFlatBankSlot, false, 0, false, 0);
	}

	/**
	 * Returns a copy carrying a proven dense category-local rank. Range validity against the
	 * request size is checked by {@link LayoutRequestValidator}, not here.
	 */
	public LayoutEntry withDenseCategoryRank(int rank)
	{
		return new LayoutEntry(item, sourceFlatBankSlot, true, rank, hasLockedTarget, lockedTarget);
	}

	/**
	 * Returns a copy carrying a required final target index. Range validity against the request
	 * size is checked by {@link LayoutRequestValidator}, not here.
	 */
	public LayoutEntry withLockedTarget(int target)
	{
		return new LayoutEntry(item, sourceFlatBankSlot, hasDenseCategoryRank, denseCategoryRank, true, target);
	}

	public BankPreviewItem getItem()
	{
		return item;
	}

	public int getSourceFlatBankSlot()
	{
		return sourceFlatBankSlot;
	}

	public boolean hasDenseCategoryRank()
	{
		return hasDenseCategoryRank;
	}

	public int getDenseCategoryRank()
	{
		if (!hasDenseCategoryRank)
		{
			throw new IllegalStateException("entry has no proven dense category rank");
		}

		return denseCategoryRank;
	}

	public boolean hasLockedTarget()
	{
		return hasLockedTarget;
	}

	public int getLockedTarget()
	{
		if (!hasLockedTarget)
		{
			throw new IllegalStateException("entry has no locked target");
		}

		return lockedTarget;
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;

/** Shared canonical ordering for completed plans, search states and geometry validation. */
final class LayoutOrdering
{
	static final Comparator<PlacedBlock> IDENTITY = Comparator.comparing(PlacedBlock::getRuleKey)
		.thenComparing(PlacedBlock::getAtomKeys, LayoutOrdering::compareValues);
	static final List<Comparator<PlacedBlock>> COMPONENTS = Collections.unmodifiableList(Arrays.asList(
		IDENTITY,
		Comparator.comparingInt(PlacedBlock::getWidthPreferenceRank),
		Comparator.comparingInt(PlacedBlock::getWidth),
		Comparator.comparingInt(block -> block.getShapePrimitive().ordinal()),
		Comparator.comparingInt(PlacedBlock::getStartRow),
		Comparator.comparingInt(PlacedBlock::getStartColumn),
		Comparator.comparing(PlacedBlock::getRows, LayoutOrdering::compareRows)));
	private static final Comparator<LayoutCandidate.Row> ROW =
		Comparator.comparingInt(LayoutCandidate.Row::getStartOffset)
			.thenComparing(LayoutCandidate.Row::getItemIds, LayoutOrdering::compareValues);

	private LayoutOrdering() { }

	static int compareBlocks(PlacedBlock left, PlacedBlock right)
	{
		for (Comparator<PlacedBlock> component : COMPONENTS)
		{
			int result = component.compare(left, right);
			if (result != 0) return result;
		}
		return 0;
	}

	/** Compare each component across all blocks before proceeding to the next component. */
	static int compareBlockVectors(List<PlacedBlock> left, List<PlacedBlock> right)
	{
		for (Comparator<PlacedBlock> component : COMPONENTS)
		{
			int result = compareLists(left, right, component);
			if (result != 0) return result;
		}
		return 0;
	}

	static <T extends Comparable<? super T>> int compareValues(List<T> left, List<T> right)
	{
		return compareLists(left, right, Comparator.naturalOrder());
	}

	private static int compareRows(List<LayoutCandidate.Row> left, List<LayoutCandidate.Row> right)
	{
		return compareLists(left, right, ROW);
	}

	private static <T> int compareLists(List<T> left, List<T> right, Comparator<? super T> comparator)
	{
		int shared = Math.min(left.size(), right.size());
		for (int index = 0; index < shared; index++)
		{
			int result = comparator.compare(left.get(index), right.get(index));
			if (result != 0) return result;
		}
		return Integer.compare(left.size(), right.size());
	}
}

