package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.*;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * Validates dense indices 0..n-1, the exact request item multiset, quantities, placeholders and
 * locks; rejects null, filler and phantom items. Any conflict yields no placements. Success
 * rebuilds placements from request metadata. Inputs remain unchanged; aggregation by ID and
 * canonical conflict sorting make validation independent of plan order.
 */
public final class LayoutPlanValidator
{
	private LayoutPlanValidator()
	{
	}

	public static LayoutResult validate(LayoutRequest request, List<LayoutPlacement> plan)
	{
		Objects.requireNonNull(request, "request");
		Objects.requireNonNull(plan, "plan");

		List<LayoutConflict> requestConflicts = LayoutRequestValidator.validate(request);
		if (!requestConflicts.isEmpty())
		{
			return LayoutResult.conflict(requestConflicts);
		}

		List<LayoutConflict> conflicts = new ArrayList<>();
		int size = request.size();
		if (plan.size() != size)
		{
			conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_SIZE_MISMATCH, LayoutConflict.NO_ITEM,
				"plan has " + plan.size() + " placements for " + size + " request entries"));
		}

		Map<Integer, LayoutEntry> entriesByItemId = new TreeMap<>();
		for (LayoutEntry entry : request.getEntries())
		{
			entriesByItemId.put(entry.getItem().getItemId(), entry);
		}

		// Canonicalize first: group every valid-ID placement per item ID so that no check depends
		// on which occurrence the plan list happens to present first.
		Map<Integer, List<LayoutPlacement>> placementsByItemId = new TreeMap<>();
		for (LayoutPlacement placement : plan)
		{
			if (placement == null)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.NULL_ENTRY, LayoutConflict.NO_ITEM,
					"plan placements must not contain null"));
				continue;
			}

			BankPreviewItem item = placement.getItem();
			int itemId = item.getItemId();
			if (itemId == ItemID.BANK_FILLER)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.BANK_FILLER_ITEM, itemId,
					"plan must not contain Bank Filler"));
				continue;
			}
			if (item.isBlank())
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.BLANK_ITEM, itemId,
					"plan must not contain blank preview items"));
				continue;
			}
			if (itemId <= 0)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.NON_POSITIVE_ITEM_ID, itemId,
					"plan item ID must be positive, got " + itemId));
				continue;
			}

			placementsByItemId.computeIfAbsent(itemId, key -> new ArrayList<>()).add(placement);
		}

		Map<Integer, Integer> targetsByItemId = new TreeMap<>();
		Map<Integer, List<Integer>> itemIdsByTarget = new TreeMap<>();
		for (Map.Entry<Integer, List<LayoutPlacement>> group : placementsByItemId.entrySet())
		{
			int itemId = group.getKey();
			List<LayoutPlacement> placements = group.getValue();
			if (placements.size() > 1)
			{
				List<Integer> targets = new ArrayList<>();
				for (LayoutPlacement placement : placements)
				{
					targets.add(placement.getTargetIndex());
				}
				Collections.sort(targets);
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_DUPLICATE_ITEM, itemId,
					"plan places item " + itemId + " on targets " + targets));
				continue;
			}

			LayoutPlacement placement = placements.get(0);
			LayoutEntry entry = entriesByItemId.get(itemId);
			if (entry == null)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_PHANTOM_ITEM, itemId,
					"plan places item " + itemId + " that is not in the request"));
				continue;
			}

			BankPreviewItem item = placement.getItem();
			if (item.getQuantity() != entry.getItem().getQuantity())
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_QUANTITY_MISMATCH, itemId,
					"plan quantity " + item.getQuantity() + " differs from request quantity "
						+ entry.getItem().getQuantity()));
			}
			if (item.isPlaceholder() != entry.getItem().isPlaceholder())
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_PLACEHOLDER_MISMATCH, itemId,
					"plan placeholder state differs from request placeholder state"));
			}

			int target = placement.getTargetIndex();
			targetsByItemId.put(itemId, target);
			if (target < 0 || target >= size)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_TARGET_OUT_OF_RANGE, itemId,
					"target " + target + " is outside 0.." + (size - 1)));
			}
			else
			{
				itemIdsByTarget.computeIfAbsent(target, key -> new ArrayList<>()).add(itemId);
			}
		}

		for (Map.Entry<Integer, List<Integer>> target : itemIdsByTarget.entrySet())
		{
			if (target.getValue().size() > 1)
			{
				List<Integer> itemIds = new ArrayList<>(target.getValue());
				Collections.sort(itemIds);
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_DUPLICATE_TARGET, LayoutConflict.NO_ITEM,
					"target " + target.getKey() + " is used by items " + itemIds));
			}
		}

		for (Map.Entry<Integer, LayoutEntry> requested : entriesByItemId.entrySet())
		{
			int itemId = requested.getKey();
			if (!placementsByItemId.containsKey(itemId))
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_MISSING_ITEM, itemId,
					"plan does not place request item " + itemId));
				continue;
			}

			LayoutEntry entry = requested.getValue();
			Integer target = targetsByItemId.get(itemId);
			if (entry.hasLockedTarget() && target != null && target != entry.getLockedTarget())
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.PLAN_LOCK_VIOLATION, itemId,
					"item " + itemId + " is locked to target " + entry.getLockedTarget()
						+ " but placed on " + target));
			}
		}

		if (!conflicts.isEmpty())
		{
			conflicts.sort(LayoutConflict.CANONICAL_ORDER);
			return LayoutResult.conflict(conflicts);
		}

		// Rebuild the result from the request's own immutable items, never from plan metadata.
		List<LayoutPlacement> ordered = new ArrayList<>(size);
		for (Map.Entry<Integer, Integer> target : targetsByItemId.entrySet())
		{
			ordered.add(new LayoutPlacement(entriesByItemId.get(target.getKey()).getItem(), target.getValue()));
		}
		ordered.sort((left, right) -> Integer.compare(left.getTargetIndex(), right.getTargetIndex()));
		return LayoutResult.success(ordered);
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;


/**
 * Immutable category request with entries, curated nonnull rules and optional proven dense order.
 * Invalid entries, including nulls, are retained for typed validation conflicts. Dense order must
 * be an exact unique permutation of request IDs; flat source slots do not establish it.
 */
public final class LayoutRequest
{
	private final List<LayoutEntry> entries;
	private final List<SemanticRule> rules;
	private final int gridStartColumn;
	private final boolean hasCurrentDenseCategoryOrder;
	private final List<Integer> currentDenseCategoryOrder;

	public LayoutRequest(List<LayoutEntry> entries, List<SemanticRule> rules)
	{
		this(entries, rules, null, 0);
	}

	public LayoutRequest(List<LayoutEntry> entries, List<SemanticRule> rules,
		List<Integer> currentDenseCategoryOrder)
	{
		this(entries, rules, currentDenseCategoryOrder, 0);
	}

	private LayoutRequest(List<LayoutEntry> entries, List<SemanticRule> rules,
		List<Integer> currentDenseCategoryOrder, int gridStartColumn)
	{
		Objects.requireNonNull(entries, "entries");
		Objects.requireNonNull(rules, "rules");
		if (gridStartColumn < 0 || gridStartColumn >= SemanticRule.MAX_WIDTH)
		{
			throw new IllegalArgumentException("gridStartColumn must be between 0 and 7");
		}
		for (SemanticRule rule : rules)
		{
			Objects.requireNonNull(rule, "rules must not contain null");
		}

		this.entries = Collections.unmodifiableList(new ArrayList<>(entries));
		this.rules = Collections.unmodifiableList(new ArrayList<>(rules));
		this.gridStartColumn = gridStartColumn;
		this.hasCurrentDenseCategoryOrder = currentDenseCategoryOrder != null;
		this.currentDenseCategoryOrder = currentDenseCategoryOrder == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(currentDenseCategoryOrder));
	}

	/**
	 * Returns an immutable copy whose local target zero begins at the supplied physical bank
	 * column. Dense targets, locks, and movement facts remain request-local.
	 */
	public LayoutRequest withGridStartColumn(int column)
	{
		return new LayoutRequest(entries, rules,
			hasCurrentDenseCategoryOrder ? currentDenseCategoryOrder : null, column);
	}

	public int size()
	{
		return entries.size();
	}

	public List<LayoutEntry> getEntries()
	{
		return entries;
	}

	public List<SemanticRule> getRules()
	{
		return rules;
	}

	public int getGridStartColumn()
	{
		return gridStartColumn;
	}

	public boolean hasCurrentDenseCategoryOrder()
	{
		return hasCurrentDenseCategoryOrder;
	}

	public List<Integer> getCurrentDenseCategoryOrder()
	{
		if (!hasCurrentDenseCategoryOrder)
		{
			throw new IllegalStateException("request has no current dense category order");
		}

		return currentDenseCategoryOrder;
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.*;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * Validates a {@link LayoutRequest} into a list of typed {@link LayoutConflict}s. An empty result
 * means the request is valid.
 *
 * <p>The validator never mutates the request. It aggregates unordered facts (duplicate IDs, lock
 * collisions, rank collisions, rule overlap) before emitting conflicts and sorts the final list by
 * the canonical (type, itemId, detail) order, so the exact same conflict list is produced for any
 * input iteration order that is not semantically meaningful.</p>
 */
public final class LayoutRequestValidator
{
	private LayoutRequestValidator()
	{
	}

	public static List<LayoutConflict> validate(LayoutRequest request)
	{
		Objects.requireNonNull(request, "request");

		List<LayoutConflict> conflicts = new ArrayList<>();
		validateEntries(request, conflicts);
		validateLocks(request, conflicts);
		validateRules(request, conflicts);
		validateDenseCategoryOrder(request, conflicts);
		conflicts.sort(LayoutConflict.CANONICAL_ORDER);
		return Collections.unmodifiableList(conflicts);
	}

	private static void validateEntries(LayoutRequest request, List<LayoutConflict> conflicts)
	{
		Map<Integer, Integer> occurrencesByItemId = new TreeMap<>();
		for (LayoutEntry entry : request.getEntries())
		{
			if (entry == null)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.NULL_ENTRY, LayoutConflict.NO_ITEM,
					"request entries must not contain null"));
				continue;
			}

			BankPreviewItem item = entry.getItem();
			int itemId = item.getItemId();
			if (itemId == ItemID.BANK_FILLER)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.BANK_FILLER_ITEM, itemId,
					"Bank Filler is not a real layout entry"));
			}
			else if (item.isBlank())
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.BLANK_ITEM, itemId,
					"blank preview items are not real layout entries"));
			}
			else if (itemId <= 0)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.NON_POSITIVE_ITEM_ID, itemId,
					"item ID must be positive, got " + itemId));
			}
			else if (item.isPlaceholder() && item.getQuantity() != 0)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.INVALID_PLACEHOLDER_STATE, itemId,
					"a real bank placeholder must have quantity 0, got " + item.getQuantity()));
			}
			else
			{
				occurrencesByItemId.merge(itemId, 1, Integer::sum);
			}
		}

		for (Map.Entry<Integer, Integer> occurrence : occurrencesByItemId.entrySet())
		{
			if (occurrence.getValue() > 1)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.DUPLICATE_ITEM_ID, occurrence.getKey(),
					"item ID " + occurrence.getKey() + " appears " + occurrence.getValue()
						+ " times and cannot be guided safely"));
			}
		}
	}

	private static void validateLocks(LayoutRequest request, List<LayoutConflict> conflicts)
	{
		int size = request.size();
		Map<Integer, List<Integer>> itemIdsByLockedTarget = new TreeMap<>();
		for (LayoutEntry entry : request.getEntries())
		{
			if (entry == null || !entry.hasLockedTarget())
			{
				continue;
			}

			int target = entry.getLockedTarget();
			int itemId = entry.getItem().getItemId();
			if (target < 0 || target >= size)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.LOCK_TARGET_OUT_OF_RANGE, itemId,
					"locked target " + target + " is outside 0.." + (size - 1)));
				continue;
			}

			itemIdsByLockedTarget.computeIfAbsent(target, key -> new ArrayList<>()).add(itemId);
		}

		for (Map.Entry<Integer, List<Integer>> lock : itemIdsByLockedTarget.entrySet())
		{
			if (lock.getValue().size() > 1)
			{
				List<Integer> itemIds = new ArrayList<>(lock.getValue());
				Collections.sort(itemIds);
				conflicts.add(new LayoutConflict(LayoutConflict.Type.DUPLICATE_LOCK_TARGET, LayoutConflict.NO_ITEM,
					"target " + lock.getKey() + " is locked by items " + itemIds));
			}
		}
	}

	private static void validateRules(LayoutRequest request, List<LayoutConflict> conflicts)
	{
		Map<String, Integer> occurrencesByRuleKey = new TreeMap<>();
		Map<Integer, Set<String>> ruleKeysByItemId = new TreeMap<>();
		for (SemanticRule rule : request.getRules())
		{
			occurrencesByRuleKey.merge(rule.getRuleKey(), 1, Integer::sum);
			for (Integer itemId : rule.getMemberItemIds())
			{
				ruleKeysByItemId.computeIfAbsent(itemId, key -> new TreeSet<>()).add(rule.getRuleKey());
			}
		}

		for (Map.Entry<String, Integer> occurrence : occurrencesByRuleKey.entrySet())
		{
			if (occurrence.getValue() > 1)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.DUPLICATE_RULE_KEY, LayoutConflict.NO_ITEM,
					"rule key " + occurrence.getKey() + " appears " + occurrence.getValue() + " times"));
			}
		}

		for (Map.Entry<Integer, Set<String>> selection : ruleKeysByItemId.entrySet())
		{
			if (selection.getValue().size() > 1)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.RULE_ITEM_OVERLAP, selection.getKey(),
					"item " + selection.getKey() + " is selected by rules " + selection.getValue()));
			}
		}
	}

	private static void validateDenseCategoryOrder(LayoutRequest request, List<LayoutConflict> conflicts)
	{
		int size = request.size();
		if (!request.hasCurrentDenseCategoryOrder())
		{
			for (LayoutEntry entry : request.getEntries())
			{
				if (entry != null && entry.hasDenseCategoryRank())
				{
					conflicts.add(new LayoutConflict(LayoutConflict.Type.DENSE_RANK_WITHOUT_ORDER,
						entry.getItem().getItemId(),
						"entry rank " + entry.getDenseCategoryRank()
							+ " requires a complete currentDenseCategoryOrder"));
				}
			}
			return;
		}

		List<Integer> order = request.getCurrentDenseCategoryOrder();
		Set<Integer> requestItemIds = new HashSet<>();
		for (LayoutEntry entry : request.getEntries())
		{
			if (entry != null)
			{
				requestItemIds.add(entry.getItem().getItemId());
			}
		}

		Set<Integer> orderItemIds = new HashSet<>();
		boolean permutation = order.size() == size;
		for (Integer itemId : order)
		{
			if (itemId == null || !orderItemIds.add(itemId) || !requestItemIds.contains(itemId))
			{
				permutation = false;
				break;
			}
		}
		permutation = permutation && orderItemIds.size() == requestItemIds.size();

		if (!permutation)
		{
			conflicts.add(new LayoutConflict(LayoutConflict.Type.DENSE_ORDER_NOT_PERMUTATION, LayoutConflict.NO_ITEM,
				"currentDenseCategoryOrder must be an exact unique permutation of all request item IDs"));
		}

		Map<Integer, List<Integer>> itemIdsByRank = new TreeMap<>();
		for (LayoutEntry entry : request.getEntries())
		{
			if (entry == null || !entry.hasDenseCategoryRank())
			{
				continue;
			}

			int itemId = entry.getItem().getItemId();
			int rank = entry.getDenseCategoryRank();
			if (rank < 0 || rank >= size)
			{
				conflicts.add(new LayoutConflict(LayoutConflict.Type.DENSE_RANK_OUT_OF_RANGE, itemId,
					"entry rank " + rank + " is outside 0.." + (size - 1)));
				continue;
			}

			itemIdsByRank.computeIfAbsent(rank, key -> new ArrayList<>()).add(itemId);
			if (permutation)
			{
				int expectedRank = order.indexOf(itemId);
				if (rank != expectedRank)
				{
					conflicts.add(new LayoutConflict(LayoutConflict.Type.DENSE_ORDER_RANK_MISMATCH, itemId,
						"entry rank " + rank + " does not match order rank " + expectedRank));
				}
			}
		}

		for (Map.Entry<Integer, List<Integer>> rank : itemIdsByRank.entrySet())
		{
			if (rank.getValue().size() > 1)
			{
				List<Integer> itemIds = new ArrayList<>(rank.getValue());
				Collections.sort(itemIds);
				conflicts.add(new LayoutConflict(LayoutConflict.Type.DENSE_RANK_DUPLICATE, LayoutConflict.NO_ITEM,
					"rank " + rank.getKey() + " is claimed by items " + itemIds));
			}
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;


/**
 * The immutable outcome of validating or planning one category layout: either a complete list of
 * placements, or a non-empty list of typed conflicts. There is never a partial plan — a conflicted
 * result carries no placements at all.
 */
public final class LayoutResult
{
	private final List<LayoutPlacement> placements;
	private final List<LayoutConflict> conflicts;

	private LayoutResult(List<LayoutPlacement> placements, List<LayoutConflict> conflicts)
	{
		this.placements = placements;
		this.conflicts = conflicts;
	}

	static LayoutResult success(List<LayoutPlacement> placements)
	{
		Objects.requireNonNull(placements, "placements");
		for (LayoutPlacement placement : placements)
		{
			Objects.requireNonNull(placement, "placements must not contain null");
		}

		return new LayoutResult(Collections.unmodifiableList(new ArrayList<>(placements)),
			Collections.emptyList());
	}

	static LayoutResult conflict(List<LayoutConflict> conflicts)
	{
		Objects.requireNonNull(conflicts, "conflicts");
		if (conflicts.isEmpty())
		{
			throw new IllegalArgumentException("a conflicted result requires at least one conflict");
		}
		for (LayoutConflict conflict : conflicts)
		{
			Objects.requireNonNull(conflict, "conflicts must not contain null");
		}

		return new LayoutResult(Collections.emptyList(),
			Collections.unmodifiableList(new ArrayList<>(conflicts)));
	}

	public boolean isSuccess()
	{
		return conflicts.isEmpty();
	}

	public List<LayoutPlacement> getPlacements()
	{
		return placements;
	}

	public List<LayoutConflict> getConflicts()
	{
		return conflicts;
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;


/**
 * The lexicographic layout score: eighteen named non-negative integer components, minimized from
 * left to right. There is no weighted floating-point total, and the {@link DeterministicTieKey}
 * deliberately stays outside this numeric tuple — it is consulted only when two scores are exactly
 * equal, via {@link #compareByScoreThenTieKey}.
 *
 * <p>The two movement components exist only for a proven complete dense category order. Use
 * {@link Builder#movement(LayoutRequest, int, int)} to keep them zero whenever that proof is absent.
 * {@code unrestrictedSwapLowerBound} allows unrestricted swaps and does not model tab transfers or
 * guidance restrictions.</p>
 */
public final class LayoutScore implements Comparable<LayoutScore>
{
	public static final int COMPONENT_COUNT = 18;

	private static final int HIGH_MISSED_RELATIONS = 0;
	private static final int HIGH_MISSED_COMPLETENESS = 1;
	private static final int MEDIUM_MISSED_RELATIONS = 2;
	private static final int MEDIUM_MISSED_COMPLETENESS = 3;
	private static final int LOW_MISSED_RELATIONS = 4;
	private static final int LOW_MISSED_COMPLETENESS = 5;
	private static final int ORIENTATION_EVIDENCE_REGRET = 6;
	private static final int WIDTH_EVIDENCE_REGRET = 7;
	private static final int SEMANTIC_FRAGMENTATION = 8;
	private static final int SEMANTIC_ROW_BREAKS = 9;
	private static final int START_COLUMN_DEVIATION = 10;
	private static final int LOCKED_PREFIX_SPILLOVER = 11;
	private static final int SPILLOVER_COMPATIBILITY_COST = 12;
	private static final int SPILLOVER_TRANSITIONS = 13;
	private static final int NOMINAL_FOOTPRINT_SLACK = 14;
	private static final int SEMANTIC_SPAN = 15;
	private static final int UNRESTRICTED_SWAP_LOWER_BOUND = 16;
	private static final int TOTAL_RANK_DISPLACEMENT = 17;

	private final int[] components;

	private LayoutScore(int[] components)
	{
		this.components = components;
	}

	public static Builder builder()
	{
		return new Builder();
	}

	public static LayoutScore zero()
	{
		return builder().build();
	}

	/**
	 * Compares two complete plans: first by the numeric score tuple, and only when the scores are
	 * exactly equal by the separate deterministic tie key.
	 */
	public static int compareByScoreThenTieKey(LayoutScore leftScore, DeterministicTieKey leftKey,
		LayoutScore rightScore, DeterministicTieKey rightKey)
	{
		int result = leftScore.compareTo(rightScore);
		if (result != 0)
		{
			return result;
		}

		return leftKey.compareTo(rightKey);
	}

	public int getHighMissedRelations()
	{
		return components[HIGH_MISSED_RELATIONS];
	}

	public int getHighMissedCompleteness()
	{
		return components[HIGH_MISSED_COMPLETENESS];
	}

	public int getMediumMissedRelations()
	{
		return components[MEDIUM_MISSED_RELATIONS];
	}

	public int getMediumMissedCompleteness()
	{
		return components[MEDIUM_MISSED_COMPLETENESS];
	}

	public int getLowMissedRelations()
	{
		return components[LOW_MISSED_RELATIONS];
	}

	public int getLowMissedCompleteness()
	{
		return components[LOW_MISSED_COMPLETENESS];
	}

	public int getOrientationEvidenceRegret()
	{
		return components[ORIENTATION_EVIDENCE_REGRET];
	}

	public int getWidthEvidenceRegret()
	{
		return components[WIDTH_EVIDENCE_REGRET];
	}

	public int getSemanticFragmentation()
	{
		return components[SEMANTIC_FRAGMENTATION];
	}

	public int getSemanticRowBreaks()
	{
		return components[SEMANTIC_ROW_BREAKS];
	}

	public int getStartColumnDeviation()
	{
		return components[START_COLUMN_DEVIATION];
	}

	public int getLockedPrefixSpillover()
	{
		return components[LOCKED_PREFIX_SPILLOVER];
	}

	public int getSpilloverCompatibilityCost()
	{
		return components[SPILLOVER_COMPATIBILITY_COST];
	}

	public int getSpilloverTransitions()
	{
		return components[SPILLOVER_TRANSITIONS];
	}

	public int getNominalFootprintSlack()
	{
		return components[NOMINAL_FOOTPRINT_SLACK];
	}

	public int getSemanticSpan()
	{
		return components[SEMANTIC_SPAN];
	}

	public int getUnrestrictedSwapLowerBound()
	{
		return components[UNRESTRICTED_SWAP_LOWER_BOUND];
	}

	public int getTotalRankDisplacement()
	{
		return components[TOTAL_RANK_DISPLACEMENT];
	}

	/**
	 * The full component tuple in comparison order, as a defensive copy.
	 */
	public int[] toComponentArray()
	{
		return Arrays.copyOf(components, components.length);
	}

	int componentAt(int index)
	{
		return components[index];
	}

	@Override
	public int compareTo(LayoutScore other)
	{
		for (int index = 0; index < COMPONENT_COUNT; index++)
		{
			int result = Integer.compare(components[index], other.components[index]);
			if (result != 0)
			{
				return result;
			}
		}

		return 0;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof LayoutScore))
		{
			return false;
		}

		return Arrays.equals(components, ((LayoutScore) other).components);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(components);
	}

	@Override
	public String toString()
	{
		return "LayoutScore" + Arrays.toString(components);
	}

	public static final class Builder
	{
		private final int[] components = new int[COMPONENT_COUNT];

		private Builder()
		{
		}

		public Builder highMissedRelations(int value)
		{
			return set(HIGH_MISSED_RELATIONS, value, "highMissedRelations");
		}

		public Builder highMissedCompleteness(int value)
		{
			return set(HIGH_MISSED_COMPLETENESS, value, "highMissedCompleteness");
		}

		public Builder mediumMissedRelations(int value)
		{
			return set(MEDIUM_MISSED_RELATIONS, value, "mediumMissedRelations");
		}

		public Builder mediumMissedCompleteness(int value)
		{
			return set(MEDIUM_MISSED_COMPLETENESS, value, "mediumMissedCompleteness");
		}

		public Builder lowMissedRelations(int value)
		{
			return set(LOW_MISSED_RELATIONS, value, "lowMissedRelations");
		}

		public Builder lowMissedCompleteness(int value)
		{
			return set(LOW_MISSED_COMPLETENESS, value, "lowMissedCompleteness");
		}

		public Builder orientationEvidenceRegret(int value)
		{
			return set(ORIENTATION_EVIDENCE_REGRET, value, "orientationEvidenceRegret");
		}

		public Builder widthEvidenceRegret(int value)
		{
			return set(WIDTH_EVIDENCE_REGRET, value, "widthEvidenceRegret");
		}

		public Builder semanticFragmentation(int value)
		{
			return set(SEMANTIC_FRAGMENTATION, value, "semanticFragmentation");
		}

		public Builder semanticRowBreaks(int value)
		{
			return set(SEMANTIC_ROW_BREAKS, value, "semanticRowBreaks");
		}

		public Builder startColumnDeviation(int value)
		{
			return set(START_COLUMN_DEVIATION, value, "startColumnDeviation");
		}

		public Builder lockedPrefixSpillover(int value)
		{
			return set(LOCKED_PREFIX_SPILLOVER, value, "lockedPrefixSpillover");
		}

		public Builder spilloverCompatibilityCost(int value)
		{
			return set(SPILLOVER_COMPATIBILITY_COST, value, "spilloverCompatibilityCost");
		}

		public Builder spilloverTransitions(int value)
		{
			return set(SPILLOVER_TRANSITIONS, value, "spilloverTransitions");
		}

		public Builder nominalFootprintSlack(int value)
		{
			return set(NOMINAL_FOOTPRINT_SLACK, value, "nominalFootprintSlack");
		}

		public Builder semanticSpan(int value)
		{
			return set(SEMANTIC_SPAN, value, "semanticSpan");
		}

		/**
		 * The only way to set the two movement components ({@code unrestrictedSwapLowerBound} and
		 * {@code totalRankDisplacement}): there are deliberately no direct setters. Without a
		 * validated request carrying a proven complete dense category order both components are forced
		 * to zero for every plan, regardless of the supplied values.
		 */
		public Builder movement(LayoutRequest request, int unrestrictedSwapLowerBound,
			int totalRankDisplacement)
		{
			Objects.requireNonNull(request, "request");
			boolean provenCompleteDenseOrder = request.hasCurrentDenseCategoryOrder()
				&& LayoutRequestValidator.validate(request).isEmpty();
			if (!provenCompleteDenseOrder)
			{
				return set(UNRESTRICTED_SWAP_LOWER_BOUND, 0, "unrestrictedSwapLowerBound")
					.set(TOTAL_RANK_DISPLACEMENT, 0, "totalRankDisplacement");
			}

			return set(UNRESTRICTED_SWAP_LOWER_BOUND, unrestrictedSwapLowerBound, "unrestrictedSwapLowerBound")
				.set(TOTAL_RANK_DISPLACEMENT, totalRankDisplacement, "totalRankDisplacement");
		}

		public LayoutScore build()
		{
			return new LayoutScore(Arrays.copyOf(components, components.length));
		}

		private Builder set(int index, int value, String name)
		{
			if (value < 0)
			{
				throw new IllegalArgumentException(name + " must not be negative");
			}

			components[index] = value;
			return this;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.organize.*;
import java.util.*;
import java.util.List;



/** Reviewed quick-access geometry for the active Ironman main tab. */
public final class MainQuickAccessSemanticRuleSet
{
	private static final String GRACEFUL_FAMILY_PREFIX = "tools.graceful-";
	private static final String GRACEFUL_BASE_FAMILY = "tools.graceful-base";
	/** Wear order, which is not catalogue order: the cape reads last, as it did. */
	private static final List<String> GRACEFUL_PIECE_ORDER = Collections.unmodifiableList(
		Arrays.asList("graceful hood", "graceful top", "graceful legs",
			"graceful gloves", "graceful boots", "graceful cape"));
	private static final int GRACEFUL_COLUMN = 7;
	private static final int RUNE_BLOCK_SECOND_ROW = 8;

	private MainQuickAccessSemanticRuleSet()
	{
	}

	public static LayoutRequest forEntries(List<LayoutEntry> entries)
	{
		Objects.requireNonNull(entries, "entries");
		List<LayoutEntry> nativeEntries = new ArrayList<>();
		List<LayoutEntry> reassigned = new ArrayList<>();
		for (LayoutEntry entry : entries)
		{
			(BankTags.hasDifferentMainTag(entry.getItem()) ? reassigned : nativeEntries).add(entry);
		}
		if (!reassigned.isEmpty())
		{
			// Retagged runes/tools must not be pulled back into their old
			// geometry. They remain real entries placed by the effective order.
			LayoutRequest nativeRequest = forEntries(nativeEntries);
			List<LayoutEntry> combined = new ArrayList<>(nativeRequest.getEntries());
			combined.addAll(reassigned);
			return new LayoutRequest(combined, nativeRequest.getRules());
		}
		List<LayoutEntry> anchored = anchorReviewedTargets(entries);
		List<SemanticRule> rules = new ArrayList<>(
			AchievementDiarySemanticRuleSet.forEntries(anchored).getRules());
		SemanticRule graceful = gracefulRule(anchored);
		if (graceful != null)
		{
			rules.add(graceful);
		}
		SemanticRule quickTools = quickToolRule(anchored);
		if (quickTools != null)
		{
			rules.add(quickTools);
		}
		rules.addAll(RuneSemanticRuleSet.forMainEntries(anchored).getRules());
		return new LayoutRequest(anchored, rules);
	}

	private static List<LayoutEntry> anchorReviewedTargets(List<LayoutEntry> entries)
	{
		for (LayoutEntry entry : entries)
		{
			if (entry.hasLockedTarget())
			{
				return entries;
			}
		}
		int ownedGraceful = gracefulColumn(entries).size();
		boolean anchorGraceful = ownedGraceful >= 2
			&& GRACEFUL_COLUMN + (ownedGraceful - 1) * SemanticRule.MAX_WIDTH < entries.size();
		boolean hasCoins = contains(entries, 995);
		boolean hasQuickTools = !presentQuickTools(entries).isEmpty();
		int runeTarget = hasCoins || hasQuickTools ? RUNE_BLOCK_SECOND_ROW : 0;
		Map<Integer, Integer> runeTargets = runeTargets(entries, runeTarget);
		Map<Integer, Integer> gracefulTargets = gracefulTargets(entries, anchorGraceful);
		Map<Integer, Integer> quickToolTargets = quickToolTargets(entries, hasCoins ? 1 : 0);

		List<LayoutEntry> anchored = new ArrayList<>(entries.size());
		for (LayoutEntry entry : entries)
		{
			if (entry.getItem().getItemId() == 995)
			{
				anchored.add(entry.withLockedTarget(0));
			}
			else if (gracefulTargets.containsKey(entry.getItem().getItemId()))
			{
				anchored.add(entry.withLockedTarget(gracefulTargets.get(entry.getItem().getItemId())));
			}
			else if (runeTargets.containsKey(entry.getItem().getItemId()))
			{
				anchored.add(entry.withLockedTarget(runeTargets.get(entry.getItem().getItemId())));
			}
			else if (quickToolTargets.containsKey(entry.getItem().getItemId()))
			{
				anchored.add(entry.withLockedTarget(quickToolTargets.get(entry.getItem().getItemId())));
			}
			else
			{
				anchored.add(entry);
			}
		}
		return Collections.unmodifiableList(anchored);
	}

	private static Map<Integer, Integer> gracefulTargets(List<LayoutEntry> entries,
		boolean anchorGraceful)
	{
		Map<Integer, Integer> targets = new LinkedHashMap<>();
		if (!anchorGraceful) return targets;
		int row = 0;
		for (Integer itemId : gracefulColumn(entries))
		{
			targets.put(itemId, GRACEFUL_COLUMN + row++ * 8);
		}
		return targets;
	}

	private static Map<Integer, Integer> runeTargets(List<LayoutEntry> entries, int startTarget)
	{
		Map<Integer, Integer> targets = new LinkedHashMap<>();
		List<List<Integer>> rows = RuneSemanticRuleSet.mainRows(entries);
		for (int row = 0; row < rows.size(); row++)
		{
			int column = 0;
			for (Integer itemId : rows.get(row))
			{
				if (contains(entries, itemId)) targets.put(itemId, startTarget + row * 8 + column++);
			}
		}
		for (Integer target : targets.values())
		{
			if (target >= entries.size()) return Collections.emptyMap();
		}
		return targets;
	}

	private static Map<Integer, Integer> quickToolTargets(List<LayoutEntry> entries, int startTarget)
	{
		Map<Integer, Integer> targets = new LinkedHashMap<>();
		List<Integer> tools = presentQuickTools(entries);
		if (startTarget % 8 + tools.size() > 8 || startTarget + tools.size() > entries.size())
		{
			return targets;
		}
		for (int index = 0; index < tools.size(); index++)
		{
			targets.put(tools.get(index), startTarget + index);
		}
		return targets;
	}

	/** Canonical compact Main run: best axe, best pickaxe, hammer, chisel, spade. */
	private static SemanticRule quickToolRule(List<LayoutEntry> entries)
	{
		List<Integer> tools = presentQuickTools(entries);
		if (tools.size() < 2) return null;
		List<SemanticAtom.Member> members = new ArrayList<>();
		for (int index = 0; index < tools.size(); index++)
		{
			members.add(new SemanticAtom.Member("quick-tool-" + index, tools.get(index)));
		}
		return SemanticRule.builder()
			.ruleKey("main.quick-tools")
			.atoms(Collections.singletonList(new SemanticAtom("main.quick-tools", members)))
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.HORIZONTAL_RUN)
			.allowedWidths(Collections.singleton(tools.size()))
			.build();
	}

	private static List<Integer> presentQuickTools(List<LayoutEntry> entries)
	{
		List<Integer> tools = new ArrayList<>();
		for (int rank = 0; rank < 5; rank++)
		{
			for (LayoutEntry entry : entries)
			{
				if (IronmanQuickToolSelector.quickAccessRank(entry.getItem().getItemId()) == rank)
				{
					tools.add(entry.getItem().getItemId());
					break;
				}
			}
		}
		return Collections.unmodifiableList(tools);
	}

	/**
	 * The graceful pieces this tab stands in a column, in wear order.
	 *
	 * <p>Read from the tab rather than from a list of IDs, so the column
	 * follows whichever set actually reached the tab. A player who files their
	 * old set with the tools and their new one here gets the column on the new
	 * one, without the plugin having an opinion about which recolour is the
	 * real one. Owning two and saying nothing gives the column to the more
	 * complete set, and the base set breaks a tie.</p>
	 */
	private static List<Integer> gracefulColumn(List<LayoutEntry> entries)
	{
		Map<String, List<LayoutEntry>> byFamily = new java.util.TreeMap<>();
		for (LayoutEntry entry : entries)
		{
			String key = ItemSetCatalog.setKeyOf(entry.getItem().getItemId()).orElse("");
			if (key.startsWith(GRACEFUL_FAMILY_PREFIX))
			{
				byFamily.computeIfAbsent(key, ignored -> new ArrayList<>()).add(entry);
			}
		}

		List<LayoutEntry> chosen = Collections.emptyList();
		for (Map.Entry<String, List<LayoutEntry>> family : byFamily.entrySet())
		{
			boolean better = family.getValue().size() > chosen.size()
				|| (family.getValue().size() == chosen.size()
					&& GRACEFUL_BASE_FAMILY.equals(family.getKey()));
			if (better)
			{
				chosen = family.getValue();
			}
		}

		List<Integer> column = new ArrayList<>(chosen.size());
		for (String piece : GRACEFUL_PIECE_ORDER)
		{
			for (LayoutEntry entry : chosen)
			{
				if (piece.equalsIgnoreCase(entry.getItem().getDisplayName().trim()))
				{
					column.add(entry.getItem().getItemId());
				}
			}
		}
		// A piece whose name does not read like the others still belongs to the
		// set, so it follows rather than being dropped from its own column.
		for (LayoutEntry entry : chosen)
		{
			if (!column.contains(entry.getItem().getItemId()))
			{
				column.add(entry.getItem().getItemId());
			}
		}
		return column;
	}

	private static SemanticRule gracefulRule(List<LayoutEntry> entries)
	{
		List<SemanticAtom.Member> members = new ArrayList<>();
		for (Integer itemId : gracefulColumn(entries))
		{
			members.add(new SemanticAtom.Member("slot-" + members.size(), itemId));
		}
		if (members.size() < 2)
		{
			return null;
		}
		return SemanticRule.builder()
			.ruleKey("main.graceful-column")
			.atoms(Collections.singletonList(new SemanticAtom("outfit.graceful", members)))
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.VERTICAL_RUN)
			.allowedWidths(Collections.singleton(1))
			.build();
	}

	private static boolean contains(List<LayoutEntry> entries, int itemId)
	{
		for (LayoutEntry entry : entries)
		{
			if (entry.getItem().getItemId() == itemId) return true;
		}
		return false;
	}

}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.catalog.*;
import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.*;
import java.util.List;


/**
 * Packs a category by following the sorter's order. The real bank always
 * compacts, so density is never a choice — the only decision is what happens
 * when a semantic family (a charge set, an outfit) meets the end of a row.
 * Single items are never plucked out of their flow to fix it: the family is
 * the movable thing, sliding behind the whole run of singles that follows it
 * until it finds a gap it fits cleanly, and wrapping in place when none is
 * near.
 *
 * <p>Everything else about the sorter's sequence is preserved. The item a
 * player expects first is first; nothing jumps the queue to make a rectangle
 * work out.</p>
 */
final class OrderPreservingPacker
{
	/** How far ahead a row may borrow singles from, in sequence positions. */
	private static final int NUDGE_WINDOW = 2 * SemanticRule.MAX_WIDTH;
	private static final int GRID_COLUMNS = SemanticRule.MAX_WIDTH;

	private OrderPreservingPacker()
	{
	}

	static LayoutResult pack(LayoutRequest request, List<Integer> fallbackItemIds)
	{
		Map<Integer, BankPreviewItem> itemsById = new HashMap<>();
		for (LayoutEntry entry : request.getEntries())
		{
			itemsById.put(entry.getItem().getItemId(), entry.getItem());
		}

		// An item belongs to the first atom that names it; a family is a run of
		// consecutive fallback items under one atom. A rule can hold many
		// families (every potion's doses under one rule), so the atom is the
		// unit that must stay whole. The sorter already placed family members
		// side by side, so runs are how families arrive here.
		Map<Integer, String> ruleKeyByItemId = new HashMap<>();
		for (SemanticRule rule : request.getRules())
		{
			for (SemanticAtom atom : rule.getAtoms())
			{
				for (Integer itemId : atom.getItemIds())
				{
					ruleKeyByItemId.putIfAbsent(itemId, rule.getRuleKey() + "/" + atom.getAtomKey());
				}
			}
		}
		// Charge and dose families are families even when no rule names them:
		// a run of glories must neither wrap mid-family nor be broken up to
		// serve as a nudge for someone else's row.
		for (Integer itemId : fallbackItemIds)
		{
			ResourceItemSortMetadataCatalog.INSTANCE.findById(itemId)
				.filter(metadata -> metadata.getVariantKind() == ItemSortMetadata.VariantKind.CHARGE
					|| metadata.getVariantKind() == ItemSortMetadata.VariantKind.DOSE)
				.ifPresent(metadata ->
					ruleKeyByItemId.putIfAbsent(itemId, "family:" + metadata.getFamilyKey()));
		}

		List<List<Integer>> blocks = toBlocks(fallbackItemIds, ruleKeyByItemId);

		// Place blocks in order. When a family block would straddle a row edge,
		// borrow the next few singles from the window ahead to finish the row.
		Map<Integer, Boolean> placed = new LinkedHashMap<>();
		List<Integer> laidOut = new ArrayList<>(fallbackItemIds.size());
		int column = Math.floorMod(request.getGridStartColumn(), GRID_COLUMNS);
		for (int blockIndex = 0; blockIndex < blocks.size(); blockIndex++)
		{
			List<Integer> block = blocks.get(blockIndex);
			List<Integer> pending = new ArrayList<>();
			for (Integer itemId : block)
			{
				if (!placed.containsKey(itemId))
				{
					pending.add(itemId);
				}
			}
			if (pending.isEmpty())
			{
				continue;
			}

			int gap = (GRID_COLUMNS - column) % GRID_COLUMNS;
			boolean isFamily = pending.size() > 1 && pending.size() <= GRID_COLUMNS;
			boolean wouldStraddle = gap != 0 && pending.size() > gap;
			if (isFamily && wouldStraddle)
			{
				// The family slides behind the run of singles that follows it,
				// as far as the run reaches, to the latest point it still fits
				// a row cleanly. The singles' own order is never disturbed.
				List<Integer> run = consecutiveSingles(blocks, blockIndex + 1, placed);
				for (int deferred = run.size(); deferred > 0; deferred--)
				{
					int columnAfter = (column + deferred) % GRID_COLUMNS;
					int gapAfter = (GRID_COLUMNS - columnAfter) % GRID_COLUMNS;
					if (gapAfter == 0 || gapAfter >= pending.size())
					{
						for (Integer itemId : run.subList(0, deferred))
						{
							placed.put(itemId, Boolean.TRUE);
							laidOut.add(itemId);
						}
						column = columnAfter;
						break;
					}
				}
			}

			for (Integer itemId : pending)
			{
				placed.put(itemId, Boolean.TRUE);
				laidOut.add(itemId);
				column = (column + 1) % GRID_COLUMNS;
			}
		}

		List<LayoutPlacement> placements = new ArrayList<>(laidOut.size());
		for (int index = 0; index < laidOut.size(); index++)
		{
			placements.add(new LayoutPlacement(itemsById.get(laidOut.get(index)), index));
		}
		return LayoutResult.success(placements);
	}

	private static List<List<Integer>> toBlocks(List<Integer> fallbackItemIds,
		Map<Integer, String> ruleKeyByItemId)
	{
		List<List<Integer>> blocks = new ArrayList<>();
		List<Integer> current = new ArrayList<>();
		String currentKey = null;
		for (Integer itemId : fallbackItemIds)
		{
			String key = ruleKeyByItemId.get(itemId);
			boolean continuesRun = !current.isEmpty() && currentKey != null && currentKey.equals(key);
			if (!continuesRun && !current.isEmpty())
			{
				blocks.add(current);
				current = new ArrayList<>();
			}
			if (key == null)
			{
				// A single is its own block, so it can be borrowed as a nudge.
				blocks.add(new ArrayList<>(List.of(itemId)));
				currentKey = null;
				continue;
			}
			current.add(itemId);
			currentKey = key;
		}
		if (!current.isEmpty())
		{
			blocks.add(current);
		}
		return blocks;
	}

	/** The unbroken run of single items directly after a block, within the window. */
	private static List<Integer> consecutiveSingles(List<List<Integer>> blocks, int fromBlock,
		Map<Integer, Boolean> placed)
	{
		List<Integer> run = new ArrayList<>();
		for (int index = fromBlock; index < blocks.size() && run.size() < NUDGE_WINDOW; index++)
		{
			List<Integer> block = blocks.get(index);
			if (block.size() != 1 || placed.containsKey(block.get(0)))
			{
				break;
			}
			run.add(block.get(0));
		}
		return run;
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.List;
import java.util.Objects;

/**
 * Immutable positioned candidate geometry and identity for DeterministicTieKey. Identity and
 * geometry derive from one candidate; width rank derives from its validated group. Equality
 * includes all fields, physical position and internal geometry.
 */
public final class PlacedBlock
{
	private final LayoutCandidate candidate;
	private final int widthPreferenceRank;
	private final int startRow;
	private final int startColumn;

	private PlacedBlock(LayoutCandidate candidate, int widthPreferenceRank, int startRow, int startColumn)
	{
		this.candidate = Objects.requireNonNull(candidate, "candidate");
		this.widthPreferenceRank = widthPreferenceRank;
		if (startRow < 0)
		{
			throw new IllegalArgumentException("startRow must not be negative");
		}
		this.startRow = startRow;
		if (startColumn < 0 || startColumn >= SemanticRule.MAX_WIDTH)
		{
			throw new IllegalArgumentException("startColumn must be within 0.." + (SemanticRule.MAX_WIDTH - 1));
		}
		if (startColumn > SemanticRule.MAX_WIDTH - candidate.getWidth())
		{
			throw new IllegalArgumentException("block with start column " + startColumn + " and width "
				+ candidate.getWidth()
				+ " does not fit the eight-column grid");
		}
		this.startColumn = startColumn;
	}

	static PlacedBlock place(LayoutCandidateGroup group, LayoutCandidate candidate,
		int startRow, int startColumn)
	{
		Objects.requireNonNull(group, "group");
		int widthPreferenceRank = LayoutCandidateScorer.widthPreferenceRank(group, candidate);
		return new PlacedBlock(candidate, widthPreferenceRank, startRow, startColumn);
	}

	public String getRuleKey()
	{
		return candidate.getRuleKey();
	}

	public List<String> getAtomKeys()
	{
		return candidate.getAtomKeys();
	}

	public int getWidthPreferenceRank()
	{
		return widthPreferenceRank;
	}

	public int getWidth()
	{
		return candidate.getWidth();
	}

	public ShapePrimitive getShapePrimitive()
	{
		return candidate.getShapePrimitive();
	}

	public int getStartRow()
	{
		return startRow;
	}

	public int getStartColumn()
	{
		return startColumn;
	}

	public List<LayoutCandidate.Row> getRows()
	{
		return candidate.getRows();
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof PlacedBlock))
		{
			return false;
		}

		PlacedBlock block = (PlacedBlock) other;
		return widthPreferenceRank == block.widthPreferenceRank
			&& startRow == block.startRow
			&& startColumn == block.startColumn
			&& candidate.equals(block.candidate);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(candidate, widthPreferenceRank, startRow, startColumn);
	}

	@Override
	public String toString()
	{
		return "PlacedBlock{" + getRuleKey() + ", atoms=" + getAtomKeys() + ", prefRank="
			+ widthPreferenceRank + ", width=" + getWidth() + ", " + getShapePrimitive() + ", start=("
			+ startRow + "," + startColumn + "), rows=" + getRows() + "}";
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.catalog.*;
import java.util.*;
import java.util.List;



/**
 * Exact canonical potion-dose families used by the supplies-category semantic layout. Each owned
 * family projects to a horizontal run in reviewed descending-dose order without name inference.
 */
public final class PotionDoseSemanticRuleSet
{
	private static final String RULE_KEY = "potion.dose-runs";
	private static final Set<Integer> ALL_WIDTHS = Collections.unmodifiableSet(
		new LinkedHashSet<>(Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8)));

	private static final OrderedItemFamilies FAMILIES = new OrderedItemFamilies(
		PotionDoseSemanticRuleSet.class.getResourceAsStream(
			"/com/pkoka5/ironmanbankarchitect/catalog/potion-layout-families.tsv"), 4);

	private PotionDoseSemanticRuleSet()
	{
	}

	/**
	 * Creates a request without claiming a dense current order or adding entry-level dense ranks.
	 */
	public static LayoutRequest forEntries(List<LayoutEntry> entries)
	{
		Objects.requireNonNull(entries, "entries");
		validateMetadata();
		return new LayoutRequest(entries, Collections.singletonList(buildRule()));
	}

	private static SemanticRule buildRule()
	{
		List<SemanticAtom> atoms = new ArrayList<>(FAMILIES.entries().size());
		for (Map.Entry<String, List<Integer>> family : FAMILIES.entries().entrySet())
		{
			List<SemanticAtom.Member> members = new ArrayList<>();
			for (int index = 0; index < 4; index++)
			{
				members.add(new SemanticAtom.Member("dose-" + (4 - index), family.getValue().get(index)));
			}
			atoms.add(new SemanticAtom(family.getKey(), members));
		}

		return SemanticRule.builder()
			.ruleKey(RULE_KEY)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.HORIZONTAL_RUN)
			.allowedWidths(ALL_WIDTHS)
			.build();
	}

	private static void validateMetadata()
	{
		for (Map.Entry<String, List<Integer>> family : FAMILIES.entries().entrySet())
		{
			for (int index = 0; index < family.getValue().size(); index++)
			{
				validateMember(family.getKey(), family.getValue().get(index), 4 - index);
			}
		}
	}

	private static void validateMember(String expectedFamilyKey, int itemId, int expectedDose)
	{
		ItemSortMetadata metadata = ResourceItemSortMetadataCatalog.INSTANCE.findById(itemId)
			.orElseThrow(() -> new IllegalStateException(
				"Missing potion semantic metadata for itemId " + itemId));
		if (!expectedFamilyKey.equals(metadata.getFamilyKey())
			|| metadata.getVariantKind() != ItemSortMetadata.VariantKind.DOSE
			|| metadata.getVariantValue() != expectedDose)
		{
			throw new IllegalStateException("Potion semantic metadata mismatch for itemId " + itemId
				+ ": expected family=" + expectedFamilyKey + ", kind=DOSE, dose=" + expectedDose
				+ " but was family=" + metadata.getFamilyKey() + ", kind="
				+ metadata.getVariantKind() + ", dose=" + metadata.getVariantValue());
		}
	}

}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.catalog.*;
import java.util.*;
import java.util.List;



/**
 * Exact canonical resource relationships used by the category-level semantic layout engine.
 * Display names are deliberately absent: every family and stage is validated against the local
 * curated metadata before a request is created.
 */
public final class ResourceSemanticRuleSet
{
	private static final String METAL_RULE_KEY = "resource.metal.material-rows";
	private static final String PRESENT_MATERIAL_ROWS_RULE_KEY = "resource.material.present-rows";
	private static final String GEM_RULE_KEY = "resource.gem.raw-processed";
	private static final String WOOD_RULE_KEY = "resource.wood.material-rows";
	private static final String CRAFTING_RULE_KEY = "resource.crafting.workflow-rows";
	private static final String FLETCHING_RULE_KEY = "resource.fletching.tier-runs";

	private static final Set<Integer> ALL_WIDTHS = Collections.unmodifiableSet(
		new LinkedHashSet<>(Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8)));

	private static final OrderedItemFamilies TABLE = new OrderedItemFamilies(
		ResourceSemanticRuleSet.class.getResourceAsStream(
			"/com/pkoka5/ironmanbankarchitect/catalog/resource-layout-families.tsv"), 0, false);
	private static final RequiredResource<Data> DATA = new RequiredResource<>("resource layout", Data::new);

	private static final class Data
	{
		private final List<RowFact> metalRows = rows("METAL_ROWS");
		private final List<FamilyFact> metalFamilies = families("METAL_FAMILIES");
		private final List<Integer> metalSpilloverOres = TABLE.ids("METAL_SPILLOVER_ORES");
		private final List<Integer> metalSpilloverBars = TABLE.ids("METAL_SPILLOVER_BARS");
		private final List<Integer> sailingOres = TABLE.ids("SAILING_ORES");
		private final List<Integer> sailingProcessedMetals = TABLE.ids("SAILING_PROCESSED_METALS");
		private final List<Integer> supplementalMiningMaterials = TABLE.ids("SUPPLEMENTAL_MINING_MATERIALS");

		private final FamilyFact opalFamily = families("OPAL_FAMILY").get(0);
		private final List<FamilyFact> gemFamilies = families("GEM_FAMILIES");

		private final List<RowFact> woodRows = rows("WOOD_ROWS");

		private final List<RowFact> craftingRows = rows("CRAFTING_ROWS");

		private final List<RowFact> fletchingRows = rows("FLETCHING_ROWS");
		private final List<Integer> fletchingStringComponents = TABLE.ids("FLETCHING_STRING_COMPONENTS");
		private final List<Integer> fletchingSpecialComponents = TABLE.ids("FLETCHING_SPECIAL_COMPONENTS");

		private final List<SemanticRule> rules = Collections.unmodifiableList(Arrays.asList(
			stageMatrix(METAL_RULE_KEY, metalFamilies, null),
			stageMatrix(GEM_RULE_KEY, gemFamilies, SemanticWidthEvidenceFacts.GEM_RAW_PROCESSED),
			rowGroupMatrix(WOOD_RULE_KEY, woodRows),
			rowGroupMatrix(CRAFTING_RULE_KEY, craftingRows),
			horizontalRuns(FLETCHING_RULE_KEY, fletchingRows)));
	}

	private static List<RowFact> rows(String group)
	{
		List<RowFact> rows = new ArrayList<>();
		TABLE.group(group).forEach((key, ids) -> rows.add(new RowFact(key, ids)));
		return Collections.unmodifiableList(rows);
	}

	private static List<FamilyFact> families(String group)
	{
		List<FamilyFact> families = new ArrayList<>();
		TABLE.group(group).forEach((key, ids) ->
		{
			if (ids.size() != 2) throw new IllegalStateException("Invalid resource family: " + key);
			families.add(new FamilyFact(key, ids.get(0), ids.get(1)));
		});
		return Collections.unmodifiableList(families);
	}

	private ResourceSemanticRuleSet()
	{
	}

	/**
	 * Creates a request without claiming a dense current order or adding entry-level dense ranks.
	 * Flat source bank slots retain only their placement-context meaning.
	 */
	public static LayoutRequest forEntries(List<LayoutEntry> entries)
	{
		Objects.requireNonNull(entries, "entries");
		validateRows(DATA.get().metalRows);
		validateMetadata(Collections.singletonList(DATA.get().opalFamily));
		validateMetadata(DATA.get().gemFamilies);
		validateRows(DATA.get().woodRows);
		validateRows(DATA.get().craftingRows);
		validateRows(DATA.get().fletchingRows);
		return new LayoutRequest(anchoredEntries(entries), rulesForEntries(entries));
	}

	/**
	 * Creates a request for entries already restricted to one {@code ResourceSkillZone}. A zone's
	 * physical window can be too small to hold a {@code ROW_GROUP_MATRIX} rule's full coupled block
	 * (all its rows share one origin and are placed as an all-or-nothing unit), so every such rule
	 * is decoupled here into independently placeable {@code HORIZONTAL_RUN} rows. Declared row order
	 * is preserved via an ordinal rule-key prefix so tie-breaking never falls back to alphabetical
	 * atom-key order. Metal/gem stage matrices and existing horizontal-run rules are unaffected.
	 */
	public static LayoutRequest forZoneEntries(List<LayoutEntry> entries)
	{
		Objects.requireNonNull(entries, "entries");
		validateRows(DATA.get().metalRows);
		validateMetadata(Collections.singletonList(DATA.get().opalFamily));
		validateMetadata(DATA.get().gemFamilies);
		validateRows(DATA.get().woodRows);
		validateRows(DATA.get().craftingRows);
		validateRows(DATA.get().fletchingRows);
		return new LayoutRequest(anchoredEntries(entries),
			decoupleRowGroupMatrices(rulesForEntries(entries)));
	}

	private static List<SemanticRule> decoupleRowGroupMatrices(List<SemanticRule> rules)
	{
		List<SemanticRule> decoupled = new ArrayList<>();
		for (SemanticRule rule : rules)
		{
			if (rule.getShapePrimitive() != ShapePrimitive.ROW_GROUP_MATRIX)
			{
				decoupled.add(rule);
				continue;
			}

			List<SemanticAtom> atoms = rule.getAtoms();
			for (int index = 0; index < atoms.size(); index++)
			{
				SemanticAtom atom = atoms.get(index);
				SemanticRule.Builder builder = SemanticRule.builder()
					.ruleKey(String.format("zone-row-%02d.%s", index, atom.getAtomKey()))
					.atoms(Collections.singletonList(atom))
					.confidenceTier(rule.getConfidenceTier())
					.shapePrimitive(ShapePrimitive.HORIZONTAL_RUN)
					.allowedWidths(rule.getAllowedWidths());
				if (rule.hasWidthEvidence())
				{
					builder.widthEvidence(rule.getWidthEvidence());
				}
				if (!rule.getSpilloverCompatibleRuleKeys().isEmpty())
				{
					builder.spilloverCompatibleRuleKeys(rule.getSpilloverCompatibleRuleKeys());
				}
				decoupled.add(builder.build());
			}
		}
		return Collections.unmodifiableList(decoupled);
	}

	private static List<LayoutEntry> anchoredEntries(List<LayoutEntry> entries)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			present.add(entry.getItem().getItemId());
			if (entry.hasLockedTarget())
			{
				return entries;
			}
		}
		if (Collections.disjoint(present, DATA.get().supplementalMiningMaterials))
		{
			return entries;
		}

		List<Integer> anchorOrder = new ArrayList<>();
		for (FamilyFact family : DATA.get().metalFamilies)
		{
			anchorOrder.add(family.rawItemId);
		}
		for (FamilyFact family : DATA.get().metalFamilies)
		{
			anchorOrder.add(family.processedItemId);
		}
		anchorOrder.addAll(DATA.get().metalSpilloverOres);
		anchorOrder.addAll(DATA.get().metalSpilloverBars);
		anchorOrder.addAll(DATA.get().sailingOres);
		anchorOrder.addAll(DATA.get().sailingProcessedMetals);
		anchorOrder.addAll(DATA.get().supplementalMiningMaterials);
		for (Integer anchorItemId : anchorOrder)
		{
			if (!present.contains(anchorItemId))
			{
				continue;
			}
			List<LayoutEntry> anchored = new ArrayList<>(entries.size());
			for (LayoutEntry entry : entries)
			{
				anchored.add(entry.getItem().getItemId() == anchorItemId
					? entry.withLockedTarget(0) : entry);
			}
			return Collections.unmodifiableList(anchored);
		}
		return entries;
	}

	private static List<SemanticRule> rulesForEntries(List<LayoutEntry> entries)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			present.add(entry.getItem().getItemId());
		}
		if (Collections.disjoint(present, DATA.get().supplementalMiningMaterials))
		{
			return DATA.get().rules;
		}

		List<SemanticRule> rules = new ArrayList<>();
		rules.add(stageMatrix(METAL_RULE_KEY, DATA.get().metalFamilies, null));
		rules.add(presentMaterialRule(present));
		return Collections.unmodifiableList(rules);
	}

	private static SemanticRule presentMaterialRule(Set<Integer> present)
	{
		List<SemanticAtom> atoms = new ArrayList<>();
		addPresentChunks(atoms, "metal.ores-spillover", DATA.get().metalSpilloverOres, present);
		addPresentChunks(atoms, "metal.bars-spillover", DATA.get().metalSpilloverBars, present);
		addPresentChunks(atoms, "sailing.ores", DATA.get().sailingOres, present);
		addPresentChunks(atoms, "sailing.processed-metals", DATA.get().sailingProcessedMetals, present);
		addPresentChunks(atoms, "mining.supplemental", DATA.get().supplementalMiningMaterials, present);
		for (RowFact row : DATA.get().woodRows)
		{
			addPresentChunks(atoms, row.familyKey, row.itemIds, present);
		}
		addPresentGemStages(atoms, present);
		for (RowFact row : DATA.get().craftingRows)
		{
			addPresentChunks(atoms, row.familyKey, row.itemIds, present);
		}
		addCompactPresentFletchingRows(atoms, present);

		return SemanticRule.builder()
			.ruleKey(PRESENT_MATERIAL_ROWS_RULE_KEY)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.ROW_GROUP_MATRIX)
			.allowedWidths(ALL_WIDTHS)
			.build();
	}

	private static void addCompactPresentFletchingRows(List<SemanticAtom> atoms, Set<Integer> present)
	{
		List<List<Integer>> families = Arrays.asList(
			DATA.get().fletchingRows.get(0).itemIds,
			DATA.get().fletchingStringComponents,
			DATA.get().fletchingRows.get(1).itemIds,
			DATA.get().fletchingRows.get(2).itemIds,
			DATA.get().fletchingRows.get(3).itemIds,
			DATA.get().fletchingSpecialComponents,
			DATA.get().fletchingRows.get(4).itemIds,
			DATA.get().fletchingRows.get(5).itemIds);
		List<Integer> packedRow = new ArrayList<>();
		int rowIndex = 0;
		for (List<Integer> family : families)
		{
			List<Integer> ownedFamily = new ArrayList<>();
			for (Integer itemId : family)
			{
				if (present.contains(itemId))
				{
					ownedFamily.add(itemId);
				}
			}
			if (ownedFamily.isEmpty())
			{
				continue;
			}
			if (!packedRow.isEmpty() && packedRow.size() + ownedFamily.size() > 8)
			{
				addPresentChunks(atoms, "fletching.owned-workflows-" + rowIndex++, packedRow, present);
				packedRow = new ArrayList<>();
			}
			packedRow.addAll(ownedFamily);
			if (packedRow.size() == 8)
			{
				addPresentChunks(atoms, "fletching.owned-workflows-" + rowIndex++, packedRow, present);
				packedRow = new ArrayList<>();
			}
		}
		if (!packedRow.isEmpty())
		{
			addPresentChunks(atoms, "fletching.owned-workflows-" + rowIndex, packedRow, present);
		}
	}

	private static void addPresentGemStages(List<SemanticAtom> atoms, Set<Integer> present)
	{
		List<Integer> raw = new ArrayList<>(DATA.get().gemFamilies.size() + 1);
		List<Integer> processed = new ArrayList<>(DATA.get().gemFamilies.size() + 1);
		raw.add(DATA.get().opalFamily.rawItemId);
		processed.add(DATA.get().opalFamily.processedItemId);
		for (FamilyFact family : DATA.get().gemFamilies)
		{
			raw.add(family.rawItemId);
			processed.add(family.processedItemId);
		}
		addPresentChunks(atoms, "gem.raw", raw, present);
		addPresentChunks(atoms, "gem.processed", processed, present);
	}

	private static void addPresentChunks(List<SemanticAtom> atoms, String atomKey,
		List<Integer> canonicalIds, Set<Integer> present)
	{
		List<SemanticAtom.Member> members = new ArrayList<>();
		int chunk = 0;
		for (Integer itemId : canonicalIds)
		{
			if (!present.contains(itemId))
			{
				continue;
			}
			if (members.size() == 8)
			{
				atoms.add(new SemanticAtom(atomKey + "-" + chunk++, members));
				members = new ArrayList<>();
			}
			members.add(new SemanticAtom.Member("member-" + members.size(), itemId));
		}
		if (!members.isEmpty())
		{
			atoms.add(new SemanticAtom(atomKey + "-" + chunk, members));
		}
	}

	private static SemanticRule horizontalRuns(String ruleKey, List<RowFact> rows)
	{
		List<SemanticAtom> atoms = atomsForRows(rows);
		return SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.HORIZONTAL_RUN)
			.allowedWidths(ALL_WIDTHS)
			.build();
	}

	private static SemanticRule rowGroupMatrix(String ruleKey, List<RowFact> rows)
	{
		return SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(atomsForRows(rows))
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.ROW_GROUP_MATRIX)
			.allowedWidths(ALL_WIDTHS)
			.build();
	}

	private static List<SemanticAtom> atomsForRows(List<RowFact> rows)
	{
		List<SemanticAtom> atoms = new ArrayList<>(rows.size());
		for (RowFact row : rows)
		{
			List<SemanticAtom.Member> members = new ArrayList<>(row.itemIds.size());
			for (int index = 0; index < row.itemIds.size(); index++)
			{
				members.add(new SemanticAtom.Member("tier-" + index, row.itemIds.get(index)));
			}
			atoms.add(new SemanticAtom(row.familyKey, members));
		}

		return atoms;
	}

	private static SemanticRule stageMatrix(String ruleKey, List<FamilyFact> families,
		WidthEvidence widthEvidence)
	{
		List<SemanticAtom> atoms = new ArrayList<>(families.size());
		for (FamilyFact family : families)
		{
			atoms.add(new SemanticAtom(family.familyKey, Arrays.asList(
				new SemanticAtom.Member("raw", family.rawItemId),
				new SemanticAtom.Member("processed", family.processedItemId))));
		}

		SemanticRule.Builder builder = SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.STAGE_MATRIX)
			.allowedWidths(ALL_WIDTHS);
		if (widthEvidence != null)
		{
			builder.widthEvidence(widthEvidence);
		}
		return builder.build();
	}

	private static void validateMetadata(List<FamilyFact> families)
	{
		for (FamilyFact family : families)
		{
			validateMember(family.familyKey, family.rawItemId, 0);
			validateMember(family.familyKey, family.processedItemId, 1);
		}
	}

	private static void validateRows(List<RowFact> rows)
	{
		for (RowFact row : rows)
		{
			for (int index = 0; index < row.itemIds.size(); index++)
			{
				validateMember(row.familyKey, row.itemIds.get(index), index);
			}
		}
	}

	private static void validateMember(String expectedFamilyKey, int itemId, int expectedStage)
	{
		ItemSortMetadata metadata = ResourceItemSortMetadataCatalog.INSTANCE.findById(itemId)
			.orElseThrow(() -> new IllegalStateException(
				"Missing resource semantic metadata for itemId " + itemId));
		if (!expectedFamilyKey.equals(metadata.getFamilyKey())
			|| metadata.getVariantKind() != ItemSortMetadata.VariantKind.WORKFLOW_STAGE
			|| metadata.getVariantValue() != expectedStage)
		{
			throw new IllegalStateException("Resource semantic metadata mismatch for itemId " + itemId
				+ ": expected family=" + expectedFamilyKey + ", kind=WORKFLOW_STAGE, stage="
				+ expectedStage + " but was family=" + metadata.getFamilyKey() + ", kind="
				+ metadata.getVariantKind() + ", stage=" + metadata.getVariantValue());
		}
	}


	private static final class RowFact
	{
		private final String familyKey;
		private final List<Integer> itemIds;

		private RowFact(String familyKey, List<Integer> itemIds)
		{
			this.familyKey = familyKey;
			this.itemIds = itemIds;
		}
	}

	private static final class FamilyFact
	{
		private final String familyKey;
		private final int rawItemId;
		private final int processedItemId;

		private FamilyFact(String familyKey, int rawItemId, int processedItemId)
		{
			this.familyKey = familyKey;
			this.rawItemId = rawItemId;
			this.processedItemId = processedItemId;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;



/** Exact canonical four-wide rune rows; non-rune entries remain ordinary dense spillover. */
public final class RuneSemanticRuleSet
{
	private static final String RULE_KEY = "runes.four-wide-rows";
	private static final List<List<Integer>> ROWS = Collections.unmodifiableList(Arrays.asList(
		row(556, 555, 557, 554),
		row(558, 562, 560, 565),
		row(559, 564, 561, 563),
		row(9075, 566, 4699, 21880),
		row(4695, 4696, 4698, 4697),
		row(4694, 28929, 30843)));

	private RuneSemanticRuleSet()
	{
	}

	public static LayoutRequest forEntries(List<LayoutEntry> entries)
	{
		Objects.requireNonNull(entries, "entries");
		return new LayoutRequest(anchorFirstRune(entries),
			Collections.singletonList(ruleForRows(ROWS)));
	}

	static LayoutRequest forMainEntries(List<LayoutEntry> entries)
	{
		Objects.requireNonNull(entries, "entries");
		return new LayoutRequest(entries,
			Collections.singletonList(ruleForRows(mainRows(entries))));
	}

	static Integer firstPresentRuneId(List<LayoutEntry> entries)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			present.add(entry.getItem().getItemId());
		}
		for (List<Integer> row : ROWS)
		{
			for (Integer itemId : row)
			{
				if (present.contains(itemId)) return itemId;
			}
		}
		return null;
	}

	static List<List<Integer>> mainRows(List<LayoutEntry> entries)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			present.add(entry.getItem().getItemId());
		}
		List<List<Integer>> rows = new ArrayList<>();
		rows.add(ROWS.get(0));
		rows.add(ROWS.get(1));
		rows.add(ROWS.get(2));
		List<Integer> tail = new ArrayList<>();
		for (int row = 3; row < ROWS.size(); row++)
		{
			for (Integer itemId : ROWS.get(row))
			{
				if (present.contains(itemId)) tail.add(itemId);
			}
		}
		if (present.contains(8013)) tail.add(8013);
		for (int offset = 0; offset < tail.size(); offset += 4)
		{
			rows.add(Collections.unmodifiableList(new ArrayList<>(
				tail.subList(offset, Math.min(offset + 4, tail.size())))));
		}
		return Collections.unmodifiableList(rows);
	}

	private static List<LayoutEntry> anchorFirstRune(List<LayoutEntry> entries)
	{
		for (LayoutEntry entry : entries)
		{
			if (entry.hasLockedTarget())
			{
				return entries;
			}
		}
		Integer firstRune = firstPresentRuneId(entries);
		if (firstRune != null)
		{
			List<LayoutEntry> anchored = new ArrayList<>(entries.size());
			for (LayoutEntry entry : entries)
			{
				anchored.add(entry.getItem().getItemId() == firstRune
					? entry.withLockedTarget(0) : entry);
			}
			return Collections.unmodifiableList(anchored);
		}
		return entries;
	}

	private static SemanticRule ruleForRows(List<List<Integer>> rows)
	{
		return SemanticRule.builder()
			.ruleKey(RULE_KEY)
			.atoms(atoms(rows))
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.ROW_GROUP_MATRIX)
			.allowedWidths(Collections.singleton(4))
			.build();
	}

	private static List<SemanticAtom> atoms(List<List<Integer>> rows)
	{
		List<SemanticAtom> atoms = new ArrayList<>();
		for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++)
		{
			List<SemanticAtom.Member> members = new ArrayList<>();
			for (int column = 0; column < rows.get(rowIndex).size(); column++)
			{
				members.add(new SemanticAtom.Member("rune-" + column, rows.get(rowIndex).get(column)));
			}
			atoms.add(new SemanticAtom("rune-row-" + rowIndex, members));
		}
		return atoms;
	}

	private static List<Integer> row(Integer... itemIds)
	{
		return Collections.unmodifiableList(Arrays.asList(itemIds));
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * One immutable semantic atom: the smallest indivisible ordered member group of a rule. Its
 * meaning depends on the rule's shape primitive:
 *
 * <ul>
 * <li>{@code HORIZONTAL_RUN} / {@code VERTICAL_RUN}: the atom is the projected item family;</li>
 * <li>{@code STAGE_MATRIX}: each atom is one family column and member keys identify the stages;</li>
 * <li>{@code ROW_GROUP_MATRIX}: each atom is one explicit row.</li>
 * </ul>
 *
 * <p>Atoms are curated in code, so malformed atoms fail fast: keys must be stable lowercase keys,
 * item IDs must be positive, unique within the atom, and never Bank Filler.</p>
 */
public final class SemanticAtom
{
	private final String atomKey;
	private final List<Member> members;

	public SemanticAtom(String atomKey, List<Member> members)
	{
		this.atomKey = SemanticRule.requireRuleKey(atomKey, "atomKey");
		this.members = requireMembers(members);
	}

	public String getAtomKey()
	{
		return atomKey;
	}

	public List<Member> getMembers()
	{
		return members;
	}

	/**
	 * The atom's item IDs in reviewed member order.
	 */
	public List<Integer> getItemIds()
	{
		List<Integer> itemIds = new ArrayList<>(members.size());
		for (Member member : members)
		{
			itemIds.add(member.getItemId());
		}
		return Collections.unmodifiableList(itemIds);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof SemanticAtom))
		{
			return false;
		}

		SemanticAtom atom = (SemanticAtom) other;
		return atomKey.equals(atom.atomKey) && members.equals(atom.members);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(atomKey, members);
	}

	@Override
	public String toString()
	{
		return "SemanticAtom{" + atomKey + ", members=" + members + "}";
	}

	private static List<Member> requireMembers(List<Member> members)
	{
		if (members == null || members.isEmpty())
		{
			throw new IllegalArgumentException("members must not be empty");
		}

		Set<String> seenMemberKeys = new HashSet<>();
		Set<Integer> seenItemIds = new HashSet<>();
		for (Member member : members)
		{
			if (member == null)
			{
				throw new IllegalArgumentException("members must not contain null");
			}
			if (!seenMemberKeys.add(member.getMemberKey()))
			{
				throw new IllegalArgumentException("duplicate member key " + member.getMemberKey());
			}
			if (!seenItemIds.add(member.getItemId()))
			{
				throw new IllegalArgumentException("duplicate member item ID " + member.getItemId());
			}
		}

		return Collections.unmodifiableList(new ArrayList<>(members));
	}

	/**
	 * One ordered atom member: a stable member/stage key plus exactly one canonical item ID.
	 */
	public static final class Member
	{
		private final String memberKey;
		private final int itemId;

		public Member(String memberKey, int itemId)
		{
			this.memberKey = SemanticRule.requireRuleKey(memberKey, "memberKey");
			if (itemId <= 0)
			{
				throw new IllegalArgumentException("itemId must be positive");
			}
			if (itemId == ItemID.BANK_FILLER)
			{
				throw new IllegalArgumentException("Bank Filler is never an atom member");
			}
			this.itemId = itemId;
		}

		public String getMemberKey()
		{
			return memberKey;
		}

		public int getItemId()
		{
			return itemId;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof Member))
			{
				return false;
			}

			Member member = (Member) other;
			return itemId == member.itemId && memberKey.equals(member.memberKey);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(memberKey, itemId);
		}

		@Override
		public String toString()
		{
			return memberKey + "=" + itemId;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;



/**
 * Pure public facade for planning one category on the fixed eight-column bank grid. The caller
 * supplies the existing deterministic micro-sort order explicitly; source bank slots, request-list
 * order, and a proven current dense order have different meanings and are never substituted for it.
 *
 * <p>The engine only returns manual target guidance. It performs no bank actions and exposes no
 * mouse, keyboard, packet, or game-state mutation path.</p>
 */
public final class SemanticBlockLayoutEngine
{
	public LayoutResult plan(LayoutRequest request, List<Integer> stableFallbackItemIds)
	{
		Objects.requireNonNull(request, "request");

		// Reviewed geometries pin exact slots and still go through the bounded
		// packer, whose search honours locks. Everything else follows the
		// sorter's order, with families nudged off row edges rather than moved.
		boolean anchored = false;
		for (LayoutEntry entry : request.getEntries())
		{
			if (entry.hasLockedTarget())
			{
				anchored = true;
				break;
			}
		}
		// Curated two-dimensional geometry - vertical outfit columns, stage
		// matrices, and matrices with a fixed or evidenced width such as the
		// diary grid, gear set columns, and ore-above-bar - only the bounded
		// packer can express. A matrix rule with free width and no evidence is
		// really a bag of families, and follows the sorter's order like any
		// one-dimensional run.
		for (SemanticRule rule : request.getRules())
		{
			ShapePrimitive shape = rule.getShapePrimitive();
			boolean widthShaped = rule.getAllowedWidths().size() < SemanticRule.MAX_WIDTH
				|| rule.hasWidthEvidence() || rule.hasPreferredWidth();
			// A rule that names a single present item has no geometry to keep;
			// one runecrafting talisman must not drag a whole tools tab here.
			if (rule.getMemberItemIds().size() < 2)
			{
				continue;
			}
			if (shape == ShapePrimitive.VERTICAL_RUN || shape == ShapePrimitive.STAGE_MATRIX
				|| (shape == ShapePrimitive.ROW_GROUP_MATRIX && widthShaped))
			{
				anchored = true;
				break;
			}
		}
		if (anchored)
		{
			return planDetailed(request, stableFallbackItemIds,
				BoundedLayoutPacker.Limits.production()).getResult();
		}

		List<LayoutConflict> requestConflicts = LayoutRequestValidator.validate(request);
		if (!requestConflicts.isEmpty())
		{
			return LayoutResult.conflict(requestConflicts);
		}
		List<Integer> fallback = validateFallbackOrder(request, stableFallbackItemIds);
		if (fallback == null)
		{
			return LayoutResult.conflict(Collections.singletonList(new LayoutConflict(
				LayoutConflict.Type.FALLBACK_ORDER_NOT_PERMUTATION,
				LayoutConflict.NO_ITEM,
				"stableFallbackItemIds must be an exact unique permutation of all request item IDs")));
		}
		return OrderPreservingPacker.pack(request, fallback);
	}

	static BoundedLayoutPacker.Outcome planDetailed(LayoutRequest request,
		List<Integer> stableFallbackItemIds, BoundedLayoutPacker.Limits limits)
	{
		Objects.requireNonNull(request, "request");
		Objects.requireNonNull(limits, "limits");

		List<LayoutConflict> requestConflicts = LayoutRequestValidator.validate(request);
		if (!requestConflicts.isEmpty())
		{
			return BoundedLayoutPacker.Outcome.conflict(LayoutResult.conflict(requestConflicts));
		}

		List<Integer> fallback = validateFallbackOrder(request, stableFallbackItemIds);
		if (fallback == null)
		{
			LayoutConflict conflict = new LayoutConflict(
				LayoutConflict.Type.FALLBACK_ORDER_NOT_PERMUTATION,
				LayoutConflict.NO_ITEM,
				"stableFallbackItemIds must be an exact unique permutation of all request item IDs");
			return BoundedLayoutPacker.Outcome.conflict(
				LayoutResult.conflict(Collections.singletonList(conflict)));
		}

		return BoundedLayoutPacker.packValidated(request, fallback, limits);
	}

	private static List<Integer> validateFallbackOrder(LayoutRequest request,
		List<Integer> stableFallbackItemIds)
	{
		if (stableFallbackItemIds == null || stableFallbackItemIds.size() != request.size())
		{
			return null;
		}

		Set<Integer> requested = new HashSet<>();
		for (LayoutEntry entry : request.getEntries())
		{
			requested.add(entry.getItem().getItemId());
		}

		Set<Integer> seen = new HashSet<>();
		List<Integer> validated = new ArrayList<>(stableFallbackItemIds.size());
		for (Integer itemId : stableFallbackItemIds)
		{
			if (itemId == null || !requested.contains(itemId) || !seen.add(itemId))
			{
				return null;
			}
			validated.add(itemId);
		}
		return seen.size() == requested.size()
			? Collections.unmodifiableList(validated)
			: null;
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Immutable semantic topology, confidence, shape, widths and spillover compatibility. Atoms
 * preserve structure; getMemberItemIds() is only a flat overlap-validation view. Invalid curated
 * rules throw IllegalArgumentException: stable lowercase keys, unique atom keys and positive unique
 * IDs are required; members exclude Bank Filler. LayoutRequestValidator reports cross-rule
 * conflicts.
 */
public final class SemanticRule
{
	static final int MIN_WIDTH = 1;
	static final int MAX_WIDTH = 8;

	private static final Pattern KEY_PATTERN = Pattern.compile("[a-z0-9]+(?:[._-][a-z0-9]+)*");

	private final String ruleKey;
	private final List<SemanticAtom> atoms;
	private final List<Integer> memberItemIds;
	private final ConfidenceTier confidenceTier;
	private final ShapePrimitive shapePrimitive;
	private final Set<Integer> allowedWidths;
	private final WidthEvidence widthEvidence;
	private final Set<String> spilloverCompatibleRuleKeys;

	private SemanticRule(Builder builder)
	{
		this.ruleKey = requireRuleKey(builder.ruleKey, "ruleKey");
		this.atoms = requireAtoms(builder.atoms);
		this.memberItemIds = flattenUniqueItemIds(this.atoms);
		this.confidenceTier = Objects.requireNonNull(builder.confidenceTier, "confidenceTier");
		this.shapePrimitive = Objects.requireNonNull(builder.shapePrimitive, "shapePrimitive");
		this.allowedWidths = requireAllowedWidths(builder.allowedWidths);
		this.widthEvidence = builder.widthEvidence;
		this.spilloverCompatibleRuleKeys = requireCompatibleKeys(builder.spilloverCompatibleRuleKeys);

		if (hasPreferredWidth() && !allowedWidths.contains(getPreferredWidth()))
		{
			throw new IllegalArgumentException("preferredWidth must be one of the allowed widths");
		}
		if (shapePrimitive == ShapePrimitive.VERTICAL_RUN && hasPreferredWidth()
			&& getPreferredWidth() != 1)
		{
			throw new IllegalArgumentException(
				"vertical-run width evidence may only prefer its structurally feasible width 1");
		}
	}

	public static Builder builder()
	{
		return new Builder();
	}

	public String getRuleKey()
	{
		return ruleKey;
	}

	/**
	 * The explicit ordered semantic topology: families for runs, family columns for a stage
	 * matrix, or explicit rows for a row-group matrix.
	 */
	public List<SemanticAtom> getAtoms()
	{
		return atoms;
	}

	/**
	 * Derived flat ID view over all atoms in atom/member order. Used for cross-rule overlap
	 * validation only; the semantic structure lives in {@link #getAtoms()}.
	 */
	public List<Integer> getMemberItemIds()
	{
		return memberItemIds;
	}

	public ConfidenceTier getConfidenceTier()
	{
		return confidenceTier;
	}

	public ShapePrimitive getShapePrimitive()
	{
		return shapePrimitive;
	}

	public Set<Integer> getAllowedWidths()
	{
		return allowedWidths;
	}

	public boolean hasWidthEvidence()
	{
		return widthEvidence != null;
	}

	public WidthEvidence getWidthEvidence()
	{
		if (widthEvidence == null)
		{
			throw new IllegalStateException("rule has no width evidence");
		}
		return widthEvidence;
	}

	public boolean hasPreferredWidth()
	{
		return widthEvidence != null && widthEvidence.hasPreferredWidth();
	}

	public int getPreferredWidth()
	{
		if (!hasPreferredWidth())
		{
			throw new IllegalStateException("rule has no evidence-backed width preference");
		}

		return widthEvidence.getPreferredWidth();
	}

	public Set<String> getSpilloverCompatibleRuleKeys()
	{
		return spilloverCompatibleRuleKeys;
	}

	static String requireRuleKey(String value, String field)
	{
		if (value == null || !KEY_PATTERN.matcher(value).matches())
		{
			throw new IllegalArgumentException(field + " must be a lowercase stable key");
		}

		return value;
	}

	private static List<SemanticAtom> requireAtoms(List<SemanticAtom> atoms)
	{
		if (atoms == null || atoms.isEmpty())
		{
			throw new IllegalArgumentException("atoms must not be empty");
		}

		Set<String> seenAtomKeys = new HashSet<>();
		for (SemanticAtom atom : atoms)
		{
			if (atom == null)
			{
				throw new IllegalArgumentException("atoms must not contain null");
			}
			if (!seenAtomKeys.add(atom.getAtomKey()))
			{
				throw new IllegalArgumentException("duplicate atom key " + atom.getAtomKey());
			}
		}

		return Collections.unmodifiableList(new ArrayList<>(atoms));
	}

	private static List<Integer> flattenUniqueItemIds(List<SemanticAtom> atoms)
	{
		List<Integer> itemIds = new ArrayList<>();
		Set<Integer> seen = new HashSet<>();
		for (SemanticAtom atom : atoms)
		{
			for (SemanticAtom.Member member : atom.getMembers())
			{
				if (!seen.add(member.getItemId()))
				{
					throw new IllegalArgumentException(
						"item ID " + member.getItemId() + " appears in more than one atom");
				}
				itemIds.add(member.getItemId());
			}
		}

		return Collections.unmodifiableList(itemIds);
	}

	private static Set<Integer> requireAllowedWidths(Set<Integer> widths)
	{
		if (widths == null || widths.isEmpty())
		{
			throw new IllegalArgumentException("allowedWidths must not be empty");
		}

		for (Integer width : widths)
		{
			if (width == null || width < MIN_WIDTH || width > MAX_WIDTH)
			{
				throw new IllegalArgumentException("allowedWidths must be within " + MIN_WIDTH + ".." + MAX_WIDTH);
			}
		}

		return Collections.unmodifiableSet(new TreeSet<>(widths));
	}

	private static Set<String> requireCompatibleKeys(Set<String> keys)
	{
		if (keys == null || keys.isEmpty())
		{
			return Collections.emptySet();
		}

		Set<String> validated = new TreeSet<>();
		for (String key : keys)
		{
			validated.add(requireRuleKey(key, "spilloverCompatibleRuleKeys"));
		}

		return Collections.unmodifiableSet(validated);
	}

	public static final class Builder
	{
		private String ruleKey;
		private List<SemanticAtom> atoms;
		private ConfidenceTier confidenceTier;
		private ShapePrimitive shapePrimitive;
		private Set<Integer> allowedWidths;
		private WidthEvidence widthEvidence;
		private Set<String> spilloverCompatibleRuleKeys;

		private Builder()
		{
		}

		public Builder ruleKey(String value)
		{
			this.ruleKey = value;
			return this;
		}

		public Builder atoms(List<SemanticAtom> value)
		{
			this.atoms = value;
			return this;
		}

		public Builder confidenceTier(ConfidenceTier value)
		{
			this.confidenceTier = value;
			return this;
		}

		public Builder shapePrimitive(ShapePrimitive value)
		{
			this.shapePrimitive = value;
			return this;
		}

		public Builder allowedWidths(Set<Integer> value)
		{
			this.allowedWidths = value;
			return this;
		}

		public Builder widthEvidence(WidthEvidence value)
		{
			this.widthEvidence = Objects.requireNonNull(value, "widthEvidence");
			return this;
		}

		public Builder spilloverCompatibleRuleKeys(Set<String> value)
		{
			this.spilloverCompatibleRuleKeys = value;
			return this;
		}

		public SemanticRule build()
		{
			return new SemanticRule(this);
		}
	}
}

