/**
 * The four V1 semantic shape primitives. Each rule prescribes exactly one primitive; alternative
 * orientations per rule are deliberately out of scope for V1.
 */
public enum ShapePrimitive
{
	HORIZONTAL_RUN,
	VERTICAL_RUN,
	STAGE_MATRIX,
	ROW_GROUP_MATRIX
