/** Exact canonical outfit columns plus compact horizontal tool runs grouped by primary skill. */
public final class ToolOutfitSemanticRuleSet
{
	private static final String OUTFIT_RULE_KEY = "tool.outfit-columns";
	private static final String SKILL_RUN_RULE_KEY = "tool.primary-skill-runs";
	private static final Set<Integer> ALL_WIDTHS = Collections.unmodifiableSet(
		new LinkedHashSet<>(Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8)));
	private static final OrderedItemFamilies TABLE = new OrderedItemFamilies(
		ToolOutfitSemanticRuleSet.class.getResourceAsStream(
			"/com/pkoka5/ironmanbankarchitect/catalog/tool-layout-families.tsv"), 0, false);
	private static final RequiredResource<List<OutfitFact>> OUTFITS =
		new RequiredResource<>("tool outfits", ToolOutfitSemanticRuleSet::buildOutfits);
	private static final RequiredResource<List<ToolFamilyFact>> TOOL_FAMILIES = new RequiredResource<>("tool families", () ->
	{
		List<ToolFamilyFact> families = new ArrayList<>();
		TABLE.group("families").forEach((key, ids) -> families.add(tools(key, ids)));
		return Collections.unmodifiableList(families);
	});

	private static List<OutfitFact> buildOutfits()
	{
		List<OutfitFact> outfits = new ArrayList<>();
		TABLE.group("outfits").forEach((key, ids) -> outfits.add(outfit(key, ids.stream().mapToInt(Integer::intValue).toArray())));

		Set<Integer> reserved = new LinkedHashSet<>();
		for (OutfitFact outfit : outfits)
		{
			for (int itemId : outfit.itemIds) reserved.add(itemId);
		}
		for (ItemSetCatalog.SetDefinition definition : ItemSetCatalog.sets("tools"))
		{
			boolean overlaps = false;
			for (Integer itemId : definition.getItemIds())
			{
				if (reserved.contains(itemId))
				{
					overlaps = true;
					break;
				}
			}
			if (!overlaps)
			{
				int[] itemIds = new int[definition.getItemIds().size()];
				for (int index = 0; index < itemIds.length; index++)
				{
					itemIds[index] = definition.getItemIds().get(index);
					reserved.add(itemIds[index]);
				}
				outfits.add(outfit(definition.getKey(), itemIds));
			}
		}
		return Collections.unmodifiableList(outfits);
	}

	private ToolOutfitSemanticRuleSet()
	{
	}

	public static LayoutRequest forEntries(List<LayoutEntry> entries)
	{
		Objects.requireNonNull(entries, "entries");
		List<LayoutEntry> anchored = anchoredEntries(entries);
		List<SemanticRule> rules = new ArrayList<>();
		SemanticRule outfitRule = buildOutfitRule(anchored);
		if (outfitRule != null)
		{
			rules.add(outfitRule);
		}
		SemanticRule skillRuns = buildPresentRows(anchored, SKILL_RUN_RULE_KEY, TOOL_FAMILIES.get());
		if (skillRuns != null)
		{
			rules.add(skillRuns);
		}
		return new LayoutRequest(anchored, rules);
	}

	private static List<LayoutEntry> anchoredEntries(List<LayoutEntry> entries)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			if (entry.hasLockedTarget())
			{
				return entries;
			}
			present.add(entry.getItem().getItemId());
		}

		Map<Integer, Integer> lockedTargets = new LinkedHashMap<>();
		int outfitColumn = 0;
		int maxOutfitHeight = 0;
		for (OutfitFact outfit : outfitsFor(entries))
		{
			List<Integer> owned = presentIds(outfit.itemIds, present);
			if (owned.size() < 2 || outfitColumn >= 8)
			{
				continue;
			}
			lockedTargets.put(owned.get(0), outfitColumn++);
			maxOutfitHeight = Math.max(maxOutfitHeight, owned.size());
		}

		int priorityRow = maxOutfitHeight;
		int runecraftingRows = lockPriorityRows(TABLE.ids("RUNECRAFTING_PRIORITY"), present,
			priorityRow, entries.size(), lockedTargets);
		priorityRow += runecraftingRows;
		int containerRows = present.contains(19634)
			? lockPriorityRows(TABLE.ids("IRONMAN_CONTAINER_PRIORITY"), present, priorityRow,
				entries.size(), lockedTargets)
			: 0;

		// A sparse tab may end before the row below its tallest outfit exists.
		if (runecraftingRows == 0 && containerRows == 0 && maxOutfitHeight * 8 < entries.size())
		{
			for (ToolFamilyFact family : TOOL_FAMILIES.get())
			{
				List<Integer> owned = presentIds(family.itemIds, present);
				if (owned.size() >= 2)
				{
					lockedTargets.put(owned.get(0), maxOutfitHeight * 8);
					break;
				}
			}
		}
		if (lockedTargets.isEmpty())
		{
			return entries;
		}

		List<LayoutEntry> anchored = new ArrayList<>(entries.size());
		for (LayoutEntry entry : entries)
		{
			Integer target = lockedTargets.get(entry.getItem().getItemId());
			anchored.add(target == null ? entry : entry.withLockedTarget(target));
		}
		return Collections.unmodifiableList(anchored);
	}

	private static int lockPriorityRows(List<Integer> itemIds, Set<Integer> present,
		int startRow, int entryCount, Map<Integer, Integer> lockedTargets)
	{
		List<Integer> owned = presentIds(itemIds, present);
		if (owned.size() < 2)
		{
			return 0;
		}
		int rows = (owned.size() + 7) / 8;
		int lastTarget = (startRow + rows - 1) * 8 + (owned.size() - 1) % 8;
		if (lastTarget >= entryCount)
		{
			return 0;
		}
		for (int index = 0; index < owned.size(); index++)
		{
			lockedTargets.put(owned.get(index),
				(startRow + index / 8) * 8 + index % 8);
		}
		return rows;
	}

	private static List<Integer> presentIds(int[] itemIds, Set<Integer> present)
	{
		List<Integer> owned = new ArrayList<>();
		for (int itemId : itemIds)
		{
			if (present.contains(itemId)) owned.add(itemId);
		}
		return owned;
	}

	private static List<Integer> presentIds(List<Integer> itemIds, Set<Integer> present)
	{
		List<Integer> owned = new ArrayList<>();
		for (Integer itemId : itemIds)
		{
			if (present.contains(itemId)) owned.add(itemId);
		}
		return owned;
	}

	private static SemanticRule buildOutfitRule(List<LayoutEntry> entries)
	{
		List<ItemSetCatalog.SetDefinition> definitions = new ArrayList<>(OUTFITS.get().size());
		for (OutfitFact outfit : outfitsFor(entries))
		{
			List<Integer> itemIds = new ArrayList<>(outfit.itemIds.length);
			for (int itemId : outfit.itemIds) itemIds.add(itemId);
			definitions.add(ItemSetCatalog.definition("tools", outfit.key, outfit.key, itemIds));
		}
		return VerticalItemSetRuleFactory.build(OUTFIT_RULE_KEY, entries, definitions);
	}

	private static List<OutfitFact> outfitsFor(List<LayoutEntry> entries)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries) present.add(entry.getItem().getItemId());
		List<OutfitFact> outfits = new ArrayList<>(OUTFITS.get());
		int best = -1;
		int count = -1;
		for (int i = 0; i < outfits.size(); i++)
		{
			OutfitFact outfit = outfits.get(i);
			int owned = presentIds(outfit.itemIds, present).size();
			if (outfit.key.startsWith("outfit.raiments-eye") && owned > count)
			{
				best = i;
				count = owned;
			}
		}
		if (best >= 0)
		{
			OutfitFact outfit = outfits.get(best);
			List<Integer> ids = presentIds(outfit.itemIds, present);
			ids.addAll(presentIds(TABLE.ids("EYE_SHARED"), present));
			outfits.set(best, outfit(outfit.key, ids.stream().mapToInt(Integer::intValue).toArray()));
		}
		return outfits;
	}

	private static SemanticRule buildPresentRows(List<LayoutEntry> entries, String ruleKey,
		List<ToolFamilyFact> families)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			present.add(entry.getItem().getItemId());
		}

		List<SemanticAtom> atoms = new ArrayList<>();
		for (ToolFamilyFact family : families)
		{
			if (family.key.equals("tool.utility-containers") && !present.contains(19634))
			{
				continue;
			}
			List<SemanticAtom.Member> members = new ArrayList<>();
			int chunk = 0;
			for (Integer itemId : family.itemIds)
			{
				if (!present.contains(itemId))
				{
					continue;
				}
				if (members.size() == 8)
				{
					atoms.add(new SemanticAtom(family.key + "-" + chunk++, members));
					members = new ArrayList<>();
				}
				members.add(new SemanticAtom.Member("tool-" + members.size(), itemId));
			}
			if (!members.isEmpty())
			{
				atoms.add(new SemanticAtom(family.key + "-" + chunk, members));
			}
		}
		if (atoms.isEmpty())
		{
			return null;
		}
		return SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.ROW_GROUP_MATRIX)
			.allowedWidths(ALL_WIDTHS)
			.build();
	}

	private static OutfitFact outfit(String key, int... itemIds)
	{
		return new OutfitFact(key, itemIds);
	}


	private static ToolFamilyFact tools(String key, List<Integer> itemIds)
	{
		return new ToolFamilyFact(key, itemIds);
	}

	private static final class OutfitFact
	{
		private final String key;
		private final int[] itemIds;

		private OutfitFact(String key, int[] itemIds)
		{
			this.key = key;
			this.itemIds = itemIds;
		}
	}

	private static final class ToolFamilyFact
	{
		private final String key;
		private final List<Integer> itemIds;

		private ToolFamilyFact(String key, List<Integer> itemIds)
		{
			this.key = key;
			this.itemIds = itemIds;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;


/** Builds one exact-ID vertical rule containing only owned sets with at least two pieces. */
final class VerticalItemSetRuleFactory
{
	private VerticalItemSetRuleFactory()
	{
	}

	static SemanticRule build(String ruleKey, List<LayoutEntry> entries,
		List<ItemSetCatalog.SetDefinition> definitions)
	{
		Set<Integer> present = new LinkedHashSet<>();
		for (LayoutEntry entry : entries)
		{
			present.add(entry.getItem().getItemId());
		}

		List<SemanticAtom> atoms = new ArrayList<>();
		for (ItemSetCatalog.SetDefinition definition : definitions)
		{
			List<SemanticAtom.Member> members = new ArrayList<>();
			for (Integer itemId : definition.getItemIds())
			{
				if (present.contains(itemId))
				{
					members.add(new SemanticAtom.Member("piece-" + members.size(), itemId));
				}
			}
			if (members.size() >= 2)
			{
				atoms.add(new SemanticAtom(definition.getKey(), members));
			}
		}
		if (atoms.isEmpty())
		{
			return null;
		}
		return SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.VERTICAL_RUN)
			.allowedWidths(Collections.singleton(1))
			.build();
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import java.util.*;
import java.util.List;



/**
 * Immutable aggregate template evidence for nominal block widths 1 through 8. Each vector entry is
 * an exact distinct-template or distinct-family support count for that width; missing widths may
 * not be silently treated as zero.
 *
 * <p>A preference becomes active only when the best width has support from at least five
 * templates and three families, reaches a 60% integer support rate, and leads the runner-up by at
 * least two templates. When those thresholds are not met every width has zero regret and rank.</p>
 */
public final class WidthEvidence
{
	private static final int MIN_TOP_TEMPLATE_SUPPORT = 5;
	private static final int MIN_TOP_FAMILY_SUPPORT = 3;
	private static final int MIN_SUPPORT_RATE = 600;
	private static final int MIN_RUNNER_UP_LEAD = 2;

	private final int eligibleTemplateCount;
	private final List<Integer> distinctTemplateSupportByWidth;
	private final List<Integer> distinctFamilySupportByWidth;
	private final boolean hasPreferredWidth;
	private final int preferredWidth;
	private final int bestSupportRate;

	public WidthEvidence(int eligibleTemplateCount, List<Integer> distinctTemplateSupportByWidth,
		List<Integer> distinctFamilySupportByWidth)
	{
		if (eligibleTemplateCount <= 0)
		{
			throw new IllegalArgumentException("eligibleTemplateCount must be positive");
		}
		this.eligibleTemplateCount = eligibleTemplateCount;
		this.distinctTemplateSupportByWidth = requireSupportVector(
			distinctTemplateSupportByWidth, eligibleTemplateCount, true);
		this.distinctFamilySupportByWidth = requireSupportVector(
			distinctFamilySupportByWidth, Integer.MAX_VALUE, false);
		validateAlignedSupport(this.distinctTemplateSupportByWidth, this.distinctFamilySupportByWidth);

		int bestWidth = SemanticRule.MIN_WIDTH;
		for (int width = SemanticRule.MIN_WIDTH + 1; width <= SemanticRule.MAX_WIDTH; width++)
		{
			if (getDistinctTemplateSupport(width) > getDistinctTemplateSupport(bestWidth))
			{
				bestWidth = width;
			}
		}

		int bestTemplateSupport = getDistinctTemplateSupport(bestWidth);
		int runnerUpSupport = 0;
		for (int width = SemanticRule.MIN_WIDTH; width <= SemanticRule.MAX_WIDTH; width++)
		{
			if (width != bestWidth)
			{
				runnerUpSupport = Math.max(runnerUpSupport, getDistinctTemplateSupport(width));
			}
		}

		this.bestSupportRate = supportRate(bestTemplateSupport);
		this.hasPreferredWidth = bestTemplateSupport >= MIN_TOP_TEMPLATE_SUPPORT
			&& getDistinctFamilySupport(bestWidth) >= MIN_TOP_FAMILY_SUPPORT
			&& bestSupportRate >= MIN_SUPPORT_RATE
			&& bestTemplateSupport - runnerUpSupport >= MIN_RUNNER_UP_LEAD;
		this.preferredWidth = bestWidth;
	}

	public int getEligibleTemplateCount()
	{
		return eligibleTemplateCount;
	}

	public List<Integer> getDistinctTemplateSupportByWidth()
	{
		return distinctTemplateSupportByWidth;
	}

	public List<Integer> getDistinctFamilySupportByWidth()
	{
		return distinctFamilySupportByWidth;
	}

	public int getDistinctTemplateSupport(int width)
	{
		return distinctTemplateSupportByWidth.get(index(width));
	}

	public int getDistinctFamilySupport(int width)
	{
		return distinctFamilySupportByWidth.get(index(width));
	}

	public int getSupportRate(int width)
	{
		return supportRate(getDistinctTemplateSupport(width));
	}

	public boolean hasPreferredWidth()
	{
		return hasPreferredWidth;
	}

	public int getPreferredWidth()
	{
		if (!hasPreferredWidth)
		{
			throw new IllegalStateException("width evidence does not clear the preference threshold");
		}
		return preferredWidth;
	}

	/**
	 * Exact integer support-rate regret for one width. Inactive evidence is deliberately neutral.
	 */
	public int regretForWidth(int width)
	{
		int supportRate = getSupportRate(width);
		return hasPreferredWidth ? bestSupportRate - supportRate : 0;
	}

	/**
	 * Dense evidence rank used only after numeric-score equality: best support is rank 0, and equal
	 * support counts share a rank. Inactive evidence gives every width rank 0.
	 */
	public int preferenceRankForWidth(int width)
	{
		int support = getDistinctTemplateSupport(width);
		if (!hasPreferredWidth)
		{
			return 0;
		}

		Set<Integer> higherSupportCounts = new HashSet<>();
		for (Integer candidateSupport : distinctTemplateSupportByWidth)
		{
			if (candidateSupport > support)
			{
				higherSupportCounts.add(candidateSupport);
			}
		}
		return higherSupportCounts.size();
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof WidthEvidence))
		{
			return false;
		}

		WidthEvidence evidence = (WidthEvidence) other;
		return eligibleTemplateCount == evidence.eligibleTemplateCount
			&& distinctTemplateSupportByWidth.equals(evidence.distinctTemplateSupportByWidth)
			&& distinctFamilySupportByWidth.equals(evidence.distinctFamilySupportByWidth);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(eligibleTemplateCount, distinctTemplateSupportByWidth,
			distinctFamilySupportByWidth);
	}

	@Override
	public String toString()
	{
		return "WidthEvidence{eligible=" + eligibleTemplateCount + ", templates="
			+ distinctTemplateSupportByWidth + ", families=" + distinctFamilySupportByWidth + "}";
	}

	private int supportRate(int support)
	{
		return (int) ((1000L * support) / eligibleTemplateCount);
	}

	private static int index(int width)
	{
		if (width < SemanticRule.MIN_WIDTH || width > SemanticRule.MAX_WIDTH)
		{
			throw new IllegalArgumentException("width must be within "
				+ SemanticRule.MIN_WIDTH + ".." + SemanticRule.MAX_WIDTH);
		}
		return width - SemanticRule.MIN_WIDTH;
	}

	private static List<Integer> requireSupportVector(List<Integer> values, int maximum,
		boolean templateVector)
	{
		if (values == null || values.size() != SemanticRule.MAX_WIDTH)
		{
			throw new IllegalArgumentException("support vectors must contain exactly one value for widths 1..8");
		}

		List<Integer> validated = new ArrayList<>(values.size());
		for (Integer value : values)
		{
			if (value == null || value < 0 || value > maximum)
			{
				throw new IllegalArgumentException(templateVector
					? "template support must be within 0..eligibleTemplateCount"
					: "family support must not be negative");
			}
			validated.add(value);
		}
		return Collections.unmodifiableList(validated);
	}

	private static void validateAlignedSupport(List<Integer> templateSupport, List<Integer> familySupport)
	{
		for (int index = 0; index < templateSupport.size(); index++)
		{
			if ((templateSupport.get(index) == 0) != (familySupport.get(index) == 0))
			{
				throw new IllegalArgumentException(
					"template and family support must both be zero or both be positive for each width");
			}
		}
	}
}

package com.pkoka5.ironmanbankarchitect.overlay;

import static com.pkoka5.ironmanbankarchitect.overlay.BankOverlayGeometry.isSafeGeometry;
import static com.pkoka5.ironmanbankarchitect.overlay.BankOverlayGeometry.itemViewportBounds;
import com.pkoka5.ironmanbankarchitect.IronmanBankArchitectConfig;
import com.pkoka5.ironmanbankarchitect.bank.BankItemIds;
import com.pkoka5.ironmanbankarchitect.guide.BankGuideController;
import com.pkoka5.ironmanbankarchitect.organize.*;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.*;



/**
 * Tints every bank item with the colour of the tab the blueprint sends it to.
 *
 * <p>This is the one piece of guidance that needs nothing but a scan: it makes
 * the plan visible in the bank itself before the player commits to moving
 * anything. It draws only, so unlike the move guide it does not care which bank
 * view, rearrange mode, or tag filter is active.</p>
 */
public final class BankCategoryOverlay extends Overlay
{
	private static final int LEGEND_PADDING = 6;
	private static final int LEGEND_SWATCH = 8;
	private static final int LEGEND_GAP = 8;
	private static final Color LEGEND_BACKGROUND = new Color(0, 0, 0, 205);
	private static final Color LEGEND_FOREGROUND = new Color(255, 255, 255, 235);

	private final Client client;
	private final BankGuideController guideController;
	private final IronmanBankArchitectConfig config;
	private final BankOverlayReservations reservations;
	private final Map<Integer, Integer> canonicalItemIdCache = new HashMap<>();
	private BankOrganizationPreview cachedPreview;
	private PlannedCategoryIndex cachedIndex;

	public BankCategoryOverlay(Plugin plugin, Client client, BankGuideController guideController,
		IronmanBankArchitectConfig config, BankOverlayReservations reservations)
	{
		super(plugin);
		this.client = client;
		this.guideController = guideController;
		this.config = config;
		this.reservations = reservations;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
		setMovable(false);
		setResizable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		reservations.clearLegend();
		// Tied to assign mode rather than drawn whenever a scan exists: a
		// coloured bank now means a mode is running, and closing the mode
		// gives the player their ordinary bank back.
		if (!config.showCategoryOverlay() || !guideController.isCategoryAssignMode())
		{
			return null;
		}

		Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bankItems == null || bankItems.isHidden())
		{
			return null;
		}

		BankOrganizationPreview preview = guideController.organizationPreview();
		if (preview == null)
		{
			return null;
		}

		Widget bankItemsContainer = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		Rectangle gridBounds = itemViewportBounds(bankItems.getBounds(),
			bankItemsContainer == null || bankItemsContainer.isHidden()
				? null : bankItemsContainer.getBounds());
		if (!isSafeGeometry(gridBounds))
		{
			return null;
		}

		refreshIndex(preview);
		int opacity = config.categoryOverlayOpacity();
		TreeSet<Integer> shownCategories = new TreeSet<>();

		Graphics2D bankGraphics = (Graphics2D) graphics.create();
		try
		{
			bankGraphics.clip(gridBounds);
			bankGraphics.setStroke(new BasicStroke(2f));
			for (Widget child : itemWidgets(bankItems))
			{
				if (child == null || child.isHidden() || child.getItemId() <= 0)
				{
					continue;
				}
				Rectangle bounds = child.getBounds();
				if (!isSafeGeometry(bounds) || !gridBounds.intersects(bounds))
				{
					continue;
				}
				int categoryIndex = cachedIndex.categoryIndexFor(canonicalItemId(child.getItemId()));
				if (categoryIndex < 0)
				{
					continue;
				}
				shownCategories.add(categoryIndex);
				bankGraphics.setColor(CategoryPalette.colorFor(cachedIndex.paletteIndex(categoryIndex), opacity));
				bankGraphics.fill(bounds);
				bankGraphics.setColor(CategoryPalette.colorFor(cachedIndex.paletteIndex(categoryIndex)));
				bankGraphics.draw(bounds);
			}
		}
		finally
		{
			bankGraphics.dispose();
		}

		if (!shownCategories.isEmpty())
		{
			drawLegend(graphics, gridBounds, shownCategories);
		}
		return null;
	}

	private void refreshIndex(BankOrganizationPreview preview)
	{
		if (cachedPreview != preview || cachedIndex == null)
		{
			cachedPreview = preview;
			cachedIndex = PlannedCategoryIndex.from(preview);
			canonicalItemIdCache.clear();
		}
	}

	private Widget[] itemWidgets(Widget container)
	{
		Widget[] children = container.getChildren();
		return children == null ? container.getDynamicChildren() : children;
	}

	private int canonicalItemId(int itemId)
	{
		return canonicalItemIdCache.computeIfAbsent(itemId, id -> BankItemIds.canonical(client, id));
	}
	/**
	 * Colours mean nothing without names, so the legend lists only the
	 * destinations actually on screen. It is placed beside the bank when the
	 * canvas has room, because covering bank slots would defeat the overlay.
	 */
	private void drawLegend(Graphics2D graphics, Rectangle gridBounds,
		Iterable<Integer> categoryIndexes)
	{
		Graphics2D legendGraphics = (Graphics2D) graphics.create();
		try
		{
			BankOverlayText.prepare(legendGraphics, BankOverlayText.regularFont());
			FontMetrics metrics = legendGraphics.getFontMetrics();

			int lines = 0;
			int textWidth = 0;
			for (int categoryIndex : categoryIndexes)
			{
				lines++;
				textWidth = Math.max(textWidth,
					metrics.stringWidth(cachedIndex.categoryName(categoryIndex)));
			}

			// Line height follows the font so the legend keeps its shape if the
			// client's font ever changes size.
			int lineHeight = metrics.getHeight();
			int width = LEGEND_PADDING * 2 + LEGEND_SWATCH + LEGEND_GAP + textWidth;
			int height = LEGEND_PADDING * 2 + lines * lineHeight;
			Rectangle legend = legendBounds(gridBounds, width, height);
			reservations.reserveLegend(legend);

			legendGraphics.setColor(LEGEND_BACKGROUND);
			legendGraphics.fillRect(legend.x, legend.y, legend.width, legend.height);

			int y = legend.y + LEGEND_PADDING;
			for (int categoryIndex : categoryIndexes)
			{
				legendGraphics.setColor(CategoryPalette.colorFor(cachedIndex.paletteIndex(categoryIndex)));
				legendGraphics.fillRect(legend.x + LEGEND_PADDING,
					y + (lineHeight - LEGEND_SWATCH) / 2, LEGEND_SWATCH, LEGEND_SWATCH);
				BankOverlayText.draw(legendGraphics, cachedIndex.categoryName(categoryIndex),
					legend.x + LEGEND_PADDING + LEGEND_SWATCH + LEGEND_GAP,
					y + metrics.getAscent(), LEGEND_FOREGROUND);
				y += lineHeight;
			}
		}
		finally
		{
			legendGraphics.dispose();
		}
	}

	/**
	 * Prefers the free canvas to the right of the bank, then the left, and only
	 * falls back to overlapping the bank when neither side fits.
	 */
	Rectangle legendBounds(Rectangle gridBounds, int width, int height)
	{
		return legendBounds(gridBounds, width, height, client.getCanvasWidth(),
			client.getCanvasHeight());
	}

	static Rectangle legendBounds(Rectangle gridBounds, int width, int height,
		int canvasWidth, int canvasHeight)
	{
		int x;
		if (gridBounds.x + gridBounds.width + LEGEND_GAP + width <= canvasWidth)
		{
			x = gridBounds.x + gridBounds.width + LEGEND_GAP;
		}
		else if (gridBounds.x - LEGEND_GAP - width >= 0)
		{
			x = gridBounds.x - LEGEND_GAP - width;
		}
		else
		{
			x = Math.max(0, Math.min(gridBounds.x, canvasWidth - width));
		}

		int y = Math.max(0, Math.min(gridBounds.y, canvasHeight - height));
		return new Rectangle(x, y, width, height);
	}
}

package com.pkoka5.ironmanbankarchitect.overlay;

