	private static String summarizedNames(List<String> names)
	{
		int shown = Math.min(3, names.size());
		String more = names.size() > shown
			? " (+" + (names.size() - shown) + " more)" : "";
		return String.join(", ", names.subList(0, shown)) + more;
	}

