		for (int tab = 1; tab <= 9; tab++) assertTrue(allMain.get(tab).isEmpty());
		fixture.counts[0] = 2;
		Map<Integer, List<Integer>> noMain = BankSnapshotReader.readTabOrders(fixture.client, fixture.snapshot()).get();
		assertTrue(noMain.get(0).isEmpty());
