package com.pkoka5.ironmanbankarchitect.bank;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class BankSnapshotTest
{
	@Test
	public void preservesItemIdQuantityAndSlotIndex()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(new BankItemSnapshot(209, 3, 12)));

		assertEquals(1, snapshot.getItems().size());
		assertEquals(209, snapshot.getItems().get(0).getItemId());
		assertEquals(3, snapshot.getItems().get(0).getQuantity());
		assertEquals(12, snapshot.getItems().get(0).getSlotIndex());
	}

	@Test
	public void skipsInvalidIdsAndQuantities()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(0, 1, 0),
			new BankItemSnapshot(-1, 1, 1),
			new BankItemSnapshot(209, 0, 2),
			new BankItemSnapshot(259, -4, 3),
			new BankItemSnapshot(221, 2, 4)
		));

		assertEquals(1, snapshot.getItems().size());
		assertEquals(221, snapshot.getItems().get(0).getItemId());
		assertEquals(2, snapshot.getTotalQuantity(221));
	}

	@Test
	public void bankFillerIsExcludedEvenFromManuallyBuiltSnapshots()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(ItemID.BANK_FILLER, 1, 0),
			new BankItemSnapshot(209, 1, 1)));

		assertEquals(1, snapshot.getItems().size());
		assertEquals(209, snapshot.getItems().get(0).getItemId());
		assertEquals(0, snapshot.getTotalQuantity(ItemID.BANK_FILLER));
	}

	@Test
	public void duplicateItemIdsAggregateAndPreserveFirstSlot()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(209, 3, 7),
			new BankItemSnapshot(259, 1, 8),
			new BankItemSnapshot(209, 5, 20)
		));

		assertEquals(2, snapshot.getItems().size());
		assertEquals(8, snapshot.getTotalQuantity(209));
		assertEquals(7, snapshot.getItems().get(0).getSlotIndex());
		assertEquals(Arrays.asList(3, 5),
			snapshot.getItems().get(0).getPhysicalSlotQuantities());
	}

	@Test
	public void preservesPlaceholderWithoutTreatingItAsOwned()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(6687, 0, 14, true)
		));

		assertEquals(1, snapshot.getItems().size());
		assertEquals(0, snapshot.getTotalQuantity(6687));
		assertEquals(14, snapshot.getItems().get(0).getSlotIndex());
		assertEquals(true, snapshot.getItems().get(0).isPlaceholder());
		assertEquals(Arrays.asList(0),
			snapshot.getItems().get(0).getPhysicalSlotQuantities());
	}

	@Test
	public void preservesPlaceholderAndOwnedOccurrencesThatShareAnItemId()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(6687, 0, 14, true),
			new BankItemSnapshot(6687, 3, 20)
		));

		assertEquals(3, snapshot.getTotalQuantity(6687));
		assertEquals(false, snapshot.getItems().get(0).isPlaceholder());
		assertEquals(Arrays.asList(0, 3),
			snapshot.getItems().get(0).getPhysicalSlotQuantities());
	}

	@Test
	public void preservesEveryPlaceholderOccurrenceForOneItemId()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(6687, 0, 14, true),
			new BankItemSnapshot(6687, 0, 20, true)
		));

		assertEquals(true, snapshot.getItems().get(0).isPlaceholder());
		assertEquals(Arrays.asList(0, 0),
			snapshot.getItems().get(0).getPhysicalSlotQuantities());
	}

	/**
	 * Reordering cannot invalidate analysis, including when equal-ID copies
	 * have different quantities or one of them is a placeholder.
	 */
	@Test
	public void contentsIgnorePositionsButKeepEveryPhysicalQuantity()
	{
		BankSnapshot snapshot = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(209, 3, 0),
			new BankItemSnapshot(221, 0, 1, true),
			new BankItemSnapshot(209, 2, 2)));

		BankSnapshot reordered = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(209, 2, 0),
			new BankItemSnapshot(209, 3, 1),
			new BankItemSnapshot(221, 0, 2, true)));
		assertEquals(Map.of(209, List.of(2, 3), 221, List.of(0)), snapshot.contents());
		assertEquals(snapshot.contents(), reordered.contents());
	}

	@Test
	public void contentsDetectChangesThatAnItemIdSetWouldMiss()
	{
		BankSnapshot original = new BankSnapshot(List.of(new BankItemSnapshot(209, 2, 0)));
		for (BankSnapshot changed : List.of(
			new BankSnapshot(List.of(new BankItemSnapshot(209, 3, 0))),
			new BankSnapshot(List.of(new BankItemSnapshot(209, 0, 0, true))),
			new BankSnapshot(List.of(new BankItemSnapshot(209, 1, 0),
				new BankItemSnapshot(209, 1, 1))),
			new BankSnapshot(List.of(new BankItemSnapshot(209, 2, 0),
				new BankItemSnapshot(209, 0, 1, true))),
			new BankSnapshot(List.of())))
		{
			assertNotEquals(original.contents(), changed.contents());
		}
	}
}

package com.pkoka5.ironmanbankarchitect.blueprint;

import static org.junit.Assert.assertEquals;
