public class ItemUsageTagsTest
{
	@Test public void functionalFamiliesHaveExactDestinationsWithoutPromotingQuestNamesakes()
	{
		for (int id : new int[]{3095, 3101, 6587, 1017, 4089, 4099, 4109, 23047, 1724, 1167,
			2961, 24697, 33709, 33711, 33713})
			assertEquals("Functional equipment " + id, ItemCategory.GEAR,
				CompositeItemCatalog.DEFAULT.describeOrUnknown(id).getCategory());
		for (int id : new int[]{4773, 4778, 4783, 4788, 4793, 4798, 4803})
			assertEquals("ammo", CompositeItemCatalog.DEFAULT.describeOrUnknown(id).getSubcategory());
		for (int id : new int[]{4599, 4600, 6408, 6410, 6412, 6414, 6416, 6418, 6420})
		{
			assertEquals(ItemCategory.TOOL, CompositeItemCatalog.DEFAULT.describeOrUnknown(id).getCategory());
			assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(id).hasTag("thieving-utility"));
		}
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(4683).hasTag("prayer-gear"));
		assertEquals(ItemCategory.CLEANUP, CompositeItemCatalog.DEFAULT.describeOrUnknown(20405).getCategory());
	}
	@Test public void clueFactsDoNotSpreadToNotesNamesakesOrPoisonedWeapons()
	{
		for (int id : new int[]{579, 1061, 1167, 1205, 4310, 5525})
			assertTrue("Missing canonical clue role " + id,
				CompositeItemCatalog.DEFAULT.describeOrUnknown(id).hasTag("clue-required"));
		for (int id : new int[]{580, 6893, 1206, 1221, 7394, 4304})
			assertFalse("Unreviewed clue variant " + id,
				CompositeItemCatalog.DEFAULT.describeOrUnknown(id).hasTag("clue-required"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(24695).hasTag("bloom-utility"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(33713).hasTag("bloom-utility"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(24587).hasTag("exchange-for-rune-pouch"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(24587).hasTag("rune-container"));
	}

	@Test public void utilityFactsApplyOnlyToReviewedCanonicalStates()
	{
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(4252).hasTag("refill-required"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(4251).hasTag("refill-required"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(2963).hasTag("bloom-utility"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(2961).hasTag("bloom-utility"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(5315).hasTag("storage-option-seed-vault"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(23650).hasTag("rune-container"));
	}

	@Test public void skillingFactsDoNotInventExperienceBonusesForWarmGloves()
	{
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(20712).hasTag("warm-clothing"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(20712).hasTag("skilling-outfit"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(5553).hasTag("thieving-utility"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(25434).hasTag("prayer-training"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(30045).hasTag("weight-reducing"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(20705).hasTag("skilling-outfit"));
		for (int id : new int[]{29263, 29265, 29267, 29269})
			assertEquals("skilling-outfit", CompositeItemCatalog.DEFAULT.describeOrUnknown(id).getSubcategory());
	}

	@Test public void exactFactsRespectFunctionalExceptions()
	{
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(4300).hasTag("clue-required"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(4304).hasTag("clue-required"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(19689).hasTag("warm-clothing"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(19687).hasTag("warm-clothing"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(11061).hasTag("special-attack"));
		assertFalse(CompositeItemCatalog.DEFAULT.describeOrUnknown(9091).hasTag("transport-access"));
		assertTrue(CompositeItemCatalog.DEFAULT.describeOrUnknown(259).hasTag("herb"));
	}

	@Test public void malformedFactsCannotSilentlyChangeTheCatalog()
	{
		String[] invalid = {"# schema=2\n1\tgear", "# schema=1\n", "# schema=1\n0\tgear",
			"# schema=1\n1\tgear\n1\tquest-use", "# schema=1\n1\tgear,gear",
			"# schema=1\n1\tgear,", "# schema=1\n1\tbad tag", "# schema=1\n1\tgear\textra"};
		for (String text : invalid)
		{
			try { ItemUsageTags.load(new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8))); fail(text); }
			catch (IllegalStateException expected) { }
		}
		try { ItemUsageTags.load(null); fail("missing resource"); }
		catch (IllegalStateException expected) { }
	}

	@Test(expected = UnsupportedOperationException.class)
	public void factsAreImmutable()
	{
		ItemUsageTags.forItem(772).add("cosmetic");
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.*;

public class OrderedItemFamiliesTest
{
	@Test
	public void bundledTablesRetainEveryOriginalFamilyAndMemberInOrder() throws Exception
	{
		// Fingerprints independently calculated from the former Java literals at 0046cd2.
		assertOriginal("potion", 4, 22, "30902cec1cf66b2e8807a265f6a367abd796203cabaf7e6da6e9154e4e1beb5f");
		assertOriginal("farming", 0, 11, "b0d9cebddc4c4c19c2bf1ee30179f20424f5c1d77662280a9d50227ee50a65a1");
		assertOriginal("gear", 0, 43, "45ca82269e019bda9b9f3d194485e5558ceb964de06354d73fcea5bd7fb52b82");
		// Reviewed October 2: append Guild hunter and Golden prospector columns.
		assertOriginal("tool", 0, 34, "dc28e8281d146af28855b2b5928eae099558ef9e22495fef296ac846944bd6ce");
		assertOriginal("resource", 0, 40, "8a8d2e0b5c704af9e462c61d3ee6d746d6de004db25ef573e82467d6e7b93a57");
	}

	@Test
	public void extractedRunecraftingConstantsMatchRuneLiteAndBarrowsKeepsPartOrder()
	{
		OrderedItemFamilies tools = new OrderedItemFamilies(getClass().getResourceAsStream("tool-layout-families.tsv"), 0, false);
		List<Integer> priority = tools.ids("RUNECRAFTING_PRIORITY");
		assertEquals(List.of(
			net.runelite.api.gameval.ItemID.RCU_POUCH_SMALL,
			net.runelite.api.gameval.ItemID.RCU_POUCH_MEDIUM,
			net.runelite.api.gameval.ItemID.RCU_POUCH_MEDIUM_DEGRADE,
			net.runelite.api.gameval.ItemID.RCU_POUCH_LARGE,
			net.runelite.api.gameval.ItemID.RCU_POUCH_LARGE_DEGRADE,
			net.runelite.api.gameval.ItemID.RCU_POUCH_GIANT,
			net.runelite.api.gameval.ItemID.RCU_POUCH_GIANT_DEGRADE,
			net.runelite.api.gameval.ItemID.RCU_POUCH_COLOSSAL,
			net.runelite.api.gameval.ItemID.RCU_POUCH_COLOSSAL_DEGRADE,
			net.runelite.api.gameval.ItemID.MAGIC_EMERALD_NECKLACE), priority.subList(26, priority.size()));
		assertEquals(priority, tools.group("families").get("tool.runecrafting"));
		List<Integer> ahrim = new OrderedItemFamilies(getClass().getResourceAsStream("gear-layout-families.tsv"), 0)
			.ids("gear.barrows-ahrim");
		assertEquals(List.of(4708, 4856, 4857, 4858, 4859, 4860), ahrim.subList(0, 6));
		assertEquals(List.of(4710, 4862, 4863, 4864, 4865, 4866), ahrim.subList(6, 12));
		assertEquals(List.of(4712, 4868, 4869, 4870, 4871, 4872), ahrim.subList(12, 18));
		assertEquals(List.of(4714, 4874, 4875, 4876, 4877, 4878), ahrim.subList(18, 24));
	}

	@Test
	public void badResourcesFailOnUseWithoutPublishingPartialFamilies()
	{
		assertThrows(CatalogUnavailableException.class, () -> new OrderedItemFamilies(null, 0).entries());
		for (String data : List.of("# schema=10\na\t1", "# schema=1\n", "# schema=1\na\t0",
			"# schema=1\na\t1,1", "# schema=1\na\t1\nb\t1", "# schema=1\na\t1\na\t2",
			"# schema=1\na\tx", "# schema=1\na\t1\nbad row", "# schema=1\n\t1"))
		{
			OrderedItemFamilies table = table(data, 0);
			assertThrows(data, CatalogUnavailableException.class, table::entries);
			assertThrows(data, CatalogUnavailableException.class, table::entries);
		}
		assertThrows(CatalogUnavailableException.class, () -> table("# schema=1\na\t1,2,3", 4).entries());
	}

	@Test
	public void loadedFamiliesCannotBeMutated()
	{
		Map<String, List<Integer>> entries = table("# schema=1\na\t2,1", 0).entries();
		assertEquals(List.of(2, 1), entries.get("a"));
		assertThrows(UnsupportedOperationException.class, entries::clear);
		assertThrows(UnsupportedOperationException.class, () -> entries.get("a").clear());
	}

	@Test
	public void overlappingGroupsRetainOrderButRejectDuplicatesWithinOneRow()
	{
		OrderedItemFamilies table = new OrderedItemFamilies(new ByteArrayInputStream(
			"# schema=1\ngroup/second\t2,1\ngroup/first\t1,3\nother\t3".getBytes(StandardCharsets.UTF_8)), 0, false);
		assertEquals(List.of("second", "first"), List.copyOf(table.group("group").keySet()));
		assertEquals(List.of(2, 1), table.group("group").get("second"));
		assertThrows(UnsupportedOperationException.class, () -> table.group("group").clear());
		assertThrows(CatalogUnavailableException.class, () -> table.group("missing"));
		assertThrows(CatalogUnavailableException.class, () -> table.ids("missing"));
		OrderedItemFamilies duplicate = new OrderedItemFamilies(new ByteArrayInputStream(
			"# schema=1\na\t1,1".getBytes(StandardCharsets.UTF_8)), 0, false);
		assertThrows(CatalogUnavailableException.class, duplicate::entries);
	}

	private static OrderedItemFamilies table(String data, int width)
	{
		return new OrderedItemFamilies(new ByteArrayInputStream(data.getBytes(StandardCharsets.UTF_8)), width);
	}

	private static void assertOriginal(String name, int width, int rows, String expected) throws Exception
	{
		Map<String, List<Integer>> families = new OrderedItemFamilies(OrderedItemFamiliesTest.class
			.getResourceAsStream(name + "-layout-families.tsv"), width, !name.equals("tool") && !name.equals("resource")).entries();
		assertEquals(rows, families.size());
		StringBuilder canonical = new StringBuilder();
		families.forEach((key, ids) -> canonical.append(key).append('\t')
			.append(ids.stream().map(String::valueOf).collect(Collectors.joining(","))).append('\n'));
		byte[] digest = MessageDigest.getInstance("SHA-256").digest(canonical.toString().getBytes(StandardCharsets.UTF_8));
		StringBuilder hex = new StringBuilder();
		for (byte value : digest) hex.append(String.format("%02x", value & 255));
		assertEquals(expected, hex.toString());
	}
}

