	@Test
	public void rejectsBankFillerMetadataExplicitly()
	{
		assertInvalid(validRow(ItemID.BANK_FILLER), "Bank Filler", "forbidden");
	}

	@Test
	public void validatesSourceManifestShapeDatesAndDuplicates()
	{
		String valid = "test-source\thttps://oldschool.runescape.wiki/w/Food?oldid=1\t2026-07-13\t1\tCC BY-NC-SA 3.0\n";
		Set<String> loaded = ResourceItemSortMetadataCatalog.loadSourceKeys(stream(SCHEMA + valid));
		assertEquals(Collections.singleton("test-source"), loaded);

		assertInvalidSource(valid + valid, "line 3", "duplicate source_key");
		assertInvalidSource("test-source\thttp://example.com\t2026-07-13\t1\tlicense\n",
			"HTTPS", "source_url");
		assertInvalidSource("test-source\thttps://example.com\tnot-a-date\t1\tlicense\n",
			"line 2", "not-a-date");
		assertInvalidSource("Bad Source\thttps://example.com\t2026-07-13\t1\tlicense\n",
			"source_key", "lowercase stable key");
		assertInvalidSource("test-source\thttps://oldschool.runescape.wiki/w/Food?oldid=2\t2026-07-13\t1\tlicense\n",
			"oldid", "revision");
		assertInvalidSource("test-source\thttps://oldschool.runescape.wiki/w/Food?oldid=abc\t2026-07-13\tabc\tCC BY-NC-SA 3.0\n",
			"revision", "numeric");
		assertInvalidSource("test-source\thttps://oldschool.runescape.wiki/w/Food?oldid=1\t2026-07-13\t1\tunknown\n",
			"license", "CC BY-NC-SA 3.0");
	}

	@Test
	public void acceptsBomBeforeSchemaAndRejectsMissingOrUnsupportedSchemas()
	{
		Map<Integer, ItemSortMetadata> loaded = ResourceItemSortMetadataCatalog.loadMetadata(
			stream("\uFEFF" + SCHEMA + validRow(385)), Collections.singleton("test-source"));
		assertTrue(loaded.containsKey(385));

		assertSchemaInvalid(validRow(385), "first non-empty line", "schema=1");
		assertSchemaInvalid("# schema=2\n" + validRow(385), "first non-empty line", "schema=1");
	}

	private static String validRow(int itemId)
	{
		return itemId + "\tfood.shark\tNONE\t0\tSTANDARD\tFIXED\t20\t20\t0\tNONE\ttest-source\n";
	}

	private static void assertDoseFamily(String familyKey, int[] itemIds)
	{
		for (int index = 0; index < itemIds.length; index++)
		{
			ItemSortMetadata metadata = ResourceItemSortMetadataCatalog.INSTANCE.findById(itemIds[index]).get();
			assertEquals(familyKey, metadata.getFamilyKey());
			assertEquals(ItemSortMetadata.VariantKind.DOSE, metadata.getVariantKind());
			assertEquals(4 - index, metadata.getVariantValue());
		}
	}

	private static void assertWorkflowFamily(String familyKey, int grimyItemId, int cleanItemId,
		int unfinishedItemId)
	{
		ItemSortMetadata grimy = ResourceItemSortMetadataCatalog.INSTANCE.findById(grimyItemId).get();
		ItemSortMetadata clean = ResourceItemSortMetadataCatalog.INSTANCE.findById(cleanItemId).get();
		ItemSortMetadata unfinished = ResourceItemSortMetadataCatalog.INSTANCE.findById(unfinishedItemId).get();
		assertEquals(familyKey, grimy.getFamilyKey());
		assertEquals(familyKey, clean.getFamilyKey());
		assertEquals(familyKey, unfinished.getFamilyKey());
		assertEquals(ItemSortMetadata.VariantKind.WORKFLOW_STAGE, grimy.getVariantKind());
		assertEquals(ItemSortMetadata.VariantKind.WORKFLOW_STAGE, clean.getVariantKind());
		assertEquals(ItemSortMetadata.VariantKind.WORKFLOW_STAGE, unfinished.getVariantKind());
		assertEquals(0, grimy.getVariantValue());
		assertEquals(1, clean.getVariantValue());
		assertEquals(3, unfinished.getVariantValue());
	}

	private static void assertResourceWorkflowFamily(String familyKey, int rawItemId, int processedItemId)
	{
		ItemSortMetadata raw = ResourceItemSortMetadataCatalog.INSTANCE.findById(rawItemId).get();
		ItemSortMetadata processed = ResourceItemSortMetadataCatalog.INSTANCE.findById(processedItemId).get();
		assertEquals(familyKey, raw.getFamilyKey());
		assertEquals(familyKey, processed.getFamilyKey());
		assertEquals(ItemSortMetadata.VariantKind.WORKFLOW_STAGE, raw.getVariantKind());
		assertEquals(ItemSortMetadata.VariantKind.WORKFLOW_STAGE, processed.getVariantKind());
		assertEquals(0, raw.getVariantValue());
		assertEquals(1, processed.getVariantValue());
	}

	private static void assertOrderedWorkflowFamily(String familyKey, int[] itemIds)
	{
		for (int index = 0; index < itemIds.length; index++)
		{
			ItemSortMetadata metadata = ResourceItemSortMetadataCatalog.INSTANCE
				.findById(itemIds[index]).get();
			assertEquals(familyKey, metadata.getFamilyKey());
			assertEquals(ItemSortMetadata.VariantKind.WORKFLOW_STAGE, metadata.getVariantKind());
			assertEquals(index, metadata.getVariantValue());
		}
	}

	private static void assertInvalid(String content, String... messageParts)
	{
		try
		{
			Map<Integer, ItemSortMetadata> ignored = ResourceItemSortMetadataCatalog.loadMetadata(
				stream(SCHEMA + content), Collections.singleton("test-source"));
			fail("expected invalid metadata, loaded " + ignored.size() + " rows");
		}
		catch (IllegalStateException ex)
		{
			for (String part : messageParts)
			{
				assertTrue("message should contain " + part + ": " + ex.getMessage(),
					ex.getMessage().contains(part));
			}
		}
	}

	private static void assertInvalidSource(String content, String... messageParts)
	{
		try
		{
			ResourceItemSortMetadataCatalog.loadSourceKeys(stream(SCHEMA + content));
			fail("expected invalid source metadata");
		}
		catch (IllegalStateException ex)
		{
			for (String part : messageParts)
			{
				assertTrue("message should contain " + part + ": " + ex.getMessage(),
					ex.getMessage().contains(part));
			}
		}
	}

	private static void assertSchemaInvalid(String content, String... messageParts)
	{
		try
		{
			ResourceItemSortMetadataCatalog.loadMetadata(stream(content), Collections.singleton("test-source"));
			fail("expected invalid schema");
		}
		catch (IllegalStateException ex)
		{
			for (String part : messageParts)
			{
				assertTrue("message should contain " + part + ": " + ex.getMessage(),
					ex.getMessage().contains(part));
			}
		}
	}

	private static ByteArrayInputStream stream(String value)
	{
		return new ByteArrayInputStream(value.getBytes(StandardCharsets.UTF_8));
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.pkoka5.ironmanbankarchitect.match.HardcodedSlotItemMappings;
import com.pkoka5.ironmanbankarchitect.match.SlotItemMapping;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import org.junit.Test;

public class StaticItemCatalogTest
{
	private static final List<Integer> VERIFIED_PHASE_B_ITEM_IDS = Arrays.asList(
		5297, 209, 259, 101, 221, 145, 147, 149
	);

	private static final List<String> VERIFIED_PHASE_B_SLOT_KEYS = Arrays.asList(
		"herblore.irit.seed",
		"herblore.irit.grimy",
		"herblore.irit.clean",
		"herblore.irit.unf",
		"herblore.irit.secondary",
		"herblore.super-attack.3",
		"herblore.super-attack.2",
		"herblore.super-attack.1"
	);

	@Test
	public void catalogFindsAllVerifiedPhaseBItemIds()
	{
		for (int itemId : VERIFIED_PHASE_B_ITEM_IDS)
		{
			assertTrue("expected catalog entry for item " + itemId, StaticItemCatalog.INSTANCE.findById(itemId).isPresent());
		}
	}

	@Test
	public void unknownIdReturnsUnknownSafely()
	{
		int unmappedItemId = 999999;

		assertFalse(StaticItemCatalog.INSTANCE.findById(unmappedItemId).isPresent());

		CatalogItem described = StaticItemCatalog.INSTANCE.describeOrUnknown(unmappedItemId);
		assertEquals(unmappedItemId, described.getItemId());
		assertEquals(ItemCategory.UNKNOWN, described.getCategory());
		assertEquals("unknown", described.getSubcategory());
		assertTrue(described.getTags().isEmpty());
		assertFalse(described.getWorkflowKey().isPresent());
	}

	@Test
	public void describeOrUnknownHandlesZeroWithoutThrowing()
	{
		CatalogItem described = StaticItemCatalog.INSTANCE.describeOrUnknown(0);

		assertEquals(0, described.getItemId());
		assertEquals(ItemCategory.UNKNOWN, described.getCategory());
	}

	@Test
	public void describeOrUnknownHandlesNegativeIdWithoutThrowing()
	{
		CatalogItem described = StaticItemCatalog.INSTANCE.describeOrUnknown(-1);

		assertEquals(-1, described.getItemId());
		assertEquals(ItemCategory.UNKNOWN, described.getCategory());
	}

	@Test
	public void describeOrUnknownHandlesIntegerMinValueWithoutThrowing()
	{
		CatalogItem described = StaticItemCatalog.INSTANCE.describeOrUnknown(Integer.MIN_VALUE);

		assertEquals(Integer.MIN_VALUE, described.getItemId());
		assertEquals(ItemCategory.UNKNOWN, described.getCategory());
	}

	@Test
	public void knownItemConstructionStillRejectsNonPositiveItemId()
	{
		assertThrowsIllegalArgument(() -> new CatalogItem(0, "Test item", ItemCategory.HERBLORE, "test", Collections.emptySet(), null));
		assertThrowsIllegalArgument(() -> new CatalogItem(-1, "Test item", ItemCategory.HERBLORE, "test", Collections.emptySet(), null));
	}

	@Test
	public void iritWorkflowCategoriesAndTagsAreCorrect()
	{
		assertCategoryAndTags(5297, ItemCategory.FARMING, "irit", "herb-seed");
		assertCategoryAndTags(209, ItemCategory.HERBLORE, "irit", "grimy");
		assertCategoryAndTags(259, ItemCategory.HERBLORE, "irit", "clean");
		assertCategoryAndTags(101, ItemCategory.HERBLORE, "irit", "unfinished-potion");
		assertCategoryAndTags(221, ItemCategory.HERBLORE, "secondary", "super-attack");
		assertCategoryAndTags(145, ItemCategory.POTION, "super-attack", "dose-3");
		assertCategoryAndTags(147, ItemCategory.POTION, "super-attack", "dose-2");
		assertCategoryAndTags(149, ItemCategory.POTION, "super-attack", "dose-1");
	}

	@Test
	public void superAttackFourIsNotPartOfPhaseBIritCatalogWorkflow()
	{
		// Super attack (4), item ID 2436, is reserved for a future Potion / Consumables / PvM
		// Supplies catalog area and must not appear in this Phase B Irit prep catalog.
		assertFalse(StaticItemCatalog.INSTANCE.findById(2436).isPresent());
	}

	@Test
	public void hardcodedSlotItemMappingIdsArePresentInCatalog()
	{
		for (String slotKey : VERIFIED_PHASE_B_SLOT_KEYS)
		{
			Optional<SlotItemMapping> mapping = HardcodedSlotItemMappings.forSlotKey(slotKey);
			assertTrue("expected a hardcoded mapping for " + slotKey, mapping.isPresent());

			int itemId = mapping.get().getItemId();
			assertTrue("expected catalog entry for mapped item " + itemId + " (" + slotKey + ")",
				StaticItemCatalog.INSTANCE.containsId(itemId));
		}
	}

	@Test
	public void noDuplicateItemIdsInStaticCatalog()
	{
		Set<Integer> uniqueIds = new HashSet<>(VERIFIED_PHASE_B_ITEM_IDS);
		uniqueIds.add(34024);
		assertEquals(uniqueIds.size(), StaticItemCatalog.INSTANCE.size());
	}

	private static void assertThrowsIllegalArgument(Runnable action)
	{
		try
		{
			action.run();
			throw new AssertionError("expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}
	}

	private static void assertCategoryAndTags(int itemId, ItemCategory expectedCategory, String... expectedTags)
	{
		CatalogItem item = StaticItemCatalog.INSTANCE.findById(itemId)
			.orElseThrow(() -> new AssertionError("expected catalog entry for item " + itemId));

		assertEquals(expectedCategory, item.getCategory());
		for (String expectedTag : expectedTags)
		{
			assertTrue("expected item " + itemId + " to have tag " + expectedTag, item.hasTag(expectedTag));
		}
	}
}

package com.pkoka5.ironmanbankarchitect.catalog;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Two combat families were split across tabs by classification gaps: every
 * Void body piece failed closed into storage cleanup while the rest of the set
 * was gear, and the cannon lists named some parts but not others.
 */
public class VoidAndCannonClassificationTest
{
	private static final int[] VOID_TOPS = {
		8839, 13072, 15737, 20465, 20467, 20468, 24177, 24178, 26463, 26469,
		27000, 27003, 33476, 33478, 33480, 33481, 33482, 33483
	};

	private static final int[] CANNON_PARTS = {
		6, 8, 10, 12, 26520, 26522, 26524, 26526
	};

	@Test
	public void everyVoidBodyPieceIsCombatEquipment()
	{
		for (int itemId : VOID_TOPS)
