import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class BankTabPlanTest
{
	@Test
	public void emptyNumberedCategoriesAreCompressedWithoutLosingIdentity()
	{
		BankTabPlan plan = BankTabPlan.fromPreview(preview(
			items(10), items(20), Collections.emptyList(), items(40),
			Collections.emptyList(), Collections.emptyList(), Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), items(100)));

		assertEquals(3, plan.getNumberedTabs().size());
		assertEquals(1, plan.getNumberedTabs().get(0).getBankTabNumber());
		assertEquals(2, plan.getNumberedTabs().get(0).getBlueprintCategoryNumber());
		assertEquals("Combat Gear",
			plan.getNumberedTabs().get(0).getCategoryName());
		assertEquals(2, plan.getNumberedTabs().get(1).getBankTabNumber());
		assertEquals(4, plan.getNumberedTabs().get(1).getBlueprintCategoryNumber());
		assertEquals("Herblore & Potion Making",
			plan.getNumberedTabs().get(1).getCategoryName());
		assertEquals(3, plan.getNumberedTabs().get(2).getBankTabNumber());
		assertEquals(10, plan.getNumberedTabs().get(2).getBlueprintCategoryNumber());
		assertEquals(Arrays.asList(20, 40, 100, 10), ids(plan.getFlattenedItems()));
		assertEquals("Frequently Used, Runes & Teleports", plan.getMainCategoryName());
		assertEquals(Arrays.asList(10), ids(plan.getMainItems()));
	}

	@SafeVarargs
	private static BankOrganizationPreview preview(List<BankPreviewItem>... categoryItems)
	{
		if (categoryItems.length != 10)
		{
			throw new IllegalArgumentException("expected ten categories");
		}
		List<BankCategoryPreview> categories = new ArrayList<>();
		for (int index = 0; index < categoryItems.length; index++)
		{
			categories.add(new BankCategoryPreview(
				BankPresets.IRONMAN.getCategories().get(index), categoryItems[index]));
		}
		return new BankOrganizationPreview(BankPresets.IRONMAN, categories);
	}

	private static List<BankPreviewItem> items(int... itemIds)
	{
		List<BankPreviewItem> items = new ArrayList<>();
		for (int itemId : itemIds)
		{
			items.add(new BankPreviewItem(itemId, "Item " + itemId, 1));
		}
		return items;
	}

	private static List<Integer> ids(List<BankPreviewItem> items)
	{
		List<Integer> ids = new ArrayList<>();
		for (BankPreviewItem item : items)
		{
			ids.add(item.getItemId());
		}
		return ids;
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.organize.*;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Cross-feature checks use physical occurrences, including quantities and placeholders. */
public class CustomizedLayoutGuidanceTest
{
	@Test
	public void customizedLayoutsKeepEveryOccurrenceAndBothGuideModesFinish()
	{
		List<BankItemSnapshot> raw = new ArrayList<>();
		for (int id : new int[]{995, 1161, 1161, 882, 2959, 2434, 139, 141, 143,
			5318, 5504, 11850, 11852, 1755, 952, 1042, 1038})
		{
			raw.add(new BankItemSnapshot(id, raw.size() + 1, raw.size()));
		}
		raw.add(new BankItemSnapshot(1161, 0, raw.size(), true));
		BankLayoutPlan layout = BankLayoutPlan.parse(BankPresets.IRONMAN,
			"currency+frequently-used|ammunition+cleanup+gear|food+potions|runes+teleports"
				+ "|tools+skilling-outfits+containers|raw-resources+gems+ammo-components"
				+ "|produce+grimy-herbs+clean-herbs+herb-seeds+seeds+unfinished-potions+secondaries+potion-doses+herblore-other"
				+ "|cosmetics+clues+collection-log|quest-items|boss-loot");
		CategoryOverrideSource corrections = id -> id == 1161 ? Optional.of("ammunition")
			: id == 5318 ? Optional.of("produce") : Optional.empty();
		Map<String, Integer> expected = new HashMap<>();
		for (BankItemSnapshot item : raw)
		{
			expected.merge(item.getItemId() + ":" + item.getQuantity() + ":" + item.isPlaceholder(), 1, Integer::sum);
		}
		int combinations = 0;
		for (GearLayout gear : GearLayout.values())
		for (PotionDoseOrder doses : PotionDoseOrder.values())
		for (TabOrder order : TabOrder.values())
		for (boolean gather : new boolean[]{false, true})
		for (boolean arranged : new boolean[]{false, true})
		{
			Map<BankCategorySortMode, TabOrder> orders = new EnumMap<>(BankCategorySortMode.class);
			for (BankCategorySortMode mode : BankCategorySortMode.values()) orders.put(mode, order);
			BankLayoutOptions options = new BankLayoutOptions(true, true, false, orders, gear,
				doses, RuneOrder.ALPHABETICAL, TeleportOrder.ALPHABETICAL, gather);
			if (arranged)
			{
				options = options.withBlockArrangements(BlockArrangements.parse(
					BlockArrangements.EMPTY.withTag("ammunition", Arrays.asList("set:gear.adamant-armour", "item:882"))
						.withTag("cosmetics", Arrays.asList("set:cosmetic-family.partyhats")).serialize()));
			}
			String context = gear + "/" + doses + "/" + order + "/" + gather + "/" + arranged;
			BankOrganizationPreview preview = BankOrganizationPreviewBuilder.build(new BankSnapshot(raw),
				CompositeItemCatalog.DEFAULT, BankPresets.IRONMAN, GearStatsSource.NONE, ItemValueSource.NONE,
				corrections, layout, options);
			Map<String, Integer> actual = new HashMap<>();
			for (int destination = 0; destination < preview.getCategories().size(); destination++)
			for (BankPreviewItem item : preview.getCategories().get(destination).getItems())
			{
				assertFalse(context, item.isBlank());
				actual.merge(item.getItemId() + ":" + item.getQuantity() + ":" + item.isPlaceholder(), 1, Integer::sum);
				if (item.getItemId() == 1161) assertEquals(context, layout.destinationOf("ammunition"), destination);
				if (item.getItemId() == 5318) assertEquals(context, layout.destinationOf("produce"), destination);
			}
			assertEquals(context, expected, actual);
			BankTabPlan plan = BankTabPlan.fromPreview(preview);
			for (RearrangeMode mode : RearrangeMode.values()) verifySorting(plan, mode, context);
			int[] missing = plan.getFlattenedItems().stream().mapToInt(BankPreviewItem::getItemId).toArray();
			missing = Arrays.copyOfRange(missing, 1, missing.length);
			assertFalse(context, TabRouteAdvisor.assess(missing, plan, new int[9]).getMove().isPresent());
			combinations++;
		}
		assertEquals(48, combinations);
	}

	private static void verifySorting(BankTabPlan plan, RearrangeMode mode, String context)
	{
		List<Integer> live = new ArrayList<>();
		int[] counts = new int[9];
		Random random = new Random(20260907);
		for (BankTabPlan.TargetTab tab : plan.getNumberedTabs())
		{
			counts[tab.getBankTabNumber() - 1] = tab.getItems().size();
			appendShuffled(live, tab.getItems(), random);
		}
		appendShuffled(live, plan.getMainItems(), random);
		TabRouteAdvisor.Session session = new TabRouteAdvisor.Session();
		int previousEstimate = Integer.MAX_VALUE;
		for (int step = 0; step <= live.size() * 2; step++)
		{
			int[] ids = live.stream().mapToInt(Integer::intValue).toArray();
			TabRouteAdvisor.Assessment advice = session.assess(ids, plan, counts, step + 1, 1, mode);
			if (advice.getStatus() == TabRouteAdvisor.Status.COMPLETE)
			{
				assertArrayEquals(context, plan.getFlattenedItems().stream().mapToInt(BankPreviewItem::getItemId).toArray(), ids);
				return;
			}
			assertEquals(context, TabRouteAdvisor.Status.READY, advice.getStatus());
			if (mode == RearrangeMode.INSERT)
			{
				int estimate = advice.getProgress().getRemainingDragsEstimate();
				if (previousEstimate != Integer.MAX_VALUE) assertEquals(context, previousEstimate - 1, estimate);
				previousEstimate = estimate;
			}
			TabRouteAdvisor.Move move = advice.getMove().get();
			assertEquals(context, move.getItemId(), (int) live.get(move.getFromSlot()));
			assertEquals(context, mode == RearrangeMode.SWAP ? TabRouteAdvisor.MoveType.SWAP_SECTION
				: TabRouteAdvisor.MoveType.INSERT_SECTION, move.getType());
			if (mode == RearrangeMode.SWAP) Collections.swap(live, move.getFromSlot(), move.getToSlot());
			else live.add(move.getToSlot(), live.remove(move.getFromSlot()));
		}
		fail("Guidance did not finish: " + context + "/" + mode);
	}

	private static void appendShuffled(List<Integer> live, List<BankPreviewItem> items, Random random)
	{
		List<Integer> section = new ArrayList<>();
		for (BankPreviewItem item : items) section.add(item.getItemId());
		Collections.shuffle(section, random);
		live.addAll(section);
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.Assessment;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.Move;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.MoveType;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.Status;
import com.pkoka5.ironmanbankarchitect.organize.BankCategoryPreview;
import com.pkoka5.ironmanbankarchitect.organize.BankOrganizationPreview;
import com.pkoka5.ironmanbankarchitect.organize.BankPresets;
import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class GuideSortingEfficiencyTest
{
	@Test
	public void partialTabDistributionRespectsTheSelectedSortingMode()
	{
		int[] actual = {1, 2, 3, 6, 999, 4, 5};
		BankTabPlan plan = plan(items(1, 2, 3, 4, 5, 6));
		Assessment insert = TabRouteAdvisor.assess(actual, plan, counts(4), 0,
			RearrangeMode.INSERT);
		Assessment swap = TabRouteAdvisor.assess(actual, plan, counts(4), 0,
			RearrangeMode.SWAP);

		assertEquals(Status.READY, insert.getStatus());
		assertEquals(MoveType.DISTRIBUTE_TO_TAB, insert.getMove().get().getType());
		assertEquals(4, insert.getMove().get().getItemId());
		assertEquals(5, insert.getMove().get().getFromSlot());
		assertEquals(5, swap.getMove().get().getItemId());
		assertEquals(1, independentMinimumInserts(new int[]{1, 2, 3, 6, 4, 5},
			new int[]{1, 2, 3, 4, 5, 6}));
		assertEquals(2, independentMinimumInserts(new int[]{1, 2, 3, 6, 5, 4},
			new int[]{1, 2, 3, 4, 5, 6}));
	}

	@Test
	public void everyFixedPrefixGetsAnInsertOptimalAppendTail()
	{
		List<Integer> target = Arrays.asList(1, 2, 3, 4, 5, 6);
		int[] targetIds = array(target);
		List<BankPreviewItem> targetItems = items(targetIds);
		BankTabPlan plan = plan(targetItems);
		Set<List<Integer>> checkedPrefixes = new HashSet<>();
		for (List<Integer> permutation : permutations(target))
		{
			for (int length = 1; length < target.size(); length++)
			{
				List<Integer> prefix = new ArrayList<>(permutation.subList(0, length));
				if (!checkedPrefixes.add(prefix)) continue;
				List<Integer> missing = new ArrayList<>(target);
				missing.removeAll(prefix);
				int optimum = target.size();
				for (List<Integer> tail : permutations(missing))
				{
					List<Integer> candidate = new ArrayList<>(prefix);
					candidate.addAll(tail);
					optimum = Math.min(optimum,
						independentMinimumInserts(array(candidate), targetIds));
				}

				List<Integer> bank = new ArrayList<>(prefix);
				bank.add(999);
				List<Integer> reversedMissing = new ArrayList<>(missing);
				Collections.reverse(reversedMissing);
				bank.addAll(reversedMissing);
				int filled = prefix.size();
				while (filled < target.size())
				{
					Assessment assessment = TabRouteAdvisor.assess(array(bank), plan,
						counts(filled), 0, RearrangeMode.INSERT);
					assertEquals("prefix " + prefix, Status.READY, assessment.getStatus());
					Move move = assessment.getMove().get();
					assertEquals(MoveType.DISTRIBUTE_TO_TAB, move.getType());
					assertEquals(1, move.getTargetTab());
					assertTrue(move.getFromSlot() >= filled);
					bank.add(filled, bank.remove(move.getFromSlot()));
					filled++;
				}
				assertEquals(Integer.valueOf(999), bank.get(target.size()));
				assertEquals("prefix " + prefix, optimum,
					independentMinimumInserts(array(bank.subList(0, target.size())), targetIds));
				assertEquals(optimum,
					SectionInsertPlanner.minimumRemainingInserts(array(bank), 0, targetItems));
			}
		}
		assertEquals(1236, checkedPrefixes.size());
	}

	@Test
	public void uniqueOccurrenceOffsetsAndInsertBoundsMatchIndependentSemantics()
	{
		List<Integer> target = Arrays.asList(41, 7, 88, 3, 19, 62);
		int[] targetIds = array(target);
		List<BankPreviewItem> targetItems = items(targetIds);
		for (List<Integer> permutation : permutations(target))
		{
			int[] section = array(permutation);
			int[] actual = new int[section.length + 3];
			actual[0] = 9000;
			actual[1] = 9001;
			System.arraycopy(section, 0, actual, 2, section.length);
			actual[actual.length - 1] = 9002;
			int[] expectedOffsets = new int[section.length];
			for (int index = 0; index < section.length; index++)
				expectedOffsets[index] = target.indexOf(section[index]);
			assertArrayEquals(expectedOffsets,
				ItemOccurrenceMatcher.orderedTargetOffsets(actual, 2, targetItems));
			int minimum = independentMinimumInserts(section, targetIds);
			assertEquals(minimum,
				SectionInsertPlanner.minimumRemainingInserts(actual, 2, targetItems));
			SectionInsertPlanner.Step step = SectionInsertPlanner.nextStep(actual, 2, targetItems);
			if (minimum == 0)
			{
				assertNull(step);
				continue;
			}
			assertNotNull(step);
			assertTrue(step.getFromSlot() >= 2 && step.getFromSlot() < 8);
			assertTrue(step.getDropSlot() >= 2 && step.getDropSlot() < 8);
			int[] after = SectionInsertPlanner.applyInsert(actual,
				step.getFromSlot(), step.getDropSlot());
			assertEquals(9000, after[0]);
			assertEquals(9001, after[1]);
			assertEquals(9002, after[after.length - 1]);
			assertEquals(minimum - 1,
				independentMinimumInserts(Arrays.copyOfRange(after, 2, 8), targetIds));
		}
	}

	@Test
	public void uniqueMatchingStillRejectsInvalidSectionsAndMultiplicityChanges()
	{
		List<BankPreviewItem> target = items(1, 2, 3);
		assertNull(ItemOccurrenceMatcher.orderedTargetOffsets(new int[]{1, 2, 3}, -1, target));
		assertNull(ItemOccurrenceMatcher.orderedTargetOffsets(new int[]{1, 2}, 0, target));
		assertNull(ItemOccurrenceMatcher.orderedTargetOffsets(new int[]{1, 2, 99}, 0, target));
		assertNull(ItemOccurrenceMatcher.orderedTargetOffsets(new int[]{1, 2, 2}, 0, target));
		assertNull(ItemOccurrenceMatcher.orderedTargetOffsets(new int[]{1}, 0, items()));
	}

	@Test
	public void thousandItemRotationKeepsTheLongRunAndMovesOnlyItsShortTail()
	{
		int size = 1000;
		int rotated = 137;
		int[] target = new int[size];
		int[] actual = new int[size];
		int[] expectedOffsets = new int[size];
		for (int index = 0; index < size; index++)
		{
			target[index] = index + 1;
			actual[index] = (index + rotated) % size + 1;
			expectedOffsets[index] = actual[index] - 1;
		}
		List<BankPreviewItem> targetItems = items(target);
		assertArrayEquals(expectedOffsets,
			ItemOccurrenceMatcher.orderedTargetOffsets(actual, 0, targetItems));
		assertEquals(rotated,
			SectionInsertPlanner.minimumRemainingInserts(actual, 0, targetItems));
		SectionInsertPlanner.Step step = SectionInsertPlanner.nextStep(actual, 0, targetItems);
		assertNotNull(step);
		assertEquals(1, step.getItem().getItemId());
		assertEquals(size - rotated, step.getFromSlot());
		assertEquals(0, step.getDropSlot());
		assertEquals(rotated - 1, SectionInsertPlanner.minimumRemainingInserts(
			SectionInsertPlanner.applyInsert(actual, step.getFromSlot(), step.getDropSlot()),
			0, targetItems));
	}

	// Independent common-subsequence bound, without occurrence mapping or LIS.
	private static int independentMinimumInserts(int[] actual, int[] target)
	{
		int[][] lengths = new int[actual.length + 1][target.length + 1];
		for (int current = 1; current <= actual.length; current++)
			for (int desired = 1; desired <= target.length; desired++)
				lengths[current][desired] = actual[current - 1] == target[desired - 1]
					? lengths[current - 1][desired - 1] + 1
					: Math.max(lengths[current - 1][desired], lengths[current][desired - 1]);
		return actual.length - lengths[actual.length][target.length];
	}

	private static BankTabPlan plan(List<BankPreviewItem> target)
	{
		List<BankCategoryPreview> categories = new ArrayList<>();
		for (int index = 0; index < 10; index++)
			categories.add(new BankCategoryPreview(BankPresets.IRONMAN.getCategories().get(index),
				index == 0 ? items(999) : index == 1 ? target : Collections.emptyList()));
		return BankTabPlan.fromPreview(new BankOrganizationPreview(BankPresets.IRONMAN, categories));
	}

	private static List<BankPreviewItem> items(int... ids)
	{
		List<BankPreviewItem> result = new ArrayList<>();
		for (int id : ids) result.add(new BankPreviewItem(id, "Item " + id, 1));
		return result;
	}

	private static int[] counts(int first)
	{
		int[] result = new int[TabRouteAdvisor.MAX_TABS];
		result[0] = first;
		return result;
	}

	private static int[] array(List<Integer> values)
	{
		return values.stream().mapToInt(Integer::intValue).toArray();
	}

	private static List<List<Integer>> permutations(List<Integer> values)
	{
		List<List<Integer>> result = new ArrayList<>();
		permute(new ArrayList<>(values), 0, result);
		return result;
	}

	private static void permute(List<Integer> values, int position, List<List<Integer>> result)
	{
		if (position == values.size())
		{
			result.add(new ArrayList<>(values));
			return;
		}
		for (int selected = position; selected < values.size(); selected++)
		{
			Collections.swap(values, position, selected);
			permute(values, position + 1, result);
			Collections.swap(values, position, selected);
		}
	}
}

package com.pkoka5.ironmanbankarchitect.guide;

import com.pkoka5.ironmanbankarchitect.organize.BankCategoryPreview;
