	public void byFamilyUnitesDoseFamiliesAcrossTheBucketBoundary()
	{
		BankSnapshot bank = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(12625, 38, 0),  // Stamina potion(4)
			new BankItemSnapshot(385, 184, 1),   // Shark
