package com.pkoka5.ironmanbankarchitect.organize;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class BankLayoutPlanTest
{
	private static final BankPreset PRESET = BankPresets.IRONMAN;

	@Test
	public void newAlchTagFollowsLootInOldLayoutsAndKeepsExplicitCustomPlacement()
	{
		for (BankPreset preset : Arrays.asList(BankPresets.IRONMAN, BankPresets.MAIN))
		{
			BankLayoutPlan edited = BankLayoutPlan.defaultFor(preset).withTagAt("boss-loot", 4)
				.withTagAt("alch", 2).withCurrentOrder(4, true);
			String oldPlan = edited.serialize().replace("+alch", "").replace("alch+", "");
			BankLayoutPlan migrated = BankLayoutPlan.parse(preset, oldPlan);
			assertEquals(4, migrated.destinationOf("alch"));
			assertEquals(4, migrated.destinationOf("boss-loot"));
			assertTrue(migrated.keepsCurrentOrder(4));
			BankLayoutPlan restored = BankLayoutPlan.parse(preset, edited.serialize());
			assertEquals(2, restored.destinationOf("alch"));
			assertEquals(4, restored.destinationOf("boss-loot"));
		}
	}

	@Test
	public void defaultPlanKeepsEachCategorysTagsTogetherOnItsOwnDestination()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET);

		List<BankCategory> categories = PRESET.getCategories();
		assertEquals(BankLayoutPlan.DESTINATION_COUNT, plan.getDestinations().size());
		for (int index = 0; index < categories.size(); index++)
		{
			List<String> expected = new ArrayList<>();
			for (BankTag tag : BankTags.forCategory(categories.get(index).getKey()))
			{
				expected.add(tag.getKey());
			}
			assertEquals(expected, plan.getTagKeys(index));
		}
		assertTrue(plan.isDefault(PRESET));
	}

	/** The reported case: food leaves the potions tab without taking potions along. */
	@Test
	public void oneTagOfABundleCanMoveWithoutTheRest()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET).withTagAt("food", 8);

		assertEquals(8, plan.destinationOf("food"));
		assertFalse(plan.getTagKeys(8).contains("potions"));
		assertFalse(plan.destinationOf("potions") == 8);
		assertFalse(plan.isDefault(PRESET));
	}

	@Test
	public void everyTagOfThePlanHasExactlyOneDestination()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET)
			.withTagAt("runes", 2)
			.withTagAt("teleports", 5);

		for (BankTag tag : BankTags.all())
		{
			assertTrue(tag.getKey(), plan.destinationOf(tag.getKey()) >= 0);
			assertEquals(tag.getKey(), 1, countPlacements(plan, tag.getKey()));
		}
	}

	@Test
	public void mainSectionCanBeLeftEmpty()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET);
		for (String key : new ArrayList<>(plan.getTagKeys(BankLayoutPlan.MAIN_DESTINATION_INDEX)))
		{
			plan = plan.withTagAt(key, 5);
		}

		assertTrue(plan.getTagKeys(BankLayoutPlan.MAIN_DESTINATION_INDEX).isEmpty());
	}

	@Test
	public void shiftingWithinADestinationDecidesWhichTagLeadsTheTab()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET).withTagAt("food", 0);
		List<String> before = plan.getTagKeys(0);

		BankLayoutPlan shifted = plan.withTagShifted("food", -1);

		assertEquals(before.size(), shifted.getTagKeys(0).size());
		assertEquals(before.get(before.size() - 2),
			shifted.getTagKeys(0).get(before.size() - 1));
	}

	@Test
	public void shiftingPastTheEndOfADestinationIsIgnored()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET);
		String first = plan.getTagKeys(1).get(0);

		assertSame(plan, plan.withTagShifted(first, -1));
	}

	@Test
	public void movingATagWhereItAlreadySitsChangesNothing()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET);

		assertSame(plan, plan.withTagAt("potions", plan.destinationOf("potions")));
	}

	@Test
	public void planSurvivesASaveAndLoadRound()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET)
			.withTagAt("food", 8)
			.withTagAt("runes", 3)
			.withTagAt(PRESET.getCategories().get(0).getKey().equals("currency-utilities")
				? "currency" : "currency", 4);

		BankLayoutPlan reloaded = BankLayoutPlan.parse(PRESET, plan.serialize());

		assertEquals(plan.getDestinations(), reloaded.getDestinations());
	}

	@Test
	public void unplacedTagsJoinTheFallbackDestinationRatherThanDisappearing()
	{
		BankLayoutPlan plan = BankLayoutPlan.parse(PRESET,
			"potions|" + BankLayoutPlan.FALLBACK_TAG_KEY + "||||||||");

		assertEquals(1, plan.destinationOf(BankLayoutPlan.FALLBACK_TAG_KEY));
		assertEquals(BankTags.all().size(), placedCount(plan));
		assertTrue(plan.getTagKeys(1).contains("clean-herbs"));
	}

	@Test
	public void remainderFallsToTheLastDestinationWhenTheFallbackTagIsAlsoUnplaced()
	{
		BankLayoutPlan plan = BankLayoutPlan.parse(PRESET, "potions|||||||||");

		assertEquals(BankTags.all().size(), placedCount(plan));
		assertTrue(plan.getTagKeys(BankLayoutPlan.DESTINATION_COUNT - 1)
			.contains(BankLayoutPlan.FALLBACK_TAG_KEY));
	}

	@Test
	public void unknownAndRepeatedKeysAreDroppedInsteadOfBreakingThePlan()
	{
		BankLayoutPlan plan = BankLayoutPlan.parse(PRESET,
			"potions+not-a-tag|potions|||||||food");

		assertEquals(Collections.singletonList("potions"), plan.getTagKeys(0));
		assertTrue(plan.getTagKeys(1).isEmpty());
		assertEquals(BankTags.all().size(), placedCount(plan));
	}

	/** A plan stored before tags existed named categories, and must still load. */
	@Test
	public void aStoredCategoryKeyIsReadAsAllOfItsTags()
	{
		BankLayoutPlan plan = BankLayoutPlan.parse(PRESET, "potions-food|combat-gear||||||||");

		for (BankTag tag : BankTags.forCategory("potions-food"))
		{
			assertEquals(tag.getKey(), 0, plan.destinationOf(tag.getKey()));
		}
		for (BankTag tag : BankTags.forCategory("combat-gear"))
		{
			assertEquals(tag.getKey(), 1, plan.destinationOf(tag.getKey()));
		}
	}

	@Test
	public void theOlderCommaSeparatedCategoryOrderIsStillRead()
	{
		List<String> reversed = new ArrayList<>();
		for (BankCategory category : PRESET.getCategories())
		{
			reversed.add(0, category.getKey());
		}

		BankLayoutPlan plan = BankLayoutPlan.parse(PRESET, String.join(",", reversed));

		for (int index = 0; index < reversed.size(); index++)
		{
			List<String> expected = new ArrayList<>();
			for (BankTag tag : BankTags.forCategory(reversed.get(index)))
			{
				expected.add(tag.getKey());
			}
			assertEquals(expected, plan.getTagKeys(index));
		}
	}

	@Test
	public void blankStoredPlanFallsBackToThePresetArrangement()
	{
		assertTrue(BankLayoutPlan.parse(PRESET, "").isDefault(PRESET));
		assertTrue(BankLayoutPlan.parse(PRESET, null).isDefault(PRESET));
	}

	@Test
	public void severalBundlesCanShareOneTab()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET)
			.withTagAt("cosmetics", 1)
			.withTagAt("collection-log", 1);

		assertTrue(plan.getTagKeys(1).containsAll(Arrays.asList("cosmetics", "collection-log")));
	}

	private static int countPlacements(BankLayoutPlan plan, String tagKey)
	{
		int count = 0;
		for (List<String> destination : plan.getDestinations())
		{
			count += Collections.frequency(destination, tagKey);
		}

		return count;
	}

	private static int placedCount(BankLayoutPlan plan)
	{
		int count = 0;
		for (List<String> destination : plan.getDestinations())
		{
			count += destination.size();
		}

		return count;
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class BankLayoutSharingTest
{
	private static final BankPreset PRESET = BankPresets.IRONMAN;

	@Test
	public void aSharedLayoutSurvivesTheRoundTripToAnotherPlayer()
	{
		BankLayoutPlan mine = BankLayoutPlan.defaultFor(PRESET)
			.withTagAt("food", 8)
			.withTagAt("runes", 3);

		String code = BankLayoutShareCode.encode("Maugor setup", mine);
		BankLayoutShareCode received = BankLayoutShareCode.decode(code).get();
		BankLayoutPlan theirs = BankLayoutPlan.parse(PRESET, received.getPlan());

		assertEquals("Maugor setup", received.getName());
		assertEquals(mine.getDestinations(), theirs.getDestinations());
	}

	@Test
	public void mainShareCodesPreservePresetIdentityAndKeepCurrentOrderFlags()
	{
		BankLayoutPlan mine = BankLayoutPlan.defaultFor(BankPresets.MAIN)
			.withTagAt("food", 8).withCurrentOrder(2, true).withCurrentOrder(7, true);
		String encoded = BankLayoutShareCode.encode("Main setup", mine, BankPresets.MAIN);
		BankLayoutShareCode decoded = BankLayoutShareCode.decode("  " + encoded + "\n").get();
		BankLayoutPlan received = BankLayoutPlan.parse(BankPresets.MAIN, decoded.getPlan());

		assertTrue(encoded.startsWith("BAv2~MAIN~"));
		assertEquals(BankPresetType.MAIN, decoded.getPresetType());
		assertEquals("Main setup", decoded.getName());
		assertEquals(mine.serialize(), received.serialize());
		assertTrue(received.keepsCurrentOrder(2));
		assertTrue(received.keepsCurrentOrder(7));
		assertFalse(received.keepsCurrentOrder(1));
	}

	@Test
	public void explicitIronmanEncodingRetainsTheExistingShareFormat()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET).withCurrentOrder(1, true);
		String original = BankLayoutShareCode.encode("Ironman setup", plan);
		String explicit = BankLayoutShareCode.encode("Ironman setup", plan, PRESET);

		assertEquals(original, explicit);
		assertTrue(explicit.startsWith("BAv1~"));
		assertEquals(BankPresetType.IRONMAN, BankLayoutShareCode.decode(explicit).get().getPresetType());
	}

	@Test
	public void legacyShareCodesAlwaysIdentifyAsIronman()
	{
		BankLayoutShareCode legacy = BankLayoutShareCode.decode("BAv1~Old layout~currency|gear|food+potions").get();

		assertEquals(BankPresetType.IRONMAN, legacy.getPresetType());
		assertEquals("Old layout", legacy.getName());
		assertEquals("currency|gear|food+potions", legacy.getPlan());
	}

	@Test
	public void versionedCodesRejectMissingUnknownAndUnavailablePresets()
	{
		for (String malformed : new String[]{"BAv2", "BAv2~", "BAv2~MAIN", "BAv2~MAIN~name",
			"BAv2~~name~food|gear", "BAv2~Unknown~name~food|gear", "BAv2~PVM~name~food|gear",
			"BAv2~PVP~name~food|gear", "BAv2~SKILLER~name~food|gear", "BAv2~MAIN~name~",
			"BAv2~MAIN~name~   ", "BAv3~MAIN~name~food|gear"})
			assertFalse(malformed, BankLayoutShareCode.decode(malformed).isPresent());
	}

	@Test
	public void pastedTextWithSurroundingWhitespaceStillDecodes()
	{
		String code = BankLayoutShareCode.encode("Setup", BankLayoutPlan.defaultFor(PRESET));

		assertTrue(BankLayoutShareCode.decode("  " + code + "\n").isPresent());
	}

	@Test
	public void textThatIsNotAShareCodeIsRefusedRatherThanGuessedAt()
	{
		assertFalse(BankLayoutShareCode.decode(null).isPresent());
		assertFalse(BankLayoutShareCode.decode("").isPresent());
		assertFalse(BankLayoutShareCode.decode("hello there").isPresent());
		assertFalse(BankLayoutShareCode.decode("BAv1~name").isPresent());
		assertFalse(BankLayoutShareCode.decode("BAv1~name~").isPresent());
	}

	@Test
	public void aNameCannotCarryTheSeparatorsThatWouldSplitTheCode()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(PRESET);

		Optional<BankLayoutShareCode> decoded =
			BankLayoutShareCode.decode(BankLayoutShareCode.encode("od~d|na+me;setup", plan));

		assertTrue(decoded.isPresent());
		assertEquals("od d na me setup", decoded.get().getName());
	}

	@Test
	public void aBlankNameBecomesSomethingTheReceiverCanRead()
	{
		assertEquals("Shared layout", BankLayoutShareCode.sanitize("   "));
		assertEquals("Shared layout", BankLayoutShareCode.sanitize(null));
	}

	@Test
	public void thereIsAlwaysABundledProfileToFallBackOn()
	{
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "");

		assertEquals(BankLayoutProfiles.DEFAULT_NAME, profiles.names().get(0));
		assertTrue(profiles.isDefaultActive());
		assertEquals("", profiles.activePlan());
	}

	@Test
	public void savingAProfileMakesItTheOneInUseAndSurvivesReload()
	{
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "")
			.withProfile("Skiller", "potions|gear");

		BankLayoutProfiles reloaded =
			BankLayoutProfiles.parse(profiles.serialize(), profiles.getActiveName());

		assertEquals("Skiller", reloaded.getActiveName());
		assertEquals("potions|gear", reloaded.activePlan());
		assertEquals(2, reloaded.names().size());
	}

	@Test
	public void thebundledProfileCannotBeOverwrittenOrRemoved()
	{
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "")
			.withProfile(BankLayoutProfiles.DEFAULT_NAME, "potions|gear");

		assertNotEquals(BankLayoutProfiles.DEFAULT_NAME, profiles.getActiveName());
		assertEquals("", profiles.planFor(BankLayoutProfiles.DEFAULT_NAME));

		BankLayoutProfiles afterRemoval = profiles.without(BankLayoutProfiles.DEFAULT_NAME);
		assertTrue(afterRemoval.names().contains(BankLayoutProfiles.DEFAULT_NAME));
	}

	@Test
	public void removingTheProfileInUseFallsBackToTheBundledOne()
	{
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "")
			.withProfile("Skiller", "potions|gear");

		BankLayoutProfiles removed = profiles.without("Skiller");

		assertTrue(removed.isDefaultActive());
		assertFalse(removed.names().contains("Skiller"));
	}

	@Test
	public void animportNeverOverwritesALayoutTheplayerAlreadyHas()
	{
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "")
			.withProfile("Skiller", "potions|gear");

		assertEquals("Skiller 2", profiles.freeName("Skiller"));
		assertEquals("Pvm", profiles.freeName("Pvm"));
	}

	@Test
	public void importingAMaximumLengthNamePreservesBothPlansAfterReload()
	{
		String originalName = "1234567890123456789012345678901234567890";
		String originalPlan = BankLayoutPlan.defaultFor(PRESET).withTagAt("food", 8).serialize();
		String importedPlan = BankLayoutPlan.defaultFor(PRESET).withTagAt("food", 3).serialize();
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "")
			.withProfile(originalName, originalPlan);
		String importedName = profiles.freeName(originalName);

		assertTrue(importedName.length() <= 40);
		assertNotEquals(originalName, importedName);
		assertEquals(importedName, BankLayoutShareCode.sanitize(importedName));
		assertEquals(importedName, BankLayoutProfiles.freeName(originalName, profiles.names()));
		profiles = profiles.withProfile(importedName, importedPlan);
		BankLayoutProfiles reloaded = BankLayoutProfiles.parse(profiles.serialize(), profiles.getActiveName());

		assertEquals(3, reloaded.names().size());
		assertEquals(originalPlan, reloaded.planFor(originalName));
		assertEquals(importedPlan, reloaded.activePlan());
		assertEquals(importedName, reloaded.getActiveName());
	}

	@Test
	public void twoDigitSuffixesAlsoFitAndCheckTheirFinalStoredName()
	{
		String wanted = "1234567890123456789012345678901234567890";
		List<String> existing = new ArrayList<>();
		existing.add(wanted);
		for (int suffix = 2; suffix <= 9; suffix++)
		{
			existing.add(wanted.substring(0, 38) + " " + suffix);
		}
		String freeName = BankLayoutProfiles.freeName(wanted, existing);

		assertEquals(wanted.substring(0, 37) + " 10", freeName);
		assertEquals(freeName, BankLayoutShareCode.sanitize(freeName));
		assertFalse(existing.contains(freeName));
	}

	@Test
	public void aSemicolonInAProfileNameCannotBreakItsActivePlanOnReload()
	{
		String plan = BankLayoutPlan.defaultFor(PRESET).withTagAt("gear", 8).serialize();
		String name = BankLayoutShareCode.sanitize("Raid; prep");
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "")
			.withProfile("Raid; prep", plan);
		BankLayoutProfiles reloaded = BankLayoutProfiles.parse(profiles.serialize(), profiles.getActiveName());

		assertFalse(name.contains(";"));
		assertEquals(name + " 2", BankLayoutProfiles.freeName("Raid; prep", profiles.names()));
		assertEquals(name, profiles.getActiveName());
		assertEquals(name, reloaded.getActiveName());
		assertEquals(plan, reloaded.activePlan());
		assertEquals(2, reloaded.names().size());
	}

	@Test
	public void aLegacyActiveSemicolonNameIsRecoveredWithoutLosingOtherProfiles()
	{
		String oldName = "Raid; prep";
		String plan = BankLayoutPlan.defaultFor(PRESET).withTagAt("gear", 8).serialize();
		BankLayoutProfiles recovered = BankLayoutProfiles.parse(
			"Skiller~original;" + oldName + "~" + plan + ";Bossing~other", oldName);
		String recoveredName = BankLayoutShareCode.sanitize(oldName);

		assertEquals("Raid  prep", recoveredName);
		assertEquals(recoveredName, recovered.getActiveName());
		assertEquals(plan, recovered.activePlan());
		assertEquals("original", recovered.planFor("Skiller"));
		assertEquals("other", recovered.planFor("Bossing"));
		assertEquals(4, recovered.names().size());
		BankLayoutProfiles reloaded = BankLayoutProfiles.parse(recovered.serialize(), recovered.getActiveName());
		assertEquals(recovered.names(), reloaded.names());
		assertEquals(recoveredName, reloaded.getActiveName());
		assertEquals(plan, reloaded.activePlan());
	}

	@Test
	public void aMalformedStoredEntryIsSkippedWithoutLosingTheRest()
	{
		BankLayoutProfiles profiles = BankLayoutProfiles.parse(
			"broken;Skiller~potions|gear;alsobroken~", "Skiller");

		assertEquals(2, profiles.names().size());
		assertEquals("Skiller", profiles.getActiveName());
	}

	@Test
	public void anUnknownActiveNameFallsBackToTheBundledProfile()
	{
		BankLayoutProfiles profiles = BankLayoutProfiles.parse("", "Gone");

		assertTrue(profiles.isDefaultActive());
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static org.junit.Assert.assertEquals;
