package com.pkoka5.ironmanbankarchitect.organize;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BankTagsTest
{
	@Test
	public void everyCategoryOfThePresetSplitsIntoAtLeastOneTag()
	{
		for (BankCategory category : BankPresets.IRONMAN.getCategories())
		{
			List<BankTag> tags = BankTags.forCategory(category.getKey());
			assertTrue(category.getKey() + " has no tags", !tags.isEmpty());
			for (BankTag tag : tags)
			{
				assertEquals(category.getKey(), tag.getCategoryKey());
			}
		}
	}

	@Test
	public void tagKeysAreUnique()
	{
		Set<String> keys = new HashSet<>();
		for (BankTag tag : BankTags.all())
		{
			assertTrue("duplicate tag key: " + tag.getKey(), keys.add(tag.getKey()));
		}

		assertEquals(keys.size(), BankTags.all().size());
	}

	/** The reported case: potions and food were one bundle and must now separate. */
	@Test
	public void potionsAndFoodAreSeparateTags()
	{
		BankTag potions = BankTags.tagFor("potions-food", "potion");
		BankTag food = BankTags.tagFor("potions-food", "food");

		assertEquals("potions", potions.getKey());
		assertEquals("food", food.getKey());
	}

	@Test
	public void theMainSectionBundleSplitsIntoRunesTeleportsAndCurrency()
	{
		assertEquals("runes", BankTags.tagFor("currency-utilities", "rune").getKey());
		assertEquals("teleports", BankTags.tagFor("currency-utilities", "teleport").getKey());
		assertEquals("currency", BankTags.tagFor("currency-utilities", "currency").getKey());
	}

	/**
	 * The refined teleport subcategories must keep reaching the Teleports tag.
	 * When tablet and scroll were introduced without being listed here, every
	 * city tablet fell through to the Frequently Used catch-all and a plan
	 * sent them wherever that tag lived - usually the front of the main tab.
	 */
	@Test
	public void refinedTeleportSubcategoriesStayOnTheTeleportsTag()
	{
		assertEquals("teleports", BankTags.tagFor("currency-utilities", "teleport-tablet").getKey());
		assertEquals("teleports", BankTags.tagFor("currency-utilities", "teleport-scroll").getKey());
		assertEquals("teleports", BankTags.tagFor("currency-utilities", "teleport-charge").getKey());
		assertEquals("teleports", BankTags.tagFor("currency-utilities", "transport-access").getKey());
	}

	@Test
	public void theHerbloreChainSplitsIntoItsWorkflowSteps()
	{
		assertEquals("grimy-herbs", BankTags.tagFor("herblore", "grimy-herb").getKey());
		assertEquals("clean-herbs", BankTags.tagFor("herblore", "clean-herb").getKey());
		assertEquals("secondaries", BankTags.tagFor("herblore", "secondary").getKey());
		assertEquals("unfinished-potions", BankTags.tagFor("herblore", "unfinished-potion").getKey());
		assertEquals("potion-doses", BankTags.tagFor("herblore", "potion-dose-2").getKey());
	}

	@Test
	public void anUnmatchedSubcategoryFallsToItsCategoryCatchAllRatherThanVanishing()
	{
		assertEquals("raw-resources", BankTags.tagFor("resources", "not-a-subcategory").getKey());
		assertEquals("gear", BankTags.tagFor("combat-gear", "head").getKey());
		assertEquals("cleanup", BankTags.tagFor("storage-cleanup", "junk").getKey());
		assertEquals("frequently-used", BankTags.tagFor("currency-utilities", "").getKey());
		assertEquals("clues", BankTags.tagFor("clues-cosmetics", null).getKey());
	}

	/**
	 * A stored plan names both, and a key that could be either would be read as
	 * one tag where the player meant a whole bundle.
	 */
	@Test
	public void noTagKeyCollidesWithACategoryKey()
	{
		for (BankCategory category : BankPresets.IRONMAN.getCategories())
		{
			assertFalse("tag key collides with category " + category.getKey(),
				BankTags.isKnown(category.getKey()));
		}
	}

	@Test
	public void subcategoryMatchingIgnoresCaseAndSurroundingSpace()
	{
		assertEquals("food", BankTags.tagFor("potions-food", "  FOOD ").getKey());
	}

	@Test
	public void everyTagIsReachableByItsOwnKey()
	{
		for (BankTag tag : BankTags.all())
		{
			assertTrue(BankTags.isKnown(tag.getKey()));
			assertEquals(tag, BankTags.byKey(tag.getKey()));
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static org.junit.Assert.assertEquals;

import java.util.Arrays;
import java.util.Collections;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Saved arrangements preserve future data without overriding current edits. */
public class BlockArrangementsTest
{
	@Test
	public void unknownVersionDoesNotSwallowANewerEdit()
	{
		String stored = BlockArrangements.parse("v2!gear>item:1")
			.withTag("gear", Collections.singletonList("item:2"))
			.serialize();

		assertEquals("the saved choice must survive a reload",
			Arrays.asList("item:2"), BlockArrangements.parse(stored).orders().get("gear"));
	}

	@Test
	public void anUntouchedUnknownVersionRoundTripsVerbatim()
	{
		assertEquals("v10!gear>item:1", BlockArrangements.parse("v10!gear>item:1").serialize());
	}

	@Test
	public void futurePayloadSurvivesRepeatedEditsAndCannotResurrectARemovedTag()
	{
		String future = "v2!gear>item:1!opaque>你好^!";
		String stored = BlockArrangements.parse(future)
			.withTag("gear", Arrays.asList("item:2")).serialize();
		String payload = Base64.getUrlEncoder().withoutPadding()
			.encodeToString(future.getBytes(StandardCharsets.UTF_8));
		assertTrue(stored.contains("!U" + payload));
		stored = BlockArrangements.parse(stored).withTag("tools", Arrays.asList("item:3"))
			.withoutTag("gear").serialize();
		assertTrue(stored.contains("!U" + payload));
		assertEquals(Collections.singletonMap("tools", Arrays.asList("item:3")),
			BlockArrangements.parse(stored).orders());
	}

	@Test
	public void legacyValuesStayReadableAndUntouchedInputStaysVerbatim()
	{
		String legacy = "v1!gear>item:1^item:2!unrecognized";
		BlockArrangements parsed = BlockArrangements.parse(legacy);
		assertEquals(Arrays.asList("item:1", "item:2"), parsed.orders().get("gear"));
		assertEquals(legacy, parsed.serialize());
		assertEquals(legacy, parsed.withTag("gear", Arrays.asList("item:1", "item:2")).serialize());
		String edited = parsed.withTag("tools", Arrays.asList("name:!>^~;+你好")).serialize();
		assertEquals(Arrays.asList("name:!>^~;+你好"),
			BlockArrangements.parse(edited).orders().get("tools"));
	}

	@Test
	public void malformedNewRecordsStayOpaqueAfterEdits()
	{
		String input = "BAblocks2!Tnot-base64>%%%";
		assertEquals(input, BlockArrangements.parse(input).serialize());
		String edited = BlockArrangements.parse(input).withTag("gear", Arrays.asList("item:2"))
			.serialize();
		assertEquals(Collections.singletonMap("gear", Arrays.asList("item:2")),
			BlockArrangements.parse(edited).orders());
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The block-order law: curated output stands byte for byte until the player
 * saves an arrangement, and from then on their block sequence wins, newcomers
 * anchoring after their nearest curated predecessor.
 */
public class BlockOrderTest
{
	private static final String PARTYHATS = "set:cosmetic-family.partyhats";
	private static final String DYES = "set:cosmetic-family.dyes";
	private static final String FIRELIGHTERS = "set:cosmetic-family.firelighters";
	private static final String KITTEN = "item:1559";

	// Blue and red partyhats, blue and red dye, the kitten.
	private static final BankSnapshot COSMETICS = new BankSnapshot(Arrays.asList(
		new BankItemSnapshot(1042, 1, 0),
		new BankItemSnapshot(1038, 1, 1),
		new BankItemSnapshot(1767, 1, 2),
		new BankItemSnapshot(1763, 1, 3),
		new BankItemSnapshot(1559, 1, 4)));

	@Test
	public void withoutAnArrangementTheCuratedOrderStandsByteForByte()
	{
		BankLayoutOptions unrelated = BankLayoutOptions.DEFAULTS.withBlockArrangements(
			BlockArrangements.EMPTY.withTag("teleports", Arrays.asList("item:8007")));

		assertEquals(idsOn(build(COSMETICS, BankLayoutOptions.DEFAULTS), cosmeticsTab()),
			idsOn(build(COSMETICS, unrelated), cosmeticsTab()));
	}

	@Test
	public void aSavedSequenceReordersWholeBlocks()
	{
		BankLayoutOptions arranged = BankLayoutOptions.DEFAULTS.withBlockArrangements(
			BlockArrangements.EMPTY.withTag("cosmetics",
				Arrays.asList(DYES, KITTEN, PARTYHATS)));

		assertEquals(Arrays.asList(1767, 1763, 1559, 1042, 1038),
			idsOn(build(COSMETICS, arranged), cosmeticsTab()));
	}

	/**
	 * A block the player never saw slots in after its nearest curated-order
	 * predecessor among the arranged blocks, not at the tail: the firelighter
	 * follows the partyhats because curation files it after them.
	 */
	@Test
	public void aNewcomerBlockAnchorsAfterItsCuratedPredecessor()
	{
		List<BankItemSnapshot> withFirelighter = new ArrayList<>(COSMETICS.getItems());
		withFirelighter.add(new BankItemSnapshot(7329, 1, 5));
		BankLayoutOptions arranged = BankLayoutOptions.DEFAULTS.withBlockArrangements(
			BlockArrangements.EMPTY.withTag("cosmetics",
				Arrays.asList(KITTEN, PARTYHATS, DYES)));

		assertEquals(Arrays.asList(1559, 1042, 1038, 7329, 1767, 1763),
			idsOn(build(new BankSnapshot(withFirelighter), arranged), cosmeticsTab()));
	}

	/**
	 * An arrangement saved before an item joined a catalogued family still
	 * places it: the stored item key resolves to the family that now holds it.
	 */
	@Test
	public void anItemKeyResolvesToTheFamilyThatNowContainsIt()
	{
		BankLayoutOptions arranged = BankLayoutOptions.DEFAULTS.withBlockArrangements(
			BlockArrangements.EMPTY.withTag("cosmetics",
				Arrays.asList("item:1042", DYES)));

		assertEquals(Arrays.asList(1042, 1038, 1767, 1763, 1559),
			idsOn(build(COSMETICS, arranged), cosmeticsTab()));
	}

	@Test
	public void gearListPlaysTheSetsInTheArrangedOrder()
	{
		BankSnapshot gear = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(1161, 1, 0),   // Adamant full helm
			new BankItemSnapshot(1123, 1, 1),   // Adamant platebody
			new BankItemSnapshot(9674, 1, 2),   // Proselyte hauberk
			new BankItemSnapshot(9676, 1, 3))); // Proselyte cuisse
		BankLayoutOptions arranged = new BankLayoutOptions(true, true, true,
			Collections.emptyMap(), GearLayout.LIST, PotionDoseOrder.GRAB_AREA,
			RuneOrder.ALPHABETICAL, TeleportOrder.ALPHABETICAL)
			.withBlockArrangements(BlockArrangements.EMPTY.withTag("gear",
				Arrays.asList("set:gear.proselyte", "set:gear.adamant-armour")));

		assertEquals(Arrays.asList(9674, 9676, 1161, 1123),
			idsOn(build(gear, arranged), gearTab()));
	}

	@Test
	public void theBlockDescriptorsMirrorTheEffectiveOrder()
	{
		BankLayoutOptions arranged = BankLayoutOptions.DEFAULTS.withBlockArrangements(
			BlockArrangements.EMPTY.withTag("cosmetics",
				Arrays.asList(DYES, KITTEN, PARTYHATS)));

		List<BankBlockDescriptor> blocks =
			build(COSMETICS, arranged).getBlockDescriptors().get("cosmetics");
		List<String> keys = new ArrayList<>();
		for (BankBlockDescriptor block : blocks)
		{
			keys.add(block.getBlockKey());
		}

		assertEquals(Arrays.asList(DYES, KITTEN, PARTYHATS), keys);
		assertEquals(2, blocks.get(0).getMemberCount());
		assertTrue(blocks.get(2).getDisplayName().length() > 0);
	}

	@Test
	public void arrangementsRoundTripAndPreserveWhatTheyDoNotUnderstand()
	{
		BlockArrangements arrangements = BlockArrangements.EMPTY
			.withTag("cosmetics", Arrays.asList(DYES, PARTYHATS))
			.withTag("teleports", Arrays.asList("name:varrock teleport"));

		assertEquals(arrangements, BlockArrangements.parse(arrangements.serialize()));
		assertEquals(Collections.emptyList(),
			new ArrayList<>(arrangements.withoutTag("cosmetics")
				.withoutTag("teleports").orders().keySet()));

		// A value written by a newer format survives a parse-serialize cycle.
		String newer = "v9?whatever&the&future&stores";
		assertEquals(newer, BlockArrangements.parse(newer).serialize());
	}

	private static int cosmeticsTab()
	{
		return BankLayoutPlan.defaultFor(BankPresets.IRONMAN).destinationOf("cosmetics");
	}

	private static int gearTab()
	{
		return BankLayoutPlan.defaultFor(BankPresets.IRONMAN).destinationOf("gear");
	}

	private static List<Integer> idsOn(BankOrganizationPreview preview, int destination)
	{
		BankCategoryPreview tab = preview.getCategories().get(destination);
		List<Integer> ids = new ArrayList<>();
		for (BankPreviewItem item : tab.getItems())
		{
			ids.add(item.getItemId());
		}
		return ids;
	}

	private static BankOrganizationPreview build(BankSnapshot snapshot, BankLayoutOptions options)
	{
		return BankOrganizationPreviewBuilder.build(snapshot, CompositeItemCatalog.DEFAULT,
			BankPresets.IRONMAN, GearStatsSource.NONE, ItemValueSource.NONE,
			CategoryOverrideSource.NONE, BankLayoutPlan.defaultFor(BankPresets.IRONMAN), options);
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.guide.BankTabPlan;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.*;

public class BlueprintItemOrdersTest
{
	@Test public void fullCapacityOrderRoundTripsWithoutLosingAnyOccurrence()
	{
		List<Integer> ids = java.util.stream.IntStream.rangeClosed(1, BlueprintItemOrders.BANK_CAPACITY)
			.boxed().collect(Collectors.toList());
		BankOrganizationPreview original = preview(ids.toArray(new Integer[0]));
		Collections.reverse(ids);
		BlueprintItemOrders orders = BlueprintItemOrders.parse(BlueprintItemOrders.EMPTY.withTab(0, ids).serialize());
		assertEquals(ids, ids(orders.apply(original), 0));
		assertEquals(BlueprintItemOrders.BANK_CAPACITY, orders.apply(original).getPlannedItemCount());
	}

	@Test public void changedItemAssignmentDisablesRouteAndRestoringItReactivatesRoute()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(BankPresets.IRONMAN);
		int target = plan.destinationOf("tools");
		BlueprintItemOrders orders = BlueprintItemOrders.EMPTY.withDestinations(Collections.singletonMap(
			"4151#0", new BlueprintItemOrders.Destination(target, "gear", "tools")));
		BankOrganizationPreview corrected = weaponPreview(plan, orders, id -> java.util.Optional.of("food"));
		assertTrue(ids(corrected, target).isEmpty());
		assertEquals(Arrays.asList(4151, 4151), ids(corrected, plan.destinationOf("food")));
		assertEquals(Collections.singletonList(4151), ids(weaponPreview(plan,
			BlueprintItemOrders.parse(orders.serialize()), CategoryOverrideSource.NONE), target));
	}

	@Test public void crossTabMoveSurvivesReloadAndMovesOnlyOnePhysicalCopy()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(BankPresets.IRONMAN);
		int target = plan.destinationOf("tools");
		BlueprintItemOrders orders = BlueprintItemOrders.EMPTY.withDestinations(Collections.singletonMap(
			"4151#1", new BlueprintItemOrders.Destination(target, "gear", "tools")));
		orders = BlueprintItemOrders.parse(orders.serialize());
		BankOrganizationPreview original = weaponPreview(plan, BlueprintItemOrders.EMPTY, CategoryOverrideSource.NONE);
		BankOrganizationPreview moved = weaponPreview(plan, orders, CategoryOverrideSource.NONE);
		assertEquals(2, moved.getPlannedItemCount());
		assertEquals(Collections.singletonList(4151), ids(moved, target));
		assertEquals(Collections.singletonList(4151), ids(moved, plan.destinationOf("gear")));
		assertEquals(1, moved.getCategories().get(target).getItems().get(0).getBlueprintOccurrence());
		assertEquals("tools", moved.getCategories().get(target).getItems().get(0).getLayoutTagKey());
		assertEquals(original.toPreviewText(), weaponPreview(plan, orders.resetTab(target),
			CategoryOverrideSource.NONE).toPreviewText());
		BankLayoutPlan changedPlan = plan.withTagAt("tools", 9);
		assertTrue(ids(weaponPreview(changedPlan, orders, CategoryOverrideSource.NONE), target).isEmpty());
	}

	private static BankOrganizationPreview weaponPreview(BankLayoutPlan plan, BlueprintItemOrders orders,
		CategoryOverrideSource overrides)
	{
		return BankOrganizationPreviewBuilder.build(new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(4151, 1, 0), new BankItemSnapshot(4151, 1, 1))),
			CompositeItemCatalog.DEFAULT, BankPresets.IRONMAN, GearStatsSource.NONE, ItemValueSource.NONE,
			overrides, plan, BankLayoutOptions.DEFAULTS.withItemOrders(orders));
	}

	@Test public void savedCoinsAndTokensLeadAfterAnalysisAndReload()
	{
		BankSnapshot bank = new BankSnapshot(Arrays.asList(new BankItemSnapshot(2347, 1, 0),
			new BankItemSnapshot(995, 500, 1), new BankItemSnapshot(13204, 12, 2)));
		BlueprintItemOrders orders = BlueprintItemOrders.parse(BlueprintItemOrders.EMPTY
			.withTab(0, Arrays.asList(995, 13204, 2347)).serialize());
		BankOrganizationPreview preview = BankOrganizationPreviewBuilder.build(bank,
			CompositeItemCatalog.DEFAULT, BankPresets.IRONMAN, GearStatsSource.NONE, ItemValueSource.NONE,
			CategoryOverrideSource.NONE, BankLayoutPlan.defaultFor(BankPresets.IRONMAN),
			BankLayoutOptions.DEFAULTS.withItemOrders(orders));
		assertEquals(Arrays.asList(995, 13204, 2347), ids(preview, 0));
		assertTrue(preview.getCategories().get(0).hasManualOrder());
		BankTabPlan plan = BankTabPlan.fromPreview(preview);
		assertEquals(TabRouteAdvisor.Status.COMPLETE, TabRouteAdvisor.assess(
			new int[]{995, 13204, 2347}, plan, new int[9]).getStatus());
		assertTrue(BankBlueprintTextExporter.export(preview).contains("col=2 slot=2 | id=13204"));
	}

	@Test public void absentItemsReturnAndNewItemsAppendWithoutInventedSlots()
	{
		BlueprintItemOrders orders = BlueprintItemOrders.EMPTY.withTab(0, Arrays.asList(1, 2, 3));
		assertEquals(Arrays.asList(1, 3, 4), ids(orders.apply(preview(3, 4, 1)), 0));
		orders = orders.withTab(0, Arrays.asList(3, 1, 4));
		assertEquals(Arrays.asList(3, 2, 1, 4), ids(orders.apply(preview(4, 2, 1, 3)), 0));
	}

	@Test public void duplicatesArePhysicalAndNothingIsLost()
	{
		BlueprintItemOrders orders = BlueprintItemOrders.EMPTY.withTab(0, Arrays.asList(7, 2, 7));
		assertEquals(Arrays.asList(7, 2, 7, 9, 7), ids(orders.apply(preview(9, 7, 7, 2, 7)), 0));
	}

	@Test public void resetAndEmptyDefaultsLeaveAutomaticPreviewUntouched()
	{
		BankOrganizationPreview preview = preview(3, 2, 1);
		assertSame(preview, BlueprintItemOrders.EMPTY.apply(preview));
		assertSame(preview, BlueprintItemOrders.EMPTY.withTab(0, Arrays.asList(1, 2, 3))
			.withTab(0, Collections.emptyList()).apply(preview));
		BlueprintItemOrders otherTab = BlueprintItemOrders.EMPTY.withTab(1, Arrays.asList(1, 2));
		assertSame(preview.getCategories().get(0), otherTab.apply(preview).getCategories().get(0));
	}

	@Test public void profileNamesRoundTripAndOrdersDoNotLeak()
	{
		BlueprintOrderProfiles profiles = BlueprintOrderProfiles.parse("");
		profiles.put("Personal ~ ; é", BlueprintItemOrders.EMPTY.withTab(0, Arrays.asList(2, 1)));
		profiles.put("Bossing", BlueprintItemOrders.EMPTY.withTab(0, Arrays.asList(1, 2)));
		profiles = BlueprintOrderProfiles.parse(profiles.serialize());
		assertEquals(Arrays.asList(2, 1), ids(profiles.forProfile("Personal ~ ; é").apply(preview(1, 2)), 0));
		assertEquals(Arrays.asList(1, 2), ids(profiles.forProfile("Bossing").apply(preview(2, 1)), 0));
		profiles.remove("Bossing");
		assertFalse(profiles.forProfile("Bossing").hasTab(0));
		assertTrue(profiles.forProfile("Personal ~ ; é").hasTab(0));
	}

	@Test public void malformedTabsAreIsolatedAndFutureVersionsAreNotOverwritten()
	{
		BlueprintItemOrders parsed = BlueprintItemOrders.parse("v1|0:2,1|1:bad|22:1|2:-1");
		assertEquals(Arrays.asList(2, 1), ids(parsed.apply(preview(1, 2)), 0));
		assertFalse(parsed.hasTab(1));
		BlueprintItemOrders future = BlueprintItemOrders.parse("v3|keep-this");
		assertFalse(future.isSupported());
		assertEquals("v3|keep-this", future.serialize());
		assertThrows(IllegalStateException.class, () -> future.withTab(0, Arrays.asList(1)));
		assertThrows(IllegalArgumentException.class, () -> BlueprintItemOrders.EMPTY.withTab(10, Arrays.asList(1)));
		assertThrows(IllegalArgumentException.class, () -> BlueprintItemOrders.EMPTY.withTab(0,
			Collections.nCopies(BlueprintItemOrders.BANK_CAPACITY + 1, 1)));
	}

	private static BankOrganizationPreview preview(Integer... ids)
	{
		return new BankOrganizationPreview(BankPresets.IRONMAN, Arrays.asList(new BankCategoryPreview(
			BankPresets.IRONMAN.getCategories().get(0), Arrays.stream(ids)
				.map(id -> new BankPreviewItem(id, "Item " + id, 1)).collect(Collectors.toList()))));
	}
	private static List<Integer> ids(BankOrganizationPreview preview, int tab)
	{
		return preview.getCategories().get(tab).getItems().stream().map(BankPreviewItem::getItemId)
			.collect(Collectors.toList());
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class BlueprintOrderProfilesTest
{
	@Test public void sanitizedLegacyNameRetainsItemOrdersAndRoutesThroughEditsAndRemoval()
	{
		String legacyName = "Raid; prep";
		String canonicalName = BankLayoutShareCode.sanitize(legacyName);
		assertEquals("Raid  prep", canonicalName);
		BlueprintItemOrders original = BlueprintItemOrders.parse(
			"v1|0:995,2347|r:995#0:0:currency:frequently-used");
		BlueprintOrderProfiles profiles = BlueprintOrderProfiles.parse(entry(legacyName, original));
		assertEquals(original.serialize(), profiles.forProfile(canonicalName).serialize());

		BlueprintItemOrders edited = profiles.forProfile(canonicalName).withTab(0, Arrays.asList(2347, 995));
		profiles.put(canonicalName, edited);
		assertEquals("Update the original record rather than making a duplicate",
			entry(legacyName, edited), profiles.serialize());
		profiles = BlueprintOrderProfiles.parse(profiles.serialize());
		assertEquals(edited.serialize(), profiles.forProfile(canonicalName).serialize());
		assertEquals(edited.serialize(), profiles.forProfile(legacyName).serialize());
		BlueprintItemOrders.Destination route = profiles.forProfile(canonicalName).destinations().get("995#0");
		assertEquals(0, route.tab);
		assertEquals("currency", route.originalTag);
		assertEquals("frequently-used", route.tag);

		BlueprintOrderProfiles cleared = BlueprintOrderProfiles.parse(profiles.serialize());
		cleared.put(canonicalName, BlueprintItemOrders.EMPTY);
		assertEquals("Clearing the canonical profile also clears its legacy record", "", cleared.serialize());
		profiles.remove(canonicalName);
		assertEquals("", profiles.serialize());
	}

	@Test public void exactCanonicalNameWinsWithoutOverwritingItsSeparateLegacyRecord()
	{
		String legacyName = "Raid; prep";
		String canonicalName = BankLayoutShareCode.sanitize(legacyName);
		BlueprintItemOrders legacy = BlueprintItemOrders.EMPTY.withTab(0, Arrays.asList(995, 2347));
		BlueprintItemOrders canonical = BlueprintItemOrders.EMPTY.withTab(0, Arrays.asList(1755, 952));
		BlueprintOrderProfiles profiles = BlueprintOrderProfiles.parse(
			entry(legacyName, legacy) + ";" + entry(canonicalName, canonical));
		assertEquals(canonical.serialize(), profiles.forProfile(canonicalName).serialize());
		assertEquals(legacy.serialize(), profiles.forProfile(legacyName).serialize());

		BlueprintItemOrders edited = canonical.withTab(0, Arrays.asList(952, 1755));
		profiles.put(canonicalName, edited);
		assertEquals(entry(legacyName, legacy) + ";" + entry(canonicalName, edited), profiles.serialize());
		profiles = BlueprintOrderProfiles.parse(profiles.serialize());
		assertEquals(edited.serialize(), profiles.forProfile(canonicalName).serialize());
		assertEquals(legacy.serialize(), profiles.forProfile(legacyName).serialize());
		profiles.remove(canonicalName);
		assertEquals("Removing the exact record preserves the separate legacy record",
			entry(legacyName, legacy), profiles.serialize());
	}

	private static String entry(String name, BlueprintItemOrders orders)
	{
		return Base64.getUrlEncoder().withoutPadding().encodeToString(name.getBytes(StandardCharsets.UTF_8))
			+ "~" + orders.serialize();
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CatalogItem;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.catalog.ItemCategory;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import org.junit.Test;

public class CannonGroupingFeedbackTest
{
	private static final List<Integer> NORMAL = Arrays.asList(6, 8, 10, 12);
	private static final List<Integer> ORNAMENTED = Arrays.asList(26520, 26522, 26524, 26526);
	private static final List<BankPreset> PRESETS = Arrays.asList(BankPresets.IRONMAN, BankPresets.MAIN);

	@Test
	public void completeCannonsStayInCompactBlocksInEveryGearLayoutAndPreset()
	{
		for (List<Integer> cannonIds : Arrays.asList(NORMAL, ORNAMENTED, bothCannons()))
		{
			Fixture fixture = new Fixture().add(cannonIds);
			assertAutomaticLayouts(fixture, true);
		}
	}

	@Test
	public void spareCannonPartsDoNotSplitToCompleteASparseEquipmentRow()
	{
		Fixture fixture = new Fixture().addPrimaries(GearSlot.BODY, 0).addUtility(2).add(NORMAL);
		assertAutomaticLayouts(fixture, true);
	}

	@Test
	public void busyCombatTabsKeepCannonsTogetherAndPreservePrimaryStyleColumns()
	{
		Fixture fixture = new Fixture().addPrimaries(GearSlot.HEAD, 0)
			.addPrimaries(GearSlot.BODY, 1).addUtility(24)
			.add(Arrays.asList(544, 542, 4716, 4718, 4720, 4722, 9672, 9674, 9676))
			.add(bothCannons());
		for (BankPreset preset : PRESETS)
		{
			for (GearLayout layout : GearLayout.values())
			{
				BankCategoryPreview combat = combat(build(fixture, preset, options(preset, layout, true)), preset);
				assertBlocksAndContents(fixture, combat);
				if (layout == GearLayout.GRID_STYLES)
				{
					List<Integer> target = ids(combat);
					for (int row = 0; row < 2; row++)
					{
						for (int style = 0; style < 4; style++)
						{
							assertEquals("Primary combat style column changed",
								Integer.valueOf(primaryId(row, style)), target.get(row * 8 + style));
						}
					}
				}
			}
		}
	}

	@Test
	public void incompleteCannonsKeepTheirOwnedComponentsTogetherWithoutAddingMissingParts()
	{
		for (List<Integer> partial : Arrays.asList(
			Arrays.asList(6, 12), Arrays.asList(8, 10, 12),
			Arrays.asList(26520, 26524), Arrays.asList(26522, 26524, 26526),
			Arrays.asList(6, 8, 10, 12, 26522, 26526),
			Arrays.asList(6, 10, 26520, 26522, 26524, 26526)))
		{
			Fixture fixture = new Fixture().addPrimaries(GearSlot.BODY, 0).addUtility(3).add(partial);
			assertAutomaticLayouts(fixture, true);
		}
	}

	@Test
	public void mixedCannonFinishesStayTogetherEvenWhenOneVariantHasOnlyOneOwnedComponent()
	{
		for (List<Integer> parts : Arrays.asList(
			Arrays.asList(6, 8, 10, 26526), Arrays.asList(6, 26526),
			Arrays.asList(6, 26522, 26524, 26526),
			Collections.singletonList(6), Collections.singletonList(26526)))
		{
			Fixture fixture = new Fixture().add(Arrays.asList(4716, 4718, 4720, 4722))
				.addUtility(8).add(parts);
			for (BankPreset preset : PRESETS)
			{
				for (GearLayout layout : GearLayout.values())
				{
					BankCategoryPreview combat = combat(build(fixture, preset, options(preset, layout, true)), preset);
					assertBlocksAndContents(fixture, combat);
					assertCompactRectangle(ids(combat), bothCannons());
					if (parts.size() == 1)
					{
						assertEquals("A lone cannon component must stay before the gear-set run",
							parts.get(0), ids(combat).get(0));
					}
				}
			}
		}
	}

	@Test
	public void disablingEquipmentRowFillStillKeepsBothCannonsCompact()
	{
		Fixture fixture = new Fixture().addPrimaries(GearSlot.HEAD, 0).addUtility(5).add(bothCannons());
		assertAutomaticLayouts(fixture, false);
	}

	@Test
	public void capturedPhysicalOrderWinsWhenThePlayerChoosesToSeparateCannonParts()
	{
		Fixture fixture = new Fixture().addPrimaries(GearSlot.BODY, 0).addUtility(2).add(NORMAL);
		List<Integer> manual = Arrays.asList(6, primaryId(0, 0), 8, primaryId(0, 1),
			10, primaryId(0, 2), 12, primaryId(0, 3), 951000, 951001);
		for (BankPreset preset : PRESETS)
		{
			for (GearLayout layout : GearLayout.values())
			{
				BankLayoutOptions options = options(preset, layout, true);
				BankOrganizationPreview before = build(fixture, preset, options);
				int destination = BankLayoutPlan.defaultFor(preset).destinationOf("gear");
				BlueprintItemOrders captured = BlueprintItemOrders.capture(
					Collections.singletonMap(destination, manual), before, BlueprintItemOrders.EMPTY);
				BankCategoryPreview after = combat(build(fixture, preset, options.withItemOrders(captured)), preset);
				assertTrue("Captured order must retain manual placement", after.hasManualOrder());
				assertEquals(manual, ids(after));
				assertContents(fixture, after);
			}
		}
	}

	private static void assertAutomaticLayouts(Fixture fixture, boolean fillRows)
	{
		for (BankPreset preset : PRESETS)
		{
			for (GearLayout layout : GearLayout.values())
			{
				assertBlocksAndContents(fixture,
					combat(build(fixture, preset, options(preset, layout, fillRows)), preset));
			}
		}
	}

	private static void assertBlocksAndContents(Fixture fixture, BankCategoryPreview combat)
	{
		assertContents(fixture, combat);
		assertCompactRectangle(ids(combat), NORMAL);
		assertCompactRectangle(ids(combat), ORNAMENTED);
	}

	private static void assertContents(Fixture fixture, BankCategoryPreview combat)
	{
		List<Integer> expected = new ArrayList<>(fixture.items.keySet());
		List<Integer> actual = ids(combat);
		assertEquals("Unexpected item loss or duplication", expected.size(), actual.size());
		Collections.sort(expected);
		Collections.sort(actual);
		assertEquals("Combat contents changed", expected, actual);
		for (BankPreviewItem item : combat.getItems())
		{
			assertFalse("Cannon grouping inserted an empty bank slot", item.isBlank());
		}
	}

	private static void assertCompactRectangle(List<Integer> target, List<Integer> family)
	{
		List<Integer> positions = family.stream().filter(target::contains)
			.map(target::indexOf).collect(Collectors.toList());
		if (positions.size() < 2) return;
		int minRow = positions.stream().mapToInt(index -> index / 8).min().getAsInt();
		int maxRow = positions.stream().mapToInt(index -> index / 8).max().getAsInt();
		int minColumn = positions.stream().mapToInt(index -> index % 8).min().getAsInt();
		int maxColumn = positions.stream().mapToInt(index -> index % 8).max().getAsInt();
		assertEquals("Cannon components occupy a split or interrupted block: " + positions,
			positions.size(), (maxRow - minRow + 1) * (maxColumn - minColumn + 1));
	}

	private static BankLayoutOptions options(BankPreset preset, GearLayout layout, boolean fillRows)
	{
		BankLayoutOptions defaults = BankLayoutOptions.defaultFor(preset);
		return new BankLayoutOptions(fillRows, defaults.fillHerbloreRows(), defaults.alchPile(),
			Collections.emptyMap(), layout, defaults.potionDoses(), defaults.runeOrder(),
			defaults.teleportOrder(), false);
	}

	private static BankOrganizationPreview build(Fixture fixture, BankPreset preset, BankLayoutOptions options)
	{
		List<BankItemSnapshot> snapshots = new ArrayList<>();
		List<Integer> reverseSource = new ArrayList<>(fixture.items.keySet());
		Collections.reverse(reverseSource);
		for (int itemId : reverseSource)
		{
			snapshots.add(new BankItemSnapshot(itemId, 1, snapshots.size() * 2));
		}
		return BankOrganizationPreviewBuilder.build(new BankSnapshot(snapshots),
			id -> Optional.ofNullable(fixture.items.get(id)), preset,
			id -> Optional.ofNullable(fixture.stats.get(id)), ItemValueSource.NONE,
			CategoryOverrideSource.NONE, BankLayoutPlan.defaultFor(preset), options);
	}

	private static BankCategoryPreview combat(BankOrganizationPreview preview, BankPreset preset)
	{
		return preview.getCategories().get(BankLayoutPlan.defaultFor(preset).destinationOf("gear"));
	}

	private static List<Integer> ids(BankCategoryPreview category)
	{
		return category.getItems().stream().map(BankPreviewItem::getItemId).collect(Collectors.toList());
	}

	private static List<Integer> bothCannons()
	{
		List<Integer> result = new ArrayList<>(NORMAL);
		result.addAll(ORNAMENTED);
		return result;
	}

	private static int primaryId(int row, int style)
	{
		return 950000 + row * 10 + style;
	}

	private static final class Fixture
	{
		private final Map<Integer, CatalogItem> items = new LinkedHashMap<>();
		private final Map<Integer, GearStats> stats = new LinkedHashMap<>();

		private Fixture add(List<Integer> ids)
		{
			for (int id : ids) items.put(id, CompositeItemCatalog.DEFAULT.describeOrUnknown(id));
			return this;
		}

		private Fixture addPrimaries(GearSlot slot, int row)
		{
			for (int style = 0; style < 4; style++)
			{
				int id = primaryId(row, style);
				items.put(id, gear(id, "Primary " + row + " " + style));
				stats.put(id, new GearStats(slot, style == 0 ? 10 : 0, 0, 0,
					style == 2 ? 10 : 0, style == 1 ? 10 : 0, 0, 0,
					style == 3 ? 10 : 0, 2000));
			}
			return this;
		}

		private Fixture addUtility(int count)
		{
			for (int index = 0; index < count; index++)
			{
				int id = 951000 + index;
				items.put(id, gear(id, "Utility " + index));
			}
			return this;
		}

		private static CatalogItem gear(int id, String name)
		{
			return new CatalogItem(id, name, ItemCategory.GEAR, "gear", Collections.emptySet(), null);
		}
	}
