		int[] original = {13579, 13583, 13585, 13587, 13589, 13581,
			13627, 13629, 13631, 13633, 13635, 13637, 995, 556, 558, 562,
			554, 555, 559, 564, 557, 561, 563, 565, 560, 566, 9075, 21880,
			2347, 1755, 952, 8013, 4251, 21389, 12791, 13393, 19564,
