	private static BankOrganizationPreview main(BankSnapshot bank)
	{
		return main(bank, BankLayoutOptions.DEFAULTS, CategoryOverrideSource.NONE);
	}

	private static BankOrganizationPreview main(BankSnapshot bank, BankLayoutOptions options,
		CategoryOverrideSource overrides)
	{
		return BankOrganizationPreviewBuilder.build(bank, CompositeItemCatalog.DEFAULT,
			BankPresets.MAIN, GearStatsSource.NONE, ItemValueSource.NONE, overrides,
			BankLayoutPlan.defaultFor(BankPresets.MAIN), options);
	}

	private static BankSnapshot bank(int... itemIds)
	{
		List<BankItemSnapshot> items = new ArrayList<>();
		for (int index = 0; index < itemIds.length; index++)
		{
			items.add(new BankItemSnapshot(itemIds[index], 1, index));
		}
		return new BankSnapshot(items);
	}

	private static List<Integer> ids(BankOrganizationPreview preview, int destination)
	{
		return preview.getCategories().get(destination).getItems().stream()
			.filter(item -> !item.isBlank()).map(BankPreviewItem::getItemId)
			.collect(Collectors.toList());
	}

	private static void assertDestinationContains(BankOrganizationPreview preview,
		int destination, Integer... expected)
	{
		List<Integer> actual = ids(preview, destination);
		assertTrue("destination " + destination + ": " + actual,
			actual.containsAll(Arrays.asList(expected)));
	}

	private static void assertContiguousRun(List<Integer> actual, Integer... run)
	{
		int start = actual.indexOf(run[0]);
		assertTrue("Missing family in " + actual, start >= 0);
		assertTrue("Truncated family in " + actual, start + run.length <= actual.size());
		assertEquals(Arrays.asList(run), actual.subList(start, start + run.length));
	}

	private static void assertPermutationOfBank(BankSnapshot bank, BankOrganizationPreview preview)
	{
		List<Integer> expected = bank.getItems().stream().map(BankItemSnapshot::getItemId)
			.collect(Collectors.toList());
		List<Integer> actual = preview.getPlannedItems().stream().map(BankPreviewItem::getItemId)
			.collect(Collectors.toList());
		assertEquals("Blank or duplicate physical slots in " + actual, expected.size(), actual.size());
		Collections.sort(expected);
		Collections.sort(actual);
		assertEquals(expected, actual);
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class MainLayoutProfilesTest
{
	private static final String MAIN_DEFAULT = "Main - All-Round";

	@Test
	public void mainHasItsOwnPermanentBundledProfile()
	{
		BankLayoutProfiles profiles = main("", "");

		assertEquals(MAIN_DEFAULT, BankLayoutProfiles.defaultName(BankPresets.MAIN));
		assertEquals(BankLayoutProfiles.DEFAULT_NAME, BankLayoutProfiles.defaultName(BankPresets.IRONMAN));
		assertEquals(MAIN_DEFAULT, profiles.getDefaultName());
		assertEquals(Arrays.asList(MAIN_DEFAULT), profiles.names());
		assertTrue(profiles.isDefaultActive());
		assertEquals("", profiles.activePlan());
	}

	@Test
	public void mainDefaultCannotBeOverwrittenOrDeleted()
	{
		BankLayoutProfiles profiles = main(MAIN_DEFAULT + "~corrupted-bundled-plan", MAIN_DEFAULT);
		assertEquals("", profiles.activePlan());
		profiles = profiles.withProfile(MAIN_DEFAULT, "my-main-plan");

		assertNotEquals(MAIN_DEFAULT, profiles.getActiveName());
		assertEquals("my-main-plan", profiles.activePlan());
		assertEquals("", profiles.planFor(MAIN_DEFAULT));
		BankLayoutProfiles afterRemoval = profiles.without(MAIN_DEFAULT);
		assertTrue(afterRemoval.names().contains(MAIN_DEFAULT));
		assertEquals(profiles.getActiveName(), afterRemoval.getActiveName());
		BankLayoutProfiles reloaded = main(afterRemoval.serialize(), afterRemoval.getActiveName());
		assertEquals(MAIN_DEFAULT, reloaded.getDefaultName());
		assertEquals("my-main-plan", reloaded.activePlan());
	}

	@Test
	public void deletingMainActiveLayoutFallsBackToMainDefault()
	{
		BankLayoutProfiles profiles = main("", "").withProfile("My bank", "main-plan");
		BankLayoutProfiles removed = profiles.without("My bank");

		assertEquals(MAIN_DEFAULT, removed.getActiveName());
		assertTrue(removed.isDefaultActive());
		assertFalse(removed.names().contains("My bank"));
		assertEquals(MAIN_DEFAULT, main(removed.serialize(), "Unknown layout").getActiveName());
	}

	@Test
	public void presetsCanSaveTheSameLayoutNameWithIndependentPlans()
	{
		BankLayoutProfiles ironman = BankLayoutProfiles.parse("", "").withProfile("My bank", "ironman-plan");
		BankLayoutProfiles main = main("", "").withProfile("My bank", "main-plan");
		ironman = BankLayoutProfiles.parse(ironman.serialize(), ironman.getActiveName());
		main = main(main.serialize(), main.getActiveName());

		assertEquals("My bank", ironman.getActiveName());
		assertEquals("My bank", main.getActiveName());
		assertEquals("ironman-plan", ironman.activePlan());
		assertEquals("main-plan", main.activePlan());
		assertEquals(Arrays.asList(BankLayoutProfiles.DEFAULT_NAME, "My bank"), ironman.names());
		assertEquals(Arrays.asList(MAIN_DEFAULT, "My bank"), main.names());
	}

	@Test
	public void legacyIronmanDefaultNameDoesNotBecomeTheMainBundledProfile()
	{
		BankLayoutProfiles main = main("", "")
			.withProfile(BankLayoutProfiles.DEFAULT_NAME, "user-created-main-plan");

		assertEquals(BankLayoutProfiles.DEFAULT_NAME, main.getActiveName());
		assertEquals("user-created-main-plan", main.activePlan());
		assertFalse(main.isDefaultActive());
		assertEquals(MAIN_DEFAULT, main.without(BankLayoutProfiles.DEFAULT_NAME).getActiveName());
	}

	private static BankLayoutProfiles main(String value, String active)
	{
		return BankLayoutProfiles.parse(value, active, MAIN_DEFAULT);
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.guide.BankTabPlan;
import com.pkoka5.ironmanbankarchitect.guide.RearrangeMode;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;

public class MainRealBankLayoutTest
{
	@Test
	public void defaultMainLayoutHandlesTheFullReviewedRealBank() throws IOException
	{
		List<Integer> itemIds = realBankIds();
		assertEquals(770, itemIds.size());

		assertStableDenseLayout(itemIds, BankLayoutOptions.DEFAULTS, "reviewed 770-item bank");
	}

	@Test
	public void an817ItemBankHandlesEveryGearLayoutWithRowFillingOnAndOff() throws IOException
	{
		Set<Integer> extended = new LinkedHashSet<>(realBankIds());
		for (int itemId : RandomBankSimulator.loadItemUniverse())
		{
			if (extended.size() == 817) break;
			extended.add(itemId);
		}
		assertEquals(817, extended.size());
		List<Integer> itemIds = new ArrayList<>(extended);

		for (GearLayout gear : GearLayout.values())
		{
			for (boolean fill : new boolean[]{true, false})
			{
				BankLayoutOptions options = new BankLayoutOptions(fill, true, true,
					Collections.emptyMap(), gear, PotionDoseOrder.GRAB_AREA,
					RuneOrder.ELEMENTAL, TeleportOrder.ALPHABETICAL);
				assertStableDenseLayout(itemIds, options, gear + ", fill=" + fill);
			}
		}
	}

	private static void assertStableDenseLayout(List<Integer> itemIds, BankLayoutOptions options,
		String label)
	{
		BankLayoutPlan layout = BankLayoutPlan.defaultFor(BankPresets.MAIN);
		BankOrganizationPreview original = preview(itemIds, layout, options);
		List<Integer> expected = new ArrayList<>(itemIds);
		List<Integer> actual = ids(original.getPlannedItems());
		Collections.sort(expected);
		Collections.sort(actual);
		assertEquals(label + ": every physical item is present exactly once", expected, actual);
		assertFalse(label + ": no empty targets", original.getPlannedItems().stream()
			.anyMatch(BankPreviewItem::isBlank));
		assertEquals(10, original.getCategories().size());

		List<Integer> rescanned = new ArrayList<>(itemIds);
		Collections.shuffle(rescanned, new Random(20261005L));
		BankOrganizationPreview reordered = preview(rescanned, layout, options);
		for (int destination = 0; destination < 10; destination++)
		{
			assertEquals(label + ": rescan changed destination " + destination,
				ids(original.getCategories().get(destination).getItems()),
				ids(reordered.getCategories().get(destination).getItems()));
		}

		BankTabPlan tabs = BankTabPlan.fromPreview(original, layout);
		int[] actualItems = tabs.getFlattenedItems().stream()
			.mapToInt(BankPreviewItem::getItemId).toArray();
		int[] tabCounts = new int[TabRouteAdvisor.MAX_TABS];
		for (BankTabPlan.TargetTab tab : tabs.getNumberedTabs())
		{
			tabCounts[tab.getBankTabNumber() - 1] = tab.getItems().size();
		}
		for (RearrangeMode mode : RearrangeMode.values())
		{
			assertEquals(label + ": finished guidance with " + mode,
				TabRouteAdvisor.Status.COMPLETE,
				TabRouteAdvisor.assess(actualItems, tabs, tabCounts, 0, mode).getStatus());
		}
	}

	private static BankOrganizationPreview preview(List<Integer> itemIds, BankLayoutPlan layout,
		BankLayoutOptions options)
	{
		List<BankItemSnapshot> items = new ArrayList<>();
		for (int slot = 0; slot < itemIds.size(); slot++)
		{
			items.add(new BankItemSnapshot(itemIds.get(slot), 1, slot));
		}
		return BankOrganizationPreviewBuilder.build(new BankSnapshot(items),
			CompositeItemCatalog.DEFAULT, BankPresets.MAIN, GearStatsSource.NONE,
			ItemValueSource.NONE, CategoryOverrideSource.NONE, layout, options);
	}

	private static List<Integer> ids(List<BankPreviewItem> items)
	{
		return items.stream().map(BankPreviewItem::getItemId).collect(Collectors.toList());
	}

	private static List<Integer> realBankIds() throws IOException
	{
		String path = "/com/pkoka5/ironmanbankarchitect/organize/real-bank-fixture-2026-07-19.tsv";
		InputStream stream = MainRealBankLayoutTest.class.getResourceAsStream(path);
		assertTrue("missing real-bank fixture", stream != null);
		List<Integer> itemIds = new ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream,
			StandardCharsets.UTF_8)))
		{
			assertEquals("itemId\texpectedTabKey", reader.readLine());
			String line;
			while ((line = reader.readLine()) != null)
			{
				itemIds.add(Integer.parseInt(line.substring(0, line.indexOf('\t'))));
			}
		}
		return itemIds;
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

