			item(1, "Sapphire ring", "crafting-jewellery"), item(2, "Sapphire", "gem"),
			item(3, "Uncut sapphire", "uncut-gem"), item(4, "Leaping sturgeon", "raw-food"),
			item(5, "Leaping trout", "raw-food"), item(6, "Leaping salmon", "raw-food"),
