package com.pkoka5.ironmanbankarchitect.organize;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CatalogItem;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.catalog.ItemCatalog;
import com.pkoka5.ironmanbankarchitect.catalog.ItemCategory;
import com.pkoka5.ironmanbankarchitect.override.UserCategoryOverrides;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

/** Reviewed functions must survive mixed-bank stats, Alch and saved player choices. */
@RunWith(Parameterized.class)
public class ReviewedFunctionalPlacementTest
{
	private static final ItemValueSource VALUES = id -> 25000;
	// Deliberately positive stats even for non-equipment, to exercise promotion protection.
	private static final GearStatsSource STATS = id -> Optional.of(stats(
		id == 9768 || id == 9769 ? GearSlot.CAPE : GearSlot.WEAPON, id == 4151 ? 60 : 20));
	private final BankPreset preset;
	private final BankLayoutPlan plan;
	private final BankLayoutOptions defaults;

	@Parameterized.Parameters(name = "{0}")
	public static Collection<Object[]> presets()
	{
		return Arrays.asList(new Object[][] {{BankPresetType.IRONMAN}, {BankPresetType.MAIN}});
	}

	public ReviewedFunctionalPlacementTest(BankPresetType type)
	{
		preset = BankPresets.forType(type);
		plan = BankLayoutPlan.defaultFor(preset);
		defaults = BankLayoutOptions.defaultFor(preset);
	}

	@Test
	public void reviewedNonCombatRolesSurvivePositiveStatsAndAnActiveMixedBankAlchPile()
	{
		BankSnapshot bank = bank(995, 20017, 22840, 22842, 24719, 28152, 31946, 4485,
			13137, 13138, 9768, 9769, 13108, 13109, 1373, 4151);
		BankOrganizationPreview preview = build(bank, CompositeItemCatalog.DEFAULT,
			CategoryOverrideSource.NONE, defaults);
		assertEquals(bank.getPhysicalItems().size(), preview.getPlannedItemCount());
		assertTag(preview, 1373, "alch");
		assertTag(preview, 4151, "gear");
		assertTag(preview, 995, "currency");
		for (int id : new int[] {20017, 22840}) assertTag(preview, id, "cosmetics");
		for (int id : new int[] {22842, 24719}) assertTag(preview, id, "tools");
		for (int id : new int[] {28152, 31946}) assertTag(preview, id, "raw-resources");
		assertTag(preview, 4485, "quest-items");
		for (int id : new int[] {13137, 13138})
			assertTag(preview, id, preset.getType() == BankPresetType.IRONMAN ? "frequently-used" : "tools");
		for (int id : new int[] {995, 20017, 22840, 22842, 24719, 28152, 31946, 4485, 13137, 13138})
		{
			CatalogItem catalog = CompositeItemCatalog.DEFAULT.describeOrUnknown(id);
			assertEquals("Keep reviewed function " + id, catalog.getCategory(), item(preview, id).getItemCategory());
			assertEquals("Keep reviewed subcategory " + id, catalog.getSubcategory(), item(preview, id).getSubcategory());
			assertFalse("Non-combat role must not become Alch " + id, "alch".equals(item(preview, id).getLayoutTagKey()));
		}
		for (int id : new int[] {9768, 9769}) assertTag(preview, id, "gear");
		for (int id : new int[] {9768, 9769, 13108, 13109})
		{
			assertEquals("Functional equipment " + id, ItemCategory.GEAR, item(preview, id).getItemCategory());
			assertFalse("Equipment is not currency " + id, "currency".equals(item(preview, id).getLayoutTagKey()));
			assertFalse("Lower-tier item has no own teleport " + id, "teleports".equals(item(preview, id).getLayoutTagKey()));
		}
		for (int id : new int[] {13108, 13109})
			assertTag(preview, id, preset.getType() == BankPresetType.IRONMAN ? "frequently-used" : "gear");
	}

	@Test
	public void explicitTagCorrectionReloadsAndClearingItRestoresTheReviewedAutomaticRole()
	{
		BankSnapshot bank = bank(28152, 20017, 995);
		UserCategoryOverrides choice = new UserCategoryOverrides();
		choice.put(28152, "frequently-used");
		UserCategoryOverrides reloaded = UserCategoryOverrides.parse(choice.serialize());
		BankOrganizationPreview manual = build(bank, CompositeItemCatalog.DEFAULT, reloaded, defaults);
		assertTag(manual, 28152, "frequently-used");
		assertEquals(ItemCategory.SKILLING, item(manual, 28152).getItemCategory());
		assertEquals("woodcutting-supply", item(manual, 28152).getSubcategory());
		assertTag(manual, 20017, "cosmetics");
		assertTag(manual, 995, "currency");

		reloaded.remove(28152);
		BankOrganizationPreview automatic = build(bank, CompositeItemCatalog.DEFAULT,
			UserCategoryOverrides.parse(reloaded.serialize()), defaults);
		assertTag(automatic, 28152, "raw-resources");
		assertEquals(ItemCategory.SKILLING, item(automatic, 28152).getItemCategory());
		assertEquals(manual.getPlannedItemCount(), automatic.getPlannedItemCount());
	}

	@Test
	public void capturedPhysicalOrderSurvivesCorrectedFunctionsAndPlaceholderUpgradesProveNothing()
	{
		List<BankItemSnapshot> items = new ArrayList<>(bank(22840, 4485, 28152, 995, 1275).getPhysicalItems());
		items.add(new BankItemSnapshot(11920, 0, items.size(), true));
		BankSnapshot bank = new BankSnapshot(items);
		ItemCatalog legacy = id -> id == 28152
			? Optional.of(new CatalogItem(id, "Nature offerings", ItemCategory.GEAR, "weapon", Collections.emptySet(), null))
			: CompositeItemCatalog.DEFAULT.findById(id);
		BankOrganizationPreview old = build(bank, legacy, CategoryOverrideSource.NONE, defaults);
		assertEquals(ItemCategory.GEAR, item(old, 28152).getItemCategory());
		List<Integer> physicalOrder = Arrays.asList(22840, 4485, 28152, 995, 11920, 1275);
		Map<Integer, List<Integer>> physical = new LinkedHashMap<>();
		physical.put(7, physicalOrder);
		BlueprintItemOrders captured = BlueprintItemOrders.parse(
			BlueprintItemOrders.capture(physical, old, BlueprintItemOrders.EMPTY).serialize());
		assertTrue(captured.isCaptured());

		BankOrganizationPreview corrected = build(bank, CompositeItemCatalog.DEFAULT,
			CategoryOverrideSource.NONE, defaults.withItemOrders(captured));
		assertEquals(physicalOrder, ids(corrected, 7));
		assertEquals(bank.getPhysicalItems().size(), corrected.getPlannedItemCount());
		for (int tab = 0; tab < BankLayoutPlan.DESTINATION_COUNT; tab++)
			if (tab != 7) assertTrue("Captured bank remains on its saved physical tab " + tab, ids(corrected, tab).isEmpty());
		assertEquals(ItemCategory.SKILLING, item(corrected, 28152).getItemCategory());
		assertEquals("woodcutting-supply", item(corrected, 28152).getSubcategory());
		assertEquals("raw-resources", item(corrected, 28152).getLayoutTagKey());
		assertEquals("quest-items", item(corrected, 4485).getLayoutTagKey());
		assertEquals("cosmetics", item(corrected, 22840).getLayoutTagKey());
		assertTrue(item(corrected, 11920).isPlaceholder());
		assertEquals(0, item(corrected, 11920).getQuantity());
		assertFalse(item(corrected, 1275).isPlaceholder());
		assertFalse("Placeholder Dragon pickaxe cannot replace the owned Rune pickaxe for Alch",
			"alch".equals(item(corrected, 1275).getLayoutTagKey()));
		assertEquals(0, corrected.getTagCounts().getOrDefault("alch", 0).intValue());
		assertEquals(corrected.getPlannedItemCount() - 1,
			corrected.getTagCounts().values().stream().mapToInt(Integer::intValue).sum());
	}

	@Test
	public void unknownFutureEquipmentNeverBecomesAutomaticAlchWithoutAReviewedRole()
	{
		ItemCatalog catalog = id -> id == 900002
			? Optional.of(new CatalogItem(id, "Unreviewed future armour", ItemCategory.UNCATEGORIZED,
				"unknown", Collections.emptySet(), null))
			: id == 900003 ? Optional.of(new CatalogItem(id, "Reviewed production armour", ItemCategory.GEAR,
				"body", Collections.emptySet(), null)) : CompositeItemCatalog.DEFAULT.findById(id);
		GearStatsSource equipment = id -> Optional.of(stats(GearSlot.BODY, id >= 900001 ? 5 : 100));
		BankSnapshot bank = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(900001, 100, 0), new BankItemSnapshot(900002, 100, 1),
			new BankItemSnapshot(900003, 100, 2), new BankItemSnapshot(1127, 1, 3),
			new BankItemSnapshot(3140, 1, 4), new BankItemSnapshot(11832, 1, 5)));
		BankOrganizationPreview automatic = BankOrganizationPreviewBuilder.build(bank, catalog, preset,
			equipment, VALUES, CategoryOverrideSource.NONE, plan, defaults);
		// Same weak stats, bulk quantity and value qualify the reviewed control for Alch.
		assertTag(automatic, 900003, "alch");
		for (int id : new int[] {900001, 900002})
		{
			assertTag(automatic, id, "gear");
			assertEquals("Runtime equipment evidence may promote an unreviewed item " + id,
				ItemCategory.GEAR, item(automatic, id).getItemCategory());
			assertEquals("body", item(automatic, id).getSubcategory());
			assertEquals(100, item(automatic, id).getQuantity());
		}
		UserCategoryOverrides ownerChoice = UserCategoryOverrides.parse("900001=alch,900002=alch");
		BankOrganizationPreview manual = BankOrganizationPreviewBuilder.build(bank, catalog, preset,
			equipment, VALUES, ownerChoice, plan, defaults);
		assertTag(manual, 900001, "alch");
		assertTag(manual, 900002, "alch");
		assertEquals(automatic.getPlannedItemCount(), manual.getPlannedItemCount());

		BankOrganizationPreview withoutStats = BankOrganizationPreviewBuilder.build(bank, catalog, preset,
			GearStatsSource.NONE, VALUES, CategoryOverrideSource.NONE, plan, defaults);
		assertTag(withoutStats, 900001, "cleanup");
		assertEquals(ItemCategory.UNKNOWN, item(withoutStats, 900001).getItemCategory());
		assertTag(withoutStats, 900002, "cleanup");
		assertEquals(ItemCategory.UNCATEGORIZED, item(withoutStats, 900002).getItemCategory());
	}

	private BankOrganizationPreview build(BankSnapshot bank, ItemCatalog catalog,
		CategoryOverrideSource choices, BankLayoutOptions options)
	{
		return BankOrganizationPreviewBuilder.build(bank, catalog, preset, STATS, VALUES, choices, plan, options);
	}

	private static BankSnapshot bank(int... ids)
	{
		List<BankItemSnapshot> items = new ArrayList<>();
		for (int id : ids)
		{
			int quantity = id == 995 ? 100000 : id == 28152 || id == 31946 || id == 1373 ? 25 : 1;
			items.add(new BankItemSnapshot(id, quantity, items.size()));
		}
		return new BankSnapshot(items);
	}

	private static GearStats stats(GearSlot slot, int score)
	{
		return new GearStats(slot, score, score, score, 0, 0, score, 0, 0,
			score, score, score, score, score, 0, 4);
	}

	private static BankPreviewItem item(BankOrganizationPreview preview, int id)
	{
		return preview.getPlannedItems().stream().filter(item -> !item.isBlank() && item.getItemId() == id)
			.findFirst().orElseThrow(() -> new AssertionError("Missing planned item " + id));
	}

	private void assertTag(BankOrganizationPreview preview, int id, String tag)
	{
		assertEquals("Item " + id + " final tag", tag, item(preview, id).getLayoutTagKey());
		assertTrue("Item " + id + " reaches the tag's physical destination", ids(preview, plan.destinationOf(tag)).contains(id));
	}

	private static List<Integer> ids(BankOrganizationPreview preview, int tab)
	{
		return preview.getCategories().get(tab).getItems().stream().filter(item -> !item.isBlank())
			.map(BankPreviewItem::getItemId).collect(Collectors.toList());
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.catalog.CatalogItem;
import com.pkoka5.ironmanbankarchitect.catalog.ItemCategory;
import com.pkoka5.ironmanbankarchitect.catalog.ItemSortMetadataCatalog;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SupplyItemSorterTest
{
	private static final ItemSortMetadataCatalog NO_METADATA = itemId -> Optional.empty();

	@Test
	public void keepsAllFullDosePotionsAheadOfUtilitiesFoodAndDrinks()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(1, "Shark", "food"), item(2, "Super energy(4)", "potion-dose-4"),
			item(3, "Prayer potion(4)", "potion-dose-4"), item(4, "Holy wrench", "pvm-utility"),
			item(5, "Sanfew serum(4)", "potion-dose-4"), item(6, "Bandit's brew", "drink"),
			item(7, "Superattack mix(2)", "potion")), NO_METADATA);

		assertEquals(Arrays.asList("Prayer potion(4)", "Sanfew serum(4)", "Super energy(4)",
			"Holy wrench", "Superattack mix(2)", "Shark", "Bandit's brew"), names(sorted));
	}

	@Test
	public void keepsFullAndHalfPiesInOneFamily()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(1, "Half a botanical pie", "food"), item(2, "Cake", "food"),
			item(3, "Botanical pie", "food")), NO_METADATA);

		assertEquals(Arrays.asList("Botanical pie", "Half a botanical pie", "Cake"), names(sorted));
	}

	@Test
	public void sortsStandardFoodByPinnedDirectHealingInsteadOfAlphabetically()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(379, "Lobster", "food"), item(385, "Shark", "food"),
			item(373, "Swordfish", "food"), item(32352, "Marlin", "food")));

		assertEquals(Arrays.asList("Marlin", "Shark", "Swordfish", "Lobster"), names(sorted));
	}

	@Test
	public void usesStableMaximumForVariableFoodWithoutReadingLiveStats()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(385, "Shark", "food"), item(13441, "Anglerfish", "food"),
			item(391, "Manta ray", "food")));

		assertEquals(Arrays.asList("Manta ray", "Anglerfish", "Shark"), names(sorted));
	}

	@Test
	public void separatesCombatRolesAndUsesPerActionRatherThanTotalHealing()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(2303, "1/2 pineapple pizza", "food"),
			item(29143, "Cooked moonlight antelope", "food"),
			item(3144, "Cooked karambwan", "food"),
			item(2301, "Pineapple pizza", "food"),
			item(385, "Shark", "food"),
			item(333, "Trout", "food")));

		assertEquals(Arrays.asList("Shark", "Cooked karambwan", "Cooked moonlight antelope",
			"Pineapple pizza", "1/2 pineapple pizza", "Trout"), names(sorted));
	}

	@Test
	public void unknownNamesCannotSpoofCuratedHealingFacts()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(999_999, "Marlin", "food"), item(379, "Lobster", "food")));

		assertEquals(Arrays.asList("Lobster", "Marlin"), names(sorted));
	}

	@Test
	public void keepsNormalAndBlightedFamilyTogetherWithUnrestrictedFirst()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(24589, "Blighted manta ray", "food"), item(391, "Manta ray", "food")));

		assertEquals(Arrays.asList("Manta ray", "Blighted manta ray"), names(sorted));
	}

	@Test
	public void groupsCuratedPotionFamiliesAndOrdersEachOneFromFourToOne()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(143, "Prayer potion(1)", "potion-dose-1"),
			item(121, "Attack potion(3)", "potion-dose-3"),
			item(2434, "Prayer potion(4)", "potion-dose-4"),
			item(125, "Attack potion(1)", "potion-dose-1"),
			item(141, "Prayer potion(2)", "potion-dose-2"),
			item(2428, "Attack potion(4)", "potion-dose-4"),
			item(139, "Prayer potion(3)", "potion-dose-3"),
			item(123, "Attack potion(2)", "potion-dose-2")));

		assertEquals(Arrays.asList("Attack potion(4)", "Attack potion(3)",
			"Attack potion(2)", "Attack potion(1)", "Prayer potion(4)",
			"Prayer potion(3)", "Prayer potion(2)", "Prayer potion(1)"), names(sorted));
	}

	@Test
	public void usesExplicitDoseFactsInsteadOfItemIdArithmetic()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(117, "Strength potion(2)", "potion-dose-2"),
			item(113, "Strength potion(4)", "potion-dose-4"),
			item(119, "Strength potion(1)", "potion-dose-1"),
			item(115, "Strength potion(3)", "potion-dose-3")));

		assertEquals(Arrays.asList("Strength potion(4)", "Strength potion(3)",
			"Strength potion(2)", "Strength potion(1)"), names(sorted));
	}

	@Test
	public void lookalikeAndMinigameIdsCannotJoinACuratedPotionFamily()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(999_999, "Prayer potion(4)", "potion-dose-4"),
			item(143, "Altered canonical label", "potion-dose-1"),
			item(20_393, "Prayer potion(4)", "potion-dose-4"),
			item(2434, "Another altered label", "potion-dose-4")));

		assertEquals(Arrays.asList("Another altered label", "Altered canonical label",
			"Prayer potion(4)", "Prayer potion(4)"), names(sorted));
		assertEquals(20_393, sorted.get(2).getItemId());
		assertEquals(999_999, sorted.get(3).getItemId());
	}

	@Test
	public void barbarianMixesStayOutsideTheStandardDoseGrid()
	{
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(2434, "Prayer potion(4)", "potion-dose-4"),
			item(143, "Prayer potion(1)", "potion-dose-1"),
			item(11429, "Superattack mix(2)", "potion-dose-2")));

		assertEquals(Arrays.asList("Prayer potion(4)", "Prayer potion(1)",
			"Superattack mix(2)"), names(sorted));
	}

	@Test
	public void realPotionPlaceholderKeepsItsCanonicalDosePosition()
	{
		BankPreviewItem placeholder = new BankPreviewItem(new CatalogItem(6687, "Saradomin brew(3)",
			ItemCategory.POTION, "potion-dose-3", Collections.emptySet(), null), 0, true);
		List<BankPreviewItem> sorted = SupplyItemSorter.sort(Arrays.asList(
			item(6689, "Saradomin brew(2)", "potion-dose-2"), placeholder,
			item(6685, "Saradomin brew(4)", "potion-dose-4")));

		assertEquals(Arrays.asList("Saradomin brew(4)", "Saradomin brew(3)",
			"Saradomin brew(2)"), names(sorted));
		assertTrue(sorted.get(1).isPlaceholder());
		assertEquals(0, sorted.get(1).getQuantity());
	}

	private static BankPreviewItem item(int id, String name, String subcategory)
	{
		return new BankPreviewItem(new CatalogItem(id, name, ItemCategory.POTION, subcategory,
			Collections.emptySet(), null), 1);
	}

	private static List<String> names(List<BankPreviewItem> items)
	{
		return items.stream().map(BankPreviewItem::getDisplayName).collect(Collectors.toList());
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * A tab holding tags of two categories reads in the player's tag order even
 * when that order alternates between the categories, provided every category
 * on the tab is laid out as a plain run. Shaped layouts keep stacking whole.
 */
public class TagInterleaveTest
{
	private static final int GRIMY_RANARR = 207;
	private static final int CLEAN_RANARR = 257;
	private static final int STRAWBERRY = 5504;
	private static final int RANARR_SEED = 5295;
	private static final int POTATO_SEED = 5318;
	private static final int RANARR_UNF = 99;
	private static final int BIRD_NEST = 5075;
	private static final int ADAMANT_FULL_HELM = 1161;
	private static final int BRONZE_ARROW = 882;
	private static final int ROTTEN_FOOD = 2959;

	// Herbs, produce, herb seed, garden seed, unfinished potion, secondary.
	private static final BankSnapshot FARM_AND_HERBS = new BankSnapshot(Arrays.asList(
		new BankItemSnapshot(GRIMY_RANARR, 5, 0),
		new BankItemSnapshot(CLEAN_RANARR, 5, 1),
		new BankItemSnapshot(STRAWBERRY, 3, 2),
		new BankItemSnapshot(RANARR_SEED, 4, 3),
		new BankItemSnapshot(POTATO_SEED, 6, 4),
		new BankItemSnapshot(RANARR_UNF, 2, 5),
		new BankItemSnapshot(BIRD_NEST, 1, 6)));

	/** Herbs, then produce, then both seed tags, then the potion tags: H F H F H. */
	private static final String WOVEN_TAB =
		"grimy-herbs+clean-herbs+produce+herb-seeds+seeds+unfinished-potions+secondaries+herblore-other";

	private static final BankLayoutOptions FARMING_AS_LIST = new BankLayoutOptions(true, true, true,
		Collections.singletonMap(BankCategorySortMode.FARMING, TabOrder.SEQUENTIAL));

	private static final BankLayoutOptions GEAR_AS_LIST = new BankLayoutOptions(true, true, true,
		Collections.emptyMap(), GearLayout.LIST, PotionDoseOrder.GRAB_AREA, RuneOrder.ALPHABETICAL,
		TeleportOrder.ALPHABETICAL);

	@Test
	public void plainRunsOfTwoCategoriesWeaveInTheTagOrder()
	{
		BankLayoutPlan plan = planWithHerbTab(WOVEN_TAB);

		assertEquals(Arrays.asList(GRIMY_RANARR, CLEAN_RANARR, STRAWBERRY, RANARR_SEED,
				POTATO_SEED, RANARR_UNF, BIRD_NEST),
			idsOn(build(FARMING_AS_LIST, plan), plan.destinationOf("grimy-herbs")));
	}

	/**
	 * A category laid out by column keeps its block whole: with the farming
	 * grid in play the tab stacks herblore then farming as it always has.
	 */
	@Test
	public void aShapedCategoryOnTheTabKeepsTheBlocksStacked()
	{
		BankLayoutPlan plan = planWithHerbTab(WOVEN_TAB);

		assertEquals(Arrays.asList(GRIMY_RANARR, CLEAN_RANARR, RANARR_SEED, RANARR_UNF, BIRD_NEST,
				POTATO_SEED, STRAWBERRY),
			idsOn(build(BankLayoutOptions.DEFAULTS, plan), plan.destinationOf("grimy-herbs")));
	}

	/**
	 * A farming item corrected onto a herblore tag is laid out by column inside
	 * the herblore block, so that block is no longer a plain run and the tab
	 * stacks.
	 */
	@Test
	public void aFarmingItemPinnedIntoTheHerbloreBlockKeepsTheBlocksStacked()
	{
		BankLayoutPlan plan = planWithHerbTab(WOVEN_TAB);
		CategoryOverrideSource potatoSeedAsSecondary = itemId ->
			itemId == POTATO_SEED ? java.util.Optional.of("secondaries") : java.util.Optional.empty();

		assertEquals(Arrays.asList(GRIMY_RANARR, CLEAN_RANARR, RANARR_SEED, RANARR_UNF, BIRD_NEST,
				POTATO_SEED, STRAWBERRY),
			idsOn(build(FARMING_AS_LIST, plan, potatoSeedAsSecondary), plan.destinationOf("grimy-herbs")));
	}

	/** A default plan's order is bookkeeping, not a statement: the blocks stack. */
	@Test
	public void theDefaultTagOrderStillStacksTheBlocks()
	{
		BankLayoutPlan plan = planWithHerbTab(
			"herb-seeds+grimy-herbs+clean-herbs+secondaries+unfinished-potions+herblore-other+seeds+produce");

		assertEquals(Arrays.asList(GRIMY_RANARR, CLEAN_RANARR, RANARR_UNF, BIRD_NEST, RANARR_SEED,
				POTATO_SEED, STRAWBERRY),
			idsOn(build(FARMING_AS_LIST, plan), plan.destinationOf("grimy-herbs")));
	}

	@Test
	public void weavingNeverLosesOrDuplicatesAnItem()
	{
		BankOrganizationPreview preview = build(FARMING_AS_LIST, planWithHerbTab(WOVEN_TAB));

		int count = 0;
		for (BankCategoryPreview category : preview.getCategories())
		{
			count += category.getItemCount();
		}
		assertEquals(FARM_AND_HERBS.getItems().size(), count);
	}

	/**
	 * A corrected item weaves under the tag the player put it on, not the one
	 * its subcategory implies. Raised by an external review of the merged work.
	 */
	@Test
	public void aCorrectedItemWeavesUnderTheTagThePlayerChose()
	{
		BankSnapshot bank = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(ADAMANT_FULL_HELM, 1, 0),
			new BankItemSnapshot(ROTTEN_FOOD, 4, 1),
			new BankItemSnapshot(BRONZE_ARROW, 32, 2)));
		BankLayoutPlan plan = BankLayoutPlan.parse(BankPresets.IRONMAN, BankLayoutShareCode.decode(
			"BAv1~Corrected~currency+frequently-used|ammunition+cleanup+gear|food+potions+potion-doses"
				+ "|runes+teleports|tools+skilling-outfits+containers|raw-resources+gems+ammo-components|"
				+ WOVEN_TAB + "|clues+cosmetics+collection-log|quest-items|boss-loot").get().getPlan());
		int tab = plan.destinationOf("ammunition");
		CategoryOverrideSource helmAsAmmunition = itemId ->
			itemId == ADAMANT_FULL_HELM
				? java.util.Optional.of("ammunition") : java.util.Optional.empty();

		// Both ammunition-tagged items lead, because the player wrote that order.
		assertEquals(Arrays.asList(BRONZE_ARROW, ADAMANT_FULL_HELM, ROTTEN_FOOD),
			idsOn(build(bank, GEAR_AS_LIST, plan, helmAsAmmunition), tab));
	}

	@Test
	public void correctedTagOwnsItsDescriptorsAndExplicitBlockOrderWins()
	{
		BankSnapshot bank = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(ADAMANT_FULL_HELM, 1, 0),
			new BankItemSnapshot(ROTTEN_FOOD, 4, 1),
			new BankItemSnapshot(BRONZE_ARROW, 32, 2)));
		BankLayoutPlan plan = BankLayoutPlan.parse(BankPresets.IRONMAN,
			"currency+frequently-used|ammunition+cleanup+gear|food+potions+potion-doses"
				+ "|runes+teleports|tools+skilling-outfits+containers|raw-resources+gems+ammo-components|"
				+ WOVEN_TAB + "|clues+cosmetics+collection-log|quest-items|boss-loot");
		CategoryOverrideSource correction = id -> id == ADAMANT_FULL_HELM
			? java.util.Optional.of("ammunition") : java.util.Optional.empty();
		BankOrganizationPreview preview = build(bank, GEAR_AS_LIST, plan, correction);
		List<BankBlockDescriptor> blocks = preview.getBlockDescriptors().get("ammunition");
		assertEquals(2, blocks.size());
		assertEquals(false, preview.getBlockDescriptors().containsKey("gear"));
		BankLayoutOptions arranged = GEAR_AS_LIST.withBlockArrangements(
			BlockArrangements.EMPTY.withTag("ammunition",
				Arrays.asList(blocks.get(1).getBlockKey(), blocks.get(0).getBlockKey())));
		assertEquals(Arrays.asList(ADAMANT_FULL_HELM, BRONZE_ARROW, ROTTEN_FOOD),
			idsOn(build(bank, arranged, plan, correction), plan.destinationOf("ammunition")));
	}

	/**
	 * Weaving is not a herblore special case: gear on its List layout weaves
	 * with cleanup just the same, while the gear grid keeps the tab stacked.
	 */
	@Test
	public void gearOnListWeavesWithAnotherCategoryAndTheGridDoesNot()
	{
		BankSnapshot bank = new BankSnapshot(Arrays.asList(
			new BankItemSnapshot(ADAMANT_FULL_HELM, 1, 0),
			new BankItemSnapshot(ROTTEN_FOOD, 4, 1),
			new BankItemSnapshot(BRONZE_ARROW, 32, 2)));
		BankLayoutPlan plan = BankLayoutPlan.parse(BankPresets.IRONMAN, BankLayoutShareCode.decode(
			"BAv1~Gear weave~currency+frequently-used|gear+cleanup+ammunition|food+potions+potion-doses"
				+ "|runes+teleports|tools+skilling-outfits+containers|raw-resources+gems+ammo-components|"
				+ WOVEN_TAB + "|clues+cosmetics+collection-log|quest-items|boss-loot").get().getPlan());
		int gearTab = plan.destinationOf("gear");

		assertEquals(Arrays.asList(ADAMANT_FULL_HELM, ROTTEN_FOOD, BRONZE_ARROW),
			idsOn(build(bank, GEAR_AS_LIST, plan, CategoryOverrideSource.NONE), gearTab));

		List<Integer> stacked = idsOn(build(bank, BankLayoutOptions.DEFAULTS, plan, CategoryOverrideSource.NONE), gearTab);
		assertEquals(Integer.valueOf(ROTTEN_FOOD), stacked.get(2));
	}

	/** Recipe rows are a shaped layout, so a herb tab that keeps its doses stacks. */
	@Test
	public void recipeRowsKeepTheBlocksStacked()
	{
		BankLayoutPlan plan = BankLayoutPlan.parse(BankPresets.IRONMAN, BankLayoutShareCode.decode(
			"BAv1~Rows~currency+frequently-used|gear+ammunition|food+potions"
				+ "|runes+teleports|tools+skilling-outfits+containers|raw-resources+gems+ammo-components|"
				+ WOVEN_TAB + "+potion-doses|clues+cosmetics+collection-log|quest-items|boss-loot+cleanup")
			.get().getPlan());

		List<Integer> ids = idsOn(build(FARMING_AS_LIST, plan), plan.destinationOf("grimy-herbs"));

		assertEquals(Arrays.asList(POTATO_SEED, STRAWBERRY), ids.subList(5, 7));
		assertEquals(new java.util.HashSet<>(Arrays.asList(GRIMY_RANARR, CLEAN_RANARR, RANARR_SEED,
			RANARR_UNF, BIRD_NEST)), new java.util.HashSet<>(ids.subList(0, 5)));
	}

	/** Part doses stay with the potions so the herb tab is a plain run, not recipe rows. */
	private static BankLayoutPlan planWithHerbTab(String herbTab)
	{
		return BankLayoutPlan.parse(BankPresets.IRONMAN, BankLayoutShareCode.decode(
			"BAv1~Woven~currency+frequently-used|gear+ammunition|food+potions+potion-doses"
				+ "|runes+teleports|tools+skilling-outfits+containers"
				+ "|raw-resources+gems+ammo-components|" + herbTab
				+ "|clues+cosmetics+collection-log|quest-items|boss-loot+cleanup").get().getPlan());
	}

	private static BankOrganizationPreview build(BankLayoutOptions options, BankLayoutPlan plan)
	{
		return build(options, plan, CategoryOverrideSource.NONE);
	}

	private static BankOrganizationPreview build(BankLayoutOptions options, BankLayoutPlan plan,
		CategoryOverrideSource overrides)
	{
		return build(FARM_AND_HERBS, options, plan, overrides);
	}

	private static BankOrganizationPreview build(BankSnapshot bank, BankLayoutOptions options,
		BankLayoutPlan plan, CategoryOverrideSource overrides)
	{
		return BankOrganizationPreviewBuilder.build(bank, CompositeItemCatalog.DEFAULT,
			BankPresets.IRONMAN, GearStatsSource.NONE, ItemValueSource.NONE,
			overrides, plan, options);
	}

	private static List<Integer> idsOn(BankOrganizationPreview preview, int destination)
	{
		List<Integer> ids = new ArrayList<>();
		for (BankPreviewItem item : preview.getCategories().get(destination).getItems())
		{
			if (!item.isBlank())
			{
				ids.add(item.getItemId());
			}
		}
		return ids;
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The promise of splitting the bundles: a bundle keeps its own layout while its
 * tags share a tab, and splitting it degrades gracefully instead of corrupting
 * the tab. Sorting therefore has to happen after the items are grouped into
 * destinations, not before.
 */
public class TagLayoutGroupingTest
{
	// A Herblore chain: grimy and clean ranarr, a snapdragon, the secondary, an
	// unfinished potion and three prayer potion doses.
	private static final BankSnapshot HERBLORE_BANK = new BankSnapshot(Arrays.asList(
		new BankItemSnapshot(207, 5, 0),
		new BankItemSnapshot(257, 5, 1),
		new BankItemSnapshot(3000, 3, 2),
		new BankItemSnapshot(231, 20, 3),
		new BankItemSnapshot(99, 4, 4),
		new BankItemSnapshot(139, 2, 5),
		new BankItemSnapshot(141, 2, 6),
		new BankItemSnapshot(143, 2, 7),
		new BankItemSnapshot(2434, 3, 8)));

	@Test
	public void aBundleWhoseTagsShareATabIsLaidOutAsOneBlock()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(BankPresets.IRONMAN);
		int herbloreTab = plan.destinationOf("clean-herbs");

		// Every Herblore tag defaults to the same tab, which is what lets the
		// recipe sorter see the whole chain.
		for (BankTag tag : BankTags.forCategory("herblore"))
		{
			assertEquals(tag.getKey(), herbloreTab, plan.destinationOf(tag.getKey()));
		}

		List<Integer> byCategory = itemIds(build(null), herbloreCategoryIndex());
		List<Integer> byPlan = itemIds(build(plan), herbloreTab);

		assertEquals(byCategory, byPlan);
	}

	@Test
	public void movingOneTagOffTheBundleSplitsTheItemsBetweenTheTwoTabs()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(BankPresets.IRONMAN);
		int herbloreTab = plan.destinationOf("potion-doses");
		int elsewhere = herbloreTab == 8 ? 7 : 8;
		BankLayoutPlan split = plan.withTagAt("potion-doses", elsewhere);

		BankOrganizationPreview preview = build(split);
		List<Integer> movedTab = itemIds(preview, elsewhere);
		List<Integer> remaining = itemIds(preview, herbloreTab);

		assertTrue(movedTab.toString(), movedTab.containsAll(Arrays.asList(139, 141, 143)));
		assertFalse(remaining.toString(), remaining.contains(139));
		// The chain that stayed behind is still there, only shorter.
		assertTrue(remaining.toString(), remaining.contains(207));
		assertTrue(remaining.toString(), remaining.contains(257));
	}

	@Test
	public void splittingABundleNeverLosesOrDuplicatesAnItem()
	{
		BankLayoutPlan split = BankLayoutPlan.defaultFor(BankPresets.IRONMAN)
			.withTagAt("potion-doses", 8)
			.withTagAt("secondaries", 7)
			.withTagAt("food", 2);

		assertEquals(countItems(build(BankLayoutPlan.defaultFor(BankPresets.IRONMAN))),
			countItems(build(split)));
	}

	@Test
	public void tagCountsAreReportedForTheLayoutScreen()
	{
		BankOrganizationPreview preview = build(BankLayoutPlan.defaultFor(BankPresets.IRONMAN));

		assertTrue(preview.getTagCounts().toString(),
			preview.getTagCounts().getOrDefault("potion-doses", 0) >= 3);
		assertEquals(0, preview.getTagCounts().getOrDefault("not-a-tag", 0).intValue());
	}

	private static BankOrganizationPreview build(BankLayoutPlan plan)
	{
		return BankOrganizationPreviewBuilder.build(HERBLORE_BANK, CompositeItemCatalog.DEFAULT,
			BankPresets.IRONMAN, GearStatsSource.NONE, ItemValueSource.NONE,
			CategoryOverrideSource.NONE, plan);
	}

	private static int herbloreCategoryIndex()
	{
		List<BankCategory> categories = BankPresets.IRONMAN.getCategories();
		for (int index = 0; index < categories.size(); index++)
		{
			if ("herblore".equals(categories.get(index).getKey()))
			{
				return index;
			}
		}

		throw new AssertionError("herblore category missing");
	}

	private static List<Integer> itemIds(BankOrganizationPreview preview, int index)
	{
		List<Integer> ids = new ArrayList<>();
		for (BankPreviewItem item : preview.getCategories().get(index).getItems())
		{
			if (!item.isBlank())
			{
				ids.add(item.getItemId());
			}
		}

		return ids;
	}

	private static int countItems(BankOrganizationPreview preview)
	{
		int count = 0;
		for (BankCategoryPreview category : preview.getCategories())
		{
			count += category.getItemCount();
		}

		return count;
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.override.UserCategoryOverrides;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A correction names a tag, because the plan places tags. Naming a category
 * could only say which bundle an item joins, leaving the subcategory to decide
 * which part of it, which is exactly the decision the player is overruling.
 */
public class TagOverrideTest
{
	// A cowhide: classified as a resource, so its own subcategory would never
	// route it anywhere near runes.
	private static final int COWHIDE = 1739;

	private static final BankSnapshot BANK = new BankSnapshot(Arrays.asList(
		new BankItemSnapshot(COWHIDE, 5, 0),
		new BankItemSnapshot(995, 100000, 1)));

	@Test
	public void aCorrectionNamingATagPutsTheItemOnThatTag()
	{
		BankOrganizationPreview preview = build(overrides("runes"));

		assertEquals(1, count(preview, "runes"));
		assertEquals(0, count(preview, "raw-resources"));
	}

	@Test
	public void theCorrectedItemLandsOnTheTabItsTagIsOn()
	{
		BankLayoutPlan plan = BankLayoutPlan.defaultFor(BankPresets.IRONMAN)
			.withTagAt("runes", 6);

		BankOrganizationPreview preview = build(overrides("runes"), plan);

		assertTrue(idsOn(preview, 6).contains(COWHIDE));
	}

	/**
	 * Corrections stored before the bundles were split named a category, and must
	 * keep working: the category still decides the bundle, and the item's own
	 * subcategory decides which part of it, exactly as it used to.
	 */
	@Test
	public void aCorrectionStoredAsACategoryStillResolves()
	{
		BankOrganizationPreview preview = build(overrides("currency-utilities"));

		// Cowhide has no rune or teleport subcategory, so it falls to the
		// bundle's catch-all rather than being dropped.
		assertEquals(1, count(preview, "frequently-used"));
		assertEquals(0, count(preview, "raw-resources"));
	}

	@Test
	public void anUnknownStoredKeyLeavesTheAutomaticClassificationAlone()
	{
		BankOrganizationPreview preview = build(overrides("not-a-key"));

		assertEquals(1, count(preview, "raw-resources"));
	}

	private static UserCategoryOverrides overrides(String key)
	{
		UserCategoryOverrides overrides = new UserCategoryOverrides();
		overrides.put(COWHIDE, key);
		return overrides;
	}

	private static BankOrganizationPreview build(UserCategoryOverrides overrides)
	{
		return build(overrides, BankLayoutPlan.defaultFor(BankPresets.IRONMAN));
	}

	private static BankOrganizationPreview build(UserCategoryOverrides overrides,
		BankLayoutPlan plan)
	{
		return BankOrganizationPreviewBuilder.build(BANK, CompositeItemCatalog.DEFAULT,
			BankPresets.IRONMAN, GearStatsSource.NONE, ItemValueSource.NONE, overrides, plan);
	}

	private static int count(BankOrganizationPreview preview, String tagKey)
	{
		Integer count = preview.getTagCounts().get(tagKey);
		return count == null ? 0 : count;
	}

	private static java.util.List<Integer> idsOn(BankOrganizationPreview preview, int destination)
	{
		java.util.List<Integer> ids = new java.util.ArrayList<>();
		for (BankPreviewItem item : preview.getCategories().get(destination).getItems())
		{
			if (!item.isBlank())
			{
				ids.add(item.getItemId());
			}
		}

		return Collections.unmodifiableList(ids);
	}
}

package com.pkoka5.ironmanbankarchitect.organize;

import com.pkoka5.ironmanbankarchitect.catalog.CatalogItem;
import com.pkoka5.ironmanbankarchitect.catalog.ItemCategory;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TeleportItemSorterTest
{
	@Test
	public void groupsRolesAndOrdersJewelleryByHighestChargeFirst()
	{
		List<BankPreviewItem> sorted = TeleportItemSorter.sort(Arrays.asList(
			item(1, "Ring of dueling(2)", ItemCategory.TELEPORT, "teleport"),
			item(2, "Pure essence", ItemCategory.RUNE, "rune"),
			item(3, "Nature rune", ItemCategory.RUNE, "rune"),
			item(4, "Air rune", ItemCategory.RUNE, "rune"),
			item(5, "Ring of dueling(8)", ItemCategory.TELEPORT, "teleport"),
			item(6, "Rune pouch", ItemCategory.RUNE, "rune-container"),
			item(7, "Teleport to house", ItemCategory.TELEPORT, "teleport-tablet"),
			item(8, "Ectophial", ItemCategory.TELEPORT, "teleport")
		));

		assertEquals(Arrays.asList("Air rune", "Nature rune", "Pure essence", "Rune pouch",
			"Ectophial", "Ring of dueling(8)", "Ring of dueling(2)", "Teleport to house"),
			names(sorted));
	}

	@Test
	public void keepsRunecraftingUtilityWithPouchesInsteadOfElementalRunes()
	{
		List<BankPreviewItem> sorted = TeleportItemSorter.sort(Arrays.asList(
			item(1, "Binding necklace", ItemCategory.RUNE, "runecrafting-utility"),
