		BoundedLayoutPacker.Outcome outcome = plan(request, fallback);

		assertEquals(128, BoundedLayoutPacker.PRODUCTION_BEAM_WIDTH);
		assertEquals(1_000_000, BoundedLayoutPacker.PRODUCTION_CANDIDATE_ORIGIN_CAP);
