package com.pkoka5.ironmanbankarchitect.organize.layout;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class LayoutCandidateGroupTest
{
	@Test
	public void structurallyInfeasibleRunAtomsRemainEligibleFallbackGroups()
	{
		SemanticRule horizontal = rule("long.horizontal", ShapePrimitive.HORIZONTAL_RUN, allWidths(),
			atom("long.family", 1, 2, 3, 4, 5, 6, 7, 8, 9));
		LayoutCandidateGroup horizontalGroup = onlyGroup(
			request(Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8, 9), horizontal));
		assertTrue(horizontalGroup.getCandidates().isEmpty());
		assertEquals(8, horizontalGroup.getMissedRelations());
		assertEquals(1000, horizontalGroup.getMissedCompleteness());

		SemanticRule vertical = rule("vertical.no-width", ShapePrimitive.VERTICAL_RUN, widths(2, 4, 8),
			atom("vertical.family", 20, 21));
		LayoutCandidateGroup verticalGroup = onlyGroup(request(Arrays.asList(20, 21), vertical));
		assertTrue(verticalGroup.getCandidates().isEmpty());
		assertEquals(1, verticalGroup.getMissedRelations());

		SemanticRule singleton = rule("single.run", ShapePrimitive.HORIZONTAL_RUN, allWidths(),
			atom("single.family", 30, 31));
		assertEquals(Collections.emptyList(),
			LayoutCandidateGenerator.generate(request(Collections.singletonList(30), singleton)));
	}

	@Test
	public void projectedFallbackFactsUseOwnedCountOverReviewedCount()
	{
		SemanticRule rule = rule("incomplete.run", ShapePrimitive.HORIZONTAL_RUN, widths(3, 4),
			atom("incomplete.family", 10, 20, 30, 40));

		LayoutCandidateGroup group = onlyGroup(request(Arrays.asList(40, 30, 10), rule));

		assertEquals(Arrays.asList(10, 30, 40), group.getProjectedItemIds());
		assertEquals(2, group.getMissedRelations());
		assertEquals(750, group.getMissedCompleteness());
		assertEquals(4, group.getAtomProjections().get(0).getReviewedMemberCount());
		assertEquals(3, group.getAtomProjections().get(0).size());
	}

	@Test
	public void everyGeneratedCollectionIsImmutable()
	{
		SemanticRule rule = rule("immutable.stage", ShapePrimitive.STAGE_MATRIX, widths(1, 2),
			atom("family.a", 10, 11), atom("family.b", 20, 21));
		List<LayoutCandidateGroup> groups = LayoutCandidateGenerator.generate(
			request(Arrays.asList(10, 11, 20, 21), rule));
		LayoutCandidateGroup group = groups.get(0);
		LayoutCandidateGroup.AtomProjection projection = group.getAtomProjections().get(0);

		assertImmutable(groups);
		assertImmutable(group.getAtomProjections());
		assertImmutable(group.getAtomKeys());
		assertImmutable(group.getProjectedItemIds());
		assertImmutable(group.getCandidates());
		assertImmutable(projection.getMemberKeys());
		assertImmutable(projection.getItemIds());
	}

	@Test
	public void equivalentGenerationHasValueEqualityIndependentOfRuleInstances()
	{
		SemanticRule firstRule = rule("equal.stage", ShapePrimitive.STAGE_MATRIX, widths(1, 2, 3),
			atom("family.a", 10, 11), atom("family.b", 20, 21));
		SemanticRule secondRule = rule("equal.stage", ShapePrimitive.STAGE_MATRIX, widths(3, 2, 1),
			atom("family.a", 10, 11), atom("family.b", 20, 21));

		LayoutCandidateGroup first = onlyGroup(request(Arrays.asList(10, 11, 20, 21), firstRule));
		LayoutCandidateGroup second = onlyGroup(request(Arrays.asList(21, 20, 11, 10), secondRule));
		LayoutCandidateGroup incomplete = onlyGroup(request(Arrays.asList(10, 11, 20), firstRule));

		assertEquals(first, second);
		assertEquals(first.hashCode(), second.hashCode());
		assertNotEquals(first, incomplete);
		assertTrue(first.toString().contains("equal.stage"));
	}

	@Test
	public void groupRejectsCandidateIdentityItemsAndDuplicateWidthsThatDoNotMatch()
	{
		SemanticRule rule = rule("strict.run", ShapePrimitive.HORIZONTAL_RUN, widths(2, 3),
			atom("strict.family", 10, 20));
		LayoutCandidateGroup valid = onlyGroup(request(Arrays.asList(10, 20), rule));
		List<LayoutCandidateGroup.AtomProjection> projections = valid.getAtomProjections();

		assertGroupFails(() -> new LayoutCandidateGroup(rule, projections, Collections.singletonList(
			new LayoutCandidate("other.rule", ShapePrimitive.HORIZONTAL_RUN, 2,
				Collections.singletonList("strict.family"), Collections.singletonList(row(0, 10, 20))))));
		assertGroupFails(() -> new LayoutCandidateGroup(rule, projections, Collections.singletonList(
			new LayoutCandidate("strict.run", ShapePrimitive.HORIZONTAL_RUN, 2,
				Collections.singletonList("strict.family"), Collections.singletonList(row(0, 10, 30))))));
		LayoutCandidate candidate = valid.getCandidates().get(0);
		assertGroupFails(() -> new LayoutCandidateGroup(rule, projections,
			Arrays.asList(candidate, candidate)));
	}

	@Test
	public void groupRejectsNonCanonicalGeometryForEveryPrimitiveAndMissingFeasibleWidths()
	{
		SemanticRule horizontal = rule("strict.horizontal", ShapePrimitive.HORIZONTAL_RUN, widths(2),
			atom("horizontal.family", 10, 20));
		LayoutCandidateGroup horizontalGroup = onlyGroup(request(Arrays.asList(10, 20), horizontal));
		assertGroupFails(() -> new LayoutCandidateGroup(horizontal,
			horizontalGroup.getAtomProjections(), Collections.singletonList(
				new LayoutCandidate("strict.horizontal", ShapePrimitive.HORIZONTAL_RUN, 2,
					Collections.singletonList("horizontal.family"),
					Collections.singletonList(row(0, 20, 10))))));

		SemanticRule vertical = rule("strict.vertical", ShapePrimitive.VERTICAL_RUN, widths(1),
			atom("vertical.family", 30, 31));
		LayoutCandidateGroup verticalGroup = onlyGroup(request(Arrays.asList(30, 31), vertical));
		assertGroupFails(() -> new LayoutCandidateGroup(vertical,
			verticalGroup.getAtomProjections(), Collections.singletonList(
				new LayoutCandidate("strict.vertical", ShapePrimitive.VERTICAL_RUN, 1,
					Collections.singletonList("vertical.family"),
					Arrays.asList(row(0, 31), row(0, 30))))));

		SemanticRule stage = rule("strict.stage", ShapePrimitive.STAGE_MATRIX, widths(2),
			atom("stage.a", 40, 41), atom("stage.b", 50, 51));
		LayoutCandidateGroup stageGroup = onlyGroup(request(Arrays.asList(40, 41, 50, 51), stage));
		assertGroupFails(() -> new LayoutCandidateGroup(stage, stageGroup.getAtomProjections(),
			Collections.singletonList(new LayoutCandidate("strict.stage", ShapePrimitive.STAGE_MATRIX, 2,
				Arrays.asList("stage.a", "stage.b"),
				Arrays.asList(row(0, 40, 41), row(0, 50, 51))))));

		SemanticRule rowGroup = rule("strict.rows", ShapePrimitive.ROW_GROUP_MATRIX, widths(2),
			atom("row.a", 60, 61), atom("row.b", 70, 71));
		LayoutCandidateGroup rowGroupGroup = onlyGroup(
			request(Arrays.asList(60, 61, 70, 71), rowGroup));
		assertGroupFails(() -> new LayoutCandidateGroup(rowGroup,
			rowGroupGroup.getAtomProjections(), Collections.singletonList(
				new LayoutCandidate("strict.rows", ShapePrimitive.ROW_GROUP_MATRIX, 2,
					Arrays.asList("row.a", "row.b"),
					Arrays.asList(row(0, 70, 71), row(0, 60, 61))))));

		SemanticRule multipleWidths = rule("strict.widths", ShapePrimitive.HORIZONTAL_RUN,
			widths(2, 3), atom("width.family", 80, 81));
		LayoutCandidateGroup complete = onlyGroup(request(Arrays.asList(80, 81), multipleWidths));
		assertGroupFails(() -> new LayoutCandidateGroup(multipleWidths,
			complete.getAtomProjections(), Collections.singletonList(complete.getCandidates().get(0))));
	}

	private static LayoutCandidateGroup onlyGroup(LayoutRequest request)
	{
		List<LayoutCandidateGroup> groups = LayoutCandidateGenerator.generate(request);
		assertEquals(1, groups.size());
		return groups.get(0);
	}

	private static SemanticRule rule(String ruleKey, ShapePrimitive primitive, Set<Integer> allowedWidths,
		SemanticAtom... atoms)
	{
		return SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(Arrays.asList(atoms))
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(primitive)
			.allowedWidths(allowedWidths)
			.build();
	}

	private static SemanticAtom atom(String atomKey, int... itemIds)
	{
		List<SemanticAtom.Member> members = new ArrayList<>();
		for (int index = 0; index < itemIds.length; index++)
		{
			members.add(new SemanticAtom.Member("member." + index, itemIds[index]));
		}
		return new SemanticAtom(atomKey, members);
	}

	private static LayoutRequest request(List<Integer> itemIds, SemanticRule rule)
	{
		List<LayoutEntry> entries = new ArrayList<>();
		for (int index = 0; index < itemIds.size(); index++)
		{
			int itemId = itemIds.get(index);
			entries.add(LayoutEntry.of(new BankPreviewItem(itemId, "Item " + itemId, 1), index));
		}
		return new LayoutRequest(entries, Collections.singletonList(rule));
	}

	private static LayoutCandidate.Row row(int offset, Integer... itemIds)
	{
		return new LayoutCandidate.Row(offset, Arrays.asList(itemIds));
	}

	private static Set<Integer> allWidths()
	{
		return widths(1, 2, 3, 4, 5, 6, 7, 8);
	}

	private static Set<Integer> widths(int... values)
	{
		Set<Integer> result = new LinkedHashSet<>();
		for (int value : values)
		{
			result.add(value);
		}
		return result;
	}

	private static void assertGroupFails(Runnable construction)
	{
		try
		{
			construction.run();
			fail("expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}
	}

	@SuppressWarnings({"rawtypes", "unchecked"})
	private static void assertImmutable(List<?> values)
	{
		try
		{
			((List) values).add(null);
			fail("expected UnsupportedOperationException");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class LayoutCandidateScorerTest
{
	@Test
	public void gemStageMatrixGetsExactWidthRegretAndCanonicalFragmentation()
	{
		SemanticRule rule = rule("gem.workflow", ShapePrimitive.STAGE_MATRIX, widths(2, 5),
			SemanticWidthEvidenceFacts.GEM_RAW_PROCESSED,
			atom("gem.a", 10, 11), atom("gem.b", 20, 21), atom("gem.c", 30, 31),
			atom("gem.d", 40, 41), atom("gem.e", 50, 51));
		LayoutCandidateGroup group = onlyGroup(request(
			Arrays.asList(10, 11, 20, 21, 30, 31, 40, 41, 50, 51), rule));

		LayoutScore widthTwo = LayoutCandidateScorer.score(group, candidate(group, 2));
		LayoutScore widthFive = LayoutCandidateScorer.score(group, candidate(group, 5));
		int[] expectedWidthTwo = new int[LayoutScore.COMPONENT_COUNT];
		expectedWidthTwo[7] = 429;
		expectedWidthTwo[8] = 2;

		assertArrayEquals(expectedWidthTwo, widthTwo.toComponentArray());
		assertEquals(LayoutScore.zero(), widthFive);
		assertEquals(1, LayoutCandidateScorer.widthPreferenceRank(group, candidate(group, 2)));
		assertEquals(0, LayoutCandidateScorer.widthPreferenceRank(group, candidate(group, 5)));
	}

	@Test
	public void herbRowGroupUsesEvidenceWithoutInventingFragmentation()
	{
		SemanticRule rule = rule("herb.workflow", ShapePrimitive.ROW_GROUP_MATRIX, widths(2, 3, 4),
			SemanticWidthEvidenceFacts.HERB_WORKFLOW,
			atom("herb.guam", 10, 11), atom("herb.marrentill", 20, 21));
		LayoutCandidateGroup group = onlyGroup(request(Arrays.asList(10, 11, 20, 21), rule));

		assertEquals(715, LayoutCandidateScorer.score(group, candidate(group, 2)).getWidthEvidenceRegret());
		assertEquals(0, LayoutCandidateScorer.score(group, candidate(group, 3)).getWidthEvidenceRegret());
		assertEquals(715, LayoutCandidateScorer.score(group, candidate(group, 4)).getWidthEvidenceRegret());
		assertEquals(0, LayoutCandidateScorer.score(group, candidate(group, 2)).getSemanticFragmentation());
		assertEquals(1, LayoutCandidateScorer.widthPreferenceRank(group, candidate(group, 2)));
		assertEquals(0, LayoutCandidateScorer.widthPreferenceRank(group, candidate(group, 3)));
		assertEquals(1, LayoutCandidateScorer.widthPreferenceRank(group, candidate(group, 4)));
	}

	@Test
	public void absentOrInactiveEvidenceLeavesAllCandidateLocalScoresNeutral()
	{
		SemanticRule withoutEvidence = rule("plain.run", ShapePrimitive.HORIZONTAL_RUN, widths(2, 3), null,
			atom("plain.family", 10, 11));
		LayoutCandidateGroup plainGroup = onlyGroup(request(Arrays.asList(10, 11), withoutEvidence));
		assertEquals(LayoutScore.zero(), LayoutCandidateScorer.score(plainGroup, candidate(plainGroup, 2)));
		assertEquals(0, LayoutCandidateScorer.widthPreferenceRank(plainGroup, candidate(plainGroup, 3)));

		WidthEvidence inactive = new WidthEvidence(6,
			Arrays.asList(0, 2, 3, 2, 1, 0, 0, 0),
			Arrays.asList(0, 2, 6, 5, 5, 0, 0, 0));
		SemanticRule inactiveRule = rule("metal.stage", ShapePrimitive.STAGE_MATRIX, widths(2, 3), inactive,
			atom("metal.iron", 20, 21), atom("metal.steel", 30, 31));
		LayoutCandidateGroup inactiveGroup = onlyGroup(
			request(Arrays.asList(20, 21, 30, 31), inactiveRule));
		assertEquals(LayoutScore.zero(),
			LayoutCandidateScorer.score(inactiveGroup, candidate(inactiveGroup, 2)));
		assertEquals(0,
			LayoutCandidateScorer.widthPreferenceRank(inactiveGroup, candidate(inactiveGroup, 3)));
	}

	@Test
	public void scorerRejectsCandidateFromAnotherGroup()
	{
		SemanticRule firstRule = rule("a.run", ShapePrimitive.HORIZONTAL_RUN, widths(2), null,
			atom("a.family", 10, 11));
		SemanticRule secondRule = rule("b.run", ShapePrimitive.HORIZONTAL_RUN, widths(2), null,
			atom("b.family", 20, 21));
		LayoutCandidateGroup first = onlyGroup(request(Arrays.asList(10, 11), firstRule));
		LayoutCandidateGroup second = onlyGroup(request(Arrays.asList(20, 21), secondRule));

		assertScoreFails(() -> LayoutCandidateScorer.score(first, candidate(second, 2)));
		assertScoreFails(() -> LayoutCandidateScorer.widthPreferenceRank(first, candidate(second, 2)));
	}

	@Test
	public void fallbackFactsPopulateOnlyTheirExactConfidenceTier()
	{
		for (ConfidenceTier tier : ConfidenceTier.values())
		{
			SemanticRule rule = rule("fallback." + tier.ordinal(),
				ShapePrimitive.HORIZONTAL_RUN, widths(3), null, tier,
				atom("fallback.family", 10, 20, 30, 40));
			LayoutCandidateGroup group = onlyGroup(request(Arrays.asList(10, 20, 30), rule));
			int[] expected = new int[LayoutScore.COMPONENT_COUNT];
			int offset = tier == ConfidenceTier.HIGH ? 0 : tier == ConfidenceTier.MEDIUM ? 2 : 4;
			expected[offset] = 2;
			expected[offset + 1] = 750;

			assertArrayEquals(expected, LayoutCandidateScorer.scoreFallback(group).toComponentArray());
		}
	}

	private static LayoutCandidateGroup onlyGroup(LayoutRequest request)
	{
		List<LayoutCandidateGroup> groups = LayoutCandidateGenerator.generate(request);
		assertEquals(1, groups.size());
		return groups.get(0);
	}

	private static LayoutCandidate candidate(LayoutCandidateGroup group, int width)
	{
		for (LayoutCandidate candidate : group.getCandidates())
		{
			if (candidate.getWidth() == width)
			{
				return candidate;
			}
		}
		throw new AssertionError("missing width " + width);
	}

	private static SemanticRule rule(String ruleKey, ShapePrimitive primitive, Set<Integer> allowedWidths,
		WidthEvidence evidence, SemanticAtom... atoms)
	{
		return rule(ruleKey, primitive, allowedWidths, evidence, ConfidenceTier.HIGH, atoms);
	}

	private static SemanticRule rule(String ruleKey, ShapePrimitive primitive, Set<Integer> allowedWidths,
		WidthEvidence evidence, ConfidenceTier confidenceTier, SemanticAtom... atoms)
	{
		SemanticRule.Builder builder = SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(Arrays.asList(atoms))
			.confidenceTier(confidenceTier)
			.shapePrimitive(primitive)
			.allowedWidths(allowedWidths);
		if (evidence != null)
		{
			builder.widthEvidence(evidence);
		}
		return builder.build();
	}

	private static SemanticAtom atom(String atomKey, int... itemIds)
	{
		List<SemanticAtom.Member> members = new ArrayList<>();
		for (int index = 0; index < itemIds.length; index++)
		{
			members.add(new SemanticAtom.Member("stage." + index, itemIds[index]));
		}
		return new SemanticAtom(atomKey, members);
	}

	private static LayoutRequest request(List<Integer> itemIds, SemanticRule rule)
	{
		List<LayoutEntry> entries = new ArrayList<>();
		for (int index = 0; index < itemIds.size(); index++)
		{
			int itemId = itemIds.get(index);
			entries.add(LayoutEntry.of(new BankPreviewItem(itemId, "Item " + itemId, 1), index));
		}
		return new LayoutRequest(entries, Collections.singletonList(rule));
	}

	private static Set<Integer> widths(int... values)
	{
		Set<Integer> result = new LinkedHashSet<>();
		for (int value : values)
		{
			result.add(value);
		}
		return result;
	}

	private static void assertScoreFails(Runnable scoring)
	{
		try
		{
			scoring.run();
			fail("expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.fail;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class LayoutCandidateTest
{
	@Test
	public void buildsExplicitRaggedStageMatrixWithoutPhantomCells()
	{
		LayoutCandidate candidate = candidate("gem.workflow", ShapePrimitive.STAGE_MATRIX, 3,
			Arrays.asList("gem.sapphire", "gem.emerald", "gem.ruby", "gem.diamond", "gem.dragonstone"),
			row(0, 10, 20, 30), row(0, 11, 21, 31), row(0, 40, 50), row(0, 41, 51));

		assertEquals(3, candidate.getWidth());
		assertEquals(Arrays.asList(3, 3, 2, 2), rowLengths(candidate));
		assertEquals(Arrays.asList(10, 20, 30, 11, 21, 31, 40, 50, 41, 51),
			candidate.getRowMajorItemIds());
		assertEquals(10, candidate.getRowMajorItemIds().size());
	}

	@Test
	public void rowBoundariesAndOffsetsArePartOfStableIdentity()
	{
		LayoutCandidate twoThenOne = candidate("rune.rows", ShapePrimitive.ROW_GROUP_MATRIX, 2,
			Collections.singletonList("rune.group"), row(0, 1, 2), row(0, 3));
		LayoutCandidate oneThenTwo = candidate("rune.rows", ShapePrimitive.ROW_GROUP_MATRIX, 2,
			Collections.singletonList("rune.group"), row(0, 1), row(0, 2, 3));
		LayoutCandidate shifted = candidate("rune.rows", ShapePrimitive.ROW_GROUP_MATRIX, 2,
			Collections.singletonList("rune.group"), row(1, 1), row(0, 2, 3));

		assertEquals(twoThenOne.getRowMajorItemIds(), oneThenTwo.getRowMajorItemIds());
		assertNotEquals(twoThenOne, oneThenTwo);
		assertNotEquals(oneThenTwo, shifted);
		assertEquals(twoThenOne, candidate("rune.rows", ShapePrimitive.ROW_GROUP_MATRIX, 2,
			Collections.singletonList("rune.group"), row(0, 1, 2), row(0, 3)));
		assertEquals(twoThenOne.hashCode(), candidate("rune.rows", ShapePrimitive.ROW_GROUP_MATRIX, 2,
			Collections.singletonList("rune.group"), row(0, 1, 2), row(0, 3)).hashCode());
	}

	@Test
	public void everyIdentityFieldMatters()
	{
		LayoutCandidate base = candidate("potion.doses", ShapePrimitive.HORIZONTAL_RUN, 4,
			Collections.singletonList("potion.prayer"), row(0, 40, 30));

		assertNotEquals(base, candidate("potion.other", ShapePrimitive.HORIZONTAL_RUN, 4,
			Collections.singletonList("potion.prayer"), row(0, 40, 30)));
		assertNotEquals(base, candidate("potion.doses", ShapePrimitive.VERTICAL_RUN, 4,
			Collections.singletonList("potion.prayer"), row(0, 40, 30)));
		assertNotEquals(base, candidate("potion.doses", ShapePrimitive.HORIZONTAL_RUN, 5,
			Collections.singletonList("potion.prayer"), row(0, 40, 30)));
		assertNotEquals(base, candidate("potion.doses", ShapePrimitive.HORIZONTAL_RUN, 4,
			Collections.singletonList("potion.restore"), row(0, 40, 30)));
		assertNotEquals(base, candidate("potion.doses", ShapePrimitive.HORIZONTAL_RUN, 4,
			Collections.singletonList("potion.prayer"), row(0, 30, 40)));
	}

	@Test
	public void rejectsMalformedGeometryAndIdentity()
	{
		assertCandidateFails("Bad Key", 2, Collections.singletonList("atom.one"), rows(row(0, 1)));
		assertCandidateFails("rule.one", 0, Collections.singletonList("atom.one"), rows(row(0, 1)));
		assertCandidateFails("rule.one", 9, Collections.singletonList("atom.one"), rows(row(0, 1)));
		assertCandidateFails("rule.one", 2, null, rows(row(0, 1)));
		assertCandidateFails("rule.one", 2, Collections.emptyList(), rows(row(0, 1)));
		assertCandidateFails("rule.one", 2, Arrays.asList("atom.one", "atom.one"), rows(row(0, 1)));
		assertCandidateFails("rule.one", 2, Collections.singletonList("Bad Key"), rows(row(0, 1)));
		assertCandidateFails("rule.one", 2, Collections.singletonList("atom.one"), null);
		assertCandidateFails("rule.one", 2, Collections.singletonList("atom.one"), Collections.emptyList());
		assertCandidateFails("rule.one", 2, Collections.singletonList("atom.one"), Arrays.asList(row(0, 1), null));
		assertCandidateFails("rule.one", 2, Collections.singletonList("atom.one"), rows(row(1, 1, 2)));
		assertCandidateFails("rule.one", 2, Collections.singletonList("atom.one"), rows(row(0, 1), row(0, 1)));
		assertCandidateFails("rule.one", 2, Collections.singletonList("atom.one"),
			rows(row(Integer.MAX_VALUE, 1)));
	}

	@Test
	public void rowsRejectInvalidItemContent()
	{
		assertRowFails(-1, Arrays.asList(1));
		assertRowFails(0, null);
		assertRowFails(0, Collections.emptyList());
		assertRowFails(0, Arrays.asList(1, null));
		assertRowFails(0, Arrays.asList(1, 0));
		assertRowFails(0, Arrays.asList(1, -4));
		assertRowFails(0, Arrays.asList(1, ItemID.BANK_FILLER));
	}

	@Test
	public void candidateAndRowsDefensivelyCopyCollections()
	{
		List<String> atomKeys = new ArrayList<>(Collections.singletonList("atom.one"));
		List<Integer> itemIds = new ArrayList<>(Arrays.asList(1, 2));
		LayoutCandidate.Row row = new LayoutCandidate.Row(0, itemIds);
		List<LayoutCandidate.Row> rows = new ArrayList<>(Collections.singletonList(row));
		LayoutCandidate candidate = new LayoutCandidate("rule.one", ShapePrimitive.HORIZONTAL_RUN, 2,
			atomKeys, rows);

		atomKeys.add("atom.two");
		itemIds.add(3);
		rows.add(new LayoutCandidate.Row(0, Collections.singletonList(4)));
		assertEquals(Collections.singletonList("atom.one"), candidate.getAtomKeys());
		assertEquals(Arrays.asList(1, 2), candidate.getRows().get(0).getItemIds());
		assertEquals(1, candidate.getRows().size());

		assertImmutable(candidate.getAtomKeys());
		assertImmutable(candidate.getRows());
		assertImmutable(candidate.getRows().get(0).getItemIds());
	}

	private static LayoutCandidate candidate(String ruleKey, ShapePrimitive primitive, int width,
		List<String> atomKeys, LayoutCandidate.Row... rows)
	{
		return new LayoutCandidate(ruleKey, primitive, width, atomKeys, Arrays.asList(rows));
	}

	private static LayoutCandidate.Row row(int offset, Integer... itemIds)
	{
		return new LayoutCandidate.Row(offset, Arrays.asList(itemIds));
	}

	private static List<LayoutCandidate.Row> rows(LayoutCandidate.Row... rows)
	{
		return Arrays.asList(rows);
	}

	private static List<Integer> rowLengths(LayoutCandidate candidate)
	{
		List<Integer> lengths = new ArrayList<>();
		for (LayoutCandidate.Row row : candidate.getRows())
		{
			lengths.add(row.length());
		}
		return lengths;
	}

	private static void assertCandidateFails(String ruleKey, int width, List<String> atomKeys,
		List<LayoutCandidate.Row> rows)
	{
		try
		{
			new LayoutCandidate(ruleKey, ShapePrimitive.HORIZONTAL_RUN, width, atomKeys, rows);
			fail("expected construction failure");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}
	}

	private static void assertRowFails(int offset, List<Integer> itemIds)
	{
		try
		{
			new LayoutCandidate.Row(offset, itemIds);
			fail("expected construction failure");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}
	}

	@SuppressWarnings({"rawtypes", "unchecked"})
	private static void assertImmutable(List<?> values)
	{
		try
		{
			((List) values).add(null);
			fail("expected UnsupportedOperationException");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}
}

