	@Test
	public void validatorDoesNotMutateInputAndRequestCopiesDefensively()
	{
		List<LayoutEntry> entries = new ArrayList<>(Arrays.asList(entry(10, 0), entry(20, 1)));
		List<SemanticRule> rules = new ArrayList<>(Collections.singletonList(rule("herb.workflow", 10)));
		List<Integer> order = new ArrayList<>(Arrays.asList(20, 10));
		LayoutRequest request = new LayoutRequest(entries, rules, order);

		LayoutRequestValidator.validate(request);
		assertEquals(2, entries.size());
		assertEquals(1, rules.size());
		assertEquals(Arrays.asList(20, 10), order);

		entries.clear();
		rules.clear();
		order.clear();
		assertEquals(2, request.size());
		assertEquals(1, request.getRules().size());
		assertEquals(Arrays.asList(20, 10), request.getCurrentDenseCategoryOrder());
		assertTrue(LayoutRequestValidator.validate(request).isEmpty());
	}

	@Test
	public void requestCollectionsAndConflictListAreImmutable()
	{
		LayoutRequest request = new LayoutRequest(
			Arrays.asList(entry(10, 0), entry(10, 1)), Collections.emptyList());
		List<LayoutConflict> conflicts = LayoutRequestValidator.validate(request);

		try
		{
			request.getEntries().add(null);
			fail("expected UnsupportedOperationException");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}

		try
		{
			conflicts.add(new LayoutConflict(LayoutConflict.Type.NULL_ENTRY, LayoutConflict.NO_ITEM, "extra"));
			fail("expected UnsupportedOperationException");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}

	@Test
	public void repeatedValidationIsDeterministic()
	{
		LayoutRequest request = new LayoutRequest(
			Arrays.asList(entry(10, 0).withLockedTarget(0), entry(20, 1).withLockedTarget(0), entry(20, 2)),
			Arrays.asList(rule("herb.workflow", 10, 20), rule("gem.workflow", 20)));

		assertEquals(LayoutRequestValidator.validate(request), LayoutRequestValidator.validate(request));
	}

	@Test
	public void reversedEntryAndRuleOrderYieldsTheSameConflicts()
	{
		List<LayoutEntry> entries = Arrays.asList(
			entry(10, 0).withLockedTarget(1), entry(20, 1).withLockedTarget(1), entry(30, 2));
		List<SemanticRule> rules = Arrays.asList(rule("herb.workflow", 10, 30), rule("gem.workflow", 30));

		List<LayoutEntry> reversedEntries = new ArrayList<>(entries);
		Collections.reverse(reversedEntries);
		List<SemanticRule> reversedRules = new ArrayList<>(rules);
		Collections.reverse(reversedRules);

		List<LayoutConflict> forward = LayoutRequestValidator.validate(new LayoutRequest(entries, rules));
		List<LayoutConflict> backward = LayoutRequestValidator.validate(
			new LayoutRequest(reversedEntries, reversedRules));

		assertEquals(forward, backward);
	}

	@Test
	public void reversedInvalidLocksYieldTheExactSameConflictList()
	{
		List<LayoutEntry> entries = Arrays.asList(
			entry(10, 0).withLockedTarget(-1), entry(20, 1).withLockedTarget(2));
		List<LayoutEntry> reversed = new ArrayList<>(entries);
		Collections.reverse(reversed);

		List<LayoutConflict> forward = LayoutRequestValidator.validate(
			new LayoutRequest(entries, Collections.emptyList()));
		List<LayoutConflict> backward = LayoutRequestValidator.validate(
			new LayoutRequest(reversed, Collections.emptyList()));

		assertEquals(forward, backward);
		assertEquals(2, forward.size());
		assertEquals(LayoutConflict.Type.LOCK_TARGET_OUT_OF_RANGE, forward.get(0).getType());
		assertEquals(LayoutConflict.Type.LOCK_TARGET_OUT_OF_RANGE, forward.get(1).getType());
	}

	private static void assertSingleConflict(LayoutRequest request, LayoutConflict.Type type, int itemId)
	{
		List<LayoutConflict> conflicts = LayoutRequestValidator.validate(request);
		assertEquals("expected exactly one conflict, got " + conflicts, 1, conflicts.size());
		assertEquals(type, conflicts.get(0).getType());
		assertEquals(itemId, conflicts.get(0).getItemId());
	}

	private static void assertIllegalGridStart(LayoutRequest request, int column)
	{
		try
		{
			request.withGridStartColumn(column);
			fail("expected illegal gridStartColumn " + column);
		}
		catch (IllegalArgumentException expected)
		{
			assertTrue(expected.getMessage().contains("gridStartColumn"));
		}
	}

	private static LayoutEntry entry(int itemId, int sourceFlatBankSlot)
	{
		return LayoutEntry.of(new BankPreviewItem(itemId, "Item " + itemId, 1), sourceFlatBankSlot);
	}

	private static SemanticRule rule(String ruleKey, Integer... memberItemIds)
	{
		List<SemanticAtom.Member> members = new ArrayList<>();
		for (int index = 0; index < memberItemIds.length; index++)
		{
			members.add(new SemanticAtom.Member("member." + index, memberItemIds[index]));
		}
		return SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(Collections.singletonList(new SemanticAtom(ruleKey + ".members", members)))
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(ShapePrimitive.HORIZONTAL_RUN)
			.allowedWidths(new LinkedHashSet<>(Arrays.asList(2, 3)))
			.build();
	}

	private static boolean containsType(List<LayoutConflict> conflicts, LayoutConflict.Type type)
	{
		for (LayoutConflict conflict : conflicts)
		{
			if (conflict.getType() == type)
			{
				return true;
			}
		}
		return false;
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.Collections;
import java.util.regex.Pattern;
import org.junit.Test;

public class LayoutScoreTest
{
	private static final String[] COMPONENT_NAMES = {
		"highMissedRelations",
		"highMissedCompleteness",
		"mediumMissedRelations",
		"mediumMissedCompleteness",
		"lowMissedRelations",
		"lowMissedCompleteness",
		"orientationEvidenceRegret",
		"widthEvidenceRegret",
		"semanticFragmentation",
		"semanticRowBreaks",
		"startColumnDeviation",
		"lockedPrefixSpillover",
		"spilloverCompatibilityCost",
		"spilloverTransitions",
		"nominalFootprintSlack",
		"semanticSpan",
		"unrestrictedSwapLowerBound",
		"totalRankDisplacement"
	};

	@Test
	public void hasExactlyEighteenComponents()
	{
		assertEquals(18, LayoutScore.COMPONENT_COUNT);
		assertEquals(18, COMPONENT_NAMES.length);
		assertEquals(18, LayoutScore.zero().toComponentArray().length);
	}

	@Test
	public void zeroScoreHasAllComponentsZero()
	{
		assertArrayEquals(new int[18], LayoutScore.zero().toComponentArray());
	}

	@Test
	public void namedGettersMapToComponentPositionsInDocumentOrder()
	{
		int[] values = new int[18];
		for (int index = 0; index < values.length; index++)
		{
			values[index] = index + 1;
		}
		LayoutScore score = score(values);

		assertEquals(1, score.getHighMissedRelations());
		assertEquals(2, score.getHighMissedCompleteness());
		assertEquals(3, score.getMediumMissedRelations());
		assertEquals(4, score.getMediumMissedCompleteness());
		assertEquals(5, score.getLowMissedRelations());
		assertEquals(6, score.getLowMissedCompleteness());
		assertEquals(7, score.getOrientationEvidenceRegret());
		assertEquals(8, score.getWidthEvidenceRegret());
		assertEquals(9, score.getSemanticFragmentation());
		assertEquals(10, score.getSemanticRowBreaks());
		assertEquals(11, score.getStartColumnDeviation());
		assertEquals(12, score.getLockedPrefixSpillover());
		assertEquals(13, score.getSpilloverCompatibilityCost());
		assertEquals(14, score.getSpilloverTransitions());
		assertEquals(15, score.getNominalFootprintSlack());
		assertEquals(16, score.getSemanticSpan());
		assertEquals(17, score.getUnrestrictedSwapLowerBound());
		assertEquals(18, score.getTotalRankDisplacement());
		assertArrayEquals(values, score.toComponentArray());
	}

	@Test
	public void everyComponentDominatesAllLaterComponents()
	{
		for (int index = 0; index < LayoutScore.COMPONENT_COUNT; index++)
		{
			int[] smaller = new int[18];
			int[] larger = new int[18];
			smaller[index] = 1;
			larger[index] = 2;
			for (int later = index + 1; later < LayoutScore.COMPONENT_COUNT; later++)
			{
				smaller[later] = 500;
			}

			String component = COMPONENT_NAMES[index];
			assertTrue(component + " must dominate all later components",
				score(smaller).compareTo(score(larger)) < 0);
			assertTrue(component + " comparison must be antisymmetric",
				score(larger).compareTo(score(smaller)) > 0);
		}
	}

	@Test
	public void allComponentsAreMinimized()
	{
		for (int index = 0; index < LayoutScore.COMPONENT_COUNT; index++)
		{
			int[] better = new int[18];
			int[] worse = new int[18];
			worse[index] = 1;

			assertTrue(COMPONENT_NAMES[index] + " must be minimized",
				score(better).compareTo(score(worse)) < 0);
		}
	}

	@Test
	public void movementComponentsStayZeroWithoutProvenDenseOrder()
	{
		LayoutScore score = LayoutScore.builder().movement(unprovenRequest(), 7, 19).build();

		assertEquals(0, score.getUnrestrictedSwapLowerBound());
		assertEquals(0, score.getTotalRankDisplacement());
	}

	@Test
	public void movementWithoutProvenDenseOrderOverridesEarlierProvenValues()
	{
		LayoutScore score = LayoutScore.builder()
			.movement(provenRequest(), 5, 11)
			.movement(unprovenRequest(), 7, 19)
			.build();

		assertEquals(0, score.getUnrestrictedSwapLowerBound());
		assertEquals(0, score.getTotalRankDisplacement());
	}

	@Test
	public void invalidDenseOrderCannotActivateMovement()
	{
		LayoutRequest invalid = new LayoutRequest(Collections.singletonList(
			LayoutEntry.of(new BankPreviewItem(1, "Item 1", 1), 0)), Collections.emptyList(),
			Collections.singletonList(99));

		LayoutScore score = LayoutScore.builder().movement(invalid, 7, 19).build();

		assertEquals(0, score.getUnrestrictedSwapLowerBound());
		assertEquals(0, score.getTotalRankDisplacement());
	}

	@Test
	public void sourceExposesNoDirectMovementComponentSetters() throws Exception
	{
		String source = new String(Files.readAllBytes(Paths.get(
			"src/main/java/com/pkoka5/ironmanbankarchitect/organize/layout/LayoutScore.java")),
			StandardCharsets.UTF_8);

		assertFalse(Pattern.compile("\\bBuilder\\s+unrestrictedSwapLowerBound\\s*\\(").matcher(source).find());
		assertFalse(Pattern.compile("\\bBuilder\\s+totalRankDisplacement\\s*\\(").matcher(source).find());
	}

	@Test
	public void movementWithProvenDenseOrderKeepsValues()
	{
		LayoutScore score = LayoutScore.builder().movement(provenRequest(), 7, 19).build();

		assertEquals(7, score.getUnrestrictedSwapLowerBound());
		assertEquals(19, score.getTotalRankDisplacement());
	}

	@Test
	public void rejectsNegativeComponents()
	{
		try
		{
			LayoutScore.builder().semanticSpan(-1);
			fail("expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}

		try
		{
			LayoutScore.builder().movement(provenRequest(), -1, 0);
			fail("expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}

		try
		{
			LayoutScore.builder().movement(provenRequest(), 0, -1);
			fail("expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
			// expected
		}
	}

	@Test
	public void equalScoresAreEqualAndCompareZero()
	{
		int[] values = new int[18];
		Arrays.fill(values, 3);

		assertEquals(score(values), score(values));
		assertEquals(score(values).hashCode(), score(values).hashCode());
		assertEquals(0, score(values).compareTo(score(values)));
	}

	@Test
	public void toComponentArrayIsADefensiveCopy()
	{
		LayoutScore score = LayoutScore.zero();
		int[] components = score.toComponentArray();
		components[0] = 99;

		assertEquals(0, score.getHighMissedRelations());
	}

	@Test
	public void tieKeyIsOnlyConsultedOnExactlyEqualScores()
	{
		DeterministicTieKey smallerKey = tieKey("alpha.rule", Arrays.asList(1));
		DeterministicTieKey largerKey = tieKey("beta.rule", Arrays.asList(2));

		LayoutScore betterScore = LayoutScore.zero();
		LayoutScore worseScore = score(componentArray(17, 1));

		assertTrue("score must decide before the tie key",
			LayoutScore.compareByScoreThenTieKey(betterScore, largerKey, worseScore, smallerKey) < 0);
		assertTrue("equal scores must fall back to the tie key",
			LayoutScore.compareByScoreThenTieKey(betterScore, smallerKey, betterScore, largerKey) < 0);
		assertEquals("equal scores and equal keys compare zero", 0,
			LayoutScore.compareByScoreThenTieKey(betterScore, smallerKey, betterScore,
				tieKey("alpha.rule", Arrays.asList(1))));
	}

	private static int[] componentArray(int index, int value)
	{
		int[] values = new int[18];
		values[index] = value;
		return values;
	}

	private static DeterministicTieKey tieKey(String ruleKey, java.util.List<Integer> itemIds)
	{
		java.util.List<Integer> blockItems = itemIds.size() >= 2
			? itemIds
			: Arrays.asList(itemIds.get(0), itemIds.get(0) + 1000);
		PlacedBlock block = LayoutTestFixtures.placedBlock(ruleKey, ruleKey + ".atom", 0,
			blockItems.size(), ShapePrimitive.HORIZONTAL_RUN, 0, 0,
			new LayoutCandidate.Row(0, blockItems));
		return new DeterministicTieKey(Arrays.asList(block), blockItems);
	}

	private static LayoutScore score(int[] values)
	{
		return LayoutScore.builder()
			.highMissedRelations(values[0])
			.highMissedCompleteness(values[1])
			.mediumMissedRelations(values[2])
			.mediumMissedCompleteness(values[3])
			.lowMissedRelations(values[4])
			.lowMissedCompleteness(values[5])
			.orientationEvidenceRegret(values[6])
			.widthEvidenceRegret(values[7])
			.semanticFragmentation(values[8])
			.semanticRowBreaks(values[9])
			.startColumnDeviation(values[10])
			.lockedPrefixSpillover(values[11])
			.spilloverCompatibilityCost(values[12])
			.spilloverTransitions(values[13])
			.nominalFootprintSlack(values[14])
			.semanticSpan(values[15])
			.movement(provenRequest(), values[16], values[17])
			.build();
	}

	private static LayoutRequest provenRequest()
	{
		return new LayoutRequest(Collections.singletonList(
			LayoutEntry.of(new BankPreviewItem(1, "Item 1", 1), 0)), Collections.emptyList(),
			Collections.singletonList(1));
	}

	private static LayoutRequest unprovenRequest()
	{
		return new LayoutRequest(Collections.singletonList(
			LayoutEntry.of(new BankPreviewItem(1, "Item 1", 1), 0)), Collections.emptyList());
	}
}

package com.pkoka5.ironmanbankarchitect.organize.layout;

import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Test-only construction of real generated groups and candidates. Even comparator tests therefore
 * cannot bypass canonical geometry or forge a placed block's evidence rank.
 */
final class LayoutTestFixtures
{
	private LayoutTestFixtures()
	{
	}

	static PlacedBlock placedBlock(String ruleKey, String atomKey, int expectedPreferenceRank,
		int width, ShapePrimitive primitive, int startRow, int startColumn,
		LayoutCandidate.Row... rows)
	{
		LayoutCandidateGroup group = candidateGroup(ruleKey, atomKey, expectedPreferenceRank,
			width, primitive, rows);
		LayoutCandidate candidate = candidateAtWidth(group, width);
		PlacedBlock block = PlacedBlock.place(group, candidate, startRow, startColumn);
		if (block.getWidthPreferenceRank() != expectedPreferenceRank)
		{
			throw new IllegalArgumentException("fixture evidence did not produce the expected rank");
		}
		return block;
	}

	static LayoutCandidateGroup candidateGroup(String ruleKey, String atomKey,
		int expectedPreferenceRank, int width, ShapePrimitive primitive,
		LayoutCandidate.Row... rows)
	{
		if (rows == null || rows.length == 0)
		{
			throw new IllegalArgumentException("fixture rows must not be empty");
		}

		List<SemanticAtom> atoms = atoms(atomKey, primitive, rows);
		Set<Integer> allowedWidths = new LinkedHashSet<>();
		allowedWidths.add(width);
		SemanticRule.Builder builder = SemanticRule.builder()
			.ruleKey(ruleKey)
			.atoms(atoms)
			.confidenceTier(ConfidenceTier.HIGH)
			.shapePrimitive(primitive);
		WidthEvidence evidence = evidenceForRank(expectedPreferenceRank, width, allowedWidths);
		builder.allowedWidths(allowedWidths);
		if (evidence != null)
		{
			builder.widthEvidence(evidence);
		}

		List<LayoutEntry> entries = new ArrayList<>();
		int sourceIndex = 0;
		for (LayoutCandidate.Row row : rows)
		{
			for (Integer itemId : row.getItemIds())
			{
				entries.add(LayoutEntry.of(
					new BankPreviewItem(itemId, "Item " + itemId, 1), sourceIndex++));
			}
		}

		List<LayoutCandidateGroup> groups = LayoutCandidateGenerator.generate(
			new LayoutRequest(entries, Collections.singletonList(builder.build())));
		if (groups.size() != 1)
		{
			throw new IllegalArgumentException("fixture must produce exactly one candidate group");
		}
		return groups.get(0);
	}

	static LayoutCandidate candidateAtWidth(LayoutCandidateGroup group, int width)
	{
		for (LayoutCandidate candidate : group.getCandidates())
		{
			if (candidate.getWidth() == width)
			{
				return candidate;
			}
		}
		throw new IllegalArgumentException("fixture width did not produce a feasible candidate");
	}

	private static List<SemanticAtom> atoms(String atomKey, ShapePrimitive primitive,
		LayoutCandidate.Row[] rows)
	{
		if (primitive == ShapePrimitive.HORIZONTAL_RUN)
		{
			if (rows.length != 1 || rows[0].getStartOffset() != 0)
			{
				throw new IllegalArgumentException("horizontal fixture requires one zero-offset row");
			}
			return Collections.singletonList(atom(atomKey, rows[0].getItemIds()));
		}
		if (primitive == ShapePrimitive.VERTICAL_RUN)
		{
			List<Integer> itemIds = new ArrayList<>();
			for (LayoutCandidate.Row row : rows)
			{
				if (row.getStartOffset() != 0 || row.length() != 1)
				{
					throw new IllegalArgumentException(
						"vertical fixture requires zero-offset singleton rows");
				}
				itemIds.add(row.getItemIds().get(0));
			}
			return Collections.singletonList(atom(atomKey, itemIds));
		}
		if (primitive == ShapePrimitive.ROW_GROUP_MATRIX)
		{
			List<SemanticAtom> result = new ArrayList<>();
			for (int index = 0; index < rows.length; index++)
			{
				if (rows[index].getStartOffset() != 0)
				{
					throw new IllegalArgumentException("row-group fixture rows must have zero offset");
				}
				String key = rows.length == 1 ? atomKey : atomKey + ".row" + index;
				result.add(atom(key, rows[index].getItemIds()));
			}
			return result;
		}

		throw new IllegalArgumentException("test fixture does not synthesize stage matrices");
	}

	private static SemanticAtom atom(String atomKey, List<Integer> itemIds)
	{
		List<SemanticAtom.Member> members = new ArrayList<>();
		for (int index = 0; index < itemIds.size(); index++)
		{
			members.add(new SemanticAtom.Member("member." + index, itemIds.get(index)));
		}
		return new SemanticAtom(atomKey, members);
	}

	private static WidthEvidence evidenceForRank(int rank, int width, Set<Integer> allowedWidths)
	{
		if (rank == 0)
		{
			return null;
		}
		if (rank < 0 || rank > 2)
		{
			throw new IllegalArgumentException("fixture supports preference ranks zero through two");
		}

		int preferredWidth = width == SemanticRule.MAX_WIDTH ? width - 1 : width + 1;
		allowedWidths.add(preferredWidth);
		Integer[] templateSupport = new Integer[SemanticRule.MAX_WIDTH];
		Integer[] familySupport = new Integer[SemanticRule.MAX_WIDTH];
		Arrays.fill(templateSupport, 0);
		Arrays.fill(familySupport, 0);
		templateSupport[preferredWidth - 1] = 5;
		familySupport[preferredWidth - 1] = 5;
		if (rank == 1)
		{
			templateSupport[width - 1] = 3;
			familySupport[width - 1] = 3;
		}
		else
		{
			int middleWidth = firstOtherWidth(width, preferredWidth);
			templateSupport[middleWidth - 1] = 2;
			familySupport[middleWidth - 1] = 2;
		}
		return new WidthEvidence(7, Arrays.asList(templateSupport), Arrays.asList(familySupport));
	}

	private static int firstOtherWidth(int first, int second)
	{
		for (int width = SemanticRule.MIN_WIDTH; width <= SemanticRule.MAX_WIDTH; width++)
		{
			if (width != first && width != second)
			{
				return width;
			}
		}
		throw new IllegalStateException("no third width available");
	}
}

