	}
}

package com.pkoka5.ironmanbankarchitect.simulate;

import com.pkoka5.ironmanbankarchitect.catalog.CatalogItem;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.organize.BankPresets;
import com.pkoka5.ironmanbankarchitect.organize.PresetCategoryMapper;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.SimulationResult;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Test-scope cleanup observation aggregation and deterministic TSV output. */
final class CleanupReviewReporter
{
	static final String REGISTRY_RESOURCE =
		"/com/pkoka5/ironmanbankarchitect/catalog/item-registry.tsv";
	static final String HEADER =
		"itemId\tcanonicalName\tsourceConstant\toccurrenceCount";

	private CleanupReviewReporter()
	{
	}

	static Map<Integer, Integer> countCleanupOccurrences(List<SimulationResult> results)
	{
		Map<Integer, Integer> occurrences = new HashMap<>();
		for (SimulationResult result : results)
		{
			addCleanupOccurrences(occurrences, result.getSampledItemIds());
		}
		return occurrences;
	}

	static void addCleanupOccurrences(Map<Integer, Integer> occurrences,
		Iterable<Integer> sampledItemIds)
	{
		for (int itemId : sampledItemIds)
		{
			CatalogItem item = CompositeItemCatalog.DEFAULT.findById(itemId)
				.orElse(CatalogItem.unknown(itemId));
			if ("storage-cleanup".equals(
				PresetCategoryMapper.map(BankPresets.IRONMAN, item).getKey()))
			{
				occurrences.merge(itemId, 1, Integer::sum);
			}
		}
	}

	static Map<Integer, Integer> mergeSeedOccurrences(
		Iterable<Map<Integer, Integer>> seedOccurrences)
	{
		Map<Integer, Integer> aggregate = new HashMap<>();
		for (Map<Integer, Integer> seed : seedOccurrences)
		{
			for (Map.Entry<Integer, Integer> entry : seed.entrySet())
			{
				aggregate.merge(entry.getKey(), entry.getValue(), Integer::sum);
			}
		}
		return aggregate;
	}

	static List<ReviewRow> sortedRows(Map<Integer, Integer> occurrences,
		Map<Integer, RegistryRecord> registry)
	{
		List<ReviewRow> rows = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : occurrences.entrySet())
		{
			RegistryRecord record = registry.get(entry.getKey());
			rows.add(new ReviewRow(entry.getKey(), record == null ? "" : record.name,
				record == null ? "" : record.constant, entry.getValue()));
		}
		rows.sort(Comparator.comparingInt(ReviewRow::getOccurrenceCount).reversed()
			.thenComparingInt(ReviewRow::getItemId));
		return rows;
	}

	static void write(Path output, Map<Integer, Integer> occurrences) throws IOException
	{
		Path parent = output.toAbsolutePath().getParent();
		if (parent != null)
		{
			Files.createDirectories(parent);
		}
		List<ReviewRow> rows = sortedRows(occurrences, loadRegistry());
		try (BufferedWriter writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8))
		{
			writer.write(HEADER);
			writer.newLine();
			for (ReviewRow row : rows)
			{
				writer.write(row.itemId + "\t" + row.name + "\t" + row.constant
					+ "\t" + row.occurrenceCount);
				writer.newLine();
			}
		}
	}

	static Map<Integer, RegistryRecord> loadRegistry() throws IOException
	{
		InputStream stream = CleanupReviewReporter.class.getResourceAsStream(REGISTRY_RESOURCE);
		if (stream == null)
		{
			throw new IOException("item registry resource missing: " + REGISTRY_RESOURCE);
		}
		Map<Integer, RegistryRecord> records = new HashMap<>();
		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				String[] columns = line.split("\\t", -1);
				if (columns.length != 4)
				{
					continue;
				}
				try
				{
					int itemId = Integer.parseInt(columns[0].replace("\uFEFF", ""));
					records.put(itemId, new RegistryRecord(columns[1], columns[3]));
				}
				catch (NumberFormatException ignored)
				{
					// Header or malformed record.
				}
			}
		}
		return records;
	}

	static String registrySha256() throws IOException
	{
		InputStream stream = CleanupReviewReporter.class.getResourceAsStream(REGISTRY_RESOURCE);
		if (stream == null)
		{
			throw new IOException("item registry resource missing: " + REGISTRY_RESOURCE);
		}
		byte[] bytes;
		try (InputStream input = stream; ByteArrayOutputStream output = new ByteArrayOutputStream())
		{
			byte[] buffer = new byte[8192];
			int read;
			while ((read = input.read(buffer)) != -1)
			{
				output.write(buffer, 0, read);
			}
			bytes = output.toByteArray();
		}
		return sha256OfNormalisedLines(bytes);
	}

	/**
	 * SHA-256 of the given bytes with CRLF and lone CR normalised to LF.
	 *
	 * <p>The registry is a text resource and {@code .gitattributes} normalises it
	 * on commit, so a Windows checkout holds CRLF and every other checkout holds
	 * LF for the same commit. Hashing the raw bytes would make the fingerprint -
	 * the benchmark's trust anchor - depend on who checked the repository out.</p>
	 */
	static String sha256OfNormalisedLines(byte[] bytes)
	{
		ByteArrayOutputStream normalised = new ByteArrayOutputStream(bytes.length);
		for (int index = 0; index < bytes.length; index++)
		{
			if (bytes[index] == '\r')
			{
				if (index + 1 < bytes.length && bytes[index + 1] == '\n')
				{
					continue;
				}
				normalised.write('\n');
				continue;
			}
			normalised.write(bytes[index]);
		}
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(normalised.toByteArray());
			StringBuilder hex = new StringBuilder(digest.length * 2);
			for (byte value : digest)
			{
				hex.append(String.format("%02x", value & 0xff));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException("SHA-256 is unavailable", ex);
		}
	}

	static final class RegistryRecord
	{
		private final String name;
		private final String constant;

		RegistryRecord(String name, String constant)
		{
			this.name = name;
			this.constant = constant;
		}
	}

	static final class ReviewRow
	{
		private final int itemId;
		private final String name;
		private final String constant;
		private final int occurrenceCount;

		ReviewRow(int itemId, String name, String constant, int occurrenceCount)
		{
			this.itemId = itemId;
			this.name = name;
			this.constant = constant;
			this.occurrenceCount = occurrenceCount;
		}

		int getItemId()
		{
			return itemId;
		}

		int getOccurrenceCount()
		{
			return occurrenceCount;
		}

		String getName()
		{
			return name;
		}

		String getConstant()
		{
			return constant;
		}
	}
}

package com.pkoka5.ironmanbankarchitect.simulate;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.pkoka5.ironmanbankarchitect.simulate.CleanupReviewReporter.RegistryRecord;
import com.pkoka5.ironmanbankarchitect.simulate.CleanupReviewReporter.ReviewRow;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class CleanupReviewReporterTest
{
	@Test
	public void mergesOccurrenceCountsAcrossSeeds()
	{
		Map<Integer, Integer> firstSeed = counts(10, 2, 20, 1);
		Map<Integer, Integer> secondSeed = counts(10, 3, 30, 4);
		Map<Integer, Integer> thirdSeed = counts(20, 5, 30, 1);

		Map<Integer, Integer> aggregate = CleanupReviewReporter.mergeSeedOccurrences(
			Arrays.asList(firstSeed, secondSeed, thirdSeed));

		assertEquals(3, aggregate.size());
		assertEquals(Integer.valueOf(5), aggregate.get(10));
		assertEquals(Integer.valueOf(6), aggregate.get(20));
		assertEquals(Integer.valueOf(5), aggregate.get(30));
	}

	@Test
	public void equalCountsSortByAscendingItemId()
	{
		Map<Integer, Integer> occurrences = counts(30, 4, 10, 4, 20, 5);
		Map<Integer, RegistryRecord> registry = new HashMap<>();
		registry.put(10, new RegistryRecord("Ten", "TEN"));
		registry.put(20, new RegistryRecord("Twenty", "TWENTY"));
		registry.put(30, new RegistryRecord("Thirty", "THIRTY"));

		List<ReviewRow> rows = CleanupReviewReporter.sortedRows(occurrences, registry);

		assertEquals(Arrays.asList(20, 10, 30), Arrays.asList(
			rows.get(0).getItemId(), rows.get(1).getItemId(), rows.get(2).getItemId()));
	}

	@Test
	public void emptyCleanupResultWritesOnlyTheHeader() throws IOException
	{
		Path output = Files.createTempFile("cleanup-review-empty", ".tsv");
		try
		{
			CleanupReviewReporter.write(output, Collections.emptyMap());
			List<String> lines = Files.readAllLines(output, StandardCharsets.UTF_8);
			assertEquals(Collections.singletonList(CleanupReviewReporter.HEADER), lines);
		}
		finally
		{
			Files.deleteIfExists(output);
		}
	}

	@Test
	public void countsOnlyItemsEffectivelyRoutedToIronmanCleanup()
	{
		Map<Integer, Integer> occurrences = new HashMap<>();
		CleanupReviewReporter.addCleanupOccurrences(occurrences,
			Arrays.asList(1, 2, 1)); // Toolkit is cleanup; steel cannonball is combat gear.

		assertEquals(Integer.valueOf(2), occurrences.get(1));
		assertFalse(occurrences.containsKey(2));
	}

	@Test
	public void registryFingerprintMatchesTheProposedProtocol() throws IOException
	{
		assertEquals(CleanupReviewBenchmarkProtocol.REGISTRY_SHA256,
			CleanupReviewReporter.registrySha256());
	}

	@Test
	public void registryFingerprintIgnoresTheCheckoutsLineEndings()
	{
		String unix = "1\tToolkit\n2\tSteel cannonball\n";
		String windows = "1\tToolkit\r\n2\tSteel cannonball\r\n";
		String classicMac = "1\tToolkit\r2\tSteel cannonball\r";

		String expected = CleanupReviewReporter.sha256OfNormalisedLines(
			unix.getBytes(StandardCharsets.UTF_8));

		assertEquals(expected, CleanupReviewReporter.sha256OfNormalisedLines(
			windows.getBytes(StandardCharsets.UTF_8)));
		assertEquals(expected, CleanupReviewReporter.sha256OfNormalisedLines(
			classicMac.getBytes(StandardCharsets.UTF_8)));
	}

	private static Map<Integer, Integer> counts(int... pairs)
	{
		assertTrue("pairs required", pairs.length % 2 == 0);
		Map<Integer, Integer> counts = new HashMap<>();
		for (int index = 0; index < pairs.length; index += 2)
		{
			counts.put(pairs[index], pairs[index + 1]);
		}
		return counts;
	}
}

package com.pkoka5.ironmanbankarchitect.simulate;

import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.MoveType;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.Outcome;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.Scenario;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.SimulationResult;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

/**
 * Developer-only CLI: simulates many random banks against the tab guidance
 * route and writes a TSV report. Run via {@code gradlew simulateRandomBanks}
 * (optionally {@code -PsimBanks=… -PsimSeed=… -PsimMinItems=… -PsimMaxItems=…}).
 * This class is intentionally in the test source set and never ships.
 */
public final class RandomBankSimulationRunner
{
	private RandomBankSimulationRunner()
	{
	}

	public static void main(String[] args) throws IOException
	{
		if (args.length != 5)
		{
			throw new IllegalArgumentException(
				"Expected banks, seed, minItems, maxItems and output arguments");
		}
		int banks = Integer.parseInt(args[0]);
		long baseSeed = Long.parseLong(args[1]);
		int minItems = Integer.parseInt(args[2]);
		int maxItems = Integer.parseInt(args[3]);
		Path output = Paths.get(args[4]);
		if (banks < 1 || minItems < 1 || maxItems < minItems)
		{
			throw new IllegalArgumentException("Invalid banks or item range");
		}

		List<Integer> universe = RandomBankSimulator.loadItemUniverse();
		System.out.println("Item universe: " + universe.size() + " registry items");
		System.out.println("Simulating " + banks + " banks per scenario, "
			+ minItems + "-" + maxItems + " items, base seed " + baseSeed);

		Random sizes = new Random(baseSeed);
		List<SimulationResult> results = new ArrayList<>();
		for (int run = 0; run < banks; run++)
		{
			int itemCount = minItems + sizes.nextInt(maxItems - minItems + 1);
			for (Scenario scenario : Scenario.values())
			{
				results.add(RandomBankSimulator.simulate(
					baseSeed + run, scenario, itemCount, universe));
			}
		}

		writeReport(output, results);
		Path cleanupReview = output.toAbsolutePath().resolveSibling("cleanup-review.tsv");
		CleanupReviewReporter.write(cleanupReview,
			CleanupReviewReporter.countCleanupOccurrences(results));
		printSummary(results);
		System.out.println("Report: " + output.toAbsolutePath());
		System.out.println("Cleanup review: " + cleanupReview);

		boolean hardFailure = results.stream().anyMatch(SimulationOutcomePolicy::isHardFailure);
		if (hardFailure)
		{
			System.out.println("HARD FAILURES FOUND - inspect the report rows above.");
			System.exit(1);
		}
	}

	private static void printSummary(List<SimulationResult> results)
	{
		Map<Outcome, Integer> byOutcome = new EnumMap<>(Outcome.class);
		int totalMoves = 0;
		int totalSwaps = 0;
		int completed = 0;
		for (SimulationResult result : results)
		{
			byOutcome.merge(result.getOutcome(), 1, Integer::sum);
			if (result.getOutcome() == Outcome.COMPLETED)
			{
				completed++;
				totalMoves += result.getTotalMoves();
				totalSwaps += result.getSwapMoves();
			}
		}

		System.out.println();
		System.out.println("Outcomes:");
		for (Map.Entry<Outcome, Integer> entry : byOutcome.entrySet())
		{
			System.out.println("  " + entry.getKey() + ": " + entry.getValue());
		}
		if (completed > 0)
		{
			System.out.println("Average moves per completed bank: "
				+ totalMoves / completed + " (of which swaps: " + totalSwaps / completed + ")");
		}

		for (SimulationResult result : results)
		{
			if (result.getOutcome() == Outcome.COMPLETED
				|| result.getOutcome() == Outcome.UNSUPPORTED_PLAN)
			{
				continue;
			}
			System.out.println("  FAILURE seed=" + result.getSeed()
				+ " scenario=" + result.getScenario()
				+ " items=" + result.getItemCount()
				+ " outcome=" + result.getOutcome()
				+ (result.getErrorMessage().isEmpty() ? "" : " error=" + result.getErrorMessage())
				+ " itemIds=" + result.getFailedItemIds());
		}
	}

	private static void writeReport(Path output, List<SimulationResult> results)
		throws IOException
	{
		Path parent = output.toAbsolutePath().getParent();
		if (parent != null)
		{
			Files.createDirectories(parent);
		}
		try (BufferedWriter writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8))
		{
			writer.write("seed\tscenario\titemCount\tplanTabs\toutcome\tfinalStatus"
				+ "\ttotalMoves\tswaps\tminSwapsAtSortStart\tcollapses\tcreates"
				+ "\tdistributes\ttransfers\treturns\ttabReorders\terror");
			writer.newLine();
			for (SimulationResult result : results)
			{
				writer.write(result.getSeed()
					+ "\t" + result.getScenario()
					+ "\t" + result.getItemCount()
					+ "\t" + result.getPlanTabs()
					+ "\t" + result.getOutcome()
					+ "\t" + (result.getFinalStatus() == null ? "" : result.getFinalStatus())
					+ "\t" + result.getTotalMoves()
					+ "\t" + result.getSwapMoves()
					+ "\t" + result.getMinimumSwapsAtSortStart()
					+ "\t" + result.getMoveCounts().getOrDefault(MoveType.COLLAPSE_TAB, 0)
					+ "\t" + result.getMoveCounts().getOrDefault(MoveType.DRAG_TO_NEW_TAB, 0)
					+ "\t" + result.getMoveCounts().getOrDefault(MoveType.DISTRIBUTE_TO_TAB, 0)
					+ "\t" + result.getMoveCounts().getOrDefault(MoveType.TRANSFER_TO_TAB, 0)
					+ "\t" + result.getMoveCounts().getOrDefault(MoveType.RETURN_TO_MAIN, 0)
					+ "\t" + result.getMoveCounts().getOrDefault(MoveType.REORDER_TAB, 0)
					+ "\t" + result.getErrorMessage().replace('\t', ' '));
				writer.newLine();
			}
		}
	}
}

package com.pkoka5.ironmanbankarchitect.simulate;

import com.pkoka5.ironmanbankarchitect.bank.BankItemSnapshot;
import com.pkoka5.ironmanbankarchitect.bank.BankSnapshot;
import com.pkoka5.ironmanbankarchitect.catalog.CompositeItemCatalog;
import com.pkoka5.ironmanbankarchitect.guide.BankTabPlan;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.Assessment;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.Move;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.MoveType;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.Phase;
import com.pkoka5.ironmanbankarchitect.guide.TabRouteAdvisor.Status;
import com.pkoka5.ironmanbankarchitect.organize.BankOrganizationPreview;
import com.pkoka5.ironmanbankarchitect.organize.BankOrganizationPreviewBuilder;
import com.pkoka5.ironmanbankarchitect.organize.BankPresets;
import com.pkoka5.ironmanbankarchitect.organize.BankPreviewItem;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Random;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * Developer-only simulator that generates reproducible random banks from the
 * full item registry, derives the real Ironman organization plan for them, and
 * replays the {@link TabRouteAdvisor.Session} guidance loop until the bank is
 * complete. Where the transition matcher allows freedom (a distributed item can
 * land anywhere inside its tab, collapse landing order is ignored) the applied
 * position is randomized, so the walk also exercises states a real bank server
 * can produce. This class lives in the test source set and never ships.
 */
public final class RandomBankSimulator
{
	private static final String REGISTRY_RESOURCE =
		"/com/pkoka5/ironmanbankarchitect/catalog/item-registry.tsv";
	private static final Pattern CACHE_ONLY_CONSTANT = Pattern.compile(
		"(^|_)(?:INTERFACE|PLACEHOLDER|DUMMY|NULL)(?:_|$)");
	private static final int MAX_TABS = TabRouteAdvisor.MAX_TABS;

	private RandomBankSimulator()
	{
	}

	public enum Scenario
	{
		/** Every item in main in random order; no numbered tabs yet. */
		SHUFFLED_NO_TABS,
		/** Random order plus a random dirty leading-tab partition. */
		RANDOM_TABS,
		/** The plan's finished layout perturbed by a few swaps and re-deposits. */
		NEARLY_SORTED
	}

	public enum Outcome
	{
		/** Guidance reached COMPLETE and the final order matches the plan. */
		COMPLETED,
		/** The generated plan contains blank targets; guidance fails closed. */
		UNSUPPORTED_PLAN,
		/** Building the preview/plan threw before guidance could start. */
		PLAN_BUILD_ERROR,
		/** The advisor returned a blocked status other than COMPLETE. */
		ADVISOR_BLOCKED,
		/** The session stopped advancing while moves were still expected. */
		STALLED,
		/** The move budget ran out before COMPLETE. */
		NON_TERMINATING
	}

	/** Loads all usable item IDs from the bundled item registry. */
	public static List<Integer> loadItemUniverse()
	{
		List<Integer> universe = new ArrayList<>();
		InputStream stream = RandomBankSimulator.class.getResourceAsStream(REGISTRY_RESOURCE);
		if (stream == null)
		{
			throw new IllegalStateException("item registry resource missing: " + REGISTRY_RESOURCE);
		}
		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.trim().isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] columns = line.split("\\t", -1);
				if (columns.length != 4)
				{
					continue;
				}
				int itemId;
				try
				{
					itemId = Integer.parseInt(columns[0].replace("\uFEFF", ""));
				}
				catch (NumberFormatException ex)
				{
					continue;
				}
				String name = columns[1].trim();
				if (itemId <= 0 || itemId == ItemID.BANK_FILLER
					|| name.isEmpty() || "null".equalsIgnoreCase(name)
					|| "null item".equalsIgnoreCase(name)
					|| CACHE_ONLY_CONSTANT.matcher(
						columns[3].trim().toUpperCase(Locale.ROOT)).find())
				{
					continue;
				}
				universe.add(itemId);
			}
		}
		catch (IOException ex)
		{
			throw new UncheckedIOException(ex);
		}
		return universe;
	}

	public static SimulationResult simulate(long seed, Scenario scenario, int itemCount,
		List<Integer> universe)
	{
		Objects.requireNonNull(scenario, "scenario");
		Objects.requireNonNull(universe, "universe");
		if (itemCount < 1 || itemCount > universe.size())
		{
			throw new IllegalArgumentException("itemCount out of range: " + itemCount);
		}

		Random random = new Random(seed);
		List<Integer> sampled = sample(universe, itemCount, random);

		BankTabPlan plan;
		try
		{
			List<BankItemSnapshot> rawEntries = new ArrayList<>(sampled.size());
			for (int slot = 0; slot < sampled.size(); slot++)
			{
				rawEntries.add(new BankItemSnapshot(sampled.get(slot),
					1 + random.nextInt(100), slot));
			}
			BankOrganizationPreview preview = BankOrganizationPreviewBuilder.build(
				new BankSnapshot(rawEntries), CompositeItemCatalog.DEFAULT, BankPresets.IRONMAN);
			plan = BankTabPlan.fromPreview(preview);
		}
		catch (RuntimeException ex)
		{
			return SimulationResult.planBuildError(seed, scenario, itemCount, sampled, ex);
		}

		for (BankPreviewItem item : plan.getFlattenedItems())
		{
			if (item == null || item.isBlank() || item.getItemId() <= 0)
			{
				return SimulationResult.blocked(seed, scenario, itemCount, sampled,
					Outcome.UNSUPPORTED_PLAN, Status.UNSUPPORTED_PLAN, planTabs(plan));
			}
		}

		SimulatedBank bank = initialBank(scenario, sampled, plan, random);
		return walk(seed, scenario, itemCount, sampled, plan, bank, random);
	}

	private static SimulationResult walk(long seed, Scenario scenario, int itemCount,
		List<Integer> sampled, BankTabPlan plan, SimulatedBank bank, Random random)
	{
		TabRouteAdvisor.Session session = new TabRouteAdvisor.Session();
		Map<MoveType, Integer> moveCounts = new EnumMap<>(MoveType.class);
		int minimumSwapsAtSortStart = -1;
		int waits = 0;
		int tick = 0;
		int maxMoves = 6 * itemCount + 60;

		for (int moves = 0; moves <= maxMoves; moves++)
		{
			Assessment assessment = session.assess(bank.itemIds(), plan, bank.tabCounts(), ++tick);
			Status status = assessment.getStatus();
			if (status == Status.COMPLETE)
			{
				boolean verified = bank.matchesPlan(plan);
				return SimulationResult.completed(seed, scenario, itemCount, sampled, planTabs(plan),
					moveCounts, minimumSwapsAtSortStart, verified);
			}
			if (status == Status.WAITING_FOR_BANK)
			{
				if (++waits > itemCount + 8)
				{
					return SimulationResult.blocked(seed, scenario, itemCount, sampled,
						Outcome.STALLED, status, planTabs(plan));
				}
				continue;
			}
			if (status != Status.READY)
			{
				return SimulationResult.blocked(seed, scenario, itemCount, sampled,
					Outcome.ADVISOR_BLOCKED, status, planTabs(plan));
			}
			waits = 0;
			if (assessment.getProgress().getPhase() == Phase.SORTING && minimumSwapsAtSortStart < 0)
			{
				minimumSwapsAtSortStart = assessment.getProgress().getRemainingDragsEstimate();
			}
			Move move = assessment.getMove().get();
			moveCounts.merge(move.getType(), 1, Integer::sum);
			bank.apply(move, random);
		}
		return SimulationResult.blocked(seed, scenario, itemCount, sampled,
			Outcome.NON_TERMINATING, Status.READY, planTabs(plan));
	}

	private static List<Integer> sample(List<Integer> universe, int itemCount, Random random)
	{
		List<Integer> copy = new ArrayList<>(universe);
		Collections.shuffle(copy, random);
		return new ArrayList<>(copy.subList(0, itemCount));
	}

	private static SimulatedBank initialBank(Scenario scenario, List<Integer> sampled,
		BankTabPlan plan, Random random)
	{
		switch (scenario)
		{
			case SHUFFLED_NO_TABS:
				return new SimulatedBank(new ArrayList<>(sampled), new int[MAX_TABS]);
			case RANDOM_TABS:
				return randomTabsBank(sampled, random);
			case NEARLY_SORTED:
			default:
				return nearlySortedBank(plan, random);
		}
	}

	private static SimulatedBank randomTabsBank(List<Integer> sampled, Random random)
	{
		List<Integer> items = new ArrayList<>(sampled);
		int[] counts = new int[MAX_TABS];
		int tabs = random.nextInt(Math.min(MAX_TABS, sampled.size()) + 1);
		int remaining = sampled.size();
		for (int tabIndex = 0; tabIndex < tabs && remaining > 1; tabIndex++)
		{
			counts[tabIndex] = 1 + random.nextInt(Math.max(1, remaining / 3));
			remaining -= counts[tabIndex];
		}
		return new SimulatedBank(items, counts);
	}

	private static SimulatedBank nearlySortedBank(BankTabPlan plan, Random random)
	{
		List<Integer> items = new ArrayList<>();
		for (BankPreviewItem item : plan.getFlattenedItems())
		{
			items.add(item.getItemId());
		}
		int[] counts = new int[MAX_TABS];
		List<BankTabPlan.TargetTab> targets = plan.getNumberedTabs();
		for (int tabIndex = 0; tabIndex < targets.size(); tabIndex++)
		{
			counts[tabIndex] = targets.get(tabIndex).getItems().size();
		}
		SimulatedBank bank = new SimulatedBank(items, counts);

		int perturbations = 2 + random.nextInt(6);
		for (int step = 0; step < perturbations; step++)
		{
			if (random.nextBoolean() || items.size() < 2)
			{
				bank.redepositRandomItem(random);
			}
			else
			{
				Collections.swap(items, random.nextInt(items.size()),
					random.nextInt(items.size()));
			}
		}
		return bank;
	}

	private static int planTabs(BankTabPlan plan)
	{
		return plan.getNumberedTabs().size();
	}

	/**
	 * Minimal bank model: a flat unique-item list plus leading tab counts, with
	 * the same free choices a real bank server has when applying each move.
	 */
	static final class SimulatedBank
	{
		private final List<Integer> items;
		private final int[] counts;

		SimulatedBank(List<Integer> items, int[] counts)
		{
			this.items = items;
			this.counts = counts;
		}

		int[] itemIds()
		{
			int[] ids = new int[items.size()];
			for (int slot = 0; slot < ids.length; slot++)
			{
				ids[slot] = items.get(slot);
			}
			return ids;
		}

		int[] tabCounts()
		{
			return counts.clone();
		}

		boolean matchesPlan(BankTabPlan plan)
		{
			List<BankPreviewItem> flattened = plan.getFlattenedItems();
			if (items.size() != flattened.size())
			{
				return false;
			}
			for (int slot = 0; slot < items.size(); slot++)
			{
				if (items.get(slot) != flattened.get(slot).getItemId())
				{
					return false;
				}
			}
			return true;
		}

		void apply(Move move, Random random)
		{
			switch (move.getType())
			{
				case REORDER_TAB:
					int left = Math.min(move.getSourceTab(), move.getTargetTab()) - 1;
					int start = sectionStart(left);
					Collections.rotate(items.subList(start, start + counts[left] + counts[left + 1]), counts[left + 1]);
					int oldCount = counts[left];
					counts[left] = counts[left + 1];
					counts[left + 1] = oldCount;
					break;
				case COLLAPSE_TAB:
					collapse(move.getTargetTab(), random);
					break;
				case DRAG_TO_NEW_TAB:
					create(move.getFromSlot(), move.getTargetTab());
					break;
				case DISTRIBUTE_TO_TAB:
					distribute(move.getFromSlot(), move.getTargetTab(), random);
					break;
				case TRANSFER_TO_TAB:
					transfer(move.getFromSlot(), move.getSourceTab(), move.getTargetTab(), random);
					break;
				case RETURN_TO_MAIN:
					returnToMain(move.getFromSlot(), move.getSourceTab(), random);
					break;
				case SWAP_SECTION:
				default:
					Collections.swap(items, move.getFromSlot(), move.getToSlot());
					break;
			}
		}

		/** Simulates a withdraw + redeposit: the item leaves its tab and lands in main. */
		void redepositRandomItem(Random random)
		{
			int slot = random.nextInt(items.size());
			int tabIndex = tabIndexForSlot(slot);
			if (tabIndex >= 0 && counts[tabIndex] <= 1)
			{
				return;
			}
			int itemId = items.remove(slot);
			if (tabIndex >= 0)
			{
				counts[tabIndex]--;
			}
			items.add(insertPosition(mainStart(), items.size(), random), itemId);
		}

		private void collapse(int targetTab, Random random)
		{
			int targetIndex = targetTab - 1;
			int start = sectionStart(targetIndex);
			List<Integer> removed = new ArrayList<>(
				items.subList(start, start + counts[targetIndex]));
			items.subList(start, start + counts[targetIndex]).clear();
			counts[targetIndex] = 0;
			Collections.shuffle(removed, random);
			for (int itemId : removed)
			{
				items.add(insertPosition(mainStart(), items.size(), random), itemId);
			}
		}

		private void create(int fromSlot, int targetTab)
		{
			int targetIndex = targetTab - 1;
			int itemId = items.remove(fromSlot);
			items.add(sectionStart(targetIndex), itemId);
			counts[targetIndex] = 1;
		}

		private void distribute(int fromSlot, int targetTab, Random random)
		{
			int targetIndex = targetTab - 1;
			int itemId = items.remove(fromSlot);
			int start = sectionStart(targetIndex);
			items.add(insertPosition(start, start + counts[targetIndex], random), itemId);
			counts[targetIndex]++;
		}

		private void transfer(int fromSlot, int sourceTab, int targetTab, Random random)
		{
			int itemId = items.remove(fromSlot);
			counts[sourceTab - 1]--;
			int start = sectionStart(targetTab - 1);
			items.add(insertPosition(start, start + counts[targetTab - 1], random), itemId);
			counts[targetTab - 1]++;
		}

		private void returnToMain(int fromSlot, int sourceTab, Random random)
		{
			int itemId = items.remove(fromSlot);
			counts[sourceTab - 1]--;
			items.add(insertPosition(mainStart(), items.size(), random), itemId);
		}

		private int tabIndexForSlot(int slot)
		{
			int start = 0;
			for (int tabIndex = 0; tabIndex < counts.length && counts[tabIndex] > 0; tabIndex++)
			{
				if (slot < start + counts[tabIndex])
				{
					return tabIndex;
				}
				start += counts[tabIndex];
			}
			return -1;
		}

		private int sectionStart(int tabIndex)
		{
			int start = 0;
			for (int index = 0; index < tabIndex; index++)
			{
				start += counts[index];
			}
			return start;
		}

		private int mainStart()
		{
			int start = 0;
			for (int count : counts)
			{
				start += count;
			}
			return start;
		}

		private static int insertPosition(int startInclusive, int endInclusive, Random random)
		{
			return startInclusive + random.nextInt(endInclusive - startInclusive + 1);
		}
	}

	public static final class SimulationResult
	{
		private final long seed;
		private final Scenario scenario;
		private final int itemCount;
		private final int planTabs;
		private final Outcome outcome;
		private final Status finalStatus;
		private final Map<MoveType, Integer> moveCounts;
		private final int minimumSwapsAtSortStart;
		private final boolean finalOrderVerified;
		private final String errorMessage;
		private final List<Integer> failedItemIds;
		private final List<Integer> sampledItemIds;

		private SimulationResult(long seed, Scenario scenario, int itemCount,
			List<Integer> sampledItemIds, int planTabs,
			Outcome outcome, Status finalStatus, Map<MoveType, Integer> moveCounts,
			int minimumSwapsAtSortStart, boolean finalOrderVerified, String errorMessage,
			List<Integer> failedItemIds)
		{
			this.seed = seed;
			this.scenario = scenario;
			this.itemCount = itemCount;
			this.planTabs = planTabs;
			this.outcome = outcome;
			this.finalStatus = finalStatus;
			this.moveCounts = moveCounts;
			this.minimumSwapsAtSortStart = minimumSwapsAtSortStart;
			this.finalOrderVerified = finalOrderVerified;
			this.errorMessage = errorMessage;
			this.failedItemIds = failedItemIds;
			this.sampledItemIds = new ArrayList<>(sampledItemIds);
		}

		static SimulationResult completed(long seed, Scenario scenario, int itemCount,
			List<Integer> sampled, int planTabs, Map<MoveType, Integer> moveCounts,
			int minimumSwapsAtSortStart, boolean finalOrderVerified)
		{
			return new SimulationResult(seed, scenario, itemCount, sampled, planTabs,
				Outcome.COMPLETED, Status.COMPLETE, moveCounts, minimumSwapsAtSortStart,
				finalOrderVerified, "", Collections.emptyList());
		}

		static SimulationResult blocked(long seed, Scenario scenario, int itemCount,
			List<Integer> sampled, Outcome outcome, Status status, int planTabs)
		{
			return new SimulationResult(seed, scenario, itemCount, sampled, planTabs, outcome,
				status, new EnumMap<>(MoveType.class), -1, false, "", new ArrayList<>(sampled));
		}

		static SimulationResult planBuildError(long seed, Scenario scenario, int itemCount,
			List<Integer> sampled, RuntimeException ex)
		{
			return new SimulationResult(seed, scenario, itemCount, sampled, 0,
				Outcome.PLAN_BUILD_ERROR, null, new EnumMap<>(MoveType.class), -1, false,
				ex.getClass().getSimpleName() + ": " + String.valueOf(ex.getMessage()),
				new ArrayList<>(sampled));
		}

		public long getSeed()
		{
			return seed;
		}

		public Scenario getScenario()
		{
			return scenario;
		}

		public int getItemCount()
		{
			return itemCount;
		}

		public int getPlanTabs()
		{
			return planTabs;
		}

		public Outcome getOutcome()
		{
			return outcome;
		}

		public Status getFinalStatus()
		{
			return finalStatus;
		}

		public Map<MoveType, Integer> getMoveCounts()
		{
			return Collections.unmodifiableMap(moveCounts);
		}

		public int getTotalMoves()
		{
			int total = 0;
			for (int count : moveCounts.values())
			{
				total += count;
			}
			return total;
		}

		public int getSwapMoves()
		{
			return moveCounts.getOrDefault(MoveType.SWAP_SECTION, 0);
		}

		public int getMinimumSwapsAtSortStart()
		{
			return minimumSwapsAtSortStart;
		}

		public boolean isFinalOrderVerified()
		{
			return finalOrderVerified;
		}

		public String getErrorMessage()
		{
			return errorMessage;
		}

		public List<Integer> getFailedItemIds()
		{
			return Collections.unmodifiableList(failedItemIds);
		}

		public List<Integer> getSampledItemIds()
		{
			return Collections.unmodifiableList(sampledItemIds);
		}
	}
}

package com.pkoka5.ironmanbankarchitect.simulate;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.Outcome;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.Scenario;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.SimulationResult;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

public class RandomBankSimulatorTest
{
	private static List<Integer> universe;

	@BeforeClass
	public static void loadUniverse()
	{
		universe = RandomBankSimulator.loadItemUniverse();
	}

	@Test
	public void itemUniverseCoversTheFullRegistryWithoutCacheOnlyRecords()
	{
		assertTrue("universe unexpectedly small: " + universe.size(), universe.size() > 10_000);
	}

	@Test
	public void seededRandomBanksNeverStallOrDeadlockTheGuidanceLoop()
	{
		for (long seed = 1; seed <= 10; seed++)
		{
			for (Scenario scenario : Scenario.values())
			{
				for (int itemCount : new int[]{5, 24, 60})
				{
					SimulationResult result = RandomBankSimulator.simulate(
						seed, scenario, itemCount, universe);
					String context = "seed=" + seed + " scenario=" + scenario
						+ " items=" + itemCount;

					Outcome outcome = result.getOutcome();
					assertTrue(context + " outcome=" + outcome
							+ " error=" + result.getErrorMessage()
							+ " itemIds=" + result.getFailedItemIds(),
						outcome == Outcome.COMPLETED
							|| outcome == Outcome.UNSUPPORTED_PLAN);

					if (outcome == Outcome.COMPLETED)
					{
						assertTrue(context + " final order mismatch",
							result.isFinalOrderVerified());
						if (result.getMinimumSwapsAtSortStart() >= 0)
						{
							assertEquals(context + " sorting used non-minimal swaps",
								result.getMinimumSwapsAtSortStart(), result.getSwapMoves());
						}
					}
				}
			}
		}
	}

	@Test
	public void identicalSeedsReproduceIdenticalSimulationRuns()
	{
		SimulationResult first = RandomBankSimulator.simulate(
			42, Scenario.RANDOM_TABS, 30, universe);
		SimulationResult second = RandomBankSimulator.simulate(
			42, Scenario.RANDOM_TABS, 30, universe);

		assertEquals(first.getOutcome(), second.getOutcome());
		assertEquals(first.getSampledItemIds(), second.getSampledItemIds());
		assertEquals(30, first.getSampledItemIds().size());
		assertEquals(first.getTotalMoves(), second.getTotalMoves());
		assertEquals(first.getSwapMoves(), second.getSwapMoves());
		assertEquals(first.getMoveCounts(), second.getMoveCounts());
	}

	@Test
	public void planBuildErrorsFailEverySimulationEntryPoint()
	{
		SimulationResult failure = SimulationResult.planBuildError(
			1, Scenario.SHUFFLED_NO_TABS, 1, java.util.Collections.singletonList(557),
			new IllegalStateException("duplicate lock"));

		assertTrue(SimulationOutcomePolicy.isHardFailure(failure));
	}
}

package com.pkoka5.ironmanbankarchitect.simulate;

import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.Outcome;
import com.pkoka5.ironmanbankarchitect.simulate.RandomBankSimulator.SimulationResult;

/** Shared pass/fail policy for random-bank verification entry points. */
final class SimulationOutcomePolicy
{
	private SimulationOutcomePolicy()
	{
	}

	static boolean isHardFailure(SimulationResult result)
	{
		return result.getOutcome() == Outcome.PLAN_BUILD_ERROR
			|| result.getOutcome() == Outcome.STALLED
			|| result.getOutcome() == Outcome.NON_TERMINATING
			|| result.getOutcome() == Outcome.ADVISOR_BLOCKED
			|| result.getOutcome() == Outcome.COMPLETED && !result.isFinalOrderVerified();
	}
}
